'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Dialog } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { Select } from '@diki-stwn/serupa-ds';
import { RadioGroup, Radio } from '@diki-stwn/serupa-ds';
import { CopyButton } from '@diki-stwn/serupa-ds';
import { CodeBlock } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Toaster, toast } from '@diki-stwn/serupa-ds';
import { EmptyState } from '@diki-stwn/serupa-ds';
import { Table, TableHead, TableBody, TableRow, TableHeaderCell, TableCell, TableLoadingRows } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { EmptyLoadFailed } from './EmptyStates';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { FormattedDate } from '@diki-stwn/serupa-ds';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';
import { MaskedValue } from '@diki-stwn/serupa-ds';
import { ContextualHelp } from '@diki-stwn/serupa-ds';

/* API keys: the keys a workspace's scripts and tools use, making one, and revoking one. For an app to copy. What it
   carries (WCAG 2.2):
   - 1.3.1: the keys are a table with a caption, so each cell is read with its column; each Revoke is named with its
     key ("Revoke Deploy bot"), so a list of them isn't "Revoke, Revoke, Revoke".
   - 1.4.1: what a key may do is in words ("Read only"), not only a color.
   - 3.3.2: the form says what a name is for and what each kind of access allows, before anything is typed.
   - 3.3.1, 3.3.3: a missing or taken name is said next to the field, which gets focus; a create or revoke that fails
     says so in its dialog, which stays open with what was typed.
   - 3.3.4: revoking breaks whatever uses the key at once, so it asks first and says that it can't be undone.
   - A new key is shown once, as text with a Copy button that gets focus, with a plain warning that it won't be shown
     again; the list shows only its last four characters.
   - 2.4.3: after a revoke, focus goes to the next key's Revoke (or the list's heading), never to the top of the page.
   - 4.1.3, 3.3.1: while the keys load, the table is busy with placeholder rows; a failed load says so, with Try again.
   Making and revoking keys is the app's job: onCreate gets the new key's details and returns its secret, and
   onRevoke gets the key to revoke. */

export type ApiKeyAccess = 'read' | 'write';
export interface ApiKey {
  id: string;
  /** What uses it, as the person named it: "Deploy bot". */
  name: string;
  /** The key's last four characters, so people can match it to what they stored. */
  ends: string;
  access: ApiKeyAccess;
  /** When it was made: a time in ms or an ISO string. */
  created: number | string;
  /** When it was last used, or null for never. */
  lastUsed?: number | string | null | undefined;
  /** When it stops working, or null for never. */
  expires?: number | string | null | undefined;
}
export interface ApiKeyDraft {
  name: string;
  access: ApiKeyAccess;
  /** Days until it stops working, or null for never. */
  expiresInDays: number | null;
}

export interface ApiKeysProps {
  /** The workspace's keys, newest first. Default: three demo keys. */
  keys?: readonly ApiKey[] | undefined;
  /** Create key was pressed with a good name. Return the new key's secret (or its promise): a rejection keeps the dialog open and says so. */
  onCreate?: ((draft: ApiKeyDraft) => string | Promise<string>) | undefined;
  /** Revoke key was pressed and confirmed. Return its promise: a rejection keeps the key and says so. */
  onRevoke?: ((id: string) => unknown) | undefined;
  /** The keys are on their way: a busy table with placeholder rows. Default: false. */
  loading?: boolean | undefined;
  /** The keys failed to load: a "Couldn’t load your API keys" message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

// Times are days before 9:00 UTC on 12 November 2026, so the demo reads the same whenever it's drawn.
const day = (n: number) => Date.UTC(2026, 10, 12, 9) - n * 86400_000;
const demo: ApiKey[] = [
  { id: 'k1', name: 'Deploy bot', ends: '7Qx2', access: 'write', created: day(40), lastUsed: day(0), expires: day(-325) },
  { id: 'k2', name: 'Analytics export', ends: 'm4Ld', access: 'read', created: day(120), lastUsed: day(6), expires: null },
  { id: 'k3', name: 'Old staging test', ends: 'Pz09', access: 'read', created: day(300), lastUsed: null, expires: day(-10) },
];
const demoSecret = 'acme_demo_key_shown_once_8Kd7Ba3L';

const ACCESS: { value: ApiKeyAccess; label: string; hint: string }[] = [
  { value: 'read', label: 'Read only', hint: 'Can look at projects and data, not change them.' },
  { value: 'write', label: 'Read and write', hint: 'Can also change and delete projects and data.' },
];
/** Stands in for the part of a key that is never shown again, so only its last four characters are. */
const HIDDEN = 'x'.repeat(8);
const EXPIRY = [{ value: '30', label: 'In 30 days' }, { value: '90', label: 'In 90 days' }, { value: '365', label: 'In a year' }, { value: 'never', label: 'Never' }];

/** What's wrong with a new key's name, in words, or null when it's good. Names are compared without case. */
export function keyNameProblem(name: string, taken: readonly string[]): string | null {
  const n = name.trim();
  if (!n) return 'Name the key, so you know what uses it.';
  if (taken.some((t) => t.toLocaleLowerCase() === n.toLocaleLowerCase())) return `A key is already called “${n}”. Choose another name.`;
  return null;
}

/** The API keys page: a skip link, a header, then main with the h1 and Create key, and the keys. */
export function ApiKeys({ keys = demo, onCreate, onRevoke, loading = false, loadFailed = false, onRetry, online }: ApiKeysProps) {
  const locale = useLocale();
  const [made, setMade] = React.useState<ApiKey[]>([]);
  const [gone, setGone] = React.useState<ReadonlySet<string>>(new Set());
  const shown = [...made, ...keys].filter((k) => !gone.has(k.id));
  const listHeading = React.useRef<HTMLHeadingElement>(null);
  const afterRevoke = React.useRef<HTMLElement | null>(null);

  // Creating: the form, then the new key's secret, shown once.
  const [creating, setCreating] = React.useState(false);
  const [draft, setDraft] = React.useState<{ name: string; access: ApiKeyAccess; expiry: string }>({ name: '', access: 'read', expiry: '90' });
  const [nameProblem, setNameProblem] = React.useState<string | null>(null);
  const [createFailed, setCreateFailed] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  const [secret, setSecret] = React.useState<string | null>(null);
  const openCreate = (o: boolean) => {
    setCreating(o);
    if (!o) { setSecret(null); setNameProblem(null); setCreateFailed(false); setDraft({ name: '', access: 'read', expiry: '90' }); }
  };
  const create = (e: React.FormEvent) => {
    e.preventDefault();
    const found = keyNameProblem(draft.name, shown.map((k) => k.name));
    setNameProblem(found);
    setCreateFailed(false);
    if (found) { document.getElementById('key-name')?.focus(); return; }
    const d: ApiKeyDraft = { name: draft.name.trim(), access: draft.access, expiresInDays: draft.expiry === 'never' ? null : Number(draft.expiry) };
    setBusy(true);
    void Promise.resolve().then(() => (onCreate ? onCreate(d) : demoSecret)).then((s) => {
      const now = Date.now();
      setMade((m) => [{ id: `new-${now}`, name: d.name, ends: s.slice(-4), access: d.access, created: now, lastUsed: null,
        expires: d.expiresInDays === null ? null : now + d.expiresInDays * 86400_000 }, ...m]);
      setSecret(s);
      // The form's button is gone: Copy, the one thing to do now, takes focus.
      requestAnimationFrame(() => document.getElementById('key-copy')?.focus());
    }, () => setCreateFailed(true)).finally(() => setBusy(false));
  };

  // Revoking: asks first, since whatever uses the key stops working at once.
  const [revoking, setRevoking] = React.useState<ApiKey | null>(null);
  const [revokeFailed, setRevokeFailed] = React.useState(false);
  const [revokeBusy, setRevokeBusy] = React.useState(false);
  const askRevoke = (k: ApiKey | null) => { setRevoking(k); setRevokeFailed(false); };
  const revoke = () => {
    const k = revoking;
    if (!k) return;
    setRevokeBusy(true);
    setRevokeFailed(false);
    void Promise.resolve().then(() => onRevoke?.(k.id)).then(() => {
      const at = shown.indexOf(k), next = shown[at + 1] ?? shown[at - 1];
      afterRevoke.current = next ? document.getElementById(`revoke-${next.id}`) : listHeading.current;
      setGone((g) => new Set(g).add(k.id));
      setRevoking(null);
      toast({ title: `Revoked ${k.name}`, tone: 'success' });
    }, () => setRevokeFailed(true)).finally(() => setRevokeBusy(false));
  };

  const date = (t: number | string) => <FormattedDate value={t} />;
  const accessLabel = (a: ApiKeyAccess) => ACCESS.find((x) => x.value === a)!.label;
  const head = (
    <TableHead><TableRow>
      <TableHeaderCell>Name</TableHeaderCell><TableHeaderCell>Key</TableHeaderCell><TableHeaderCell>
        <span className="inline-flex items-center gap-1">Access
          <ContextualHelp label="About access" title="Access">{ACCESS.map((a) => <p key={a.value} className="m-0"><strong>{a.label}:</strong> {a.hint}</p>)}</ContextualHelp>
        </span>
      </TableHeaderCell>
      <TableHeaderCell>Created</TableHeaderCell><TableHeaderCell>Last used</TableHeaderCell><TableHeaderCell>Expires</TableHeaderCell>
      <TableHeaderCell><span className="sr-only">Actions</span></TableHeaderCell>
    </TableRow></TableHead>
  );

  return (
    <div className="min-h-screen bg-surface-sunken text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <Container as="main" size="lg" className="py-8 outline-none" id="main">
        <Stack gap={6}>
          <OfflineBanner online={online} placement="inline">These are the keys loaded before you went offline. Creating or revoking one needs a connection.</OfflineBanner>
          <PageHeader title="API keys" description="Keys let your scripts and tools use this workspace. Keep each one secret, like a password."
            primary={loadFailed ? undefined : { label: 'Create key', onSelect: () => openCreate(true) }} />

          {loadFailed ? <EmptyLoadFailed title="Couldn’t load your API keys" onRetry={() => onRetry?.()} headingLevel={2} /> : (
            <Card className="flex flex-col gap-4">
              <Heading level={2} size="lg" ref={listHeading} tabIndex={-1} className="outline-none">
                {loading ? 'Keys' : `Keys (${formatNumber(shown.length, locale)})`}
              </Heading>
              {loading ? (
                <Table caption="API keys" hideCaption loading pinStart pinEnd>{head}<TableLoadingRows columns={7} rows={3} label="Loading API keys" /></Table>
              ) : !shown.length ? (
                <EmptyState icon="key" size="sm" title="No API keys yet" headingLevel={3}
                  description="Create a key when a script or tool needs to use this workspace." />
              ) : (
                <Table caption="API keys" hideCaption pinStart pinEnd>
                  {head}
                  <TableBody>{shown.map((k) => (
                    <TableRow key={k.id}>
                      <TableCell className="font-medium">{k.name}</TableCell>
                      <TableCell className="whitespace-nowrap font-mono"><MaskedValue value={HIDDEN + k.ends} label={`${k.name} key`} /></TableCell>
                      <TableCell><Badge>{accessLabel(k.access)}</Badge></TableCell>
                      <TableCell className="whitespace-nowrap">{date(k.created)}</TableCell>
                      <TableCell className="whitespace-nowrap">{k.lastUsed == null ? 'Never' : date(k.lastUsed)}</TableCell>
                      <TableCell className="whitespace-nowrap">{k.expires == null ? 'Never' : date(k.expires)}</TableCell>
                      <TableCell>
                        <Button id={`revoke-${k.id}`} size="sm" variant="ghost" destructive aria-label={`Revoke ${k.name}`} onClick={() => askRevoke(k)}>Revoke</Button>
                      </TableCell>
                    </TableRow>
                  ))}</TableBody>
                </Table>
              )}
            </Card>
          )}

          <Dialog open={creating} onOpenChange={openCreate}
            title={secret ? 'Copy your new key' : 'Create an API key'}
            description={secret
              ? 'This is the only time it’s shown. Store it where your script reads its secrets, or in a password manager.'
              : 'Give it only the access it needs. You can revoke it at any time.'}>
            {secret ? (
              <div className="flex flex-col gap-4">
                <code id="key-secret" className="rounded-md border border-border bg-surface-sunken p-3 font-mono text-sm break-all">{secret}</code>
                <div className="flex flex-wrap gap-2">
                  <CopyButton id="key-copy" value={secret} copiedLabel="Copied" aria-describedby="key-secret" size="md">Copy the key</CopyButton>
                  <Button variant="outline" onClick={() => openCreate(false)}>Done</Button>
                </div>
                <CodeBlock title="Try it" language="bash" wrap
                  code={`curl https://api.example.com/v1/projects \\\n  -H "Authorization: Bearer ${secret}"`} />
              </div>
            ) : (
              <form onSubmit={create} noValidate className="flex flex-col gap-4">
                {createFailed ? <Alert tone="danger">Couldn’t create the key. Try again.</Alert> : null}
                <p className="m-0 text-text-muted">Fields marked * are required.</p>
                <Field label="Name" id="key-name" hint="What uses it, like “Deploy bot”." error={nameProblem ?? undefined} required>
                  <Input value={draft.name} autoComplete="off" onChange={(e) => { setDraft({ ...draft, name: e.target.value }); if (nameProblem) setNameProblem(null); }} />
                </Field>
                <Field label="Access" group>
                  <RadioGroup name="key-access" value={draft.access} onValueChange={(v) => setDraft({ ...draft, access: v })}>
                    {ACCESS.map((a) => <Radio key={a.value} value={a.value} description={a.hint}>{a.label}</Radio>)}
                  </RadioGroup>
                </Field>
                <Field label="Stops working" id="key-expiry" hint="A key that ends limits the harm if it leaks.">
                  <Select value={draft.expiry} options={EXPIRY} onChange={(e) => setDraft({ ...draft, expiry: e.target.value })} />
                </Field>
                <Button type="submit" className="self-start" loading={busy}>Create key</Button>
              </form>
            )}
          </Dialog>

          <Dialog alert open={!!revoking} onOpenChange={(o) => { if (!o) askRevoke(null); }} finalFocus={afterRevoke}
            title={revoking ? `Revoke ${revoking.name}?` : 'Revoke this key?'}
            description="Anything using this key stops working at once. You can’t undo this, but you can create a new key.">
            <div className="flex flex-col gap-4">
              {revokeFailed ? <Alert tone="danger">Couldn’t revoke the key. It still works. Try again.</Alert> : null}
              <div className="flex flex-wrap gap-2">
                <Button variant="outline" onClick={() => askRevoke(null)}>Keep it</Button>
                <Button variant="outline" destructive loading={revokeBusy} onClick={revoke}>Revoke key</Button>
              </div>
            </div>
          </Dialog>
        </Stack>
      </Container>
      <Toaster />
    </div>
  );
}

files.Appointment.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { Textarea } from '@diki-stwn/serupa-ds';
import { Calendar } from '@diki-stwn/serupa-ds';
import { RadioGroup, Radio } from '@diki-stwn/serupa-ds';
import { DescriptionList, DescriptionItem } from '@diki-stwn/serupa-ds';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { EmptyLoadFailed } from './EmptyStates';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { EmptyState } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Appointment: a time with someone, picked by day and then by time, with your details and a confirmation. For an
   app to copy. What it carries (WCAG 2.2):
   - 1.4.1, 1.3.1: days with no free time are struck through and can't be picked; once a day is picked, its times are
     a named group of radios, and a taken time is still listed, disabled, with "taken" in its name, so the reader
     knows it exists and why it can't be chosen.
   - 4.1.3, 2.4.3: picking a day says how many times are free on it, and the times' heading names the day.
   - 3.3.1, 3.3.2: name and email are required and say so; what's missing is said next to its field, and focus goes to
     the first. Book with no time says what to choose and puts focus on the times or the calendar.
   - 1.3.5: the name and email fields say what they are for autofill.
   - 1.3.1: the appointment is summed up as a description list: what, with whom, when and where.
   - 3.3.4, 4.1.3: Book shows it's busy and books only once the server says so; one that fails says so next to the
     button and keeps everything; a time taken meanwhile can be marked taken by the app.
   - 2.4.3, 4.1.3: once booked, the form gives way to a confirmation whose heading takes focus and says when.
   - 4.1.3, 3.3.1: while the times load, a placeholder named once; a failed load says so, with Try again.
   Booking is the app's job: onBook gets the day, the time and the details; reject its promise when it fails. */

export interface AppointmentService {
  /** What it is: "Eye test". */
  name: string;
  /** How long it takes, in minutes. */
  minutes: number;
  /** Who it's with: "Dr. Sari Wijaya". */
  with: string;
  /** Where: "Jl. Riau 21, Bandung". */
  where: string;
}
/** A time on a day, as "HH:mm", and whether it's still free. */
export interface AppointmentSlot {
  time: string;
  free: boolean;
}
/** What's sent: the day as "yyyy-mm-dd", the time as "HH:mm", and the details. */
export interface AppointmentRequest {
  day: string;
  time: string;
  name: string;
  email: string;
  note: string;
}

export interface AppointmentProps {
  /** What's being booked. Default: a demo eye test. */
  service?: AppointmentService | undefined;
  /** The times on each day, by "yyyy-mm-dd". A day that isn't here has no times. Default: the demo's. */
  slots?: Readonly<Record<string, readonly AppointmentSlot[]>> | undefined;
  /** The earliest day, as "yyyy-mm-dd". Pass today's. Default: "2025-03-03", for the demo. */
  today?: string | undefined;
  /** Books the appointment. Return its promise: a rejection keeps the form and says so. */
  onBook?: ((request: AppointmentRequest) => unknown) | undefined;
  /** The times are on their way from the server: placeholders, named once ("Loading times"). Default: false. */
  loading?: boolean | undefined;
  /** The times failed to load: a message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads the times again, after a failed load. */
  onRetry?: (() => void) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demoService: AppointmentService = { name: 'Eye test', minutes: 30, with: 'Dr. Sari Wijaya', where: 'Jl. Riau 21, Bandung' };
const times = (free: string[], taken: string[] = []): AppointmentSlot[] =>
  [...free.map((time) => ({ time, free: true })), ...taken.map((time) => ({ time, free: false }))].sort((a, b) => (a.time < b.time ? -1 : 1));
const demoSlots: Record<string, AppointmentSlot[]> = {
  '2025-03-04': times(['09:00', '10:30', '14:00'], ['09:30', '11:00']),
  '2025-03-05': times(['13:00', '13:30'], ['09:00']),
  '2025-03-06': times([], ['09:00', '09:30', '10:00']),
  '2025-03-07': times(['09:00', '09:30', '10:00', '15:30']),
  '2025-03-11': times(['10:00', '11:30']),
  '2025-03-12': times(['09:00'], ['10:00', '10:30']),
};

// A "yyyy-mm-dd" day at local midnight, and a day as "yyyy-mm-dd".
const day = (s: string) => { const [y, m, d] = s.split('-').map(Number); return new Date(y!, m! - 1, d); };
const iso = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

/** The days that have at least one free time, as "yyyy-mm-dd", in order. */
export const freeDays = (slots: Readonly<Record<string, readonly AppointmentSlot[]>>): string[] =>
  Object.keys(slots).filter((d) => slots[d]!.some((s) => s.free)).sort();

/** A day and a time in words: "Tuesday, March 4 at 10:30 AM". */
export function slotWords(dayIso: string, time: string, locale?: string): string {
  const [h, m] = time.split(':').map(Number);
  const d = day(dayIso);
  d.setHours(h!, m);
  const date = new Intl.DateTimeFormat(locale, { weekday: 'long', month: 'long', day: 'numeric', calendar: 'gregory', numberingSystem: 'latn' }).format(d);
  return `${date} at ${timeWords(time, locale)}`;
}
/** A time as the locale writes it: "10:30 AM", "10.30". */
export function timeWords(time: string, locale?: string): string {
  const [h, m] = time.split(':').map(Number);
  return new Intl.DateTimeFormat(locale, { hour: 'numeric', minute: '2-digit', numberingSystem: 'latn' }).format(new Date(2000, 0, 1, h, m)).replace(/[\u2009\u202f]/g, ' ');
}

/** What's wrong with the details, by field, or {} when they can be sent. */
export function detailProblems(d: Pick<AppointmentRequest, 'name' | 'email'>): Partial<Record<'name' | 'email', string>> {
  const out: Partial<Record<'name' | 'email', string>> = {};
  if (!d.name.trim()) out.name = 'Enter your name.';
  if (!d.email.trim()) out.email = 'Enter your email address.';
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.email.trim())) out.email = 'Enter an email address like name@example.com.';
  return out;
}

/** The booking page: a skip link, a header, then main with the service's h1, the day and time, your details and Book. */
export function Appointment({ service = demoService, slots = demoSlots, today = '2025-03-03', onBook, loading = false, loadFailed = false, onRetry, online }: AppointmentProps) {
  const locale = useLocale(undefined);
  const [picked, setPicked] = React.useState<string | null>(null);
  const [time, setTime] = React.useState<string | null>(null);
  const [details, setDetails] = React.useState({ name: '', email: '', note: '' });
  const [problems, setProblems] = React.useState<ReturnType<typeof detailProblems>>({});
  const [pickProblem, setPickProblem] = React.useState<string | null>(null);
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const [booked, setBooked] = React.useState<AppointmentRequest | null>(null);
  const calendar = React.useRef<HTMLDivElement>(null);
  const times = React.useRef<HTMLDivElement>(null);
  const done = React.useRef<HTMLHeadingElement>(null);
  // Free times before today can't be booked: with none from today on, there's nothing to choose.
  const open = React.useMemo(() => new Set(freeDays(slots).filter((d) => d >= today)), [slots, today]);
  const closed = React.useCallback((d: Date) => !open.has(iso(d)), [open]);
  const first = [...open][0];
  const daySlots = picked ? slots[picked] ?? [] : [];
  const freeCount = daySlots.filter((s) => s.free).length;
  const dayName = (d: string) => new Intl.DateTimeFormat(locale, { weekday: 'long', month: 'long', day: 'numeric', calendar: 'gregory', numberingSystem: 'latn' }).format(day(d));

  const pickDay = (_: Date, { iso: d }: { iso: string }) => { setPicked(d); setTime(null); setPickProblem(null); setFailed(false); };
  const edit = (patch: Partial<typeof details>) => {
    setDetails((now) => ({ ...now, ...patch }));
    setFailed(false);
  };
  const book = (e: React.FormEvent) => {
    e.preventDefault();
    setFailed(false);
    const found = detailProblems(details);
    setProblems(found);
    if (!picked || !time) {
      setPickProblem(picked ? 'Choose a time.' : 'Choose a day, then a time.');
      const target = picked ? times.current?.querySelector<HTMLElement>('input:not(:disabled)') : calendar.current?.querySelector<HTMLElement>('.srp-calendar__day[tabindex="0"]');
      target?.focus();
      return;
    }
    const firstProblem = (['name', 'email'] as const).find((k) => found[k]);
    if (firstProblem) { document.getElementById(`appointment-${firstProblem}`)?.focus(); return; }
    const request: AppointmentRequest = { day: picked, time, name: details.name.trim(), email: details.email.trim(), note: details.note.trim() };
    setBusy(true);
    void Promise.resolve().then(() => onBook?.(request)).then(() => setBooked(request), () => setFailed(true)).finally(() => setBusy(false));
  };
  React.useEffect(() => { if (booked) done.current?.focus(); }, [booked]);

  const h2 = 'm-0 text-lg font-semibold';
  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme Clinic</p>
      </header>
      <Container as="main" size="lg" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">These times are from when the page loaded and may have gone. Booking needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Services', href: '#services' }, { label: service.name }]} title={`Book an ${service.name.toLowerCase()}`}
            description={`${formatNumber(service.minutes, locale)} minutes with ${service.with}`} />

          <div className="pt-6">
            {loadFailed ? <EmptyLoadFailed title="Couldn’t load the times" onRetry={() => onRetry?.()} headingLevel={2} />
              : loading ? <Card><Skeleton shape="text" lines={6} label="Loading times" /></Card>
              : !first && !booked ? <EmptyState icon="event_busy" title="No free times" headingLevel={2}
                  description={`${service.with} has no free times in the weeks ahead. New times open every Monday.`} />
              : booked ? (
                <section aria-labelledby="booked" className="flex flex-col items-start gap-3">
                  <h2 id="booked" ref={done} tabIndex={-1} className="m-0 text-2xl font-semibold outline-none">You’re booked for {slotWords(booked.day, booked.time, locale)}</h2>
                  <p className="m-0">We’ve sent the details to {booked.email}. To change the time, use the link in that email.</p>
                  <Button variant="outline" onClick={() => { setBooked(null); setPicked(null); setTime(null); }}>Book another time</Button>
                </section>
              ) : (
                <form onSubmit={book} noValidate className="grid items-start gap-6 md:grid-cols-3">
                  <div className="flex flex-col gap-8 md:col-span-2">
                    <p className="m-0 text-text-muted">Fields marked * are required.</p>
                    <section aria-labelledby="day" className="flex flex-col gap-4">
                      <h2 id="day" className={h2}>Day</h2>
                      <p className="m-0 text-sm text-text-muted">Days with no free times are struck through.</p>
                      <Calendar ref={calendar} className="self-start" aria-labelledby="day" value={picked} onValueChange={pickDay} min={today}
                        defaultMonth={day(first ?? today)} isDateDisabled={closed} />
                      {picked ? <p id="free-times" className="m-0" role="status">{freeCount === 1 ? '1 time free' : `${formatNumber(freeCount, locale)} times free`} on {dayName(picked)}.</p> : null}
                    </section>
                    {picked ? (
                      <Field label={`Times on ${dayName(picked)}`} group required>
                        <RadioGroup ref={times} name="appointment-time" value={time} orientation="horizontal" variant="card"
                          onValueChange={(v: string) => { setTime(v); setPickProblem(null); setFailed(false); }}>
                          {daySlots.map((s) => (
                            <Radio key={s.time} value={s.time} disabled={!s.free} aria-label={s.free ? undefined : `${timeWords(s.time, locale)}, taken`}>
                              {s.free ? timeWords(s.time, locale) : <span className="line-through">{timeWords(s.time, locale)}</span>}
                            </Radio>
                          ))}
                        </RadioGroup>
                      </Field>
                    ) : null}
                    {pickProblem ? <Alert tone="danger">{pickProblem}</Alert> : null}
                    <section aria-labelledby="you" className="flex flex-col gap-4">
                      <h2 id="you" className={h2}>Your details</h2>
                      <Field label="Name" id="appointment-name" error={problems.name} required>
                        <Input autoComplete="name" value={details.name} onChange={(e) => edit({ name: e.target.value })} />
                      </Field>
                      <Field label="Email" id="appointment-email" hint="We send the details and a reminder here." error={problems.email} required>
                        <Input type="email" autoComplete="email" value={details.email} onChange={(e) => edit({ email: e.target.value })} />
                      </Field>
                      <Field label="Anything we should know?" optional>
                        <Textarea rows={3} value={details.note} onChange={(e) => edit({ note: e.target.value })} />
                      </Field>
                    </section>
                  </div>
                  <Card>
                    <section aria-labelledby="summary" className="flex flex-col gap-4">
                      <h2 id="summary" className={h2}>Your appointment</h2>
                      <DescriptionList>
                        <DescriptionItem term="What">{service.name}, {formatNumber(service.minutes, locale)} minutes</DescriptionItem>
                        <DescriptionItem term="With">{service.with}</DescriptionItem>
                        <DescriptionItem term="When">{picked && time ? slotWords(picked, time, locale) : picked ? `${dayName(picked)}, time to choose` : 'Choose a day and a time'}</DescriptionItem>
                        <DescriptionItem term="Where">{service.where}</DescriptionItem>
                      </DescriptionList>
                      {failed ? <Alert tone="danger">Couldn’t book this time. Try again, or choose another.</Alert> : null}
                      <Button type="submit" loading={busy}>Book</Button>
                    </section>
                  </Card>
                </form>
              )}
          </div>
        </Stack>
      </Container>
    </div>
  );
}

