'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { NumberInput } from '@diki-stwn/serupa-ds';
import { RangeCalendar } from '@diki-stwn/serupa-ds';
import { DescriptionList, DescriptionItem } from '@diki-stwn/serupa-ds';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { FormattedNumber } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { EmptyLoadFailed } from './EmptyStates';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Booking: a stay at one place, picked on two months side by side, with the nights counted, the nights already
   booked named, the price worked out and a way to reserve. For an app to copy. What it carries (WCAG 2.2):
   - 1.4.1, 1.3.1: the nights already booked are struck through on the calendar and also listed in words beside it,
     so nobody has to tell them apart by look, and the calendar names each picked day "start date" or "end date".
   - 3.3.1, 4.1.3: dates that take in a booked night, or fewer nights than the place lets, are said at once in an alert
     the calendar points to, naming the nights; Reserve with no dates says what to choose and puts focus on the calendar.
   - 3.3.2: the guests field says how many the place sleeps; the count can't go past it.
   - 1.3.1: the price is a description list: the nightly price times the nights, the cleaning fee and the total, in words.
   - 3.3.4, 4.1.3: Reserve shows it's busy and books only once the server says so; a booking that fails says so next to
     the button and keeps the dates.
   - 2.4.3, 4.1.3: once booked, the form gives way to a confirmation whose heading takes focus and says the dates.
   - 4.1.3, 3.3.1: while the place loads, a placeholder named once; a failed load says so, with Try again.
   Booking is the app's job: onReserve gets the stay; reject its promise when it can't be booked. */

export interface BookingPlace {
  /** What it's called: "Sea-view room". */
  name: string;
  /** Where it is: "Canggu, Bali". */
  where: string;
  /** The price of one night, in the currency's main unit. */
  price: number;
  /** A fee for each stay, whatever its length. 0 leaves it out. */
  cleaning: number;
  /** How many it sleeps. */
  maxGuests: number;
  /** The fewest nights a stay can be. */
  minNights: number;
  /** Nights already booked, each the "yyyy-mm-dd" of the day it starts. */
  taken: readonly string[];
}
/** A stay: the day the guests arrive and the day they leave, as "yyyy-mm-dd", and how many come. */
export interface BookingStay {
  start: string;
  end: string;
  guests: number;
}

export interface BookingProps {
  /** The place. Default: a demo room. */
  place?: BookingPlace | undefined;
  /** An ISO 4217 code. Default: "USD". */
  currency?: string | undefined;
  /** The earliest day a stay can start, as "yyyy-mm-dd". Pass today's. Default: "2026-11-05", for the demo. */
  today?: string | undefined;
  /** Books the stay. Return its promise: a rejection keeps the dates and says the booking failed. */
  onReserve?: ((stay: BookingStay) => unknown) | undefined;
  /** The place is on its way from the server: placeholders, named once ("Loading place"). Default: false. */
  loading?: boolean | undefined;
  /** The place failed to load: a message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads the place again, after a failed load. */
  onRetry?: (() => void) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demo: BookingPlace = {
  name: 'Sea-view room', where: 'Canggu, Bali', price: 120, cleaning: 40, maxGuests: 3, minNights: 2,
  taken: ['2026-11-12', '2026-11-13', '2026-11-14', '2026-11-26', '2026-11-27', '2026-12-24', '2026-12-25', '2026-12-26'],
};

// A "yyyy-mm-dd" day at local midnight, the day n days on from d, and a day as "yyyy-mm-dd".
const day = (s: string) => { const [y, m, d] = s.split('-').map(Number); return new Date(y!, m! - 1, d); };
const shift = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);
const iso = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

const DAY = 864e5;
/** The nights between the day the guests arrive and the day they leave. */
export const nightsBetween = (start: string, end: string): number => Math.round((day(end).getTime() - day(start).getTime()) / DAY);

/** The booked nights a stay takes in, from the first night to the last (the day it ends is not a night of it). */
export function takenIn(stay: { start: string; end: string }, taken: readonly string[]): string[] {
  const end = day(stay.end);
  return [...taken].sort().filter((n) => n >= stay.start && day(n) < end);
}

/** Booked nights in runs, each written as the stay it is: the day it starts and the day after its last night. */
export function bookedStays(taken: readonly string[]): { start: string; end: string }[] {
  const out: { start: string; end: string }[] = [];
  for (const n of [...new Set(taken)].sort()) {
    const last = out[out.length - 1];
    const next = iso(shift(day(n), 1));
    if (last && last.end === n) last.end = next;
    else out.push({ start: n, end: next });
  }
  return out;
}

const words = (locale: string | undefined, a: string, b?: string) => {
  const f = new Intl.DateTimeFormat(locale, { dateStyle: 'medium', calendar: 'gregory', numberingSystem: 'latn' });
  return (b && b !== a ? f.formatRange(day(a), day(b)) : f.format(day(a))).replace(/[\u2009\u202f]/g, ' ');
};

/** What's wrong with the dates, as a sentence, or null when they can be booked. */
export function stayProblem(stay: { start: string; end: string } | null, place: Pick<BookingPlace, 'taken' | 'minNights'>, locale?: string): string | null {
  if (!stay) return 'Choose the day you arrive and the day you leave.';
  const hit = takenIn(stay, place.taken);
  if (hit.length) return `${hit.length === 1 ? 'The night of' : 'The nights of'} ${words(locale, hit[0]!, hit[hit.length - 1])} ${hit.length === 1 ? 'is' : 'are'} already booked. Choose other dates.`;
  if (nightsBetween(stay.start, stay.end) < place.minNights) return `Stay at least ${place.minNights} nights.`;
  return null;
}

/** The booking page: a skip link, a header, then main with the place's h1, its dates, guests and price. */
export function Booking({ place = demo, currency = 'USD', today = '2026-11-05', onReserve, loading = false, loadFailed = false, onRetry, online }: BookingProps) {
  const locale = useLocale(undefined);
  const [stay, setStay] = React.useState<{ start: string; end: string } | null>(null);
  const [chosen, setGuests] = React.useState<number | null>(2);
  // Two to start, or fewer when the place sleeps fewer (which it can say only once it has loaded).
  const guests = chosen && Math.min(chosen, Math.max(1, place.maxGuests));
  const [asked, setAsked] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const [booked, setBooked] = React.useState<BookingStay | null>(null);
  const calendar = React.useRef<HTMLDivElement>(null);
  const done = React.useRef<HTMLHeadingElement>(null);
  const taken = React.useMemo(() => new Set(place.taken), [place.taken]);
  // A day closes only when the night before it is booked too: the first day of a booked run can still end a stay,
  // and the day a booked run ends can still start one.
  const closed = React.useCallback((d: Date) => taken.has(iso(d)) && taken.has(iso(shift(d, -1))), [taken]);

  const problem = stayProblem(stay, place, locale);
  const shownProblem = stay || asked ? problem : null;
  const nights = stay ? nightsBetween(stay.start, stay.end) : 0;
  const money = (n: number) => <FormattedNumber value={n} format="currency" currency={currency} />;
  const nightWords = (n: number) => `${formatNumber(n, locale)} ${n === 1 ? 'night' : 'nights'}`;

  const reserve = () => {
    setFailed(false);
    if (problem || !stay || !guests) {
      setAsked(true);
      calendar.current?.querySelector<HTMLElement>('.srp-calendar__day[tabindex="0"]')?.focus();
      return;
    }
    const s: BookingStay = { ...stay, guests };
    setBusy(true);
    void Promise.resolve().then(() => onReserve?.(s)).then(() => setBooked(s), () => setFailed(true)).finally(() => setBusy(false));
  };
  React.useEffect(() => { if (booked) done.current?.focus(); }, [booked]);

  const h2 = 'm-0 text-lg font-semibold';
  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme Stays</p>
      </header>
      <Container as="main" size="lg" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">These dates are from when the page loaded and may have gone. Reserving needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Stays', href: '#stays' }, { label: place.name }]} title={place.name}
            description={loading || loadFailed ? undefined : <>{place.where} · {money(place.price)} a night · Sleeps {formatNumber(place.maxGuests, locale)}</>} />

          <div className="pt-6">
            {loadFailed ? <EmptyLoadFailed title="Couldn’t load the place" onRetry={() => onRetry?.()} headingLevel={2} />
              : loading ? <Card><Skeleton shape="text" lines={6} label="Loading place" /></Card>
              : booked ? (
                <section aria-labelledby="booked" className="flex flex-col items-start gap-3">
                  <h2 id="booked" ref={done} tabIndex={-1} className="m-0 text-2xl font-semibold outline-none">You’re booked</h2>
                  <p className="m-0">{words(locale, booked.start, booked.end)}, {nightWords(nightsBetween(booked.start, booked.end))}, for {formatNumber(booked.guests, locale)} {booked.guests === 1 ? 'guest' : 'guests'}. We’ve sent the details to your email.</p>
                  <Button variant="outline" onClick={() => { setBooked(null); setStay(null); setAsked(false); }}>Book other dates</Button>
                </section>
              ) : (
                <div className="grid items-start gap-6 md:grid-cols-3">
                  <div className="flex flex-col gap-8 md:col-span-2">
                    <section aria-labelledby="dates" className="flex flex-col gap-4">
                      <h2 id="dates" className={h2}>Your dates</h2>
                      <p className="m-0 text-sm text-text-muted">Choose the day you arrive, then the day you leave. Stays are {formatNumber(place.minNights, locale)} nights at least.</p>
                      <RangeCalendar ref={calendar} aria-labelledby="dates" aria-describedby={shownProblem ? 'stay-problem' : undefined} months={2}
                        defaultMonth={day(today)} min={today} isDateDisabled={closed} value={stay}
                        onValueChange={(_, { iso }) => { setFailed(false); setStay(iso); }} />
                      {shownProblem ? <Alert id="stay-problem" tone="danger">{shownProblem}</Alert> : null}
                      {place.taken.length ? (
                        <div className="flex flex-col gap-1">
                          <h3 id="taken" className="m-0 text-base font-semibold">Already booked</h3>
                          <ul aria-labelledby="taken" className="m-0 flex flex-col gap-1 ps-5">
                            {bookedStays(place.taken).map((b) => <li key={b.start}>{words(locale, b.start, b.end)}</li>)}
                          </ul>
                          <p className="m-0 text-sm text-text-muted">A stay can end on the day one of these starts, and start on the day one ends.</p>
                        </div>
                      ) : null}
                    </section>
                    <section aria-labelledby="who" className="flex flex-col gap-4">
                      <h2 id="who" className={h2}>Who’s coming</h2>
                      <Field label="Guests" hint={`Up to ${formatNumber(place.maxGuests, locale)}.`} required>
                        <NumberInput value={guests} onValueChange={setGuests} min={1} max={place.maxGuests} />
                      </Field>
                    </section>
                  </div>
                  <Card>
                    <section aria-labelledby="price" className="flex flex-col gap-4">
                      <h2 id="price" className={h2}>Your stay</h2>
                      {stay && !problem ? (
                        <DescriptionList layout="split">
                          <DescriptionItem term="Arrive">{words(locale, stay.start)}</DescriptionItem>
                          <DescriptionItem term="Leave">{words(locale, stay.end)}</DescriptionItem>
                          <DescriptionItem term={<>{money(place.price)} × {nightWords(nights)}</>}>{money(place.price * nights)}</DescriptionItem>
                          {place.cleaning ? <DescriptionItem term="Cleaning">{money(place.cleaning)}</DescriptionItem> : null}
                          <DescriptionItem term="Total" emphasis>{money(place.price * nights + place.cleaning)}</DescriptionItem>
                        </DescriptionList>
                      ) : <p className="m-0 text-text-muted">Choose your dates to see the price.</p>}
                      {failed ? <Alert tone="danger">Couldn’t book these dates. Try again.</Alert> : null}
                      <Button loading={busy} onClick={reserve}>Reserve</Button>
                      <p className="m-0 text-sm text-text-muted">You won’t pay until the host confirms.</p>
                    </section>
                  </Card>
                </div>
              )}
          </div>
        </Stack>
      </Container>
    </div>
  );
}

files.ConsentBanner.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { RadioGroup, Radio } from '@diki-stwn/serupa-ds';
import { announce } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Consent banner: asks once whether optional cookies may be set, and lets the answer be changed at any time.
   For an app to copy. What it carries (WCAG 2.2):
   - 2.4.11: the banner sits at the top of the page in the normal flow, not over it, so it never hides the focused
     element, whatever is focused and however far the page is zoomed (1.4.10).
   - 2.1.2: it isn't a dialog and doesn't trap focus. Tab goes through it and on into the page; the page works
     without an answer, and no optional cookie is set until there is one.
   - Accept and reject are the same kind of button, side by side, in the same words ("Accept analytics cookies",
     "Reject analytics cookies"): neither is hidden behind a link or a paler color (3.2.4, and the law's "as easy to
     refuse as to accept").
   - 4.1.3, 2.4.3: after an answer, the banner says what was chosen and where to change it; focus moves to that
     message, so it's read, and "Hide this message" moves focus to main, never back to the page's start.
   - The choice can be changed later from "Cookie settings" (linked from the banner, the message and the footer),
     and saving there is announced.
   Setting or clearing the cookies themselves, and loading the analytics script only after "accept", is the app's
   job; here `onChange` is told. */

export type ConsentChoice = 'accepted' | 'rejected';

export interface ConsentBannerProps {
  /** The answer already given, from the cookie the app keeps. Without one, the banner asks. */
  initial?: ConsentChoice | null | undefined;
  /** Keeps the answer in localStorage under this key, so the banner doesn't ask again after a reload. */
  saveKey?: string | undefined;
  /** Called with each answer: set or clear the analytics cookies and load or unload the script. */
  onChange?: ((choice: ConsentChoice) => void) | undefined;
}

function load(key: string | undefined): ConsentChoice | null {
  if (!key) return null;
  try {
    const v = window.localStorage.getItem(key);
    return v === 'accepted' || v === 'rejected' ? v : null;
  } catch { return null; }
}
function save(key: string | undefined, choice: ConsentChoice) {
  if (!key) return;
  try { window.localStorage.setItem(key, choice); } catch { /* private mode or full: the banner asks again next time */ }
}

const SETTINGS = 'cookie-settings';
const said = (c: ConsentChoice) => `You’ve ${c === 'accepted' ? 'accepted' : 'rejected'} analytics cookies.`;

/** A page with a cookie banner at its top, a cookie settings section and a footer link back to it. */
export function ConsentBanner({ initial, saveKey, onChange }: ConsentBannerProps) {
  const [choice, setChoice] = React.useState<ConsentChoice | null>(() => load(saveKey) ?? initial ?? null);
  // 'ask' shows the question, 'told' the message after an answer, 'gone' nothing.
  const [banner, setBanner] = React.useState<'ask' | 'told' | 'gone'>(() => (choice ? 'gone' : 'ask'));
  const [draft, setDraft] = React.useState<ConsentChoice>(choice ?? 'rejected');
  const message = React.useRef<HTMLDivElement | null>(null);

  const decide = (c: ConsentChoice) => { setChoice(c); setDraft(c); save(saveKey, c); onChange?.(c); };
  const answer = (c: ConsentChoice) => { decide(c); setBanner('told'); };
  React.useEffect(() => { if (banner === 'told') message.current?.focus(); }, [banner]);
  const hide = () => { setBanner('gone'); document.getElementById('main')?.focus(); };
  const saveSettings = (e: React.FormEvent) => {
    e.preventDefault();
    decide(draft);
    if (banner === 'ask') setBanner('gone');
    announce(`Your cookie settings were saved. ${said(draft)}`);
  };

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      {banner === 'gone' ? null : (
        <section aria-labelledby="consent-title" className="border-b border-border bg-surface px-4 py-4">
          <div className="mx-auto flex max-w-3xl flex-col gap-3">
            {banner === 'ask' ? (
              <>
                <Heading level={2} size="lg" id="consent-title">Cookies on Acme</Heading>
                <p className="m-0 text-sm">We use essential cookies to make the site work. We’d also like to set analytics cookies to learn how the site is used, so we can make it better. We won’t set them unless you accept.</p>
                <div className="flex flex-wrap items-center gap-3">
                  <Button onClick={() => answer('accepted')}>Accept analytics cookies</Button>
                  <Button onClick={() => answer('rejected')}>Reject analytics cookies</Button>
                  <Link href={`#${SETTINGS}`}>Choose your cookies</Link>
                </div>
              </>
            ) : (
              <div ref={message} tabIndex={-1} className="flex flex-col gap-3 outline-none">
                <Heading level={2} size="lg" id="consent-title">Cookies on Acme</Heading>
                <p className="m-0 text-sm">{said(choice ?? draft)} You can <Link href={`#${SETTINGS}`}>change your cookie settings</Link> at any time.</p>
                <div><Button variant="secondary" onClick={hide}>Hide this message</Button></div>
              </div>
            )}
          </div>
        </section>
      )}
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <Container as="main" size="md" className="py-8 outline-none" id="main" tabIndex={-1}>
        <Stack gap={6}>
          <div className="flex flex-col gap-2">
            <Heading level={1}>Garden tools that last</Heading>
            <p className="m-0 text-text-muted">Spades, forks and shears made to be mended, not thrown away. <Link href="#shop">Shop the range</Link> or <Link href="#repairs">book a repair</Link>.</p>
          </div>
          <Card as="section" aria-labelledby={`${SETTINGS}-title`} id={SETTINGS} className="flex flex-col gap-4">
            <Heading level={2} size="lg" id={`${SETTINGS}-title`}>Cookie settings</Heading>
            <p className="m-0 text-sm">Essential cookies keep you signed in and remember what’s in your basket. They’re always on, because the site doesn’t work without them.</p>
            <form onSubmit={saveSettings} className="flex flex-col gap-4">
              <Field label="Use analytics cookies?" hint="They tell us which pages are visited and for how long. Nothing that names you." group>
                <RadioGroup name="analytics" value={draft} onValueChange={(v) => setDraft(v)}>
                  <Radio value="accepted">Yes, use analytics cookies</Radio>
                  <Radio value="rejected">No, don’t use analytics cookies</Radio>
                </RadioGroup>
              </Field>
              <div><Button type="submit">Save cookie settings</Button></div>
            </form>
          </Card>
        </Stack>
      </Container>
      <footer className="border-t border-border bg-surface px-4 py-4 text-sm">
        <div className="mx-auto flex max-w-3xl flex-wrap gap-x-6 gap-y-2">
          <span>© 2026 Acme</span>
          <Link href={`#${SETTINGS}`}>Cookie settings</Link>
        </div>
      </footer>
    </div>
  );
}

files.ContactForm.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { CascadeSelect, type CascadeOption } from '@diki-stwn/serupa-ds';
import { Textarea } from '@diki-stwn/serupa-ds';
import { Checkbox } from '@diki-stwn/serupa-ds';
import { ErrorSummary, type ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Contact form: a message to the people behind a product, with what they need to answer it, and an answer to say it
   arrived. For an app to copy. What it carries (WCAG 2.2):
   - 3.3.2, 1.3.5: each field says what it's for, which are optional, and its format; name and email say what they are
     for autofill. The topic is a CascadeSelect, a kind then what about it, read as one path ("An order, It hasn’t
     arrived"). The order number is asked for only when the topic is an order.
   - 3.3.1, 2.4.3: sending with problems shows a summary at the top that takes focus, each problem a link to its
     field, and each field says its own problem too.
   - 3.3.4, 4.1.3: Send shows it's busy; a message that can't be sent says so next to the button and keeps every field.
   - 2.4.3, 4.1.3: once sent, the form gives way to an answer whose heading takes focus, with the reference and when
     to expect a reply.
   Sending is the app's job: onSend gets the message; resolve with its reference, or reject when it can't be sent. */

export interface ContactMessage {
  name: string;
  email: string;
  /** The topic's path, its values joined by "/": "order/late", or "other" for one with no second step. */
  topic: string;
  /** With an "order/…" topic: the order's number. */
  order: string;
  message: string;
  /** Send a copy to the email given. */
  copy: boolean;
}

export interface ContactFormProps {
  /** Sends the message. Resolve with its reference ("CF-2041"); reject when it can't be sent. */
  onSend?: ((message: ContactMessage) => unknown) | undefined;
  /** How soon you answer, for the answer page: "within 2 working days". Default: that. */
  replyTime?: string | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const TOPICS: CascadeOption[] = [
  { value: 'order', label: 'An order', children: [
    { value: 'late', label: 'It hasn’t arrived' }, { value: 'wrong', label: 'Something’s wrong with it' }, { value: 'return', label: 'Sending it back' }] },
  { value: 'account', label: 'My account', children: [
    { value: 'sign-in', label: 'Signing in' }, { value: 'email', label: 'Changing my email' }, { value: 'close', label: 'Closing it' }] },
  { value: 'product', label: 'A product question' },
  { value: 'other', label: 'Something else' },
];
/** Whether a topic is about an order, so the order number is asked for. */
export const aboutOrder = (topic: string) => topic.split('/')[0] === 'order';
const LIMIT = 1000;
const blank: ContactMessage = { name: '', email: '', topic: '', order: '', message: '', copy: false };
const FIELDS = ['name', 'email', 'topic', 'order', 'message'] as const;
type Problems = Partial<Record<(typeof FIELDS)[number], string>>;

/** What's wrong with the message, by field, in the order of the form, or {} when it can be sent. */
export function contactProblems(m: ContactMessage): Problems {
  const out: Problems = {};
  if (!m.name.trim()) out.name = 'Enter your name.';
  if (!m.email.trim()) out.email = 'Enter your email address, so we can reply.';
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(m.email.trim())) out.email = 'Enter an email address like name@example.com.';
  if (!m.topic) out.topic = 'Choose what it’s about.';
  if (aboutOrder(m.topic) && m.order.trim() && !/^[A-Z]-?\d{4,}$/i.test(m.order.trim())) out.order = 'Enter the order number as it is on your receipt, like A-10432.';
  if (m.message.trim().length < 10) out.message = m.message.trim() ? 'Tell us a little more: at least 10 characters.' : 'Enter your message.';
  else if (m.message.length > LIMIT) out.message = `Shorten your message to ${LIMIT} characters.`;
  return out;
}

/** The contact page: a skip link, a header, then main with the h1 and the form, or the answer once sent. */
export function ContactForm({ onSend, replyTime = 'within 2 working days', online }: ContactFormProps) {
  const [m, setM] = React.useState<ContactMessage>(blank);
  const [problems, setProblems] = React.useState<Problems>({});
  const [tries, setTries] = React.useState(0);
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const [sent, setSent] = React.useState<{ reference: string; email: string } | null>(null);
  const answer = React.useRef<HTMLHeadingElement>(null);
  const edit = (patch: Partial<ContactMessage>) => { setM((now) => ({ ...now, ...patch })); setFailed(false); };
  const errors: ErrorSummaryItem[] = FIELDS.filter((f) => problems[f]).map((f) => ({ field: `contact-${f}`, message: problems[f] }));

  const send = (e: React.FormEvent) => {
    e.preventDefault();
    setFailed(false);
    const found = contactProblems(m);
    setProblems(found);
    setTries((t) => t + 1);
    if (Object.keys(found).length) return;
    const out: ContactMessage = { ...m, name: m.name.trim(), email: m.email.trim(), order: aboutOrder(m.topic) ? m.order.trim().toUpperCase() : '', message: m.message.trim() };
    setBusy(true);
    void Promise.resolve().then(() => onSend?.(out)).then((ref) => setSent({ reference: typeof ref === 'string' ? ref : '', email: out.email }), () => setFailed(true))
      .finally(() => setBusy(false));
  };
  React.useEffect(() => { if (sent) answer.current?.focus(); }, [sent]);

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
        <Link underline="hover" href="#help">Help center</Link>
      </header>
      <Container as="main" size="prose" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">Your message stays here. Sending it needs a connection.</OfflineBanner>
          <PageHeader title="Contact us" description={`We read every message and reply ${replyTime}. All fields are needed unless they say they’re optional.`} />
          <div className="pt-6">
            {sent ? (
              <section aria-labelledby="sent" className="flex flex-col items-start gap-3">
                <h2 id="sent" ref={answer} tabIndex={-1} className="m-0 text-2xl font-semibold outline-none">Message sent</h2>
                <p className="m-0">We’ll reply to {sent.email} {replyTime}.{m.copy ? ' A copy of your message is on its way there too.' : ''}</p>
                {sent.reference ? <p className="m-0">Your reference is <strong>{sent.reference}</strong>. Give it if you write again about this.</p> : null}
                <Link href="#help">Back to the help center</Link>
              </section>
            ) : (
              <form onSubmit={send} noValidate aria-label="Contact us" className="flex flex-col gap-4">
                <ErrorSummary key={tries} errors={errors} />
                <p className="m-0 text-text-muted">Fields marked * are required.</p>
                <Field label="Name" id="contact-name" error={problems.name} required>
                  <Input autoComplete="name" value={m.name} onChange={(e) => edit({ name: e.target.value })} />
                </Field>
                <Field label="Email" id="contact-email" hint="We only use it to reply." error={problems.email} required>
                  <Input type="email" autoComplete="email" value={m.email} onChange={(e) => edit({ email: e.target.value })} />
                </Field>
                <Field label="What’s it about?" id="contact-topic" error={problems.topic} required>
                  <CascadeSelect aria-label="What’s it about?" placeholder="Choose a topic" levels={['Kind', 'About']} options={TOPICS} value={m.topic ? m.topic.split('/') : []} onValueChange={(v) => edit({ topic: v.join('/') })} />
                </Field>
                {aboutOrder(m.topic) ? (
                  <Field label="Order number" id="contact-order" hint="On your receipt and order email, like A-10432." error={problems.order} optional>
                    <Input autoComplete="off" spellCheck={false} value={m.order} onChange={(e) => edit({ order: e.target.value })} className="max-w-48" />
                  </Field>
                ) : null}
                <Field label="Message" id="contact-message" hint={`Up to ${LIMIT} characters.`} error={problems.message} required>
                  <Textarea rows={6} maxLength={LIMIT} showCount value={m.message} onChange={(e) => edit({ message: e.target.value })} />
                </Field>
                <Checkbox checked={m.copy} onCheckedChange={(on) => edit({ copy: on })}>Send me a copy</Checkbox>
                <div className="flex flex-col items-start gap-3">
                  {failed ? <Alert tone="danger">Couldn’t send your message. Try again; everything you wrote is still here.</Alert> : null}
                  <Button type="submit" loading={busy}>Send message</Button>
                </div>
              </form>
            )}
          </div>
        </Stack>
      </Container>
    </div>
  );
}

files.CourseOverview.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Accordion, AccordionItem } from '@diki-stwn/serupa-ds';
import { Avatar } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Checkbox } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Progress } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { announce } from '@diki-stwn/serupa-ds';
import { EmptyLoadFailed } from './EmptyStates';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { Duration } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Course overview: a course's modules and lessons, how far you are, where to carry on, and marking lessons done.
   For an app to copy. What it carries (WCAG 2.2):
   - 1.3.1, 2.4.6: each module is a heading that opens its lessons, and says how many are done; the lessons are an
     ordered list, each a link with how long it takes.
   - 1.3.1, 4.1.3: progress is a progress bar named "Course progress", its value in words ("4 of 12 lessons"),
     and a change to it is said.
   - 2.4.4: Continue names the lesson it opens; once every lesson is done, it's the certificate instead.
   - 4.1.2: each lesson's Done box is named by the lesson ("Done: Kerning").
   - 2.4.3: the module with the next lesson starts open, so its lessons are where Tab goes.
   Saving progress is the app's job: onDoneChange gets the lesson and whether it's done. */

export interface Lesson { id: string; title: string; minutes: number }
export interface CourseModule { id: string; title: string; lessons: Lesson[] }

export interface CourseOverviewProps {
  title?: string | undefined;
  description?: string | undefined;
  teacher?: string | undefined;
  modules?: CourseModule[] | undefined;
  /** The ids of the lessons done so far. */
  defaultDone?: string[] | undefined;
  /** Saves a lesson as done or not. */
  onDoneChange?: ((lessonId: string, done: boolean) => void) | undefined;
  /** The lessons are still loading: a placeholder in their place. Default: false. */
  loading?: boolean | undefined;
  /** The lessons failed to load: a "Couldn’t load the course" message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads them again, from Try again. Return a promise: the button shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demoModules: CourseModule[] = [
  { id: 'm1', title: 'Seeing type', lessons: [
    { id: 'l1', title: 'Welcome, and what you need', minutes: 4 },
    { id: 'l2', title: 'Anatomy of a letter', minutes: 12 },
    { id: 'l3', title: 'Serif, sans and the rest', minutes: 15 },
  ] },
  { id: 'm2', title: 'Setting text', lessons: [
    { id: 'l4', title: 'Size and line length', minutes: 18 },
    { id: 'l5', title: 'Leading', minutes: 10 },
    { id: 'l6', title: 'Kerning and tracking', minutes: 14 },
    { id: 'l7', title: 'Practice: a page of a book', minutes: 45 },
  ] },
  { id: 'm3', title: 'Pairing and hierarchy', lessons: [
    { id: 'l8', title: 'Pairing two typefaces', minutes: 16 },
    { id: 'l9', title: 'Headings that lead', minutes: 13 },
    { id: 'l10', title: 'Final project: a poster', minutes: 90 },
  ] },
];

/** How many lessons are done of how many, and the first one not done (null when every one is). */
export function courseProgress(modules: CourseModule[], done: string[]) {
  const all = modules.flatMap((m) => m.lessons);
  const next = all.find((l) => !done.includes(l.id)) ?? null;
  return { done: all.filter((l) => done.includes(l.id)).length, total: all.length, next, nextModule: modules.find((m) => m.lessons.includes(next!))?.id ?? null };
}

/** The course page: a skip link, a header, then main with the h1, progress, Continue, and the modules. */
export function CourseOverview({ title = 'Typography for the screen', description = 'Choose, set and pair type so that it reads well on any screen.',
  teacher = 'Lena Vogel', modules = demoModules, defaultDone = ['l1', 'l2', 'l3', 'l4'], onDoneChange, loading = false, loadFailed = false, onRetry, online }: CourseOverviewProps) {
  const locale = useLocale();
  const num = (n: number) => formatNumber(n, locale);
  const [done, setDone] = React.useState(defaultDone);
  const p = courseProgress(modules, done);
  const [open, setOpen] = React.useState<string[]>(p.nextModule ? [p.nextModule] : []);
  const total = <Duration value={modules.flatMap((m) => m.lessons).reduce((a, l) => a + l.minutes, 0)} unit="minute" />;
  const lessonsWords = (d: number, t: number) => `${num(d)} of ${num(t)} lessons`;

  const mark = (id: string, on: boolean) => {
    const next = on ? [...done, id] : done.filter((d) => d !== id);
    setDone(next);
    onDoneChange?.(id, on);
    const after = courseProgress(modules, next);
    announce(after.next ? `${lessonsWords(after.done, after.total)} done.` : 'Every lesson done. Your certificate is ready.');
  };

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
        <Link underline="hover" href="#courses">Your courses</Link>
      </header>
      <Container as="main" size="md" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">This is your progress as it was when the page loaded. Lessons need a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Your courses', href: '#courses' }, { label: title }]} title={title} description={description} />
          {loadFailed ? <div className="pt-6"><EmptyLoadFailed title="Couldn’t load the course" onRetry={() => onRetry?.()} headingLevel={2} /></div>
            : loading ? <Card className="mt-6"><Skeleton shape="text" lines={6} label="Loading the course" /></Card> : (<>
          <div className="flex flex-col gap-6 pt-6">
            <p className="m-0 flex flex-wrap items-center gap-2 text-text-muted">
              <Avatar name={teacher} alt="" size="sm" />
              <span>With {teacher} · {num(p.total)} lessons · {total} in all</span>
            </p>
            <Card className="flex flex-col gap-4">
              <Progress label="Course progress" value={p.done} max={p.total} showValue tone={p.next ? 'primary' : 'success'}
                formatValue={(v, m) => lessonsWords(v, m)} />
              {p.next ? (
                <div className="flex flex-wrap items-center justify-between gap-3">
                  <p className="m-0"><span className="block text-sm text-text-muted">Up next</span><span className="font-semibold">{p.next.title}</span></p>
                  <Button href={`#lesson-${p.next.id}`} aria-label={`Continue: ${p.next.title}`}>Continue</Button>
                </div>
              ) : (
                <div className="flex flex-wrap items-center justify-between gap-3">
                  <p className="m-0 font-semibold">You’ve finished every lesson.</p>
                  <Button href="#certificate">Get your certificate</Button>
                </div>
              )}
            </Card>
            <Accordion selectionMode="multiple" value={open} onValueChange={setOpen} headingLevel={2} variant="card">
              {modules.map((m, mi) => {
                const d = m.lessons.filter((l) => done.includes(l.id)).length;
                return (
                  <AccordionItem key={m.id} value={m.id} title={<span className="flex flex-wrap items-baseline gap-x-3">
                    <span>{num(mi + 1)}. {m.title}</span>
                    <span className="text-sm font-normal text-text-muted">{d === m.lessons.length ? 'Done' : lessonsWords(d, m.lessons.length)}</span>
                  </span>}>
                    <ol className="m-0 flex list-none flex-col gap-3 pt-2">
                      {m.lessons.map((l) => (
                        <li key={l.id} className="flex flex-wrap items-center justify-between gap-3">
                          <span className="min-w-0">
                            <Link href={`#lesson-${l.id}`}>{l.title}</Link>
                            <span className="block text-sm text-text-muted"><Duration value={l.minutes} unit="minute" />{l.id === p.next?.id ? ' · Up next' : ''}</span>
                          </span>
                          <Checkbox aria-label={`Done: ${l.title}`} checked={done.includes(l.id)} onCheckedChange={(on) => mark(l.id, on)}>Done</Checkbox>
                        </li>
                      ))}
                    </ol>
                  </AccordionItem>
                );
              })}
            </Accordion>
          </div>
          </>)}
        </Stack>
      </Container>
    </div>
  );
}

files.Dashboard.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Badge, type BadgeTone } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { Meter } from '@diki-stwn/serupa-ds';
import { Progress } from '@diki-stwn/serupa-ds';
import { Chart } from '@diki-stwn/serupa-ds';
import { Table, TableBody, TableCell, TableHead, TableHeaderCell, TableRow } from '@diki-stwn/serupa-ds';
import { StatsRow, type Stat } from './StatsRow';
import { ActivityFeed, type ActivityEvent } from './ActivityFeed';
import { EmptyFirstRun, EmptyLoadFailed } from './EmptyStates';
import { useLocale } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { FabMenu } from '@diki-stwn/serupa-ds';
import { formatDate } from '@diki-stwn/serupa-ds';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Dashboard: the page an account lands on. Key numbers, how much of the plan is used, the latest projects and what
   the team did, with skeletons while it loads and a first-run state before there's anything to show. For an app to
   copy. What it carries (WCAG 2.2):
   - 1.3.1: each part is a region named by its h2 (the numbers, Usage, Recent projects, Activity), so a screen reader
     can list them and jump to one. The numbers and the projects are a list and a table, not boxes of text.
   - 1.4.1: a change says "Up 12%" or "Down 3%" in words with its arrow (StatsRow); the storage meter says "almost
     full" in words when it turns amber, not by color alone.
   - 4.1.3: while the page loads, main says it's busy (aria-busy) and each part has one named skeleton, so a screen
     reader hears "Loading" once per part, not once per grey bar. Nothing moves focus when the data arrives.
   - 2.4.4: "All projects" and each project's name are links that say where they go.
   - 1.4.10: the parts stack in one column on a phone; the table scrolls inside its own box rather than the page.
   - First run: with no projects yet, the page says so and offers the one button that starts one, instead of a row of
     zeros and empty boxes.
   Fetching the numbers, and what each one counts, is the app's job: pass them as `data`, or `loading` until then. */

export interface RecentProject {
  name: string; href: string; status: string; updated: string;
  /** The status badge's color: 'success' for running work, 'warning' for paused, 'neutral' (default) for the rest. Say the status in words too. */
  statusTone?: BadgeTone | undefined;
}
export interface DashboardData {
  /** The key numbers, two to four (StatsRow). */
  stats: readonly Stat[];
  /** Tasks opened and done each week, oldest first, for the chart. Leave it out and the chart isn't shown. */
  weekly?: { weeks: readonly string[]; opened: readonly (number | null)[]; done: readonly (number | null)[] } | undefined;
  /** Storage used and the plan's limit, in GB. */
  storage: { used: number; limit: number };
  /** A goal for the period: "Launch checklist", 3 of 5 done. */
  goal: { label: string; done: number; total: number };
  /** The latest projects, newest first: five is plenty. */
  projects: readonly RecentProject[];
  /** What the team did, newest first. */
  activity: readonly ActivityEvent[];
}

export interface DashboardProps {
  /** What the page shows. Default: a demo account. */
  data?: DashboardData | undefined;
  /** Shows skeletons in place of each part until the data arrives. */
  loading?: boolean | undefined;
  /** The numbers failed to load: a "Couldn’t load" message with Try again, which calls onRetry, in their place. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** The person's name, for the greeting. */
  name?: string | undefined;
  /** "New project" was pressed: in the header, or the first-run state. */
  onCreateProject?: (() => void) | undefined;
  /** "Invite someone" was picked in the Create button, on a phone. */
  onInvite?: (() => void) | undefined;
  /** "Upload a file" was picked in the Create button, on a phone. */
  onUpload?: (() => void) | undefined;
  /** Loads more activity. Return its promise, so the button shows it's busy. Without it, the demo pages through `data`. */
  onLoadMoreActivity?: (() => PromiseLike<unknown>) | undefined;
  /** With `onLoadMoreActivity`: false after the last page. */
  hasMoreActivity?: boolean | undefined;
  /** The rest loaded but the activity didn't: its card says so, with Try again, which calls onRetry. Default: false. */
  activityFailed?: boolean | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const day = (n: number) => new Date(Date.UTC(2026, 10, 6, 9) - n * 3600_000 * 5).toISOString();
const PEOPLE = ['Ana Lima', 'Budi Santoso', 'Chen Wei', 'Dewi Lestari'];
const demo: DashboardData = {
  stats: [
    { label: 'Active projects', value: '12', change: { amount: '2', direction: 'up' } },
    { label: 'Tasks done', value: '148', change: { amount: '12%', direction: 'up' }, trend: [96, 110, 104, 121, 132, 148] },
    { label: 'Open issues', value: '23', change: { amount: '3%', direction: 'down', good: true } },
    { label: 'Spend', value: '$3,240', change: { amount: '8%', direction: 'up', good: false } },
  ],
  weekly: { weeks: ['Oct 5', 'Oct 12', 'Oct 19', 'Oct 26', 'Nov 2', 'Nov 9'], opened: [30, 34, 28, 36, 31, 38], done: [24, 29, 31, 30, 35, 40] },
  storage: { used: 8.6, limit: 10 },
  goal: { label: 'Launch checklist', done: 3, total: 5 },
  projects: [
    { name: 'Website redesign', href: '#website-redesign', status: 'Active', updated: '2026-11-06', statusTone: 'success' },
    { name: 'Billing migration', href: '#billing-migration', status: 'Active', updated: '2026-11-05', statusTone: 'success' },
    { name: 'Help center', href: '#help-center', status: 'Paused', updated: '2026-11-03', statusTone: 'warning' },
    { name: 'Mobile app', href: '#mobile-app', status: 'Active', updated: '2026-11-02', statusTone: 'success' },
    { name: 'Data export', href: '#data-export', status: 'Done', updated: '2026-10-30' },
  ],
  activity: ([
    ['commented on', 'Website redesign'], ['closed', 'Issue 214'], ['created', 'Billing migration'], ['uploaded 3 files to', 'Help center'],
    ['invited Dewi Lestari to', 'Mobile app'], ['moved to Done', 'Data export'], ['commented on', 'Billing migration'], ['reopened', 'Issue 198'],
    ['renamed', 'Help center'], ['archived', 'Old brand kit'],
  ] satisfies Array<[string, string]>).map(([action, target], i) => ({
    id: `e${i}`, actor: { name: PEOPLE[i % 4] ?? '' }, action, target: { label: target, href: `#${target.toLowerCase().replace(/\s+/g, '-')}` }, date: day(i),
  })),
};

// "6 Nov 2026" in the reader's locale for "2026-11-06", read as that calendar day wherever the reader is; anything
// else as it came. The <time> keeps the ISO day in dateTime.
function shortDay(iso: string, locale: string): string {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);
  if (!m) return iso;
  return formatDate(iso, locale) || iso;
}

const PAGE = 4;
// In the provider's locale, as the days are, so the server's render and the browser's agree.
const gb = (n: number, locale: string) => `${n.toLocaleString(locale, { maximumFractionDigits: 1 })} GB`;

/** The dashboard page: a skip link, a header, then main with the h1 and its parts. */
export function Dashboard({ data = demo, loading = false, loadFailed = false, onRetry, name = 'Ana', onCreateProject, onInvite, onUpload, onLoadMoreActivity, hasMoreActivity = false, activityFailed = false, online }: DashboardProps) {
  const locale = useLocale();
  const [shown, setShown] = React.useState(PAGE);
  const firstRun = !loading && !loadFailed && data.projects.length === 0;
  const events = onLoadMoreActivity ? data.activity : data.activity.slice(0, shown);
  const more = () => (onLoadMoreActivity ? onLoadMoreActivity() : Promise.resolve().then(() => setShown((n) => n + PAGE)));
  const { used, limit } = data.storage;

  return (
    <div className="min-h-screen bg-surface-sunken text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <Container as="main" size="xl" className="py-8 outline-none" id="main" aria-busy={loading || undefined}>
        <Stack gap={6}>
          <OfflineBanner online={online} placement="inline">These numbers are from when the page loaded. They update when you’re back.</OfflineBanner>
          <PageHeader title={`Good morning, ${name}`} primary={firstRun ? undefined : { label: 'New project', onSelect: () => onCreateProject?.() }} />
          {/* On a phone, Create sits under the thumb: a FabMenu with what people start from here. From md up, New project
              is in the header and the rest are on their own pages, so it hides. */}
          {firstRun || loading || loadFailed ? null : (
            <FabMenu label="Create" icon="add" extended className="md:hidden" actions={[
              { label: 'New project', icon: 'create_new_folder', onSelect: () => onCreateProject?.() },
              { label: 'Invite someone', icon: 'person_add', onSelect: () => onInvite?.() },
              { label: 'Upload a file', icon: 'upload', onSelect: () => onUpload?.() },
            ]} />
          )}

          {loadFailed ? (
            <Card>
              <EmptyLoadFailed title="Couldn’t load your dashboard" onRetry={() => onRetry?.()} headingLevel={2} />
            </Card>
          ) : firstRun ? (
            <Card>
              <EmptyFirstRun title="No projects yet" headingLevel={2} createLabel="New project" onCreate={() => onCreateProject?.()}
                description="A project holds the tasks, files and people for one piece of work. Start one, and its numbers show up here."
                learnHref="#guide" learnLabel="How projects work" />
            </Card>
          ) : (
            <>
              <StatsRow title="This month" period="vs last month" stats={data.stats} loading={loading} />

              {data.weekly || loading ? (
                <section aria-labelledby="dash-weekly" className="flex min-w-0 flex-col gap-4">
                  <Heading level={2} size="lg" id="dash-weekly">Tasks each week</Heading>
                  <Card>
                    <Chart aria-label="Tasks each week" type="bar" height={200} categoryLabel="Week" loading={loading} loadingLabel="Loading: Tasks each week"
                      categories={loading ? [] : [...(data.weekly?.weeks ?? [])]}
                      series={loading ? [] : [{ name: 'Opened', values: [...(data.weekly?.opened ?? [])] }, { name: 'Done', values: [...(data.weekly?.done ?? [])] }]} />
                  </Card>
                </section>
              ) : null}

              <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
                <section aria-labelledby="dash-projects" className="flex min-w-0 flex-col gap-4 lg:col-span-2">
                  <div className="flex flex-wrap items-baseline justify-between gap-3">
                    <Heading level={2} size="lg" id="dash-projects">Recent projects</Heading>
                    <Link href="#projects">All projects</Link>
                  </div>
                  <Card padding="none" className="min-w-0 overflow-x-auto">
                    {loading ? (
                      <div className="p-4"><Skeleton shape="text" lines={5} label="Loading: Recent projects" /></div>
                    ) : (
                      <Table caption="Recent projects" hideCaption>
                        <TableHead><TableRow>
                          <TableHeaderCell>Name</TableHeaderCell><TableHeaderCell>Status</TableHeaderCell><TableHeaderCell>Updated</TableHeaderCell>
                        </TableRow></TableHead>
                        <TableBody>{data.projects.map((p) => (
                          <TableRow key={p.href}>
                            <TableCell><Link href={p.href}>{p.name}</Link></TableCell>
                            <TableCell><Badge dot tone={p.statusTone ?? 'neutral'}>{p.status}</Badge></TableCell>
                            <TableCell className="whitespace-nowrap"><time dateTime={p.updated}>{shortDay(p.updated, locale)}</time></TableCell>
                          </TableRow>
                        ))}</TableBody>
                      </Table>
                    )}
                  </Card>
                </section>

                <section aria-labelledby="dash-usage" className="flex min-w-0 flex-col gap-4">
                  <Heading level={2} size="lg" id="dash-usage">Usage</Heading>
                  <Card className="flex flex-col gap-4">
                    {loading ? <Skeleton shape="text" lines={4} label="Loading: Usage" /> : (
                      <>
                        <Meter label="Storage" showValue value={used} max={limit} high={limit * 0.8} optimum={0}
                          formatValue={(v, _, max) => `${gb(v, locale)} of ${gb(max, locale)}${v >= max * 0.8 ? ', almost full' : ''}`} />
                        <Progress label={data.goal.label} showValue value={data.goal.done} max={data.goal.total}
                          formatValue={(v, max) => `${v} of ${max} done`} />
                        <Link href="#billing">Change plan</Link>
                      </>
                    )}
                  </Card>
                </section>
              </div>

              {/* One shape loading and loaded, so the heading doesn't jump when the events arrive: the feed's own
                  skeleton rows (an avatar and two lines) stand in for the events. */}
              {activityFailed && !loading ? (
                <Card>
                  <section aria-labelledby="dash-activity" className="flex flex-col gap-4">
                    <Heading level={2} size="lg" id="dash-activity">Activity</Heading>
                    <EmptyLoadFailed size="sm" headingLevel={3} title="Couldn’t load the activity" description="The rest of the dashboard is up to date." onRetry={() => onRetry?.()} />
                  </section>
                </Card>
              ) : <Card>
                <ActivityFeed events={events} loading={loading} headingSize="lg" onLoadMore={more} total={onLoadMoreActivity ? undefined : data.activity.length}
                  hasMore={onLoadMoreActivity ? hasMoreActivity : shown < data.activity.length} />
              </Card>}
            </>
          )}
        </Stack>
      </Container>
    </div>
  );
}

files.DataExport.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Checkbox, CheckboxGroup } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { RadioGroup, Radio } from '@diki-stwn/serupa-ds';
import { ErrorSummary, type ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { EmptyLoadFailed } from './EmptyStates';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { formatDate } from '@diki-stwn/serupa-ds';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Download your data: choose what to include and in which format, see how big it will be, ask for it, and download
   it once it's ready, before its link runs out. For an app to copy. What it carries (WCAG 2.2):
   - 1.3.1: what to include is a group of checkboxes named by its question, with one that picks them all; each says
     what it holds and how big it is, as its description.
   - 3.3.2, 4.1.3: the size of what's chosen is said as it changes, and the format says what each opens in.
   - 3.3.1, 2.4.3: asking with nothing chosen shows a summary at the top that takes focus, linked to the group.
   - 3.3.4, 4.1.3: Ask shows it's busy; a request that can't be taken says so and keeps the choices.
   - 2.4.3, 4.1.3: once asked, the exports heading takes focus and the new export says it's being prepared.
   - 1.4.1: each export's state is a word (Preparing, Ready, Expired), never only a color; a ready one's link names
     its date and size, and says when it stops working.
   Making the file is the app's job: onRequest gets the request; reject when it can't be taken. */

export interface DataPart { id: string; label: string; holds: string; bytes: number }
export type ExportFormat = 'json' | 'csv';
export interface PastExport { id: string; asked: string; parts: string[]; format: ExportFormat; bytes: number; state: 'preparing' | 'ready' | 'expired'; expires?: string | undefined; href?: string | undefined }
export interface ExportRequest { parts: string[]; format: ExportFormat }

export interface DataExportProps {
  /** What can be included, each with what it holds and its size in bytes. */
  parts?: DataPart[] | undefined;
  /** Exports asked for before, newest first. */
  exports?: PastExport[] | undefined;
  /** Today, as YYYY-MM-DD: the date a new request is marked with. Default: today. */
  today?: string | undefined;
  /** Takes the request. Reject when it can't be taken. */
  onRequest?: ((request: ExportRequest) => unknown) | undefined;
  /** Your past exports are still loading: a placeholder in their place. Default: false. */
  loading?: boolean | undefined;
  /** Your past exports failed to load: a "Couldn’t load your exports" message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads them again, from Try again. Return a promise: the button shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demoParts: DataPart[] = [
  { id: 'profile', label: 'Profile and settings', holds: 'Your name, email, preferences and sign-in history', bytes: 240_000 },
  { id: 'projects', label: 'Projects', holds: 'Every project, its tasks and comments', bytes: 18_400_000 },
  { id: 'files', label: 'Files', holds: 'Everything you uploaded, in its own format', bytes: 1_320_000_000 },
  { id: 'messages', label: 'Messages', holds: 'Your conversations and their attachments', bytes: 86_000_000 },
];
const demoExports: PastExport[] = [
  { id: 'e2', asked: '2026-11-12', parts: ['profile', 'projects'], format: 'json', bytes: 18_640_000, state: 'ready', expires: '2026-11-19', href: '#export-e2' },
  { id: 'e1', asked: '2026-09-02', parts: ['profile', 'projects', 'files', 'messages'], format: 'csv', bytes: 1_380_000_000, state: 'expired' },
];
const FORMATS: { value: ExportFormat; label: string; opens: string }[] = [
  { value: 'json', label: 'JSON', opens: 'For moving to another app, or for developers' },
  { value: 'csv', label: 'CSV', opens: 'Opens in a spreadsheet, such as Excel or Numbers' },
];
const STATE = { preparing: { word: 'Preparing', tone: 'info' }, ready: { word: 'Ready', tone: 'success' }, expired: { word: 'Expired', tone: 'neutral' } } as const;

/** How big the chosen parts are together, in bytes. */
export function exportSize(parts: DataPart[], chosen: string[]) {
  return parts.filter((p) => chosen.includes(p.id)).reduce((sum, p) => sum + p.bytes, 0);
}

/** A size in the largest unit that keeps it at 1 or more, in the locale's words: "240 kB", "1.3 GB". */
export function sizeWords(bytes: number, locale?: string) {
  const units = ['byte', 'kilobyte', 'megabyte', 'gigabyte'] as const;
  let i = 0;
  let n = bytes;
  // Whole numbers of a unit (999,950 bytes rounds to 1,000 kB), so one that rounds to 1,000 is 1 of the next.
  while (Math.round(n) >= 1000 && i < units.length - 1) { n /= 1000; i++; }
  return formatNumber(n, locale, { style: 'unit', unit: units[i], unitDisplay: 'short', maximumFractionDigits: n < 10 && i ? 1 : 0 });
}

/** The page: a skip link, a header, then main with the h1, the choices, and the exports asked for before. */
export function DataExport({ parts = demoParts, exports = demoExports, today, onRequest, loading = false, loadFailed = false, onRetry, online }: DataExportProps) {
  const locale = useLocale();
  const day = (iso: string) => formatDate(iso, locale, { dateStyle: 'long' });
  const size = (b: number) => sizeWords(b, locale);
  const [chosen, setChosen] = React.useState<string[]>(parts.map((p) => p.id));
  const [format, setFormat] = React.useState<ExportFormat>('json');
  const [problem, setProblem] = React.useState('');
  const [tries, setTries] = React.useState(0);
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const [list, setList] = React.useState(exports);
  // What the app passes once loading ends replaces what was there, which was empty or the demo.
  const [wasLoading, setWasLoading] = React.useState(loading);
  if (wasLoading !== loading) { setWasLoading(loading); if (!loading) { setList(exports); } }
  const [asked, setAsked] = React.useState(0);
  const listHeading = React.useRef<HTMLHeadingElement>(null);
  const total = exportSize(parts, chosen);
  const errors: ErrorSummaryItem[] = problem ? [{ field: 'export-parts', message: problem }] : [];
  const labelOf = (id: string) => parts.find((p) => p.id === id)?.label ?? id;

  const request = (e: React.FormEvent) => {
    e.preventDefault();
    setFailed(false);
    const found = chosen.length ? '' : 'Choose at least one thing to include.';
    setProblem(found);
    setTries((t) => t + 1);
    if (found) return;
    setBusy(true);
    const req: ExportRequest = { parts: chosen, format };
    void Promise.resolve().then(() => onRequest?.(req)).then(() => {
      const on = today ?? new Date().toISOString().slice(0, 10);
      setList((now) => [{ id: `new-${now.length}`, asked: on, parts: chosen, format, bytes: total, state: 'preparing' }, ...now]);
      setAsked((n) => n + 1);
    }, () => setFailed(true)).finally(() => setBusy(false));
  };
  React.useEffect(() => { if (asked) listHeading.current?.focus(); }, [asked]);

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme Projects</p>
        <Link underline="hover" href="#settings">Settings</Link>
      </header>
      <Container as="main" size="prose" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">This is what was loaded before you went offline. Requesting an export needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Settings', href: '#settings' }, { label: 'Download your data' }]} title="Download your data"
            description="Get a copy of what you’ve put in Acme Projects. We’ll email you when it’s ready, and the link works for 7 days." />
          {loadFailed ? <div className="pt-6"><EmptyLoadFailed title="Couldn’t load your exports" onRetry={() => onRetry?.()} headingLevel={2} /></div>
            : loading ? <Card className="mt-6"><Skeleton shape="text" lines={6} label="Loading your exports" /></Card> : (<>
          <form onSubmit={request} noValidate aria-label="What to download" className="flex flex-col gap-4 pt-6">
            <ErrorSummary key={tries} errors={errors} />
            <p className="m-0 text-text-muted">Fields marked * are required.</p>
            <Field label="What should it include?" group error={problem || undefined} required>
              <CheckboxGroup id="export-parts" variant="card" value={chosen} onValueChange={(v: string[]) => { setChosen(v); setProblem(''); setFailed(false); }}>
                <Checkbox selectAll>Everything</Checkbox>
                {parts.map((p) => <Checkbox key={p.id} value={p.id} description={`${p.holds}. About ${size(p.bytes)}.`}>{p.label}</Checkbox>)}
              </CheckboxGroup>
            </Field>
            <Field label="Format" group>
              <RadioGroup name="export-format" value={format} onValueChange={(v: string) => setFormat(v as ExportFormat)}>
                {FORMATS.map((f) => <Radio key={f.value} value={f.value} description={f.opens}>{f.label}</Radio>)}
              </RadioGroup>
            </Field>
            <Card padding="sm" variant="filled">
              <p className="m-0" aria-live="polite" id="export-size">
                {chosen.length ? <>Your download will be about <strong>{size(total)}</strong>.</> : 'Choose what to include to see its size.'}
              </p>
            </Card>
            <div className="flex flex-col items-start gap-3">
              {failed ? <Alert tone="danger">Couldn’t ask for your data. Try again; your choices are still here.</Alert> : null}
              <Button type="submit" loading={busy}>Ask for my data</Button>
            </div>
          </form>
          <section aria-labelledby="export-list" className="flex flex-col gap-4 pt-6">
            <h2 id="export-list" ref={listHeading} tabIndex={-1} className="m-0 text-lg font-semibold outline-none">Your exports</h2>
            {asked ? <p role="status" id="export-asked" className="m-0">We’re preparing your data. We’ll email you when it’s ready to download.</p> : null}
            {list.length ? (
              <ul className="m-0 flex list-none flex-col gap-3 p-0">
                {list.map((x) => (
                  <li key={x.id}>
                    <Card padding="sm" className="flex-row flex-wrap items-start justify-between gap-3">
                      <div className="flex min-w-0 flex-col gap-1">
                        <p className="m-0 font-semibold">Asked for on {day(x.asked)}</p>
                        <p className="m-0 text-sm text-text-muted">{x.parts.map(labelOf).join(', ')}. {x.format.toUpperCase()}, about {size(x.bytes)}.</p>
                        {x.state === 'ready' && x.expires ? <p className="m-0 text-sm">The link works until {day(x.expires)}.</p> : null}
                        {x.state === 'expired' ? <p className="m-0 text-sm">Its link has run out. Ask again to get a new one.</p> : null}
                      </div>
                      <div className="flex flex-wrap items-center gap-3">
                        <Badge tone={STATE[x.state].tone}>{STATE[x.state].word}</Badge>
                        {x.state === 'ready' && x.href ? (
                          <Button href={x.href} variant="outline" size="sm" aria-label={`Download export of ${day(x.asked)}, ${size(x.bytes)}`}>Download</Button>
                        ) : null}
                      </div>
                    </Card>
                  </li>
                ))}
              </ul>
            ) : <p className="m-0 text-text-muted">You haven’t asked for your data yet.</p>}
          </section>
          </>)}
        </Stack>
      </Container>
    </div>
  );
}

files.DataImport.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Select } from '@diki-stwn/serupa-ds';
import { FileUpload } from '@diki-stwn/serupa-ds';
import { withViewTransition } from '@diki-stwn/serupa-ds';
import { Stepper } from '@diki-stwn/serupa-ds';
import { Checkbox } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { ErrorSummary, type ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import { Table, TableBody, TableCell, TableHead, TableHeaderCell, TableRow } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Data import: a CSV file of customers, its columns matched to the app's fields, every row checked and shown before
   anything is saved, then what happened in words. For an app to copy. What it carries (WCAG 2.2):
   - 3.3.4: nothing is saved until the last step's button, which says how many rows it saves. The check step lists
     each row's problems first, and rows with problems are skipped only when that's chosen.
   - 3.3.1, 3.3.3: a file that can't be read, a field left unmatched or a column used twice shows an ErrorSummary
     that takes focus and links to the control, each saying what to do.
   - 1.3.1, 1.4.1: the preview is a table with column headers; a row's problem is a Badge with its words and the
     message in its own column, never only a color.
   - 2.4.3, 4.1.3: each new step puts focus on its heading, so the change is said and Tab goes on from there; the
     Stepper above says which step this is in words.
   - 3.3.7: Back keeps the file and the matches, so nothing is chosen twice.
   Motion (the Motion foundation's "Layout changes"): the next step slides in from the end and Back brings the one
   before in from the start, mirrored right to left, so the way through reads as a direction. Under reduced motion
   the steps crossfade; where View Transitions are missing they swap at once.
   Saving the rows is the app's job: onImport stands in for it, and `existing` for the app's own records. */

export interface ImportField { key: 'name' | 'email' | 'phone' | 'city'; label: string; required: boolean }
export const FIELDS: ImportField[] = [
  { key: 'name', label: 'Name', required: true },
  { key: 'email', label: 'Email', required: true },
  { key: 'phone', label: 'Phone', required: false },
  { key: 'city', label: 'City', required: false },
];
export type ImportRow = Record<ImportField['key'], string>;
/** For each field, the index of the file's column that fills it, or -1 for none. */
export type ImportMapping = Record<ImportField['key'], number>;
export interface CheckedRow { line: number; row: ImportRow; problems: string[]; update: boolean }
export type DataImportStep = 'upload' | 'match' | 'check' | 'done';

export interface DataImportProps {
  /** The step it starts on, with `file`. Default: 'upload'. */
  start?: DataImportStep | undefined;
  /** A file already chosen: its name and text. */
  file?: { name: string; text: string } | undefined;
  /** Emails of the customers the app already has: a row with one of them updates that customer. */
  existing?: string[] | undefined;
  /** Saves the rows. A rejected promise keeps the check step, with "Couldn't import" and Try again. */
  onImport?: ((rows: ImportRow[]) => unknown) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

/** The rows of a CSV file: commas between cells, a line break between rows, "quoted" cells holding commas, line
    breaks and "" for a quote. Empty lines are left out. With lines, it also gets the line of the file each row
    starts on, from 1, which is a row's number past empty lines and cells of more than one line. */
export function parseCsv(text: string, lines?: number[]): string[][] {
  const rows: string[][] = [];
  let row: string[] = [], cell = '', quoted = false, line = 1, from = 1;
  const s = text.replace(/^\uFEFF/, '');
  const keep = () => { row.push(cell); cell = ''; if (row.some((c) => c.trim())) { rows.push(row); lines?.push(from); } row = []; };
  for (let i = 0; i < s.length; i++) {
    const ch = s[i]!, br = ch === '\n' || ch === '\r', crlf = ch === '\r' && s[i + 1] === '\n';
    if (br) { line++; if (crlf) i++; }
    if (quoted) {
      if (ch === '"' && s[i + 1] === '"') { cell += '"'; i++; }
      else if (ch === '"') quoted = false;
      else cell += crlf ? '\r\n' : ch;
    } else if (ch === '"' && !cell) quoted = true;
    else if (ch === ',') { row.push(cell); cell = ''; }
    else if (br) { keep(); from = line; }
    else cell += ch;
  }
  keep();
  return rows;
}

const norm = (x: string) => x.toLowerCase().replace(/[^a-z]/g, '');
const SAME: Record<ImportField['key'], string[]> = { name: ['name', 'fullname', 'customer', 'nama'], email: ['email', 'emailaddress', 'mail'], phone: ['phone', 'mobile', 'telephone', 'tel', 'telepon'], city: ['city', 'town', 'kota'] };
/** Matches each field to the column whose heading names it, or -1. */
export function guessMapping(headers: string[]): ImportMapping {
  const out = {} as ImportMapping;
  for (const f of FIELDS) out[f.key] = headers.findIndex((h) => SAME[f.key].includes(norm(h)));
  return out;
}

/** What's wrong with the matches, in the order of the fields. */
export function mappingProblems(m: ImportMapping, headers: string[]): ErrorSummaryItem[] {
  const out: ErrorSummaryItem[] = [];
  for (const f of FIELDS) {
    const col = m[f.key];
    if (col < 0) { if (f.required) out.push({ field: `import-${f.key}`, message: `Choose the column that holds each customer’s ${f.label.toLowerCase()}` }); continue; }
    const first = FIELDS.find((g) => m[g.key] === col);
    if (first && first.key !== f.key) out.push({ field: `import-${f.key}`, message: `Choose another column for ${f.label.toLowerCase()}: “${headers[col]}” is already used for ${first.label.toLowerCase()}` });
  }
  return out;
}

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
/** Each data row as the app's fields, with its problems and whether it updates a customer the app has. lines are
    the file's line of each row (parseCsv gives them); left out, the rows are lines 2 on. */
export function checkRows(data: string[][], m: ImportMapping, existing: string[], lines?: number[]): CheckedRow[] {
  const known = new Set(existing.map((e) => e.toLowerCase()));
  const seen = new Map<string, number>();
  return data.map((cells, i) => {
    const row = {} as ImportRow;
    for (const f of FIELDS) row[f.key] = m[f.key] < 0 ? '' : (cells[m[f.key]] || '').trim();
    const problems: string[] = [];
    if (!row.name) problems.push('No name');
    if (!row.email) problems.push('No email');
    else if (!EMAIL.test(row.email)) problems.push(`“${row.email}” isn’t an email address`);
    else {
      const twice = seen.get(row.email.toLowerCase());
      if (twice) problems.push(`Same email as line ${twice}`);
      else seen.set(row.email.toLowerCase(), lines?.[i] ?? i + 2);
    }
    return { line: lines?.[i] ?? i + 2, row, problems, update: known.has(row.email.toLowerCase()) };
  });
}

// A phone number reads as one piece: it doesn't break at its spaces.
const NOWRAP: Partial<Record<ImportField['key'], string>> = { phone: 'whitespace-nowrap' };
// Phone numbers and email addresses read left to right in every language: isolated, so a right-to-left page doesn't
// reverse their runs ("+62 811 0000 1234" would come out "1234 0000 811 62+").
const LTR: Partial<Record<ImportField['key'], true>> = { phone: true, email: true };
const DEMO_EXISTING = ['ani@example.com', 'budi@example.com'];
const STEPS = [{ title: 'Choose a file' }, { title: 'Match columns' }, { title: 'Check rows' }, { title: 'Done' }];
const ORDER: DataImportStep[] = ['upload', 'match', 'check', 'done'];

/** The import page: a skip link, then main with the Stepper and the step's form. */
export function DataImport({ start = 'upload', file: given, existing = DEMO_EXISTING, onImport, online }: DataImportProps) {
  const locale = useLocale();
  const plural = (n: number, one: string, many: string) => `${formatNumber(n, locale)} ${n === 1 ? one : many}`;
  const [step, setStep] = React.useState<DataImportStep>(given ? start : 'upload');
  const [file, setFile] = React.useState(given);
  const [files, setFiles] = React.useState<File[]>([]);
  const [errors, setErrors] = React.useState<ErrorSummaryItem[]>([]);
  const [tries, setTries] = React.useState(0);
  const [table, lines] = React.useMemo(() => { const l: number[] = []; return [file ? parseCsv(file.text, l) : [], l] as const; }, [file]);
  const headers = table[0] || [];
  const [mapping, setMapping] = React.useState<ImportMapping>(() => guessMapping(headers));
  const [skip, setSkip] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const [result, setResult] = React.useState<{ added: number; updated: number; skipped: number } | null>(null);
  const heading = React.useRef<HTMLHeadingElement>(null);
  const moved = React.useRef(false);
  React.useEffect(() => { if (moved.current) heading.current?.focus(); }, [step]);
  // A step further on comes in from the end, one before from the start; starting a new import goes forward too.
  const go = (s: DataImportStep, way: 'forward' | 'back' = ORDER.indexOf(s) < ORDER.indexOf(step) ? 'back' : 'forward') =>
    void withViewTransition(() => { moved.current = true; setErrors([]); setStep(s); }, { types: [way] });
  const fail = (found: ErrorSummaryItem[]) => { setErrors(found); setTries((t) => t + 1); return found.length > 0; };
  const error = (field: string) => errors.find((e) => e.field === field)?.message;

  const checked = React.useMemo(() => checkRows(table.slice(1), mapping, existing, lines.slice(1)), [table, lines, mapping, existing]);
  const bad = checked.filter((r) => r.problems.length), good = checked.filter((r) => !r.problems.length);
  const updates = good.filter((r) => r.update).length;

  const read = async (e: React.FormEvent) => {
    e.preventDefault();
    const chosen = files[0];
    if (!chosen && !file) { fail([{ field: 'import-file', message: 'Choose a CSV file to import' }]); return; }
    const next = chosen ? { name: chosen.name, text: await chosen.text() } : file!;
    const rows = parseCsv(next.text);
    if (rows.length < 2) { fail([{ field: 'import-file', message: `${next.name} has no rows under its headings. Choose a CSV file with a heading row and a row for each customer` }]); return; }
    if (next !== file) { setFile(next); setMapping(guessMapping(rows[0] ?? [])); }
    go('match');
  };
  const match = (e: React.FormEvent) => {
    e.preventDefault();
    if (!fail(mappingProblems(mapping, headers))) go('check');
  };
  const save = (e: React.FormEvent) => {
    e.preventDefault();
    if (bad.length && !skip && fail([{ field: 'import-skip', message: `Fix the ${plural(bad.length, 'row', 'rows')} with problems in the file and choose it again, or skip them` }])) return;
    setBusy(true);
    setFailed(false);
    Promise.resolve().then(() => onImport?.(good.map((r) => r.row)))
      .then(() => { setResult({ added: good.length - updates, updated: updates, skipped: bad.length }); go('done'); }, () => setFailed(true))
      .finally(() => setBusy(false));
  };
  const again = () => { setFile(undefined); setFiles([]); setSkip(false); setResult(null); go('upload', 'forward'); };
  const columns = [{ value: '-1', label: 'Not in the file' }, ...headers.map((h, i) => ({ value: String(i), label: h || `Column ${i + 1}` }))];
  const summary = errors.length ? <ErrorSummary key={tries} errors={errors} headingLevel={3} /> : null;
  const h2 = (text: string) => <Heading level={2} size="lg" ref={heading} tabIndex={-1} className="outline-none">{text}</Heading>;

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <Container as="main" size="lg" className="py-8 outline-none" id="main">
        <Stack gap={6}>
          <OfflineBanner online={online} placement="inline">Your file and columns stay here. Importing needs a connection.</OfflineBanner>
          <PageHeader title="Import customers" />
          <Stepper current={ORDER.indexOf(step) + (step === 'done' ? 1 : 0)} steps={STEPS} size="sm" />
          <Card className="flex flex-col gap-4" style={{ viewTransitionName: 'data-import-step', viewTransitionClass: 'step' }}>
            {step === 'upload' ? (
              <>
                {h2('Choose a file')}
                <p className="m-0">A CSV file with a heading row, then one row for each customer. A spreadsheet can save one: File, then Download or Export, then CSV.</p>
                {summary}
                <form noValidate onSubmit={(e) => { void read(e); }} className="flex flex-col gap-4">
                  <Field label="Customer file" error={error('import-file')}>
                    <FileUpload id="import-file" accept=".csv,text/csv" maxSize={5 * 1024 * 1024} hint="CSV, up to 5 MB" files={files} onFilesChange={setFiles} />
                  </Field>
                  <Button type="submit" className="self-start">Continue</Button>
                </form>
              </>
            ) : step === 'match' ? (
              <>
                {h2('Match columns')}
                <p className="m-0">Choose the column in <strong>{file?.name}</strong> that holds each detail. We matched the ones whose headings name them.</p>
                {summary}
                <form noValidate onSubmit={match} className="flex flex-col gap-4">
                  {FIELDS.map((f) => (
                    <Field key={f.key} label={f.label} optional={!f.required} error={error(`import-${f.key}`)}>
                      <Select id={`import-${f.key}`} options={columns} value={String(mapping[f.key])} onChange={(e) => { const v = Number(e.target.value); setMapping((o) => ({ ...o, [f.key]: v })); }} />
                    </Field>
                  ))}
                  <div className="flex flex-wrap gap-3">
                    <Button type="submit">Check rows</Button>
                    <Button variant="secondary" onClick={() => go('upload')}>Back</Button>
                  </div>
                </form>
              </>
            ) : step === 'check' ? (
              <>
                {h2('Check rows')}
                <p className="m-0">
                  {plural(good.length, 'row is', 'rows are')} ready: {plural(good.length - updates, 'new customer', 'new customers')} and {plural(updates, 'update', 'updates')} to customers you have.
                  {bad.length ? ` ${plural(bad.length, 'row has', 'rows have')} problems, listed first.` : ''} Nothing is saved until you import.
                </p>
                {summary}
                <Table caption={`Rows in ${file?.name}`} hideCaption size="sm" pinStart>
                  <TableHead>
                    <TableRow>
                      <TableHeaderCell align="end">Line</TableHeaderCell>
                      <TableHeaderCell>Status</TableHeaderCell>
                      <TableHeaderCell>Problem</TableHeaderCell>
                      {FIELDS.map((f) => <TableHeaderCell key={f.key}>{f.label}</TableHeaderCell>)}
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {[...bad, ...good].map((r) => (
                      <TableRow key={r.line}>
                        <TableCell align="end">{r.line}</TableCell>
                        <TableCell>{r.problems.length ? <Badge tone="danger">Problem</Badge> : r.update ? <Badge tone="info">Update</Badge> : <Badge tone="success">New</Badge>}</TableCell>
                        <TableCell>{r.problems.join('. ')}</TableCell>
                        {FIELDS.map((f) => <TableCell key={f.key} className={NOWRAP[f.key]}>{LTR[f.key] ? <bdi dir="ltr">{r.row[f.key]}</bdi> : r.row[f.key]}</TableCell>)}
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
                <form noValidate onSubmit={save} className="flex flex-col gap-4">
                  {bad.length ? (
                    <Field error={error('import-skip')}>
                      <Checkbox id="import-skip" checked={skip} onCheckedChange={setSkip} invalid={!!error('import-skip')}
                        description="They stay in your file, so you can fix them and import that file again.">
                        Skip the {plural(bad.length, 'row', 'rows')} with problems
                      </Checkbox>
                    </Field>
                  ) : null}
                  {failed ? <Alert tone="danger" title="Couldn’t import">Nothing was saved. Check your connection and try again.</Alert> : null}
                  <div className="flex flex-wrap gap-3">
                    <Button type="submit" loading={busy} disabled={!good.length}>{failed ? 'Try again' : `Import ${plural(good.length, 'customer', 'customers')}`}</Button>
                    <Button variant="secondary" onClick={() => go('match')}>Back</Button>
                  </div>
                </form>
              </>
            ) : (
              <>
                {h2('Import finished')}
                {result ? (
                  <ul className="m-0 flex list-disc flex-col gap-1 ps-5">
                    <li>{plural(result.added, 'customer', 'customers')} added</li>
                    <li>{plural(result.updated, 'customer', 'customers')} updated</li>
                    <li>{plural(result.skipped, 'row', 'rows')} skipped{result.skipped ? ', still in your file to fix' : ''}</li>
                  </ul>
                ) : null}
                <div className="flex flex-wrap items-center gap-4">
                  <Link href="#customers">Go to customers</Link>
                  <Button variant="secondary" onClick={again}>Import another file</Button>
                </div>
              </>
            )}
          </Card>
        </Stack>
      </Container>
    </div>
  );
}

files.DetailPage.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Dialog } from '@diki-stwn/serupa-ds';
import { InlineEdit } from '@diki-stwn/serupa-ds';
import { DescriptionList, DescriptionItem } from '@diki-stwn/serupa-ds';
import { Tabs, TabList, Tab, TabPanel } from '@diki-stwn/serupa-ds';
import { TypeToConfirm } from '@diki-stwn/serupa-ds';
import { Toaster, toast } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { EmptyLoadFailed } from './EmptyStates';
import { formatDate } from '@diki-stwn/serupa-ds';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Detail page: one thing (a project) with where it sits, its name and details editable in place, its parts in tabs,
   small removals that can be undone, and a delete that can't, behind typing its name. For an app to copy. What it
   carries (WCAG 2.2):
   - 2.4.8, 1.3.1: a breadcrumb says where the page sits, the h1 is the project's name, and each tab's panel is
     named by its tab.
   - 3.3.4: removing a task happens at once with Undo in a toast, and is done for good only when the toast goes;
     deleting the project, which can't be undone, asks for its name first, in a dialog that says what will be lost.
   - 2.4.3: after a removal, focus goes to the next task (or the list's heading), never to the top of the page; after
     the delete, to the h1 of the page that says it's gone.
   - 4.1.3: the toast says what was removed; a saved name is shown in the h1 at once.
   - 3.3.1: a name left empty says so, and the old name stays; a delete that fails says so in the dialog, which stays
     open with focus on its button, so it can be tried again.
   - 1.3.1, 1.4.10: a supporting pane (`aside`), such as the project's activity, is a complementary landmark named by
     its heading; it sits beside the tabs on a wide screen and drops below them on a narrow one, in reading order.
   Storing the changes is the app's job: onRename, onRemoveTask and onDelete get them. */

export interface ProjectTask { id: string; title: string }
export interface Project { name: string; description: string; owner: string; created: string; tasks: readonly ProjectTask[] }

export interface DetailPageProps {
  /** The project shown. Default: a demo project. */
  project?: Project | undefined;
  /** A new name or description was saved. */
  onRename?: ((field: 'name' | 'description', value: string) => void) | undefined;
  /** A removed task's toast closed without Undo: remove it for good. */
  onRemoveTask?: ((id: string) => void) | undefined;
  /** The project's name was typed and Delete pressed. Return its promise, so the button shows it's busy. */
  onDelete?: (() => unknown) | undefined;
  /** Starts with the delete dialog open, as after a delete that failed: it says so, and the delete can be tried again. */
  deleteFailed?: boolean | undefined;
  /** The project is on its way: a busy placeholder for its details, named once ("Loading project"), in place of the page. Default: false. */
  loading?: boolean | undefined;
  /** The project failed to load: a "Couldn’t load this project" message with Try again, which calls onRetry, in place of the page. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** A supporting pane beside the tabs from 1024px, and below them on a narrower screen: the project's activity, its
      people. Its title names the landmark. */
  aside?: { title: string; content: React.ReactNode } | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demo: Project = {
  name: 'Website redesign', description: 'New pages for the marketing site, with the updated brand.', owner: 'Ana Lima', created: '2026-09-14',
  tasks: [
    { id: 't1', title: 'Draft the home page copy' }, { id: 't2', title: 'Pick the photos' },
    { id: 't3', title: 'Review the pricing page' }, { id: 't4', title: 'Check the forms with a screen reader' },
  ],
};

// "14 September 2026" in the reader's locale for "2026-09-14", read as that calendar day wherever the reader is;
// anything else as it came.
function day(iso: string, locale: string): string {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);
  if (!m) return iso;
  return formatDate(iso, locale, { dateStyle: 'long' }) || iso;
}

const english = /* @__PURE__ */ new Intl.PluralRules('en');

/** The detail page: a skip link, a header, then main with the breadcrumb, the h1, the tabs and the danger zone. */
export function DetailPage({ project = demo, onRename, onRemoveTask, onDelete, deleteFailed, loading = false, loadFailed = false, onRetry, aside, online }: DetailPageProps) {
  const [name, setName] = React.useState(project.name);
  const [description, setDescription] = React.useState(project.description);
  // A new name or description from the app (another project opened, or the saved one coming back) replaces the one
  // shown; one the app passes again unchanged keeps an edit it hasn't stored yet.
  const [given, setGiven] = React.useState({ name: project.name, description: project.description });
  if (given.name !== project.name || given.description !== project.description) {
    setGiven({ name: project.name, description: project.description });
    if (given.name !== project.name) setName(project.name);
    if (given.description !== project.description) setDescription(project.description);
  }
  const [hidden, setHidden] = React.useState<ReadonlySet<string>>(new Set());
  const [asking, setAsking] = React.useState(!!deleteFailed);
  const [deleted, setDeleted] = React.useState(false);
  const [failed, setFailed] = React.useState(!!deleteFailed);
  const locale = useLocale();
  // The Undo toasts still open, and whether the project is gone: once it is, they close without removing anything,
  // since the delete took their tasks with it.
  const pending = React.useRef(new Set<string>());
  const gone = React.useRef(false);
  const tasksHeading = React.useRef<HTMLHeadingElement>(null);
  const goneHeading = React.useRef<HTMLHeadingElement>(null);
  const tasks = project.tasks.filter((t) => !hidden.has(t.id));
  const later = (f: () => void) => requestAnimationFrame(f);
  const removeButton = (id: string) => () => document.getElementById(`task-${id}`)?.focus();

  React.useEffect(() => { if (deleted) goneHeading.current?.focus(); }, [deleted]);

  const remove = (t: ProjectTask) => {
    const at = tasks.indexOf(t), next = tasks[at + 1] || tasks[at - 1];
    setHidden((h) => new Set(h).add(t.id));
    later(next ? removeButton(next.id) : () => tasksHeading.current?.focus());
    const id: string = toast.undo({
      title: `Removed “${t.title}”`,
      commit: () => { pending.current.delete(id); if (!gone.current) onRemoveTask?.(t.id); },
      onUndo: () => { pending.current.delete(id); setHidden((h) => { const n = new Set(h); n.delete(t.id); return n; }); later(removeButton(t.id)); },
    });
    pending.current.add(id);
  };
  // Saved without the spaces around it, as the check reads it.
  const save = (field: 'name' | 'description', set: (v: string) => void) => (v: string) => { const kept = v.trim(); set(kept); onRename?.(field, kept); };
  // A delete that fails, by rejecting or by throwing, keeps the dialog open and says so, instead of leaving the error
  // unhandled. The promise goes back to the button, which shows it's busy while a slow delete runs.
  const confirm = () => {
    setFailed(false);
    return Promise.resolve().then(() => onDelete?.()).then(() => {
      gone.current = true;
      for (const id of [...pending.current]) toast.dismiss(id);
      setAsking(false);
      setDeleted(true);
    }, () => setFailed(true));
  };
  const ask = (open: boolean) => { setAsking(open); if (!open) setFailed(false); };
  // What the dialog says will be lost: the tasks still there, with the word that fits the number: the words are
  // English, so the rule is too; an app translating them passes its own locale.
  const lost = tasks.length
    ? `its ${formatNumber(tasks.length, locale)} ${english.select(tasks.length) === 'one' ? 'task' : 'tasks'} and files`
    : 'its files';

  return (
    <div className="min-h-screen bg-surface-sunken text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <Container as="main" size={aside ? 'xl' : 'lg'} className="py-8 outline-none" id="main" aria-busy={loading && !loadFailed ? true : undefined}>
        <Stack gap={6}>
          <OfflineBanner online={online} placement="inline">This is the project as it was when the page loaded. Changes need a connection.</OfflineBanner>
          {loadFailed || loading ? (
            // The name isn't known yet, so the h1 says only what the page is; the way back stays.
            <>
              <Link href="#projects">Back to projects</Link>
              <Heading level={1} className="sr-only">Project</Heading>
              {loadFailed ? <EmptyLoadFailed title="Couldn’t load this project" onRetry={() => onRetry?.()} headingLevel={2} />
                : <Card><Skeleton shape="text" lines={4} label="Loading project" /></Card>}
            </>
          ) : deleted ? (
            <div className="flex flex-col gap-3">
              <Heading level={1} ref={goneHeading} tabIndex={-1} className="outline-none">{name} was deleted</Heading>
              <p className="m-0 text-text-muted">Its tasks and files are gone too.</p>
              <Link href="#projects">Back to projects</Link>
            </div>
          ) : (
            <>
              <PageHeader breadcrumb={[{ label: 'Projects', href: '#projects' }, { label: name }]} title={name} description={description}
                primary={{ label: 'Share', href: '#share' }} />

              <div className={aside ? 'grid grid-cols-1 items-start gap-6 lg:grid-cols-3' : 'contents'}>
              <Tabs defaultValue="overview" className={aside ? 'min-w-0 lg:col-span-2' : undefined}>
                <TabList aria-label="Project">
                  <Tab value="overview">Overview</Tab>
                  <Tab value="tasks">Tasks</Tab>
                  <Tab value="settings">Settings</Tab>
                </TabList>

                <TabPanel value="overview" className="pt-4">
                  <Card>
                    <DescriptionList>
                      <DescriptionItem term="Name">
                        <InlineEdit label="Project name" value={name} onValueChange={save('name', setName)}
                          validate={(v) => (v.trim() ? null : 'Enter a name for the project.')} />
                      </DescriptionItem>
                      <DescriptionItem term="Description"><InlineEdit label="Description" value={description} onValueChange={save('description', setDescription)} /></DescriptionItem>
                      <DescriptionItem term="Owner">{project.owner}</DescriptionItem>
                      <DescriptionItem term="Created"><time dateTime={project.created}>{day(project.created, locale)}</time></DescriptionItem>
                    </DescriptionList>
                  </Card>
                </TabPanel>

                <TabPanel value="tasks" className="pt-4">
                  <Card className="flex flex-col gap-4">
                    <Heading level={2} size="lg" ref={tasksHeading} tabIndex={-1} className="outline-none">Tasks ({formatNumber(tasks.length, locale)})</Heading>
                    {tasks.length ? (
                      <ul className="m-0 flex list-none flex-col divide-y divide-border p-0">
                        {tasks.map((t) => (
                          <li key={t.id} className="flex flex-wrap items-center justify-between gap-3 py-2">
                            <span className="min-w-0">{t.title}</span>
                            <Button id={`task-${t.id}`} size="sm" variant="ghost" aria-label={`Remove ${t.title}`} onClick={() => remove(t)}>Remove</Button>
                          </li>
                        ))}
                      </ul>
                    ) : <p className="m-0 text-text-muted">No tasks left.</p>}
                  </Card>
                </TabPanel>

                <TabPanel value="settings" className="pt-4">
                  <section aria-labelledby="danger" className="flex flex-col gap-4 rounded-lg border border-surface-danger bg-surface p-4">
                    <Heading level={2} size="lg" id="danger">Delete this project</Heading>
                    <p className="m-0 max-w-prose">Deleting removes the project with its tasks and files for everyone. It can’t be undone.</p>
                    <div><Button destructive variant="outline" onClick={() => ask(true)}>Delete project</Button></div>
                  </section>
                </TabPanel>
              </Tabs>
              {aside ? (
                <aside aria-labelledby="detail-aside" className="flex min-w-0 flex-col gap-3">
                  <Heading level={2} size="lg" id="detail-aside">{aside.title}</Heading>
                  {aside.content}
                </aside>
              ) : null}
              </div>

              <Dialog alert open={asking} onOpenChange={ask} title={`Delete ${name}?`}
                description={`This deletes the project and ${lost} for everyone. It can’t be undone.`}>
                <div className="flex flex-col gap-4">
                  {failed ? <Alert tone="danger">Couldn’t delete {name}. Try again.</Alert> : null}
                  <TypeToConfirm phrase={name} confirmLabel="Delete this project" onConfirm={confirm} />
                </div>
              </Dialog>
            </>
          )}
        </Stack>
      </Container>
      <Toaster />
    </div>
  );
}

files.Donation.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Checkbox } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { NumberInput } from '@diki-stwn/serupa-ds';
import { RadioGroup, Radio } from '@diki-stwn/serupa-ds';
import { ErrorSummary, type ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Donation: give once or every month, choose an amount that says what it pays for, cover the card fee if you like, and
   see the total before you give. For an app to copy. What it carries (WCAG 2.2):
   - 1.3.1: how often and how much are groups of radios named by their question; each amount says what it pays for, as
     its description, so it's read with it; Another amount brings a number field right after it.
   - 3.3.2: the lowest amount is said before you type; covering the fee says how much it adds.
   - 4.1.3, 3.3.4: the total says what you'll give and how often, and Give names it ("Give $52 a month").
   - 3.3.1, 2.4.3: giving with problems shows a summary at the top that takes focus, each problem a link to its field.
   - 3.3.4, 4.1.3: Give shows it's busy; a gift that can't be taken says so and keeps everything.
   - 2.4.3: once given, the thank-you's heading takes focus, says what was taken and how to stop a monthly gift.
   Paying is the app's job: onGive gets the gift; reject when it can't be taken. */

export interface Gift { amount: number; fee: number; monthly: boolean; name: string; email: string }

export interface DonationProps {
  /** The money it's in. Default: "USD". */
  currency?: string | undefined;
  /** The amounts to choose from, each with what it pays for. */
  amounts?: { amount: number; buys: string }[] | undefined;
  /** The lowest gift. Default: 2. */
  min?: number | undefined;
  /** The card fee as a share of the gift, and a fixed part. Default: 2.9% and 0.30. */
  fee?: { rate: number; fixed: number } | undefined;
  /** Takes the gift. Reject when it can't be taken. */
  onGive?: ((gift: Gift) => unknown) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demoAmounts = [
  { amount: 10, buys: 'A week of school meals for one child' },
  { amount: 25, buys: 'A set of schoolbooks for a year' },
  { amount: 50, buys: 'A month of a teacher’s training' },
  { amount: 100, buys: 'Desks for a classroom' },
];
const FIELDS = ['amount', 'other', 'name', 'email'] as const;
type Problems = Partial<Record<(typeof FIELDS)[number], string>>;

/** The fee that covers the card's cut of a gift, so the charity gets all of it, rounded up to the cent. */
export function coverFee(amount: number, fee: { rate: number; fixed: number }) {
  if (amount <= 0) return 0;
  // Rounded to a millionth of a cent before rounding up, so the arithmetic's last bit isn't a cent more (0.3 is 0.30).
  return Math.ceil(Math.round(((amount + fee.fixed) / (1 - fee.rate) - amount) * 1e8) / 1e6) / 100;
}

/** What's wrong with a gift, by field, in the order of the form, or {} when it can be given. */
export function giftProblems(d: { amount: string; other: number | null; name: string; email: string }, min: number, money: (n: number) => string = String): Problems {
  const out: Problems = {};
  if (!d.amount) out.amount = 'Choose an amount.';
  else if (d.amount === 'other' && (d.other === null || d.other < min)) out.other = `Enter an amount of ${money(min)} or more.`;
  if (!d.name.trim()) out.name = 'Enter your name, for the receipt.';
  if (!d.email.trim()) out.email = 'Enter your email address, for the receipt.';
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.email.trim())) out.email = 'Enter an email address like name@example.com.';
  return out;
}

/** The donation page: a skip link, a header, then main with the h1, and the form or the thank-you. */
export function Donation({ currency = 'USD', amounts = demoAmounts, min = 2, fee = { rate: 0.029, fixed: 0.3 }, onGive, online }: DonationProps) {
  const locale = useLocale();
  const money = (n: number) => formatNumber(n, locale, { style: 'currency', currency, minimumFractionDigits: Number.isInteger(n) ? 0 : 2 });
  const [d, setD] = React.useState({ monthly: 'once', amount: '', other: null as number | null, cover: false, name: '', email: '' });
  const [problems, setProblems] = React.useState<Problems>({});
  const [tries, setTries] = React.useState(0);
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const [given, setGiven] = React.useState<Gift | null>(null);
  const answer = React.useRef<HTMLHeadingElement>(null);
  const edit = (patch: Partial<typeof d>) => { setD((now) => ({ ...now, ...patch })); setFailed(false); };
  const amount = d.amount === 'other' ? d.other ?? 0 : Number(d.amount || 0);
  const added = d.cover ? coverFee(amount, fee) : 0;
  const monthly = d.monthly === 'monthly';
  const every = monthly ? ' a month' : '';
  const errors: ErrorSummaryItem[] = FIELDS.filter((f) => problems[f]).map((f) => ({ field: `donate-${f}`, message: problems[f] }));

  const give = (e: React.FormEvent) => {
    e.preventDefault();
    setFailed(false);
    const found = giftProblems(d, min, money);
    setProblems(found);
    setTries((t) => t + 1);
    if (Object.keys(found).length) return;
    setBusy(true);
    const gift: Gift = { amount, fee: added, monthly, name: d.name.trim(), email: d.email.trim() };
    void Promise.resolve().then(() => onGive?.(gift)).then(() => setGiven(gift), () => setFailed(true)).finally(() => setBusy(false));
  };
  React.useEffect(() => { if (given) answer.current?.focus(); }, [given]);

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme Schools</p>
        <Link underline="hover" href="#about">About us</Link>
      </header>
      <Container as="main" size="prose" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">Your choices stay here. Giving needs a connection.</OfflineBanner>
          <PageHeader title="Give to Acme Schools" description="Every gift goes to schools in the villages we work in. We’re a registered charity; your gift may be tax-deductible." />
          {given ? (
            <section aria-labelledby="donate-thanks" className="flex flex-col items-start gap-3 pt-6">
              <h2 id="donate-thanks" ref={answer} tabIndex={-1} className="m-0 text-2xl font-semibold outline-none">Thank you, {given.name}</h2>
              <p className="m-0">
                We’ve taken {money(given.amount + given.fee)}{given.monthly ? ', and will take it on this day each month' : ''}. Your receipt is on its way to {given.email}.
              </p>
              {given.monthly ? <p className="m-0">You can change or stop your monthly gift at any time from the link in the receipt.</p> : null}
              <Link href="#about">See what your gift does</Link>
            </section>
          ) : (
            <form onSubmit={give} noValidate aria-label="Your gift" className="flex flex-col gap-4 pt-6">
              <ErrorSummary key={tries} errors={errors} />
              <p className="m-0 text-text-muted">Fields marked * are required.</p>
              <Field label="How often?" group>
                <RadioGroup name="donate-often" orientation="horizontal" value={d.monthly} onValueChange={(v: string) => edit({ monthly: v })}>
                  <Radio value="once">Once</Radio>
                  <Radio value="monthly">Every month</Radio>
                </RadioGroup>
              </Field>
              <Field label="How much?" group error={problems.amount} required>
                <RadioGroup id="donate-amount" name="donate-amount" value={d.amount} onValueChange={(v: string) => edit({ amount: v })}>
                  {amounts.map((a) => <Radio key={a.amount} value={String(a.amount)} description={a.buys}>{money(a.amount)}{every}</Radio>)}
                  <Radio value="other">Another amount</Radio>
                </RadioGroup>
              </Field>
              {d.amount === 'other' ? (
                <Field label={`Your amount${every}`} id="donate-other" hint={`${money(min)} or more.`} error={problems.other} required>
                  <NumberInput currency={currency} min={0} value={d.other} onValueChange={(n) => edit({ other: n })} className="max-w-48" />
                </Field>
              ) : null}
              <Checkbox checked={d.cover} onCheckedChange={(on) => edit({ cover: on })}
                description={amount ? `Adds ${money(coverFee(amount, fee))}${every}, so we get all of your gift.` : 'Adds a little, so we get all of your gift.'}>
                Cover the card fee
              </Checkbox>
              <Field label="Your name" id="donate-name" error={problems.name} required>
                <Input autoComplete="name" value={d.name} onChange={(e) => edit({ name: e.target.value })} />
              </Field>
              <Field label="Your email" id="donate-email" hint="For your receipt. We never share it." error={problems.email} required>
                <Input type="email" autoComplete="email" value={d.email} onChange={(e) => edit({ email: e.target.value })} />
              </Field>
              <Card padding="sm" variant="filled">
                <p className="m-0" aria-live="polite" id="donate-total">
                  {amount ? <>You’ll give <strong>{money(amount + added)}{every}</strong>{added ? `, ${money(added)} of it for the card fee` : ''}.</> : 'Choose an amount to see your total.'}
                </p>
              </Card>
              <div className="flex flex-col items-start gap-3">
                {failed ? <Alert tone="danger">Couldn’t take your gift, and nothing was charged. Try again; everything is still here.</Alert> : null}
                <Button type="submit" loading={busy}>{amount ? `Give ${money(amount + added)}${every}` : 'Give'}</Button>
              </div>
            </form>
          )}
        </Stack>
      </Container>
    </div>
  );
}

files.EmailPreferences.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Switch } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Email preferences: the page an email's "Manage emails" or "Unsubscribe" link opens, with no sign-in. Which emails
   come, each one a switch that says what it is and how often, and one button to stop them all. For an app to copy.
   What it carries (WCAG 2.2):
   - 1.3.1, 3.3.2: the address it's about is said first; each kind of email is a switch named by what it is, with how
     often it comes as its description.
   - Ethical design: stopping every email is one button, beside Save, and asks no "Are you sure?"; it
     takes effect at once and the answer says how to undo it.
   - 4.1.3, 3.3.4: Save shows it's busy and says what changed once saved; one that fails says so next to the button
     and keeps the switches as set.
   - 2.4.3: after "Stop all emails", the answer's heading takes focus, with "Turn them back on".
   - The emails that can't be turned off (receipts, security) are named in a sentence, not as switches that can't be
     switched.
   Saving is the app's job: onSave gets every topic's choice; reject when it can't be saved. */

export interface EmailTopic {
  id: string;
  label: string;
  /** How often it comes, and what's in it: "Weekly: what's new in the shop". */
  about: string;
  on: boolean;
}

export interface EmailPreferencesProps {
  /** The address the link was sent to. Default: a demo address. */
  email?: string | undefined;
  /** The kinds of email. Default: demo topics. */
  topics?: EmailTopic[] | undefined;
  /** Saves the choices, by topic id. Reject when they can't be saved. */
  onSave?: ((choices: Record<string, boolean>) => unknown) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demo: EmailTopic[] = [
  { id: 'news', label: 'News and offers', about: 'Weekly: what’s new in the shop, and sales before anyone else.', on: true },
  { id: 'back', label: 'Back in stock', about: 'When something you saved can be bought again.', on: true },
  { id: 'tips', label: 'Tips for what you bought', about: 'Now and then: how to look after it, and what goes with it.', on: false },
  { id: 'survey', label: 'Surveys', about: 'A few times a year: tell us how we’re doing.', on: true },
];

/** What changed between two sets of choices, as the names turned on and off. */
export function emailChanges(topics: readonly EmailTopic[], before: Record<string, boolean>, after: Record<string, boolean>): { on: string[]; off: string[] } {
  return {
    on: topics.filter((t) => !before[t.id] && after[t.id]).map((t) => t.label),
    off: topics.filter((t) => before[t.id] && !after[t.id]).map((t) => t.label),
  };
}

/** Changes in words: "Turned on Surveys. Turned off News and offers.", or "Nothing changed." */
export function changeWords(c: { on: string[]; off: string[] }): string {
  const parts = [c.on.length ? `Turned on ${c.on.join(', ')}.` : '', c.off.length ? `Turned off ${c.off.join(', ')}.` : ''].filter(Boolean);
  return parts.length ? parts.join(' ') : 'Nothing changed.';
}

const choicesOf = (topics: readonly EmailTopic[]) => Object.fromEntries(topics.map((t) => [t.id, t.on]));

/** The email preferences page: a skip link, a header, then main with the h1, the address, the switches, Save and Stop all. */
export function EmailPreferences({ email = 'ana@example.com', topics = demo, onSave, online }: EmailPreferencesProps) {
  const [saved, setSaved] = React.useState<Record<string, boolean>>(() => choicesOf(topics));
  const [choices, setChoices] = React.useState<Record<string, boolean>>(() => choicesOf(topics));
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const [stopped, setStopped] = React.useState<Record<string, boolean> | null>(null);
  const [said, setSaid] = React.useState('');
  const answer = React.useRef<HTMLHeadingElement>(null);
  const focusFirst = React.useRef(false);
  const page = React.useRef<HTMLElement>(null);

  const save = (next: Record<string, boolean>) => Promise.resolve().then(() => onSave?.(next));
  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    setFailed(false); setBusy(true); setSaid('');
    const next = { ...choices };
    void save(next).then(() => {
      const words = changeWords(emailChanges(topics, saved, next));
      setSaved(next); setSaid(words);
    }, () => setFailed(true)).finally(() => setBusy(false));
  };
  const stopAll = () => {
    setFailed(false);
    const none = Object.fromEntries(topics.map((t) => [t.id, false]));
    setBusy(true);
    void save(none).then(() => { setStopped(saved); setSaved(none); setChoices(none); }, () => setFailed(true)).finally(() => setBusy(false));
  };
  const turnBack = () => {
    const back = stopped!;
    setFailed(false);
    setBusy(true);
    void save(back).then(() => { focusFirst.current = true; setSaved(back); setChoices(back); setStopped(null); setSaid(''); }, () => setFailed(true)).finally(() => setBusy(false));
  };
  React.useEffect(() => {
    if (stopped) answer.current?.focus();
    else if (focusFirst.current) { focusFirst.current = false; page.current?.querySelector<HTMLInputElement>('[role="switch"]')?.focus(); }
  }, [stopped]);

  return (
    <div className="min-h-screen bg-surface-sunken text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
        <Link underline="hover" href="#shop">Go to the shop</Link>
      </header>
      <Container as="main" size="prose" className="py-10 outline-none" ref={page} id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">Your choices stay here. Saving them needs a connection.</OfflineBanner>
          <PageHeader title="Emails from Acme" description={`Choose what comes to ${email}. Changes take effect within a day.`} />
          <Card padding="lg" className="mt-6">
            {stopped ? (
              <section aria-labelledby="stopped" className="flex flex-col items-start gap-3">
                <h2 id="stopped" ref={answer} tabIndex={-1} className="m-0 text-2xl font-semibold outline-none">You won’t get these emails any more</h2>
                <p className="m-0">We’ll still send receipts, delivery updates and security alerts, as they’re about orders and your account.</p>
                {failed ? <Alert tone="danger">Couldn’t turn them back on. Try again.</Alert> : null}
                <Button variant="secondary" loading={busy} onClick={turnBack}>Turn them back on</Button>
              </section>
            ) : (
              <form onSubmit={submit} aria-labelledby="choose" className="flex flex-col gap-4">
                <h2 id="choose" className="m-0 text-lg font-semibold">What we send</h2>
                <div className="flex flex-col gap-4">
                  {topics.map((t) => (
                    <Switch key={t.id} checked={!!choices[t.id]} description={t.about}
                      onCheckedChange={(on) => { setChoices((c) => ({ ...c, [t.id]: on })); setSaid(''); setFailed(false); }}>
                      {t.label}
                    </Switch>
                  ))}
                </div>
                <p className="m-0 text-sm text-text-muted">Receipts, delivery updates and security alerts always come, as they’re about your orders and your account.</p>
                {failed ? <Alert tone="danger">Couldn’t save your choices. Try again; they’re still set as you left them.</Alert> : null}
                <div className="flex flex-wrap gap-x-2 gap-y-3">
                  <Button type="submit" loading={busy}>Save choices</Button>
                  <Button variant="secondary" disabled={busy} onClick={stopAll}>Stop all emails</Button>
                  <p id="email-saved" role="status" className="m-0 self-center">{said ? `Saved. ${said}` : ''}</p>
                </div>
              </form>
            )}
          </Card>
        </Stack>
      </Container>
    </div>
  );
}

