'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Meter } from '@diki-stwn/serupa-ds';
import { DescriptionList, DescriptionItem } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { NumberInput } from '@diki-stwn/serupa-ds';
import { Textarea } from '@diki-stwn/serupa-ds';
import { RadioGroup, Radio } from '@diki-stwn/serupa-ds';
import { ErrorSummary, type ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Event registration: what, when and where an event is, how many places are left, and a short form to get tickets,
   or to join the waiting list once it's full. For an app to copy. What it carries (WCAG 2.2):
   - 1.3.1: when and where are named facts; the time says its time zone, so nobody turns up an hour out.
   - 1.4.1, 1.3.1: places left are a meter with its number in words beside it, not a bar alone.
   - 3.3.2, 1.3.5: each ticket type says its price and who it's for; how many tickets says its limit, and the total
     is worked out as you choose. Name and email say what they are for autofill. What would make it easier to come is
     asked for, optional.
   - 3.3.1, 2.4.3: registering with problems shows a summary at the top that takes focus, each problem a link to its
     field.
   - 3.3.4, 4.1.3: Register shows it's busy; a registration that can't be sent says so next to the button and keeps
     every field.
   - 2.4.3: once registered, the answer's heading takes focus, with the tickets, the total, and a link to add it to a
     calendar.
   Registering is the app's job: onRegister gets the registration; reject when it can't be sent. */

export interface EventDetails {
  title: string;
  /** Starts, as an ISO date and time with its offset: "2026-03-12T18:30:00+07:00". */
  start: string;
  /** Ends, the same way. */
  end: string;
  /** The event's IANA time zone, which its times are shown in: "Asia/Jakarta". */
  timeZone: string;
  /** That time zone's name for people: "Jakarta time (UTC+7)". */
  zone: string;
  place: string;
  /** Places in all, and places taken. */
  capacity: number;
  taken: number;
  tickets: { value: string; label: string; price: number; who: string }[];
}

export interface Registration {
  ticket: string;
  count: number;
  name: string;
  email: string;
  /** What would make it easier to come, optional. */
  needs: string;
  /** On the waiting list, not a ticket: the event was full. */
  waitlist: boolean;
}

export interface EventRegistrationProps {
  /** The event. Default: a demo event. */
  event?: EventDetails | undefined;
  /** ISO 4217 currency. Default: "USD". */
  currency?: string | undefined;
  /** Registers. Reject when it can't be sent. */
  onRegister?: ((registration: Registration) => unknown) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demo: EventDetails = {
  title: 'Design systems meetup', start: '2026-03-12T18:30:00+07:00', end: '2026-03-12T21:00:00+07:00', timeZone: 'Asia/Jakarta', zone: 'Jakarta time (UTC+7)',
  place: 'Acme office, 5th floor, Jl. Sudirman 21, Jakarta', capacity: 60, taken: 47,
  tickets: [
    { value: 'general', label: 'General', price: 12, who: 'Talks, dinner and drinks' },
    { value: 'student', label: 'Student', price: 5, who: 'The same, with a student card at the door' },
  ],
};
const MOST = 4;
type Problems = Partial<Record<'ticket' | 'count' | 'name' | 'email', string>>;

/** Places left, in words: "13 places left", "1 place left", "Full". */
export function placesWords(left: number, locale?: string): string {
  if (left <= 0) return 'Full';
  return `${formatNumber(left, locale)} ${left === 1 ? 'place' : 'places'} left`;
}

/** What's wrong with the registration, by field, in the order of the form, or {} when it can be sent. */
export function registrationProblems(r: Registration, left: number): Problems {
  const out: Problems = {};
  if (!r.waitlist) {
    if (!r.ticket) out.ticket = 'Choose a ticket.';
    const most = Math.min(MOST, left);
    if (!Number.isInteger(r.count) || r.count < 1 || r.count > most) out.count = `Choose from 1 to ${most} tickets.`;
  }
  if (!r.name.trim()) out.name = 'Enter your name, as it should be on the guest list.';
  if (!r.email.trim()) out.email = 'Enter your email address, for the tickets.';
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(r.email.trim())) out.email = 'Enter an email address like name@example.com.';
  return out;
}

const icsTime = (iso: string) => new Date(iso).toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
const icsText = (s: string) => s.replace(/[\\;,]/g, (c) => `\\${c}`);
/** The event as an iCalendar file, for "Add to calendar". */
export function icsFor(e: EventDetails): string {
  return ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Acme//Events//EN', 'BEGIN:VEVENT', `UID:${icsTime(e.start)}-${e.title.length}@acme.example`,
    `DTSTAMP:${icsTime(e.start)}`, `DTSTART:${icsTime(e.start)}`, `DTEND:${icsTime(e.end)}`, `SUMMARY:${icsText(e.title)}`, `LOCATION:${icsText(e.place)}`,
    'END:VEVENT', 'END:VCALENDAR'].join('\r\n');
}

/** The event's page: a skip link, a header, then main with the h1, when and where, places left, and the form, or the answer. */
export function EventRegistration({ event = demo, currency = 'USD', onRegister, online }: EventRegistrationProps) {
  const locale = useLocale();
  const left = Math.max(0, event.capacity - event.taken);
  const full = left === 0;
  const [r, setR] = React.useState<Registration>({ ticket: '', count: 1, name: '', email: '', needs: '', waitlist: full });
  const [problems, setProblems] = React.useState<Problems>({});
  const [tries, setTries] = React.useState(0);
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const [done, setDone] = React.useState<Registration | null>(null);
  const answer = React.useRef<HTMLHeadingElement>(null);
  const edit = (patch: Partial<Registration>) => { setR((now) => ({ ...now, ...patch })); setFailed(false); };
  const money = (n: number) => formatNumber(n, locale, { style: 'currency', currency });
  const ticket = event.tickets.find((t) => t.value === r.ticket);
  const time = (iso: string, opts: Intl.DateTimeFormatOptions) => new Intl.DateTimeFormat(locale, { ...opts, timeZone: event.timeZone }).format(new Date(iso));
  const when = `${time(event.start, { dateStyle: 'full' })}, ${time(event.start, { timeStyle: 'short' })} to ${time(event.end, { timeStyle: 'short' })}`;
  const errors: ErrorSummaryItem[] = (['ticket', 'count', 'name', 'email'] as const).filter((f) => problems[f]).map((f) => ({ field: `event-${f}`, message: problems[f] }));

  const register = (e: React.FormEvent) => {
    e.preventDefault();
    setFailed(false);
    const found = registrationProblems(r, left);
    setProblems(found);
    setTries((t) => t + 1);
    if (Object.keys(found).length) return;
    const out: Registration = full ? { ...r, ticket: '', count: 0, name: r.name.trim(), email: r.email.trim(), needs: r.needs.trim() }
      : { ...r, name: r.name.trim(), email: r.email.trim(), needs: r.needs.trim() };
    setBusy(true);
    void Promise.resolve().then(() => onRegister?.(out)).then(() => setDone(out), () => setFailed(true)).finally(() => setBusy(false));
  };
  React.useEffect(() => { if (done) answer.current?.focus(); }, [done]);

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme events</p>
        <Link underline="hover" href="#events">All events</Link>
      </header>
      <Container as="main" size="prose" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">Your details stay here. Registering needs a connection, and the places left may have changed.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Events', href: '#events' }, { label: event.title }]} title={event.title}
            description="An evening of short talks on design systems, then dinner. Talks are in English, with live captions on the screen." />
          <div className="flex flex-col gap-8 pt-6">
            <Card>
              <section aria-labelledby="event-facts" className="flex flex-col gap-4">
                <h2 id="event-facts" className="m-0 text-lg font-semibold">When and where</h2>
                <DescriptionList>
                  <DescriptionItem term="When"><time dateTime={event.start}>{when}</time>, {event.zone}</DescriptionItem>
                  <DescriptionItem term="Where">{event.place}</DescriptionItem>
                  <DescriptionItem term="Getting in">Step-free, with a lift to the 5th floor</DescriptionItem>
                </DescriptionList>
                <Meter label="Places" value={event.taken} max={event.capacity} high={event.capacity * 0.8} optimum={0}
                  formatValue={() => placesWords(left, locale)} showValue />
              </section>
            </Card>

            {done ? (
              <section aria-labelledby="registered" className="flex flex-col items-start gap-3">
                <h2 id="registered" ref={answer} tabIndex={-1} className="m-0 text-2xl font-semibold outline-none">{done.waitlist ? 'You’re on the waiting list' : 'You’re going'}</h2>
                {done.waitlist
                  ? <p className="m-0">We’ll email {done.email} as soon as a place comes free, and hold it for you for 24 hours.</p>
                  : <p className="m-0">{done.count === 1 ? `1 ${ticket!.label} ticket` : `${formatNumber(done.count, locale)} ${ticket!.label} tickets`}, {money(ticket!.price * done.count)} in all. The tickets are on their way to {done.email}; show them on your phone at the door.</p>}
                {done.waitlist ? null : <Link href={`data:text/calendar;charset=utf-8,${encodeURIComponent(icsFor(event))}`} download="event.ics">Add to your calendar</Link>}
              </section>
            ) : (
              <form onSubmit={register} noValidate aria-labelledby="register" className="flex flex-col gap-4">
                <h2 id="register" className="m-0 text-lg font-semibold">{full ? 'Join the waiting list' : 'Get tickets'}</h2>
                {full ? <p className="m-0">It’s full. Leave your name, and we’ll email you if a place comes free.</p> : null}
                <ErrorSummary key={tries} errors={errors} />
                <p className="m-0 text-text-muted">Fields marked * are required.</p>
                {full ? null : (
                  <>
                    <Field label="Ticket" error={problems.ticket} group required>
                      <RadioGroup id="event-ticket" name="event-ticket" variant="card" value={r.ticket} onValueChange={(v: string) => edit({ ticket: v })}>
                        {event.tickets.map((t) => <Radio key={t.value} value={t.value} description={t.who}>{t.label}: {money(t.price)}</Radio>)}
                      </RadioGroup>
                    </Field>
                    <Field label="How many tickets?" id="event-count" hint={`Up to ${formatNumber(Math.min(MOST, left), locale)}.`} error={problems.count} required>
                      <NumberInput min={1} max={Math.min(MOST, left)} value={r.count} onValueChange={(n) => edit({ count: n ?? 0 })} className="max-w-36" />
                    </Field>
                    <Card padding="sm" variant="filled">
                      <p id="event-total" className="m-0" aria-live="polite">{ticket && r.count > 0 ? <>Total: <strong>{money(ticket.price * r.count)}</strong></> : 'Choose a ticket to see your total.'}</p>
                    </Card>
                  </>
                )}
                <Field label="Your name" id="event-name" error={problems.name} required>
                  <Input autoComplete="name" value={r.name} onChange={(e) => edit({ name: e.target.value })} />
                </Field>
                <Field label="Email" id="event-email" error={problems.email} required>
                  <Input type="email" autoComplete="email" spellCheck={false} value={r.email} onChange={(e) => edit({ email: e.target.value })} />
                </Field>
                <Field label="Anything that would make it easier to come?" id="event-needs" hint="Seating, food, a quiet room, a sign language interpreter. We’ll be in touch." optional>
                  <Textarea rows={3} maxLength={500} value={r.needs} onChange={(e) => edit({ needs: e.target.value })} />
                </Field>
                <div className="flex flex-col items-start gap-3">
                  {failed ? <Alert tone="danger">Couldn’t register you. Try again; everything you entered is still here.</Alert> : null}
                  <Button type="submit" loading={busy}>{full ? 'Join the waiting list' : 'Register'}</Button>
                </div>
              </form>
            )}
          </div>
        </Stack>
      </Container>
    </div>
  );
}

files.ExpenseReport.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { SplitButton } from '@diki-stwn/serupa-ds';
import { MenuItem } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { DateField } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { FileUpload } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { NumberInput } from '@diki-stwn/serupa-ds';
import { Select } from '@diki-stwn/serupa-ds';
import { Table, TableHead, TableBody, TableFoot, TableRow, TableHeaderCell, TableCell } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { announce } from '@diki-stwn/serupa-ds';
import { EmptyLoadFailed } from './EmptyStates';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { ErrorSummary, type ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import { FormattedDate } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Expense report: add what you spent, one expense at a time, see them in a table with the total, and send the report
   to be paid back. For an app to copy. What it carries (WCAG 2.2):
   - 3.3.2: each field says what it takes; the amount says its currency; the receipt says when it's needed (over a
     limit) and what files it takes.
   - 3.3.1, 2.4.3: adding with problems shows a summary that takes focus, each problem a link to its field, and each
     field says its own.
   - 4.1.3: an expense added or removed is said, with the new total.
   - 1.3.1, 1.4.1: the expenses are a table with a caption and the total in its footer; one with no receipt says
     "Receipt needed" in words in a badge, not by color.
   - 2.5.3, 2.4.3: each Remove names its expense ("Remove: Taxi"); removing moves focus to the next row's Remove,
     or the add form's first field when none are left.
   - 3.3.4: Send for approval is checked first: the report's problems (no expenses, receipts missing) are said
     next to the button before anything is sent; once sent, the answer's heading takes focus.
   Sending is the app's job: onSubmit gets the expenses; reject when it can't be sent. */

export interface Expense {
  id: string;
  /** When: "2026-02-03". */
  date: string;
  category: string;
  what: string;
  amount: number;
  /** The receipt's file name, if one was added. */
  receipt?: string | undefined;
}

export interface ExpenseReportProps {
  /** The report's name, for the h1. Default: "Trip to Bandung, February". */
  title?: string | undefined;
  /** Expenses already added. Default: two demo expenses. */
  expenses?: Expense[] | undefined;
  /** ISO 4217 currency. Default: "USD". */
  currency?: string | undefined;
  /** Amounts over this need a receipt. Default: 25. */
  receiptOver?: number | undefined;
  /** Today, as YYYY-MM-DD: the date a new expense starts with and the latest it can be. Default: today. */
  today?: string | undefined;
  /** Sends the report. Reject when it can't be sent. */
  onSubmit?: ((expenses: Expense[]) => unknown) | undefined;
  /** Keeps the report as a draft, from the menu beside Send for approval. Reject when it can't be saved. */
  onSaveDraft?: ((expenses: Expense[]) => unknown) | undefined;
  /** The expenses are still loading: a placeholder in their place. Default: false. */
  loading?: boolean | undefined;
  /** The expenses failed to load: a "Couldn’t load your expenses" message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads them again, from Try again. Return a promise: the button shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const CATEGORIES = [
  { value: 'travel', label: 'Travel' },
  { value: 'hotel', label: 'Hotel' },
  { value: 'meals', label: 'Meals' },
  { value: 'other', label: 'Something else' },
];
const demo: Expense[] = [
  { id: 'e1', date: '2026-02-03', category: 'travel', what: 'Train to Bandung', amount: 18 },
  { id: 'e2', date: '2026-02-03', category: 'hotel', what: 'Hotel, 2 nights', amount: 140, receipt: 'hotel-invoice.pdf' },
];
type Draft = { date: string; category: string; what: string; amount: number | null; receipt: File | null };
type Problems = Partial<Record<'date' | 'category' | 'what' | 'amount' | 'receipt', string>>;
const iso = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

/** What's wrong with an expense, by field, in the order of the form, or {} when it can be added. */
export function expenseProblems(d: Draft, today: string, receiptOver: number): Problems {
  const out: Problems = {};
  if (!d.date) out.date = 'Enter the date you spent it.';
  else if (d.date > today) out.date = 'Enter a date that isn’t in the future.';
  if (!d.category) out.category = 'Choose what it was for.';
  if (!d.what.trim()) out.what = 'Say what it was, like “Taxi to the client”.';
  if (d.amount === null || !(d.amount > 0)) out.amount = 'Enter how much it cost.';
  else if (d.amount > receiptOver && !d.receipt) out.receipt = `Add the receipt: it’s needed over ${receiptOver}.`;
  return out;
}

/** The expenses that need a receipt and have none. */
export const missingReceipts = (expenses: readonly Expense[], receiptOver: number) => expenses.filter((e) => e.amount > receiptOver && !e.receipt);

/** The report's page: a skip link, a header, then main with the h1, the add form, the expenses and Send. */
/** The add form's parts, in the order they show. */
const PARTS = ['date', 'category', 'what', 'amount', 'receipt'] as const;

export function ExpenseReport({ title = 'Trip to Bandung, February', expenses = demo, currency = 'USD', receiptOver = 25, today = iso(new Date()), onSubmit, onSaveDraft, loading = false, loadFailed = false, onRetry, online }: ExpenseReportProps) {
  const locale = useLocale();
  const blank: Draft = { date: today, category: '', what: '', amount: null, receipt: null };
  const [list, setList] = React.useState(expenses);
  // What the app passes once loading ends replaces what was there, which was empty or the demo.
  const [wasLoading, setWasLoading] = React.useState(loading);
  if (wasLoading !== loading) { setWasLoading(loading); if (!loading) { setList(expenses); } }
  const [d, setD] = React.useState<Draft>(blank);
  const needsReceipt = d.amount !== null && d.amount > receiptOver;   // so the receipt is marked required, not optional, once the amount needs one
  const [problems, setProblems] = React.useState<Problems>({});
  const [tries, setTries] = React.useState(0);
  const [reportProblem, setReportProblem] = React.useState<string | null>(null);
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const [sent, setSent] = React.useState(false);
  const answer = React.useRef<HTMLHeadingElement>(null);
  const money = (n: number) => formatNumber(n, locale, { style: 'currency', currency });
  const total = list.reduce((s, e) => s + e.amount, 0);
  const label = (c: string) => CATEGORIES.find((x) => x.value === c)?.label ?? c;
  const edit = (patch: Partial<Draft>) => setD((now) => ({ ...now, ...patch }));

  const errors: ErrorSummaryItem[] = PARTS.filter((k) => problems[k]).map((k) => ({ field: `expense-${k}`, message: problems[k] }));

  const add = (e: React.FormEvent) => {
    e.preventDefault();
    const found = expenseProblems(d, today, receiptOver);
    setProblems(found);
    setTries((t) => t + 1);
    if (PARTS.some((k) => found[k])) return;
    const added: Expense = { id: `n${Date.now()}`, date: d.date, category: d.category, what: d.what.trim(), amount: d.amount!, receipt: d.receipt?.name };
    const next = [...list, added];
    setList(next); setD(blank); setReportProblem(null);
    announce(`Added ${added.what}, ${money(added.amount)}. Total ${money(next.reduce((s, x) => s + x.amount, 0))}.`);
  };
  const remove = (x: Expense) => {
    const at = list.indexOf(x), after = list[at + 1] ?? list[at - 1];
    const next = list.filter((y) => y.id !== x.id);
    setList(next);
    announce(`Removed ${x.what}. Total ${money(next.reduce((s, y) => s + y.amount, 0))}.`);
    requestAnimationFrame(() => (after ? document.getElementById(`expense-remove-${after.id}`) : document.querySelector<HTMLElement>('#expense-date input, #expense-date select'))?.focus());
  };
  // Save as draft keeps the report as it is, sent nowhere yet; it's said once saved, or says it failed.
  const [draftFailed, setDraftFailed] = React.useState(false);
  const saveDraft = () => {
    setDraftFailed(false);
    void Promise.resolve().then(() => onSaveDraft?.(list)).then(() => announce('Draft saved'), () => setDraftFailed(true));
  };
  const send = () => {
    setFailed(false);
    const missing = missingReceipts(list, receiptOver);
    const found = !list.length ? 'Add at least one expense first.' : missing.length ? `Add the receipt for ${missing.map((m) => m.what).join(', ')}: receipts are needed over ${money(receiptOver)}.` : null;
    setReportProblem(found);
    if (found) return;
    setBusy(true);
    void Promise.resolve().then(() => onSubmit?.(list)).then(() => setSent(true), () => setFailed(true)).finally(() => setBusy(false));
  };
  React.useEffect(() => { if (sent) answer.current?.focus(); }, [sent]);

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme expenses</p>
        <Link underline="hover" href="#reports">Your reports</Link>
      </header>
      <Container as="main" size="lg" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">Your expenses stay here. Sending the report needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Your reports', href: '#reports' }, { label: title }]} title={title}
            description={`Add each thing you paid for, then send the report to your manager. Receipts are needed over ${money(receiptOver)}.`} />
          {loadFailed ? <div className="pt-6"><EmptyLoadFailed title="Couldn’t load your expenses" onRetry={() => onRetry?.()} headingLevel={2} /></div>
            : loading ? <Card className="mt-6"><Skeleton shape="text" lines={6} label="Loading expenses" /></Card> : (<>
          <div className="flex flex-col gap-8 pt-6">
            {sent ? (
              <section aria-labelledby="report-sent" className="flex flex-col items-start gap-3">
                <h2 id="report-sent" ref={answer} tabIndex={-1} className="m-0 text-2xl font-semibold outline-none">Sent for approval</h2>
                <p className="m-0">{list.length === 1 ? '1 expense' : `${formatNumber(list.length, locale)} expenses`}, {money(total)} in all. Once your manager approves it, it’s paid with your next salary; we’ll email you either way.</p>
                <Link href="#reports">Back to your reports</Link>
              </section>
            ) : (
              <>
                <Card data-print="hide">
                  <form onSubmit={add} noValidate aria-labelledby="add-expense" className="flex flex-col gap-4">
                    <h2 id="add-expense" className="m-0 text-lg font-semibold">Add an expense</h2>
                    <ErrorSummary key={tries} errors={errors} headingLevel={3} />
                    <p className="m-0 text-text-muted">Fields marked * are required.</p>
                    <div className="grid gap-4 sm:grid-cols-2">
                      <Field label="Date" error={problems.date} required>
                        <DateField id="expense-date" value={d.date} max={today} onValueChange={(v) => edit({ date: v })} />
                      </Field>
                      <Field label="What for" id="expense-category" error={problems.category} required>
                        <Select placeholder="Choose one" options={CATEGORIES} value={d.category} onChange={(e) => edit({ category: e.target.value })} />
                      </Field>
                      <Field label="What it was" id="expense-what" hint="As it says on the receipt." error={problems.what} required>
                        <Input value={d.what} onChange={(e) => edit({ what: e.target.value })} />
                      </Field>
                      <Field label="Amount" id="expense-amount" hint={`In ${currency}.`} error={problems.amount} required>
                        <NumberInput currency={currency} min={0} value={d.amount} onValueChange={(n) => edit({ amount: n })} className="max-w-48" />
                      </Field>
                    </div>
                    <Field label="Receipt" error={problems.receipt} required={needsReceipt} optional={!needsReceipt}>
                      <FileUpload id="expense-receipt" accept="image/*,.pdf" maxSize={10 * 1024 * 1024} hint={`A photo or PDF. Needed over ${money(receiptOver)}.`}
                        files={d.receipt ? [d.receipt] : []} onFilesChange={(f) => edit({ receipt: f.at(-1) ?? null })} />
                    </Field>
                    <Button type="submit" variant="secondary" className="self-start">Add expense</Button>
                  </form>
                </Card>

                <section aria-labelledby="expenses" className="flex flex-col gap-4">
                  <h2 id="expenses" className="m-0 text-lg font-semibold">Expenses</h2>
                  {list.length ? (
                    <Table caption="Expenses in this report, with the total" hideCaption pinEnd>
                      <TableHead><TableRow>
                        <TableHeaderCell>Date</TableHeaderCell>
                        <TableHeaderCell>What</TableHeaderCell>
                        <TableHeaderCell align="end">Amount</TableHeaderCell>
                        <TableHeaderCell>Receipt</TableHeaderCell>
                        <TableHeaderCell data-print="hide"><span className="sr-only">Remove</span></TableHeaderCell>
                      </TableRow></TableHead>
                      <TableBody>
                        {list.map((x) => (
                          <TableRow key={x.id}>
                            <TableCell className="whitespace-nowrap"><FormattedDate value={x.date} /></TableCell>
                            <TableCell className="wrap-break-word">{x.what}<span className="block text-sm text-text-muted">{label(x.category)}</span></TableCell>
                            <TableCell className="text-end tabular-nums">{money(x.amount)}</TableCell>
                            <TableCell>{x.receipt ? <span className="wrap-anywhere">{x.receipt}</span> : x.amount > receiptOver ? <Badge tone="warning">Receipt needed</Badge> : <span className="text-text-muted">Not needed</span>}</TableCell>
                            <TableCell data-print="hide"><Button id={`expense-remove-${x.id}`} size="sm" variant="ghost" onClick={() => remove(x)} aria-label={`Remove: ${x.what}`}>Remove</Button></TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                      <TableFoot>
                        <TableRow>
                          <TableCell colSpan={2} className="font-semibold">Total</TableCell>
                          <TableCell className="text-end font-semibold tabular-nums">{money(total)}</TableCell>
                          <TableCell /><TableCell data-print="hide" />
                        </TableRow>
                      </TableFoot>
                    </Table>
                  ) : <p className="m-0 text-text-muted">None yet. Each one you add shows here, with the total.</p>}
                </section>

                <div data-print="hide" className="flex flex-col items-start gap-3">
                  {reportProblem ? <Alert tone="danger">{reportProblem}</Alert> : null}
                  {failed ? <Alert tone="danger">Couldn’t send the report. Try again; nothing is lost.</Alert> : null}
                  {draftFailed ? <Alert tone="danger">Couldn’t save the draft. Try again; nothing is lost.</Alert> : null}
                  <SplitButton loading={busy} onClick={send} menuLabel="More ways to save the report"
                    menu={<MenuItem icon="draft" onSelect={saveDraft}>Save as draft</MenuItem>}>Send for approval</SplitButton>
                </div>
              </>
            )}
          </div>
          </>)}
        </Stack>
      </Container>
    </div>
  );
}

files.FeedbackSurvey.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { Textarea } from '@diki-stwn/serupa-ds';
import { Rating } from '@diki-stwn/serupa-ds';
import { RadioGroup, Radio } from '@diki-stwn/serupa-ds';
import { Checkbox, CheckboxGroup } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Feedback survey: a few questions after something happened (a visit, an order, a call): a rating, what you came to
   do, what could be better, your words, and whether we may write back. For an app to copy. What it carries (WCAG 2.2):
   - 1.3.1, 4.1.2: the rating is a named group of radios, one per star, each named with its number ("3 stars"), so
     it's chosen with the arrow keys and read as a choice, not a picture.
   - 3.3.2: the page says how many questions there are and which one is needed; each optional one says so.
   - 1.3.1: the choices are named groups, radios for one answer and checkboxes for several.
   - 3.3.1: a missing rating, or an email asked for and not given, is said next to its question when you send, and
     focus goes to the first; the email field shows only once you've said we may write back.
   - 1.3.5: the email field says what it's for autofill.
   - 3.3.4, 4.1.3: Send shows it's busy and thanks you only once the server says so; one that fails says so next to the
     button and keeps every answer.
   - 2.4.3, 4.1.3: once sent, the questions give way to a thank-you whose heading takes focus.
   Sending is the app's job: onSend gets the answers; reject its promise when they can't be sent. */

export interface SurveyAnswers {
  /** 1 to 5, or null when not chosen. */
  rating: number | null;
  /** What they came to do, one of the topic values, or empty. */
  reason: string;
  /** What could be better, any of the improvement values. */
  better: string[];
  comments: string;
  /** They said we may write back. */
  contact: boolean;
  /** Where to write, when contact is on. */
  email: string;
}

export interface FeedbackSurveyProps {
  /** What the survey is about, for the h1: "your visit". Default: "your visit". */
  about?: string | undefined;
  /** Sends the answers. Return its promise: a rejection keeps them and says so. */
  onSend?: ((answers: SurveyAnswers) => unknown) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const REASONS = [
  { value: 'buy', label: 'To buy something' },
  { value: 'return', label: 'To return or change something' },
  { value: 'ask', label: 'To ask a question' },
  { value: 'browse', label: 'Just to look around' },
];
const BETTER = [
  { value: 'wait', label: 'Waiting time' },
  { value: 'staff', label: 'Help from staff' },
  { value: 'stock', label: 'What was in stock' },
  { value: 'price', label: 'Prices' },
];
const empty: SurveyAnswers = { rating: null, reason: '', better: [], comments: '', contact: false, email: '' };

/** What's missing from the answers, by question, or {} when they can be sent. */
export function surveyProblems(a: SurveyAnswers): Partial<Record<'rating' | 'email', string>> {
  const out: Partial<Record<'rating' | 'email', string>> = {};
  if (!a.rating) out.rating = 'Choose a rating from 1 to 5 stars.';
  if (a.contact) {
    if (!a.email.trim()) out.email = 'Enter your email address, or untick “You may write back to me”.';
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(a.email.trim())) out.email = 'Enter an email address like name@example.com.';
  }
  return out;
}

/** The survey page: a skip link, a header, then main with the h1 and the questions, or the thanks. */
export function FeedbackSurvey({ about = 'your visit', onSend, online }: FeedbackSurveyProps) {
  const [answers, setAnswers] = React.useState<SurveyAnswers>(empty);
  const [problems, setProblems] = React.useState<ReturnType<typeof surveyProblems>>({});
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const [sent, setSent] = React.useState(false);
  const rating = React.useRef<HTMLDivElement>(null);
  const thanks = React.useRef<HTMLHeadingElement>(null);
  const edit = (patch: Partial<SurveyAnswers>) => { setAnswers((now) => ({ ...now, ...patch })); setFailed(false); };

  const send = (e: React.FormEvent) => {
    e.preventDefault();
    setFailed(false);
    const found = surveyProblems(answers);
    setProblems(found);
    if (found.rating) { rating.current?.querySelector<HTMLInputElement>('input')?.focus(); return; }
    if (found.email) { document.getElementById('survey-email')?.focus(); return; }
    const out: SurveyAnswers = { ...answers, comments: answers.comments.trim(), email: answers.contact ? answers.email.trim() : '' };
    setBusy(true);
    void Promise.resolve().then(() => onSend?.(out)).then(() => setSent(true), () => setFailed(true)).finally(() => setBusy(false));
  };
  React.useEffect(() => { if (sent) thanks.current?.focus(); }, [sent]);

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <Container as="main" size="prose" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">Your answers stay here. Sending them needs a connection.</OfflineBanner>
          <PageHeader title={`How was ${about}?`} description="Four questions. Only the first is needed, and it takes a few seconds." />
          <div className="pt-6">
            {sent ? (
              <section aria-labelledby="thanks" className="flex flex-col items-start gap-3">
                <h2 id="thanks" ref={thanks} tabIndex={-1} className="m-0 text-2xl font-semibold outline-none">Thank you</h2>
                <p className="m-0">We read every answer. {answers.contact ? 'If we write back, it’ll be to the address you gave.' : 'You won’t hear from us about this.'}</p>
              </section>
            ) : (
              <form onSubmit={send} noValidate aria-label="Survey" className="flex flex-col gap-6">
                <p className="m-0 text-text-muted">Fields marked * are required.</p>
                <Field label="How would you rate it?" error={problems.rating} required>
                  <Rating ref={rating} value={answers.rating} onValueChange={(v) => { edit({ rating: v }); setProblems((p) => ({ ...p, rating: undefined })); }} invalid={!!problems.rating} size="lg" />
                </Field>
                <Field label="What did you come to do?" optional group>
                  <RadioGroup name="survey-reason" value={answers.reason || null} onValueChange={(v: string) => edit({ reason: v })}>
                    {REASONS.map((r) => <Radio key={r.value} value={r.value}>{r.label}</Radio>)}
                  </RadioGroup>
                </Field>
                <Field label="What could be better?" hint="Choose any." optional group>
                  <CheckboxGroup name="survey-better" value={answers.better} onValueChange={(v: string[]) => edit({ better: v })}>
                    {BETTER.map((b) => <Checkbox key={b.value} value={b.value}>{b.label}</Checkbox>)}
                  </CheckboxGroup>
                </Field>
                <Field label="Anything else?" optional>
                  <Textarea rows={4} value={answers.comments} onChange={(e) => edit({ comments: e.target.value })} />
                </Field>
                <Checkbox checked={answers.contact} onCheckedChange={(on) => { edit({ contact: on }); if (!on) setProblems((p) => ({ ...p, email: undefined })); }}
                  description="Only about what you wrote here.">You may write back to me</Checkbox>
                {answers.contact ? (
                  <Field label="Email" id="survey-email" error={problems.email} required>
                    <Input type="email" autoComplete="email" value={answers.email} onChange={(e) => edit({ email: e.target.value })} />
                  </Field>
                ) : null}
                <div className="flex flex-col items-start gap-3">
                  {failed ? <Alert tone="danger">Couldn’t send your answers. Try again; they’re all still here.</Alert> : null}
                  <Button type="submit" loading={busy}>Send</Button>
                </div>
              </form>
            )}
          </div>
        </Stack>
      </Container>
    </div>
  );
}

files.FileBrowser.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { IconButton } from '@diki-stwn/serupa-ds';
import { Dialog } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { TreeView, type TreeViewItem } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Menu, MenuItem } from '@diki-stwn/serupa-ds';
import { Toaster, toast } from '@diki-stwn/serupa-ds';
import { EmptyState } from '@diki-stwn/serupa-ds';
import { RelativeTime } from '@diki-stwn/serupa-ds';
import { List, ListItem, ListSelectAll, ListLoadingItems } from '@diki-stwn/serupa-ds';
import { TableActionBar } from '@diki-stwn/serupa-ds';
import { formatFileSize } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { EmptyLoadFailed } from './EmptyStates';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* File browser: one folder's files as a list people pick from, to move or delete several at once, with rename, move
   and delete on each row too. For an app to copy. What it carries (WCAG 2.2):
   - 1.3.1, 4.1.2: the files are a List with selectionMode="multiple": a grid with one Tab stop, each row named by its
     file and said as selected or not, with a checkbox for the pointer. Select all sits above it.
   - 2.1.1: Space picks the focused row, Shift with the arrows picks a run, Ctrl or Cmd+A picks every file; each row's
     More menu is reached with Right.
   - 4.1.3: the bar above the list says how many are picked ("3 selected") as the count changes, since it appears away
     from the row that was pressed.
   - 2.4.6: each More button is named with its file ("More for Logo.svg"), so a list of them isn't "More, More, More".
   - 3.3.4: a delete happens at once, with Undo in a toast, for one file or many; it's final only when the toast
     goes, so nothing asks "Are you sure?" first.
   - 2.4.3: after a delete or a move, focus goes to the list (or to the page's h1 when the folder is now empty), never
     to the top of the page. After a rename it goes back to the file's More button.
   - 3.3.1, 3.3.3: an empty or taken name is said next to the field, which keeps focus; a move with no folder chosen
     says so; a move or rename that fails says so in its dialog, which stays open with what was chosen.
   - 4.1.3, 3.3.1: while the files load, the list is busy with placeholder rows, named once; a failed load says so,
     with Try again; an empty folder says so, with the way to add the first file.
   Storing the changes is the app's job: onDelete, onMove and onRename get them, and onUpload gets Upload files. */

export type FileKind = 'folder' | 'image' | 'pdf' | 'doc' | 'sheet' | 'other';
export interface BrowserFile {
  id: string;
  /** With its extension: "Logo.svg". */
  name: string;
  /** Picks the row's icon. Default: 'other'. */
  kind?: FileKind | undefined;
  /** Its size in bytes. Leave it out for a folder. */
  bytes?: number | undefined;
  /** When it last changed: a Date, a time in ms, or an ISO string. */
  modified: Date | number | string;
  /** Where the file opens. With it, the row's name is a link. */
  href?: string | undefined;
}
export interface BrowserFolder {
  id: string;
  name: string;
  /** The folders inside it, shown under it in the move dialog's tree. */
  children?: readonly BrowserFolder[] | undefined;
}

export interface FileBrowserProps {
  /** The folder's name: the page's h1. Default: "Brand assets". */
  folder?: string | undefined;
  /** The folders above this one, from the top, each with an href. Default: Files. */
  path?: { label: string; href: string }[] | undefined;
  /** The folder's files. Default: six demo files. */
  files?: readonly BrowserFile[] | undefined;
  /** The folders files can move to. Default: three demo folders. */
  folders?: readonly BrowserFolder[] | undefined;
  /** The files picked at first, by id. Default: none. */
  defaultSelected?: string[] | undefined;
  /** Files were deleted and their Undo has passed. */
  onDelete?: ((ids: string[]) => void) | undefined;
  /** Move was pressed with a folder chosen. Return its promise: a rejection keeps the dialog open and says so. */
  onMove?: ((ids: string[], folderId: string) => unknown) | undefined;
  /** A new name was saved. Return its promise: a rejection keeps the dialog open and says so. */
  onRename?: ((id: string, name: string) => unknown) | undefined;
  /** Upload files was pressed. */
  onUpload?: (() => void) | undefined;
  /** The files are on their way: placeholder rows, named once ("Loading files"). Default: false. */
  loading?: boolean | undefined;
  /** The files failed to load: a message with Try again, which calls onRetry, in their place. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads the files again, after a failed load. */
  onRetry?: (() => void) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const now = Date.now();
const DAY = 86400_000;
const demoFiles: BrowserFile[] = [
  { id: 'f1', name: 'Logos', kind: 'folder', modified: now - 2 * DAY },
  { id: 'f2', name: 'Brand guidelines.pdf', kind: 'pdf', bytes: 4_820_000, modified: now - 3 * 3600_000 },
  { id: 'f3', name: 'Logo.svg', kind: 'image', bytes: 18_400, modified: now - 6 * DAY },
  { id: 'f4', name: 'Launch photo.jpg', kind: 'image', bytes: 3_400_000, modified: now - 9 * DAY },
  { id: 'f5', name: 'Press release.docx', kind: 'doc', bytes: 24_000, modified: now - 20 * DAY },
  { id: 'f6', name: 'Budget 2026.xlsx', kind: 'sheet', bytes: 88_000, modified: now - 41 * DAY },
];
const demoFolders: BrowserFolder[] = [{ id: 'd1', name: 'Archive' },
  { id: 'd2', name: 'Marketing', children: [{ id: 'd4', name: 'Campaigns' }, { id: 'd5', name: 'Social' }] }, { id: 'd3', name: 'Shared with clients' }];
/** The folders as the tree's items, and every folder by id at any depth. */
const toItems = (list: readonly BrowserFolder[]): TreeViewItem[] => list.map((d) => ({ id: d.id, label: d.name, icon: 'folder', ...(d.children?.length ? { children: toItems(d.children) } : null) }));
const findFolder = (list: readonly BrowserFolder[], id: string): BrowserFolder | undefined => {
  for (const d of list) { const hit = d.id === id ? d : d.children && findFolder(d.children, id); if (hit) return hit; }
  return undefined;
};
const ICON: Record<FileKind, string> = { folder: 'folder', image: 'image', pdf: 'picture_as_pdf', doc: 'description', sheet: 'table_chart', other: 'draft' };

/** "1 file" or "3 files": English's rule, since the words are English; an app translating them uses its own. */
export const countFiles = (n: number, locale = 'en-US'): string => (n === 1 ? '1 file' : `${formatNumber(n, locale)} files`);

/** What's wrong with a new name, or null: empty, or one another file here already has (whatever its case). */
export function nameProblem(name: string, id: string, files: readonly BrowserFile[]): string | null {
  const kept = name.trim();
  if (!kept) return 'Enter a name.';
  if (files.some((f) => f.id !== id && f.name.toLowerCase() === kept.toLowerCase())) return `“${kept}” is already in this folder. Choose another name.`;
  return null;
}

/** The file browser: a skip link, a header, then main with the folder's h1, the selection bar and the list. */
export function FileBrowser({ folder = 'Brand assets', path = [{ label: 'Files', href: '#files' }], files: all = demoFiles, folders = demoFolders,
  defaultSelected, onDelete, onMove, onRename, onUpload, loading = false, loadFailed = false, onRetry, online }: FileBrowserProps) {
  const locale = useLocale();
  // What's shown: the files, less those deleted or moved away, with any new names.
  const [hidden, setHidden] = React.useState<ReadonlySet<string>>(new Set());
  const [names, setNames] = React.useState<Readonly<Record<string, string>>>({});
  const files = all.filter((f) => !hidden.has(f.id)).map((f) => (names[f.id] ? { ...f, name: names[f.id]! } : f));
  const [picked, setPicked] = React.useState<string[]>(defaultSelected ?? []);
  const chosen = picked.filter((id) => files.some((f) => f.id === id));

  const title = React.useRef<HTMLHeadingElement>(null);
  const later = (f: () => void) => requestAnimationFrame(f);
  // The list is one Tab stop: its focusable row. With no rows left, the h1.
  const toList = (left: number) => later(() => {
    const row = left ? document.querySelector<HTMLElement>('#file-list [tabindex="0"]') : null;
    (row ?? title.current)?.focus();
  });
  const hide = (ids: string[]) => setHidden((h) => { const n = new Set(h); for (const id of ids) n.add(id); return n; });
  const show = (ids: string[]) => setHidden((h) => { const n = new Set(h); for (const id of ids) n.delete(id); return n; });
  const said = (ids: string[]) => (ids.length === 1 ? `“${files.find((f) => f.id === ids[0])?.name ?? ''}”` : countFiles(ids.length, locale));

  // Deleting: at once, with Undo. It's final when the toast goes.
  const remove = (ids: string[]) => {
    if (!ids.length) return;
    const what = said(ids);
    hide(ids);
    setPicked((p) => p.filter((id) => !ids.includes(id)));
    toList(files.length - ids.length);
    toast.undo({
      title: `Deleted ${what}`,
      commit: () => onDelete?.(ids),
      onUndo: () => { show(ids); toList(1); },
    });
  };

  // Moving: a dialog with the folders as a tree, one to choose.
  const [moving, setMoving] = React.useState<string[] | null>(null);
  const [target, setTarget] = React.useState('');
  const [moveError, setMoveError] = React.useState<string | null>(null);
  const [moveFailed, setMoveFailed] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  const askMove = (ids: string[]) => { setTarget(''); setMoveError(null); setMoveFailed(false); setMoving(ids); };
  const move = (e: React.FormEvent) => {
    e.preventDefault();
    const ids = moving ?? [];
    if (!target) { setMoveError('Choose a folder.'); return; }
    const to = findFolder(folders, target)?.name ?? '';
    const what = said(ids);
    setMoveFailed(false);
    setBusy(true);
    void Promise.resolve().then(() => onMove?.(ids, target)).then(() => {
      setMoving(null);
      hide(ids);
      setPicked((p) => p.filter((id) => !ids.includes(id)));
      toast({ title: `Moved ${what} to ${to}`, tone: 'success' });
      toList(files.length - ids.length);
    }, () => setMoveFailed(true)).finally(() => setBusy(false));
  };

  // Renaming: a dialog with the name, checked before it's sent.
  const [renaming, setRenaming] = React.useState<BrowserFile | null>(null);
  const [name, setName] = React.useState('');
  const [nameError, setNameError] = React.useState<string | null>(null);
  const [renameFailed, setRenameFailed] = React.useState(false);
  const moreButton = React.useRef<HTMLElement | null>(null);
  const askRename = (f: BrowserFile) => {
    moreButton.current = document.getElementById(`more-${f.id}`);
    setName(f.name); setNameError(null); setRenameFailed(false); setRenaming(f);
  };
  const rename = (e: React.FormEvent) => {
    e.preventDefault();
    const f = renaming;
    if (!f) return;
    const problem = nameProblem(name, f.id, files);
    if (problem) { setNameError(problem); document.getElementById('file-name')?.focus(); return; }
    const kept = name.trim();
    if (kept === f.name) { setRenaming(null); return; }
    setRenameFailed(false);
    setBusy(true);
    void Promise.resolve().then(() => onRename?.(f.id, kept)).then(() => {
      setNames((n) => ({ ...n, [f.id]: kept }));
      setRenaming(null);
      toast({ title: `Renamed to “${kept}”`, tone: 'success' });
    }, () => setRenameFailed(true)).finally(() => setBusy(false));
  };

  const upload = { label: 'Upload files', icon: 'upload', onSelect: () => onUpload?.() };
  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <Container as="main" size="lg" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">These are the files loaded before you went offline. Opening, moving or uploading needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[...path, { label: folder }]} title={folder} headingRef={title} primary={upload}
            description={loading || loadFailed ? undefined : countFiles(files.length, locale)} />

          <div className="flex flex-col gap-3 pt-6">
            {loadFailed ? <EmptyLoadFailed title="Couldn’t load the files" onRetry={() => onRetry?.()} headingLevel={2} />
              : !loading && !files.length ? (
                <EmptyState icon="folder_open" title="This folder is empty" headingLevel={2} description="Upload files to keep them here, or move some in from another folder."
                  actions={<Button startIcon="upload" onClick={() => onUpload?.()}>Upload files</Button>} />
              ) : <>
                {loading ? null : (
                  <div className="flex min-h-10 flex-wrap items-center gap-3">
                    <ListSelectAll values={files.map((f) => f.id)} selected={chosen} onSelectedChange={setPicked} />
                    <TableActionBar count={chosen.length} onClear={() => setPicked([])} className="flex-1">
                      <Button size="sm" variant="outline" startIcon="drive_file_move" onClick={() => askMove(chosen)}>Move</Button>
                      <Button size="sm" variant="outline" destructive startIcon="delete" onClick={() => remove(chosen)}>Delete</Button>
                    </TableActionBar>
                  </div>
                )}
                <List id="file-list" aria-label={`Files in ${folder}`} variant="card" loading={loading} selectionMode={loading ? 'none' : 'multiple'}
                  selected={chosen} onSelectedChange={setPicked}>
                  {loading ? <ListLoadingItems rows={5} showDescription leading="icon" label="Loading files" /> : files.map((f) => (
                    <ListItem key={f.id} value={f.id} href={f.href} leading={ICON[f.kind ?? 'other']} title={f.name}
                      description={<>{f.kind === 'folder' ? 'Folder' : f.bytes != null ? formatFileSize(f.bytes, locale) : null}{f.kind === 'folder' || f.bytes != null ? ', ' : null}<span className="whitespace-nowrap">changed <RelativeTime date={f.modified} /></span></>}
                      trailing={(
                        <Menu placement="bottom-end" trigger={<IconButton id={`more-${f.id}`} icon="more_vert" label={`More for ${f.name}`} size="sm" variant="ghost" hideTitle />}>
                          <MenuItem icon="edit" onSelect={() => askRename(f)}>Rename</MenuItem>
                          <MenuItem icon="drive_file_move" onSelect={() => askMove([f.id])}>Move</MenuItem>
                          <MenuItem icon="delete" destructive onSelect={() => remove([f.id])}>Delete</MenuItem>
                        </Menu>
                      )} />
                  ))}
                </List>
              </>}
          </div>

          <Dialog open={moving != null} onOpenChange={(o) => { if (!o) setMoving(null); }} title={`Move ${moving ? said(moving) : ''}`}
            description="Choose the folder to move to.">
            <form onSubmit={move} noValidate className="flex flex-col gap-4">
              {moveFailed ? <Alert tone="danger">Couldn’t move {moving ? said(moving) : ''}. Try again.</Alert> : null}
              <p className="m-0 text-text-muted">Fields marked * are required.</p>
              <Field group label="Folder" error={moveError ?? undefined} required>
                <TreeView aria-label="Folders" items={toItems(folders)} selectionMode="single" value={target ? [target] : []}
                  onValueChange={(v) => { setTarget(v[0] ?? ''); setMoveError(null); }} />
              </Field>
              <div className="flex flex-wrap gap-2">
                <Button type="submit" loading={busy}>Move</Button>
                <Button variant="outline" onClick={() => setMoving(null)}>Cancel</Button>
              </div>
            </form>
          </Dialog>

          <Dialog open={renaming != null} onOpenChange={(o) => { if (!o) setRenaming(null); }} title="Rename" finalFocus={moreButton}>
            <form onSubmit={rename} noValidate className="flex flex-col gap-4">
              {renameFailed ? <Alert tone="danger">Couldn’t rename “{renaming?.name}”. Try again.</Alert> : null}
              <Field label="Name" id="file-name" error={nameError ?? undefined} required>
                <Input name="name" value={name} autoComplete="off" onChange={(e) => { setName(e.target.value); if (nameError) setNameError(null); }} />
              </Field>
              <div className="flex flex-wrap gap-2">
                <Button type="submit" loading={busy}>Rename</Button>
                <Button variant="outline" onClick={() => setRenaming(null)}>Cancel</Button>
              </div>
            </form>
          </Dialog>
        </Stack>
      </Container>
      <Toaster />
    </div>
  );
}

files.GiftCard.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { DateField } from '@diki-stwn/serupa-ds';
import { DescriptionList, DescriptionItem } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Image } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { NumberInput } from '@diki-stwn/serupa-ds';
import { RadioGroup, Radio } from '@diki-stwn/serupa-ds';
import { Textarea } from '@diki-stwn/serupa-ds';
import { ErrorSummary, type ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { formatDate } from '@diki-stwn/serupa-ds';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Gift card: choose an amount and a design, say who it's for and when to send it, see what they'll get, and add it to
   the bag. For an app to copy. What it carries (WCAG 2.2):
   - 1.3.1: the amounts and the designs are groups of radios named by their question; Another amount brings a number
     field right after it.
   - 3.3.2, 1.3.5: each field says what it's for and which are optional; the amounts say the lowest and highest; the
     email says it's where the card goes.
   - 1.3.1, 4.1.3: the preview is a named region that shows the card as they'll get it, in words as well as the picture.
   - 3.3.1, 2.4.3: adding with problems shows a summary at the top that takes focus, each problem a link to its field.
   - 3.3.4, 4.1.3: Add to bag shows it's busy; one that can't be added says so and keeps everything.
   - 2.4.3: once added, the answer's heading takes focus, with what was added and when it's sent.
   Paying and sending are the app's job: onAdd gets the gift; reject when it can't be added. */

export interface Gift {
  amount: number;
  design: string;
  to: string;
  email: string;
  message: string;
  /** When to send it, as YYYY-MM-DD. */
  send: string;
  from: string;
}

export interface GiftCardProps {
  /** The money it's in. Default: "USD". */
  currency?: string | undefined;
  /** The amounts to choose from. Default: 25, 50 and 100. */
  amounts?: number[] | undefined;
  /** The lowest and highest amount. Default: 10 and 500. */
  min?: number | undefined;
  max?: number | undefined;
  /** Today, as YYYY-MM-DD: the first day it can be sent. Default: today. */
  today?: string | undefined;
  /** Adds the gift card to the bag. Reject when it can't be added. */
  onAdd?: ((gift: Gift) => unknown) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const art = (bg: string, fg: string, shape: string) => 'data:image/svg+xml,' + encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="480" height="300" viewBox="0 0 480 300"><rect width="480" height="300" fill="${bg}"/>${shape.replaceAll('F', fg)}</svg>`);
export const GIFT_DESIGNS = [
  { id: 'confetti', label: 'Confetti', image: art('#28305e', '#f2c14e', '<circle cx="60" cy="50" r="10" fill="F"/><circle cx="400" cy="80" r="14" fill="F"/><rect x="200" y="200" width="18" height="18" fill="F" transform="rotate(30 209 209)"/><circle cx="120" cy="230" r="8" fill="F"/><rect x="330" y="220" width="14" height="14" fill="F"/>') },
  { id: 'leaves', label: 'Leaves', image: art('#e5eedc', '#4c7a3d', '<path d="M60 260 Q120 140 240 120 Q180 240 60 260Z" fill="F"/><path d="M420 40 Q380 140 280 170 Q300 70 420 40Z" fill="F"/>') },
  { id: 'plain', label: 'Plain', image: art('#ece8e1', '#1f1f1f', '<rect x="24" y="24" width="432" height="252" fill="none" stroke="F" stroke-width="2"/>') },
];
const FIELDS = ['amount', 'other', 'to', 'email', 'message', 'send', 'from'] as const;
type Problems = Partial<Record<(typeof FIELDS)[number], string>>;
type Draft = Omit<Gift, 'amount'> & { amount: string; other: number | null };
const iso = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
const MESSAGE = 200;

/** What's wrong with a gift card, by field, in the order of the form, or {} when it can be added. */
export function giftProblems(d: Draft, today: string, min: number, max: number, money: (n: number) => string = String): Problems {
  const out: Problems = {};
  if (!d.amount) out.amount = 'Choose an amount.';
  else if (d.amount === 'other' && (d.other === null || d.other < min || d.other > max)) out.other = `Enter an amount from ${money(min)} to ${money(max)}.`;
  if (!d.to.trim()) out.to = 'Enter who it’s for.';
  if (!d.email.trim()) out.email = 'Enter their email address: that’s where it’s sent.';
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.email.trim())) out.email = 'Enter an email address like name@example.com.';
  if (d.message.length > MESSAGE) out.message = `Shorten the message to ${MESSAGE} characters.`;
  const yearOn = `${Number(today.slice(0, 4)) + 1}${today.slice(4)}`;
  if (!d.send) out.send = 'Enter the day to send it.';
  else if (d.send < today) out.send = 'Enter today or a day after it.';
  else if (d.send > yearOn) out.send = 'Enter a day within a year.';
  if (!d.from.trim()) out.from = 'Enter your name, so they know who it’s from.';
  return out;
}

/** The gift card page: a skip link, a header, then main with the h1, and the form and its preview or the answer. */
export function GiftCard({ currency = 'USD', amounts = [25, 50, 100], min = 10, max = 500, today = iso(new Date()), onAdd, online }: GiftCardProps) {
  const locale = useLocale();
  const money = (n: number) => formatNumber(n, locale, { style: 'currency', currency, maximumFractionDigits: 0 });
  const day = (s: string) => formatDate(s, locale, { dateStyle: 'long' });
  const [d, setD] = React.useState<Draft>({ amount: '', other: null, design: 'confetti', to: '', email: '', message: '', send: today, from: '' });
  const [problems, setProblems] = React.useState<Problems>({});
  const [tries, setTries] = React.useState(0);
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const [added, setAdded] = React.useState<Gift | null>(null);
  const answer = React.useRef<HTMLHeadingElement>(null);
  const edit = (patch: Partial<Draft>) => { setD((now) => ({ ...now, ...patch })); setFailed(false); };
  const amount = d.amount === 'other' ? d.other : d.amount ? Number(d.amount) : null;
  const design = GIFT_DESIGNS.find((g) => g.id === d.design) ?? GIFT_DESIGNS[0]!;
  const errors: ErrorSummaryItem[] = FIELDS.filter((f) => problems[f]).map((f) => ({ field: `gift-${f}`, message: problems[f] }));

  const add = (e: React.FormEvent) => {
    e.preventDefault();
    setFailed(false);
    const found = giftProblems(d, today, min, max, money);
    setProblems(found);
    setTries((t) => t + 1);
    if (Object.keys(found).length) return;
    setBusy(true);
    const gift: Gift = { amount: amount!, design: d.design, to: d.to.trim(), email: d.email.trim(), message: d.message.trim(), send: d.send, from: d.from.trim() };
    void Promise.resolve().then(() => onAdd?.(gift)).then(() => setAdded(gift), () => setFailed(true)).finally(() => setBusy(false));
  };
  React.useEffect(() => { if (added) answer.current?.focus(); }, [added]);

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
        <Link underline="hover" href="#bag">Bag</Link>
      </header>
      <Container as="main" size="lg" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">Your choices stay here. Adding the card to your bag needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Shop', href: '#shop' }, { label: 'Gift cards' }]} title="Send a gift card"
            description="Sent by email on the day you choose. It never expires and works in our shops and online." />
          {added ? (
            <section aria-labelledby="gift-added" className="flex flex-col items-start gap-4 pt-6">
              <h2 id="gift-added" ref={answer} tabIndex={-1} className="m-0 text-2xl font-semibold outline-none">Gift card added to your bag</h2>
              <DescriptionList layout="split" className="max-w-md">
                <DescriptionItem term="Amount">{money(added.amount)}</DescriptionItem>
                <DescriptionItem term="For">{added.to}, {added.email}</DescriptionItem>
                <DescriptionItem term="Sent on">{added.send === today ? 'Today, once you’ve paid' : day(added.send)}</DescriptionItem>
              </DescriptionList>
              <div className="flex flex-wrap gap-3">
                <Link href="#bag">Go to your bag</Link>
                <Link href="#shop">Keep shopping</Link>
              </div>
            </section>
          ) : (
            <div className="grid gap-6 pt-6 md:grid-cols-2">
              <form onSubmit={add} noValidate aria-label="Gift card" className="flex flex-col gap-4">
                <ErrorSummary key={tries} errors={errors} />
                <p className="m-0 text-text-muted">Fields marked * are required.</p>
                <Field label="Amount" hint={`From ${money(min)} to ${money(max)}.`} group error={problems.amount} required>
                  <RadioGroup id="gift-amount" name="gift-amount" orientation="horizontal" value={d.amount} onValueChange={(v: string) => edit({ amount: v })}>
                    {amounts.map((a) => <Radio key={a} value={String(a)}>{money(a)}</Radio>)}
                    <Radio value="other">Another amount</Radio>
                  </RadioGroup>
                </Field>
                {d.amount === 'other' ? (
                  <Field label="Your amount" id="gift-other" error={problems.other} required>
                    <NumberInput currency={currency} min={min} max={max} value={d.other} onValueChange={(n) => edit({ other: n })} className="max-w-48" />
                  </Field>
                ) : null}
                <Field label="Design" group>
                  <RadioGroup name="gift-design" orientation="horizontal" value={d.design} onValueChange={(v: string) => edit({ design: v })}>
                    {GIFT_DESIGNS.map((g) => <Radio key={g.id} value={g.id}>{g.label}</Radio>)}
                  </RadioGroup>
                </Field>
                <Field label="Who it’s for" id="gift-to" error={problems.to} required>
                  <Input autoComplete="off" value={d.to} onChange={(e) => edit({ to: e.target.value })} />
                </Field>
                <Field label="Their email" id="gift-email" hint="We send the card here." error={problems.email} required>
                  <Input type="email" autoComplete="off" value={d.email} onChange={(e) => edit({ email: e.target.value })} />
                </Field>
                <Field label="Message" id="gift-message" hint="Printed on the card." error={problems.message} optional>
                  <Textarea rows={3} maxLength={MESSAGE} showCount value={d.message} onChange={(e) => edit({ message: e.target.value })} />
                </Field>
                <Field label="Send on" hint="Today, or any day within a year." error={problems.send} required>
                  <DateField id="gift-send" value={d.send} min={today} onValueChange={(v) => edit({ send: v })} />
                </Field>
                <Field label="From" id="gift-from" error={problems.from} required>
                  <Input autoComplete="name" value={d.from} onChange={(e) => edit({ from: e.target.value })} />
                </Field>
                <div className="flex flex-col items-start gap-3">
                  {failed ? <Alert tone="danger">Couldn’t add it to your bag. Try again; everything is still here.</Alert> : null}
                  <Button type="submit" loading={busy}>Add to bag</Button>
                </div>
              </form>
              <section aria-labelledby="gift-preview" className="flex flex-col gap-4 md:self-start">
                <h2 id="gift-preview" className="m-0 text-lg font-semibold">What they’ll get</h2>
                <Card padding="none" className="overflow-hidden">
                  <Image src={design.image} alt={`The ${design.label} design`} ratio={1.6} />
                  <div className="flex flex-col gap-1 p-4">
                    <p className="m-0 text-2xl font-semibold">{amount ? money(amount) : 'Choose an amount'}</p>
                    <p className="m-0">For {d.to.trim() || 'them'}, from {d.from.trim() || 'you'}</p>
                    {d.message.trim() ? <p className="m-0 text-text-muted wrap-break-word">{d.message.trim()}</p> : null}
                    <p className="m-0 text-sm text-text-muted">{d.send ? `Sent on ${day(d.send)}` : 'Choose a day to send it'}</p>
                  </div>
                </Card>
              </section>
            </div>
          )}
        </Stack>
      </Container>
    </div>
  );
}

