'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { IconTile } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { SearchInput } from '@diki-stwn/serupa-ds';
import { Dialog } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { Toaster, toast } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { EmptyLoadFailed, EmptyNoResults } from './EmptyStates';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Integrations: the other apps a workspace can connect, which are connected, connecting one and disconnecting one.
   For an app to copy. What it carries (WCAG 2.2):
   - 1.3.1, 2.4.6: connected and available apps are two lists under their own headings, and each app is a heading, so
     a screen reader can list them and jump between them.
   - 2.4.6, 4.1.2: each button is named with its app ("Connect Slack", "Disconnect GitHub"), so a list of them isn't
     "Connect, Connect, Connect".
   - 1.4.1: connected is said in words, not only by a color or a mark.
   - 4.1.3: how many apps match the search is a status, so it's said politely as people type.
   - 3.3.4: disconnecting stops what the app does at once, so it asks first and says what stops.
   - 3.3.1: a connect that fails says so on that app's card, with what to do; a failed disconnect says so in its dialog.
   - 2.4.3: after a connect or a disconnect, focus goes to the app's button in the list it moved to, never to the top.
   Connecting (usually a sign-in on the other app's page) and disconnecting are the app's job: onConnect and
   onDisconnect get the app's id. */

export interface Integration {
  id: string;
  name: string;
  /** What it does once connected, in a sentence. */
  description: string;
  /** Its picture: a Serupa icon name or your own SVG. */
  icon: React.ComponentProps<typeof IconTile>['icon'];
  connected?: boolean | undefined;
  /** What stops when it's disconnected, said before it is: "New issues stop showing on your projects." */
  stops?: string | undefined;
}

export interface IntegrationsProps {
  /** The apps, in the order to show them. Default: six demo apps, two connected. */
  apps?: readonly Integration[] | undefined;
  /** Connect was pressed. Return its promise: a rejection says on the app's card that it didn't connect. */
  onConnect?: ((id: string) => unknown) | undefined;
  /** Disconnect was pressed and confirmed. Return its promise: a rejection keeps it connected and says so. */
  onDisconnect?: ((id: string) => unknown) | undefined;
  /** The apps are on their way: placeholder cards, named once ("Loading integrations"). Default: false. */
  loading?: boolean | undefined;
  /** The apps failed to load: a "Couldn’t load your integrations" message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demo: Integration[] = [
  { id: 'slack', name: 'Slack', icon: 'forum', connected: true, description: 'Posts a message to a channel when a project changes.', stops: 'Messages stop going to your Slack channels.' },
  { id: 'github', name: 'GitHub', icon: 'code', connected: true, description: 'Links pull requests and issues to projects.', stops: 'Pull requests and issues stop showing on your projects.' },
  { id: 'calendar', name: 'Google Calendar', icon: 'calendar_month', description: 'Adds project due dates to a calendar.' },
  { id: 'drive', name: 'Google Drive', icon: 'folder', description: 'Attaches files from Drive to projects.' },
  { id: 'zapier', name: 'Zapier', icon: 'bolt', description: 'Connects to thousands of other apps without code.' },
  { id: 'stripe', name: 'Stripe', icon: 'payments', description: 'Shows payments and invoices next to customers.' },
];

/** The apps whose name or description holds every word of the query. */
export function matchIntegrations(apps: readonly Integration[], query: string): Integration[] {
  const words = query.toLocaleLowerCase().split(/\s+/).filter(Boolean);
  return apps.filter((a) => words.every((w) => `${a.name} ${a.description}`.toLocaleLowerCase().includes(w)));
}

/** The integrations page: a skip link, a header, then main with the h1, a search, and the connected and available apps. */
export function Integrations({ apps = demo, onConnect, onDisconnect, loading = false, loadFailed = false, onRetry, online }: IntegrationsProps) {
  const locale = useLocale();
  const [on, setOn] = React.useState<Record<string, boolean>>({});
  const [query, setQuery] = React.useState('');
  const [busy, setBusy] = React.useState<string | null>(null);
  const [failed, setFailed] = React.useState<string | null>(null);
  const [asking, setAsking] = React.useState<Integration | null>(null);
  const [disconnectFailed, setDisconnectFailed] = React.useState(false);
  const isOn = (a: Integration) => on[a.id] ?? !!a.connected;
  const found = matchIntegrations(apps, query);
  const connected = found.filter(isOn), available = found.filter((a) => !isOn(a));
  const later = (id: string) => requestAnimationFrame(() => document.getElementById(id)?.focus());

  const connect = (a: Integration) => {
    setBusy(a.id);
    setFailed(null);
    void Promise.resolve().then(() => onConnect?.(a.id)).then(() => {
      setOn((o) => ({ ...o, [a.id]: true }));
      toast({ title: `Connected ${a.name}`, tone: 'success' });
      later(`disconnect-${a.id}`);
    }, () => setFailed(a.id)).finally(() => setBusy(null));
  };
  const ask = (a: Integration | null) => { setAsking(a); setDisconnectFailed(false); };
  const disconnect = () => {
    const a = asking;
    if (!a) return;
    setBusy(a.id);
    setDisconnectFailed(false);
    void Promise.resolve().then(() => onDisconnect?.(a.id)).then(() => {
      setOn((o) => ({ ...o, [a.id]: false }));
      setAsking(null);
      toast({ title: `Disconnected ${a.name}`, tone: 'success' });
      // The dialog gives focus back to its opener, which moved lists: Connect, in the available list, takes it.
      later(`connect-${a.id}`);
    }, () => setDisconnectFailed(true)).finally(() => setBusy(null));
  };

  const card = (a: Integration) => {
    const connectedNow = isOn(a);
    return (
      <li key={a.id} className="flex">
        <Card className="flex w-full flex-col gap-3">
          <div className="flex items-start gap-3">
            <IconTile icon={a.icon} tone={connectedNow ? 'primary' : 'neutral'} />
            <div className="flex min-w-0 flex-1 flex-col gap-1">
              <Heading level={3} size="base">{a.name}</Heading>
              <p className="m-0 text-sm text-text-muted">{a.description}</p>
            </div>
            {connectedNow ? <Badge tone="success">Connected</Badge> : null}
          </div>
          {failed === a.id ? <Alert tone="danger">Couldn’t connect {a.name}. Check that you allowed it on {a.name}’s page, then try again.</Alert> : null}
          <div className="mt-auto flex flex-wrap gap-2">
            {connectedNow ? (
              <Button id={`disconnect-${a.id}`} size="sm" variant="outline" aria-label={`Disconnect ${a.name}`} onClick={() => ask(a)}>Disconnect</Button>
            ) : (
              <Button id={`connect-${a.id}`} size="sm" variant="outline" aria-label={`Connect ${a.name}`} loading={busy === a.id} onClick={() => connect(a)}>Connect</Button>
            )}
          </div>
        </Card>
      </li>
    );
  };
  const list = (title: string, items: Integration[], none: string) => (
    <section aria-labelledby={`integrations-${title.toLowerCase()}`} className="flex flex-col gap-4">
      <Heading level={2} size="lg" id={`integrations-${title.toLowerCase()}`}>{title} ({formatNumber(items.length, locale)})</Heading>
      {items.length ? <ul className="m-0 grid list-none grid-cols-1 gap-6 p-0 md:grid-cols-2">{items.map(card)}</ul>
        : <p className="m-0 text-text-muted">{none}</p>}
    </section>
  );

  return (
    <div className="min-h-screen bg-surface-sunken text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <Container as="main" size="lg" className="py-8 outline-none" id="main">
        <Stack gap={6}>
          <OfflineBanner online={online} placement="inline">These are the apps loaded before you went offline. Connecting or disconnecting needs a connection.</OfflineBanner>
          <PageHeader title="Integrations" description="Connect the other apps your team uses. Only admins can connect or disconnect them." />

          {loadFailed ? <EmptyLoadFailed title="Couldn’t load your integrations" onRetry={() => onRetry?.()} headingLevel={2} /> : loading ? (
            <ul role="list" aria-busy="true" className="m-0 grid list-none grid-cols-1 gap-6 p-0 md:grid-cols-2">
              {/* One name for all of them: the first card is named, the others are only pictures. */}
              {[0, 1, 2, 3].map((i) => <li key={i}><Card><Skeleton shape="text" lines={3} label={i === 0 ? 'Loading integrations' : ''} /></Card></li>)}
            </ul>
          ) : <>
            <Field label="Search integrations" className="max-w-md">
              <SearchInput value={query} onChange={(e) => setQuery(e.target.value)} onClear={() => setQuery('')} clearLabel="Clear the search" />
            </Field>
            <p role="status" className="m-0 text-sm text-text-muted">{found.length === 1 ? '1 app' : `${formatNumber(found.length, locale)} apps`}</p>
            {found.length ? <>
              {list('Connected', connected, 'None of these are connected.')}
              {list('Available', available, 'Every one of these is connected.')}
            </> : (
              <EmptyNoResults query={query.trim()} headingLevel={2} title={(q) => `No apps match “${q}”`}
                description="Try another name, or what you want it to do." onClearFilters={() => setQuery('')} />
            )}
          </>}

          <Dialog alert open={!!asking} onOpenChange={(o) => { if (!o) ask(null); }}
            title={asking ? `Disconnect ${asking.name}?` : 'Disconnect?'}
            description={`${asking?.stops ?? 'It stops working with this workspace.'} You can connect it again at any time.`}>
            <div className="flex flex-col gap-4">
              {disconnectFailed ? <Alert tone="danger">Couldn’t disconnect {asking?.name}. It’s still connected. Try again.</Alert> : null}
              <div className="flex flex-wrap gap-2">
                <Button variant="outline" onClick={() => ask(null)}>Keep it</Button>
                <Button variant="outline" destructive loading={!!asking && busy === asking.id} onClick={disconnect}>Disconnect</Button>
              </div>
            </div>
          </Dialog>
        </Stack>
      </Container>
      <Toaster />
    </div>
  );
}

files.Invoice.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { VisuallyHidden } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Badge, type BadgeTone } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Table, TableHead, TableBody, TableRow, TableHeaderCell, TableCell } from '@diki-stwn/serupa-ds';
import { DescriptionList, DescriptionItem } from '@diki-stwn/serupa-ds';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { Toaster, toast } from '@diki-stwn/serupa-ds';
import { FormattedNumber } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { EmptyLoadFailed } from './EmptyStates';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Invoice: one bill, as the person paying it reads it: whether it's due, paid or overdue in words, who it's from and
   to, its lines as a table, the totals, and a way to pay or keep a copy. For an app to copy. What it carries (WCAG 2.2):
   - 1.4.1, 1.3.1: its state is a word in a badge and a sentence with the day ("Due on March 31, 2025", "Overdue by
     5 days"), never a color alone.
   - 1.3.1: the lines are a table with a caption and column headers, the amounts aligned at the end; the totals are a
     description list, with the amount due named so.
   - 2.4.4: Download names what it downloads ("Download PDF of invoice INV-2041"), starting with the words it shows (2.5.3).
   - 3.3.4, 4.1.3: Pay shows it's busy and marks the invoice paid only once the server says so; a payment that fails
     says so next to the button.
   - 2.4.3, 4.1.3: once paid, the Pay button is gone, so focus goes to the h1; the state says "Paid" and a toast says so.
   - 4.1.3, 3.3.1: while the invoice loads, a placeholder named once; a failed load says so, with Try again.
   Paying is the app's job: onPay is called with the amount due; reject its promise when the payment fails. */

export interface InvoiceLine {
  id: string;
  /** What it's for: "Design system workshop, 2 days". */
  description: string;
  quantity: number;
  /** The price of one, in the currency's main unit. */
  price: number;
}
export interface InvoiceInfo {
  /** What it's called: "INV-2041". */
  number: string;
  /** When it was issued and when it's due, as "yyyy-mm-dd". */
  issued: string;
  due: string;
  /** When it was paid, as "yyyy-mm-dd", or empty. */
  paid: string;
  /** Who it's from and to, a line each. */
  from: readonly string[];
  to: readonly string[];
  lines: readonly InvoiceLine[];
  /** The tax rate, as a fraction: 0.11 for 11%. */
  taxRate: number;
  /** Where the PDF is. */
  pdf: string;
}

export interface InvoiceProps {
  /** The invoice. Default: a demo invoice that's due. */
  invoice?: InvoiceInfo | undefined;
  /** An ISO 4217 code. Default: "USD". */
  currency?: string | undefined;
  /** Today, as "yyyy-mm-dd", to say whether it's overdue. Default: "2025-03-20", for the demo. */
  today?: string | undefined;
  /** Pays the amount due. Return its promise: a rejection says so. Without it there is no Pay button. */
  onPay?: ((amount: number) => unknown) | undefined;
  /** The invoice is on its way from the server: placeholders, named once ("Loading invoice"). Default: false. */
  loading?: boolean | undefined;
  /** The invoice failed to load: a message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads the invoice again, after a failed load. */
  onRetry?: (() => void) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demo: InvoiceInfo = {
  number: 'INV-2041', issued: '2025-03-01', due: '2025-03-31', paid: '',
  from: ['Acme Studio', 'Jl. Braga No. 12', 'Bandung 40111, Indonesia'],
  to: ['Lima & Co.', 'Jl. Sudirman 5', 'Jakarta 10220, Indonesia'],
  lines: [
    { id: 'l1', description: 'Design system workshop, 2 days', quantity: 2, price: 1200 },
    { id: 'l2', description: 'Component audit', quantity: 1, price: 800 },
    { id: 'l3', description: 'Travel, Jakarta and back', quantity: 1, price: 140 },
  ],
  taxRate: 0.11, pdf: '#inv-2041.pdf',
};

const DAY = 864e5;
const day = (s: string) => { const [y, m, d] = s.split('-').map(Number); return new Date(y!, m! - 1, d); };

/** The invoice's sums, each in whole cents: before tax, the tax, and the total. */
export function invoiceTotals(lines: readonly InvoiceLine[], taxRate: number): { subtotal: number; tax: number; total: number } {
  // Rounded to cents, so 3 × 0.10 is 0.30 and not the arithmetic's 0.30000000000000004, which onPay would get.
  const cents = (n: number) => Math.round(n * 100) / 100;
  const subtotal = cents(lines.reduce((n, l) => n + l.quantity * l.price, 0));
  const tax = cents(subtotal * taxRate);
  return { subtotal, tax, total: cents(subtotal + tax) };
}

/** Where the invoice stands on a day: paid, due (with the days left), or overdue (with the days late). */
export function invoiceState(inv: Pick<InvoiceInfo, 'due' | 'paid'>, today: string): { state: 'paid' | 'due' | 'overdue'; days: number } {
  if (inv.paid) return { state: 'paid', days: 0 };
  const days = Math.round((day(inv.due).getTime() - day(today).getTime()) / DAY);
  return days < 0 ? { state: 'overdue', days: -days } : { state: 'due', days };
}

const BADGE: Record<'paid' | 'due' | 'overdue', { label: string; tone: BadgeTone }> = {
  paid: { label: 'Paid', tone: 'success' }, due: { label: 'Due', tone: 'warning' }, overdue: { label: 'Overdue', tone: 'danger' },
};

/** The invoice page: a skip link, a header, then main with the invoice's h1, where it stands, its lines and totals. */
export function Invoice({ invoice: start = demo, currency = 'USD', today = '2025-03-20', onPay, loading = false, loadFailed = false, onRetry, online }: InvoiceProps) {
  const locale = useLocale(undefined);
  const [inv, setInv] = React.useState(start);
  // What the app passes once loading ends replaces what was there, which was empty or the demo.
  const [wasLoading, setWasLoading] = React.useState(loading);
  if (wasLoading !== loading) { setWasLoading(loading); if (!loading) { setInv(start); } }
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const heading = React.useRef<HTMLHeadingElement>(null);
  const money = (n: number) => <FormattedNumber value={n} format="currency" currency={currency} />;
  const date = (s: string) => new Intl.DateTimeFormat(locale, { dateStyle: 'long', calendar: 'gregory', numberingSystem: 'latn' }).format(day(s));
  const sums = invoiceTotals(inv.lines, inv.taxRate);
  const where = invoiceState(inv, today);
  const name = `Invoice ${inv.number}`;
  const sentence = where.state === 'paid' ? `Paid on ${date(inv.paid)}.`
    : where.state === 'overdue' ? `Overdue by ${where.days === 1 ? '1 day' : `${formatNumber(where.days, locale)} days`}. It was due on ${date(inv.due)}.`
    : `Due on ${date(inv.due)}${where.days === 0 ? ', today' : ''}.`;

  const pay = () => {
    setFailed(false);
    setBusy(true);
    void Promise.resolve().then(() => onPay?.(sums.total)).then(() => {
      setInv((i) => ({ ...i, paid: today }));
      toast({ title: `${name} is paid`, tone: 'success' });
    }, () => setFailed(true)).finally(() => setBusy(false));
  };
  // The Pay button goes once it's paid, so focus goes to the page's h1.
  const was = React.useRef(!!inv.paid);
  React.useEffect(() => { if (inv.paid && !was.current) heading.current?.focus(); was.current = !!inv.paid; }, [inv.paid]);

  const h2 = 'm-0 text-lg font-semibold';
  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <Container as="main" size="lg" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">This is the invoice as it was when the page loaded. Paying needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Invoices', href: '#invoices' }, { label: inv.number }]} title={name} headingRef={heading} />

          <div className="flex flex-col gap-8 pt-6">
            {loadFailed ? <EmptyLoadFailed title="Couldn’t load the invoice" onRetry={() => onRetry?.()} headingLevel={2} />
              : loading ? <Card><Skeleton shape="text" lines={6} label="Loading invoice" /></Card> : <>
                <section aria-labelledby="standing" className="flex flex-col items-start gap-3">
                  <h2 id="standing" className="m-0 flex flex-wrap items-center gap-3 text-2xl font-semibold">
                    {money(sums.total)} {inv.paid ? 'paid' : 'to pay'}
                    <Badge tone={BADGE[where.state].tone}>{BADGE[where.state].label}</Badge>
                  </h2>
                  <p className="m-0 text-text-muted">{sentence}</p>
                  <div data-print="hide" className="flex flex-wrap items-center gap-3">
                    {onPay && !inv.paid ? <Button loading={busy} onClick={pay}>Pay {money(sums.total)}</Button> : null}
                    <Link href={inv.pdf} download>Download PDF<VisuallyHidden> of invoice {inv.number}</VisuallyHidden></Link>
                  </div>
                  {failed ? <Alert tone="danger">The payment didn’t go through. Nothing was taken; try again, or use another card.</Alert> : null}
                </section>

                <div className="grid gap-6 md:grid-cols-3">
                  <section aria-labelledby="from">
                    <h2 id="from" className="m-0 text-sm font-semibold text-text-muted">From</h2>
                    <address className="not-italic">{inv.from.map((l) => <div key={l}>{l}</div>)}</address>
                  </section>
                  <section aria-labelledby="to">
                    <h2 id="to" className="m-0 text-sm font-semibold text-text-muted">To</h2>
                    <address className="not-italic">{inv.to.map((l) => <div key={l}>{l}</div>)}</address>
                  </section>
                  <section aria-labelledby="dates">
                    <h2 id="dates" className="m-0 text-sm font-semibold text-text-muted">Dates</h2>
                    <DescriptionList>
                      <DescriptionItem term="Issued"><time dateTime={inv.issued}>{date(inv.issued)}</time></DescriptionItem>
                      <DescriptionItem term="Due"><time dateTime={inv.due}>{date(inv.due)}</time></DescriptionItem>
                    </DescriptionList>
                  </section>
                </div>

                <section aria-labelledby="lines" className="flex flex-col gap-4">
                  <h2 id="lines" className={h2}>What it’s for</h2>
                  <Table caption={`Lines of invoice ${inv.number}`} hideCaption>
                    <TableHead><TableRow>
                      {/* On a phone the quantity and the price go under each description ("2 × $1,200.00") rather than in
                         columns of their own, so the lines fit a 390px screen in every language. */}
                      <TableHeaderCell>Description</TableHeaderCell>
                      <TableHeaderCell align="end" className="hidden sm:table-cell">Quantity</TableHeaderCell>
                      <TableHeaderCell align="end" className="hidden sm:table-cell">Price</TableHeaderCell>
                      <TableHeaderCell align="end">Amount</TableHeaderCell>
                    </TableRow></TableHead>
                    <TableBody>{inv.lines.map((l) => (
                      <TableRow key={l.id}>
                        <TableCell>{l.description}<span className="block text-sm text-text-muted sm:hidden">{formatNumber(l.quantity, locale)} × {money(l.price)}</span></TableCell>
                        <TableCell align="end" className="hidden sm:table-cell">{formatNumber(l.quantity, locale)}</TableCell>
                        <TableCell align="end" className="hidden sm:table-cell">{money(l.price)}</TableCell>
                        <TableCell align="end">{money(l.price * l.quantity)}</TableCell>
                      </TableRow>
                    ))}</TableBody>
                  </Table>
                  {/* The totals are in the table's text size, and their figures end where the Amount column's do: in by
                      the table's cell padding (pe-3) and its 1px frame (me-px). Classes, not a style attribute, so a
                      strict CSP lays it out the same. */}
                  <div className="flex justify-end pe-3">
                    <DescriptionList layout="split" className="w-full max-w-sm me-px text-sm">
                      <DescriptionItem term="Subtotal">{money(sums.subtotal)}</DescriptionItem>
                      <DescriptionItem term={`Tax (${formatNumber(inv.taxRate, locale, { style: 'percent', maximumFractionDigits: 2 })})`}>{money(sums.tax)}</DescriptionItem>
                      <DescriptionItem term="Total">{money(sums.total)}</DescriptionItem>
                      <DescriptionItem term="Paid">{money(inv.paid ? sums.total : 0)}</DescriptionItem>
                      <DescriptionItem term="Amount due" emphasis>{money(inv.paid ? 0 : sums.total)}</DescriptionItem>
                    </DescriptionList>
                  </div>
                </section>
              </>}
          </div>
        </Stack>
      </Container>
      <Toaster />
    </div>
  );
}

files.JobApplication.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { DescriptionList, DescriptionItem } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { FieldList } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { Textarea } from '@diki-stwn/serupa-ds';
import { Checkbox } from '@diki-stwn/serupa-ds';
import { RadioGroup, Radio } from '@diki-stwn/serupa-ds';
import { FileUpload } from '@diki-stwn/serupa-ds';
import { ErrorSummary, type ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Job application: what the job is, then one short form to apply, and what happens next. For an app to copy. What it
   carries (WCAG 2.2):
   - 1.3.1: what the job is (team, place, hours, pay) is a list of named facts above the form, so it's read before
     applying.
   - 3.3.2, 1.3.5: each field says what it's for, which are optional, and its format; name, email and phone say what
     they are for autofill. The CV says the file types and size it takes.
   - 1.3.1, 4.1.3: links to their work are a FieldList, a group named by its legend whose rows are "Link 1", "Link 2";
     Add a link puts focus in the new row, and it stops at 3 saying why.
   - 3.3.1, 2.4.3: applying with problems shows a summary at the top that takes focus, each problem a link to its
     field (the CV's link lands on its Choose button, the question's on its first answer), and each field says its own.
   - 3.3.4, 4.1.3: Apply shows it's busy; an application that can't be sent says so next to the button and keeps
     every field and the file.
   - 2.4.3: once sent, the form gives way to an answer whose heading takes focus, with what happens next, in order.
   Sending is the app's job: onApply gets the application; reject when it can't be sent. */

export interface JobApplicationAnswers {
  name: string;
  email: string;
  phone: string;
  /** The CV, one file. */
  cv: File | null;
  /** Links to their work, optional: a portfolio, a case study, a repository. Up to 3. */
  links?: string[] | undefined;
  /** Why this job, optional. */
  letter: string;
  /** "yes" or "no": can work where the job is. */
  rightToWork: string;
  /** Agreed to how the application is kept. */
  consent: boolean;
}

export interface JobPosting {
  title: string;
  team: string;
  place: string;
  hours: string;
  pay: string;
}

export interface JobApplicationProps {
  /** The job. Default: a demo job. */
  job?: JobPosting | undefined;
  /** Sends the application. Reject when it can't be sent. */
  onApply?: ((answers: JobApplicationAnswers) => unknown) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demoJob: JobPosting = { title: 'Product designer', team: 'Payments', place: 'Jakarta or remote in UTC+7 to UTC+9', hours: 'Full time', pay: '$48,000 to $62,000 a year' };
const MB = 1024 * 1024;
const LETTER = 2000;
const FIELDS = ['name', 'email', 'phone', 'cv', 'links', 'letter', 'rightToWork', 'consent'] as const;
type Problems = Partial<Record<(typeof FIELDS)[number], string>>;
const blank: JobApplicationAnswers = { name: '', email: '', phone: '', cv: null, letter: '', rightToWork: '', consent: false };

/** Each link's problem, in the list's order, or undefined for one that's fine or left blank. */
export function linkProblems(links: readonly string[]): (string | undefined)[] {
  return links.map((l, i) => (!l.trim() || /^https?:\/\/[^\s.]+\.[^\s]+$/i.test(l.trim()) ? undefined : `Enter link ${i + 1} as a full address, like https://example.com/work.`));
}

/** What's wrong with the application, by field, in the order of the form, or {} when it can be sent. */
export function applicationProblems(a: JobApplicationAnswers): Problems {
  const out: Problems = {};
  if (!a.name.trim()) out.name = 'Enter your full name.';
  if (!a.email.trim()) out.email = 'Enter your email address, so we can reply.';
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(a.email.trim())) out.email = 'Enter an email address like name@example.com.';
  if (a.phone.trim() && a.phone.replace(/\D/g, '').length < 7) out.phone = 'Enter a phone number with its area code, like +62 21 555 0142.';
  if (!a.cv) out.cv = 'Choose your CV.';
  const link = linkProblems(a.links ?? []).find(Boolean);
  if (link) out.links = link;
  if (a.letter.length > LETTER) out.letter = `Shorten this to ${LETTER} characters.`;
  if (!a.rightToWork) out.rightToWork = 'Say whether you can work where the job is.';
  if (!a.consent) out.consent = 'Agree to how we keep your application, so we can read it.';
  return out;
}

/** The job's page: a skip link, a header, then main with the h1, what the job is, and the form, or the answer once sent. */
export function JobApplication({ job = demoJob, onApply, online }: JobApplicationProps) {
  const [a, setA] = React.useState<JobApplicationAnswers>(blank);
  const [problems, setProblems] = React.useState<Problems>({});
  const [tries, setTries] = React.useState(0);
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const [sent, setSent] = React.useState(false);
  const answer = React.useRef<HTMLHeadingElement>(null);
  const edit = (patch: Partial<JobApplicationAnswers>) => { setA((now) => ({ ...now, ...patch })); setFailed(false); };
  const linkErrors = problems.links ? linkProblems(a.links ?? []) : [];
  // A link's problem goes to its own field: the first link that has one.
  const fieldOf = (f: (typeof FIELDS)[number]) => (f === 'links' ? `job-link-${linkErrors.findIndex(Boolean)}` : `job-${f}`);
  const errors: ErrorSummaryItem[] = FIELDS.filter((f) => problems[f]).map((f) => ({ field: fieldOf(f), message: problems[f] }));

  const apply = (e: React.FormEvent) => {
    e.preventDefault();
    setFailed(false);
    const found = applicationProblems(a);
    setProblems(found);
    setTries((t) => t + 1);
    if (Object.keys(found).length) return;
    const out = { ...a, links: (a.links ?? []).map((l) => l.trim()).filter(Boolean), name: a.name.trim(), email: a.email.trim(), phone: a.phone.trim(), letter: a.letter.trim() };
    setBusy(true);
    void Promise.resolve().then(() => onApply?.(out)).then(() => setSent(true), () => setFailed(true)).finally(() => setBusy(false));
  };
  React.useEffect(() => { if (sent) answer.current?.focus(); }, [sent]);

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme careers</p>
        <Link underline="hover" href="#jobs">All jobs</Link>
      </header>
      <Container as="main" size="prose" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">Your answers stay here. Sending the application needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Jobs', href: '#jobs' }, { label: job.title }]} title={job.title}
            description="Applying takes about 5 minutes. All fields are needed unless they say they’re optional." />
          <div className="flex flex-col gap-8 pt-6">
            <Card>
              <section aria-labelledby="about-job" className="flex flex-col gap-4">
                <h2 id="about-job" className="m-0 text-lg font-semibold">About the job</h2>
                <DescriptionList>
                  <DescriptionItem term="Team">{job.team}</DescriptionItem>
                  <DescriptionItem term="Where">{job.place}</DescriptionItem>
                  <DescriptionItem term="Hours">{job.hours}</DescriptionItem>
                  <DescriptionItem term="Pay">{job.pay}</DescriptionItem>
                </DescriptionList>
              </section>
            </Card>
            {sent ? (
              <section aria-labelledby="applied" className="flex flex-col items-start gap-3">
                <h2 id="applied" ref={answer} tabIndex={-1} className="m-0 text-2xl font-semibold outline-none">Application sent</h2>
                <p className="m-0">Thank you, {a.name.trim()}. We’ve sent a copy to {a.email.trim()}. What happens next:</p>
                <ol className="m-0 flex flex-col gap-1 ps-6">
                  <li>Someone from the {job.team} team reads it within 10 working days.</li>
                  <li>If it’s a match, we email you to book a 30-minute call.</li>
                  <li>If it isn’t, we email you too, so you’re never left waiting.</li>
                </ol>
                <Link href="#jobs">See other jobs</Link>
              </section>
            ) : (
              <form onSubmit={apply} noValidate aria-labelledby="apply" className="flex flex-col gap-4">
                <h2 id="apply" className="m-0 text-lg font-semibold">Apply</h2>
                <ErrorSummary key={tries} errors={errors} />
                <p className="m-0 text-text-muted">Fields marked * are required.</p>
                <Field label="Full name" id="job-name" error={problems.name} required>
                  <Input autoComplete="name" value={a.name} onChange={(e) => edit({ name: e.target.value })} />
                </Field>
                <Field label="Email" id="job-email" error={problems.email} required>
                  <Input type="email" autoComplete="email" spellCheck={false} value={a.email} onChange={(e) => edit({ email: e.target.value })} />
                </Field>
                <Field label="Phone" id="job-phone" hint="Only to book a call, if email doesn’t reach you." error={problems.phone} optional>
                  <Input type="tel" autoComplete="tel" value={a.phone} onChange={(e) => edit({ phone: e.target.value })} className="max-w-64" />
                </Field>
                <Field label="CV" error={problems.cv} required>
                  <FileUpload id="job-cv" accept=".pdf,.doc,.docx,application/pdf" maxSize={5 * MB} hint="PDF or Word, up to 5 MB"
                    files={a.cv ? [a.cv] : []} onFilesChange={(f) => edit({ cv: f.at(-1) ?? null })} />
                </Field>
                <FieldList label="Links to your work" hint="Optional. A portfolio, a case study or a repository: up to 3." itemLabel={(i) => `Link ${i + 1}`}
                  addLabel="Add a link" newItem={() => ''} min={0} max={3} value={a.links ?? []} onValueChange={(links) => edit({ links })}
                  errors={linkErrors}>
                  {(link, row) => (
                    <Field label="Web address" id={`job-link-${row.index}`}>
                      <Input type="url" inputMode="url" spellCheck={false} invalid={!!row.error} value={link} onChange={(e) => row.update(e.target.value)} />
                    </Field>
                  )}
                </FieldList>
                <Field label="Why this job?" id="job-letter" hint={`A few lines are plenty. Up to ${LETTER} characters.`} error={problems.letter} optional>
                  <Textarea rows={5} maxLength={LETTER} showCount value={a.letter} onChange={(e) => edit({ letter: e.target.value })} />
                </Field>
                <Field label="Are you allowed to work where the job is?" hint={job.place} error={problems.rightToWork} group required>
                  <RadioGroup id="job-rightToWork" name="job-right-to-work" value={a.rightToWork} onValueChange={(v: string) => edit({ rightToWork: v })}>
                    <Radio value="yes">Yes</Radio>
                    <Radio value="no" description="We can sometimes help with a visa: say so in “Why this job?”.">Not yet</Radio>
                  </RadioGroup>
                </Field>
                <Field error={problems.consent}>
                  <Checkbox id="job-consent" checked={a.consent} onCheckedChange={(on) => edit({ consent: on })} invalid={!!problems.consent}>
                    Keep my application for 6 months, as the <Link href="#privacy">privacy notice</Link> says
                  </Checkbox>
                </Field>
                <div className="flex flex-col items-start gap-3">
                  {failed ? <Alert tone="danger">Couldn’t send your application. Try again; everything, your CV too, is still here.</Alert> : null}
                  <Button type="submit" loading={busy}>Send application</Button>
                </div>
              </form>
            )}
          </div>
        </Stack>
      </Container>
    </div>
  );
}

files.Leaderboard.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Avatar } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { SegmentedControl } from '@diki-stwn/serupa-ds';
import { Table, TableHead, TableBody, TableRow, TableHeaderCell, TableCell } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { EmptyLoadFailed } from './EmptyStates';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { EmptyState } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Leaderboard: who's ahead this week, this month or of all time, where you are, and who's moving. For an app to copy.
   What it carries (WCAG 2.2):
   - 1.3.1: the board is a table with a caption; each row's name is its row header, so every cell is read with it.
   - 1.3.1: a tie shares its place, said as "Joint 3rd", not left to the numbers to show.
   - 1.4.1: your row says "You" in a badge, as well as being shaded; a move up or down is said in words ("Up 2"),
     never only an arrow or a color.
   - 4.1.3: switching the period says which period the board shows.
   - 1.3.2: when you're outside the top places, your row follows them after a row that says how many are between.
   Scoring is the app's job: pass the people and their points for each period. */

export type Period = 'week' | 'month' | 'all';
export interface Player { id: string; name: string; points: Record<Period, number>; moved?: Partial<Record<Period, number>> | undefined }

export interface LeaderboardProps {
  players?: Player[] | undefined;
  /** Your id. */
  me?: string | undefined;
  /** How many places show before yours. Default: 5. */
  top?: number | undefined;
  /** Still loading: a placeholder shows instead of the board. Default: false. */
  loading?: boolean | undefined;
  /** Loading failed: a "Couldn’t load the leaderboard" message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, from Try again. Return a promise: the button shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const P = (id: string, name: string, week: number, month: number, all: number, moved: Partial<Record<Period, number>> = {}): Player => ({ id, name, points: { week, month, all }, moved });
const demo: Player[] = [
  P('dewi', 'Dewi Lestari', 420, 1630, 18210, { week: 1, month: 0 }),
  P('chen', 'Chen Wei', 410, 1720, 20480, { week: -1, month: 2 }),
  P('sara', 'Sara Haddad', 380, 1490, 15020, { week: 3 }),
  P('kofi', 'Kofi Mensah', 380, 1210, 9900, { week: 0, month: -1 }),
  P('lena', 'Lena Vogel', 300, 1490, 12040, { week: -2 }),
  P('tomas', 'Tomás Ruiz', 260, 980, 8800),
  P('eko', 'Eko Prasetyo', 240, 900, 7700, { week: 1 }),
  P('maya', 'Maya Chen', 200, 870, 6100),
  P('ana', 'Ana Lima', 150, 640, 4300, { week: -1, month: 1 }),
];
const PERIODS: { value: Period; label: string; long: string }[] = [
  { value: 'week', label: 'This week', long: 'this week' },
  { value: 'month', label: 'This month', long: 'this month' },
  { value: 'all', label: 'All time', long: 'of all time' },
];

/** Players by points for a period, highest first, with their place; equal points share a place. */
export function rank(players: Player[], period: Period) {
  const sorted = [...players].sort((a, b) => b.points[period] - a.points[period] || a.name.localeCompare(b.name));
  return sorted.map((p, i) => {
    const place = sorted.findIndex((q) => q.points[period] === p.points[period]) + 1;
    const joint = sorted.filter((q) => q.points[period] === p.points[period]).length > 1;
    return { ...p, place, joint, index: i };
  });
}

/** "1st", "2nd", "3rd", "11th", "22nd". */
export function ordinal(n: number) {
  const s = n % 100 >= 11 && n % 100 <= 13 ? 'th' : ({ 1: 'st', 2: 'nd', 3: 'rd' } as Record<number, string>)[n % 10] ?? 'th';
  return `${n}${s}`;
}

/** The leaderboard page: a skip link, a header, then main with the h1, the period, and the board. */
export function Leaderboard({ players = demo, me = 'ana', top = 5, loading = false, loadFailed = false, onRetry, online }: LeaderboardProps) {
  const locale = useLocale();
  const num = (n: number) => formatNumber(n, locale);
  const [period, setPeriod] = React.useState<Period>('week');
  const ranked = rank(players, period);
  const mine = ranked.find((r) => r.id === me);
  const shown = ranked.slice(0, top);
  const apart = mine && mine.index >= top ? mine : null;
  const between = apart ? apart.index - top : 0;
  const long = PERIODS.find((p) => p.value === period)!.long;
  const placeWords = (r: (typeof ranked)[number]) => `${r.joint ? 'Joint ' : ''}${ordinal(r.place)}`;
  const movedWords = (m: number | undefined) => (!m ? 'No change' : m > 0 ? `Up ${num(m)}` : `Down ${num(-m)}`);

  const row = (r: (typeof ranked)[number]) => (
    <TableRow key={r.id} selected={r.id === me}>
      <TableCell>{placeWords(r)}</TableCell>
      <TableHeaderCell scope="row" className="font-normal">
        <span className="flex items-center gap-2">
          <Avatar name={r.name} alt="" size="sm" />
          <span className="min-w-0 wrap-break-word">{r.name}</span>
          {r.id === me ? <Badge tone="primary">You</Badge> : null}
        </span>
      </TableHeaderCell>
      <TableCell align="end">{num(r.points[period])}</TableCell>
      <TableCell className="text-text-muted">{period === 'all' ? '' : movedWords(r.moved?.[period])}</TableCell>
    </TableRow>
  );

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme Steps</p>
        <Link underline="hover" href="#challenges">Challenges</Link>
      </header>
      <Container as="main" size="md" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">These scores are from when the page loaded. They update when you’re back.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Challenges', href: '#challenges' }, { label: 'Leaderboard' }]} title="Leaderboard"
            description={loading || loadFailed || !players.length ? undefined : mine ? `You’re ${placeWords(mine).toLowerCase()} of ${num(players.length)} ${long}, with ${num(mine.points[period])} points.` : `${num(players.length)} people taking part.`} />
          {loadFailed ? <div className="pt-6"><EmptyLoadFailed title="Couldn’t load the leaderboard" onRetry={() => onRetry?.()} headingLevel={2} /></div>
            : loading ? <Card className="mt-6"><Skeleton shape="text" lines={6} label="Loading the leaderboard" /></Card>
            : !players.length ? <div className="pt-6"><EmptyState icon="leaderboard" title="No scores yet" headingLevel={2}
                description="Every step you log earns points. The first people to log theirs show here." /></div> : (<>
          <div className="flex flex-wrap items-center justify-between gap-3 pt-6">
            <SegmentedControl aria-label="Period" value={period} onValueChange={setPeriod} options={PERIODS.map(({ value, label }) => ({ value, label }))} />
            <p role="status" id="board-period" className="m-0 text-sm text-text-muted">Showing points {long}</p>
          </div>
          <div className="pt-4">
            <Table caption={`Leaderboard, points ${long}`} hideCaption>
              <TableHead><TableRow>
                <TableHeaderCell>Place</TableHeaderCell>
                <TableHeaderCell>Name</TableHeaderCell>
                <TableHeaderCell align="end">Points</TableHeaderCell>
                <TableHeaderCell>{period === 'all' ? <span className="sr-only">Change</span> : 'Change'}</TableHeaderCell>
              </TableRow></TableHead>
              <TableBody>
                {shown.map(row)}
                {apart ? (
                  <>
                    {between ? (
                      <TableRow>
                        <TableCell colSpan={4} className="text-center text-sm text-text-muted">{between === 1 ? '1 more person' : `${num(between)} more people`} between</TableCell>
                      </TableRow>
                    ) : null}
                    {row(apart)}
                  </>
                ) : null}
              </TableBody>
            </Table>
          </div>
          </>)}
        </Stack>
      </Container>
    </div>
  );
}

files.LeaveRequest.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Badge, type BadgeTone } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { RadioGroup, Radio } from '@diki-stwn/serupa-ds';
import { Textarea } from '@diki-stwn/serupa-ds';
import { RangeCalendar } from '@diki-stwn/serupa-ds';
import { DescriptionList, DescriptionItem } from '@diki-stwn/serupa-ds';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { Toaster, toast } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { EmptyLoadFailed } from './EmptyStates';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Leave request: time off asked for on a calendar, with the working days counted, weekends and holidays shown and
   left out of the count, and the balance that's left. For an app to copy. What it carries (WCAG 2.2):
   - 1.4.1, 1.3.1: weekends and holidays are struck through and can't start or end the leave; the holidays in view are
     also listed in words with their names, and the ones inside the leave are named next to the count.
   - 1.3.1: the balance is a description list in words: what's left, what's waiting for approval and what's left after.
   - 3.3.1, 4.1.3: annual leave longer than what's left is said at once in an alert the calendar points to, with the
     numbers and a way out (fewer days, or unpaid leave); Send with no dates says what to choose and puts focus on the
     calendar.
   - 3.3.4, 4.1.3: Send shows it's busy and adds the request only once the server says so; one that fails says so next
     to the button and keeps what was chosen.
   - 4.1.3, 2.4.3: a sent request goes to the top of "Your requests" as waiting for approval, a toast says so, and focus
     goes to it.
   - 1.4.1: each request's state is a word (Waiting, Approved, Declined), not only a color.
   - 4.1.3, 3.3.1: while the balance loads, a placeholder named once; a failed load says so, with Try again.
   Sending is the app's job: onSubmit gets the request; reject its promise when it can't be sent. */

export type LeaveKind = 'annual' | 'unpaid';
export interface LeaveHoliday {
  /** The day, as "yyyy-mm-dd". */
  date: string;
  /** Its name: "Eid al-Fitr". */
  name: string;
}
export interface LeaveRequestItem {
  id: string;
  kind: LeaveKind;
  /** The first and the last day away, as "yyyy-mm-dd". */
  start: string;
  end: string;
  /** The working days it takes. */
  days: number;
  status: 'waiting' | 'approved' | 'declined';
}
/** A request from the form, before it's sent. */
export interface LeaveDraft {
  kind: LeaveKind;
  start: string;
  end: string;
  days: number;
  /** A note for the approver. May be empty. */
  note: string;
}

export interface LeaveRequestProps {
  /** Days of annual leave left, before the requests still waiting. Default: 12. */
  balance?: number | undefined;
  /** Public holidays, which aren't counted. Default: the demo's. */
  holidays?: readonly LeaveHoliday[] | undefined;
  /** The days of the week that aren't worked, 0 Sunday … 6 Saturday. Default: [0, 6]. */
  weekend?: readonly number[] | undefined;
  /** Requests already made, newest first. Default: the demo's. */
  requests?: readonly LeaveRequestItem[] | undefined;
  /** The earliest day leave can start, as "yyyy-mm-dd". Pass today's. Default: "2025-03-10", for the demo. */
  today?: string | undefined;
  /** Sends the request. Return its promise: a rejection keeps the form and says the request wasn't sent. */
  onSubmit?: ((draft: LeaveDraft) => unknown) | undefined;
  /** The balance is on its way from the server: placeholders, named once ("Loading leave"). Default: false. */
  loading?: boolean | undefined;
  /** The balance failed to load: a message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads the balance again, after a failed load. */
  onRetry?: (() => void) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demoHolidays: LeaveHoliday[] = [
  { date: '2025-03-31', name: 'Eid al-Fitr' }, { date: '2025-04-01', name: 'Eid al-Fitr, second day' }, { date: '2025-04-18', name: 'Good Friday' },
];
const demoRequests: LeaveRequestItem[] = [
  { id: 'r2', kind: 'annual', start: '2025-05-12', end: '2025-05-16', days: 5, status: 'waiting' },
  { id: 'r1', kind: 'annual', start: '2025-02-03', end: '2025-02-04', days: 2, status: 'approved' },
];
const KINDS: { value: LeaveKind; label: string; hint: string }[] = [
  { value: 'annual', label: 'Annual leave', hint: 'Paid, and taken from what you have left.' },
  { value: 'unpaid', label: 'Unpaid leave', hint: 'Not paid, and doesn’t touch what you have left.' },
];
const STATUS: Record<LeaveRequestItem['status'], { label: string; tone: BadgeTone }> = {
  waiting: { label: 'Waiting', tone: 'warning' }, approved: { label: 'Approved', tone: 'success' }, declined: { label: 'Declined', tone: 'danger' },
};

// A "yyyy-mm-dd" day at local midnight, the day n days on from d, and a day as "yyyy-mm-dd".
const day = (s: string) => { const [y, m, d] = s.split('-').map(Number); return new Date(y!, m! - 1, d); };
const shift = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);
const iso = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

/** The working days from the first day to the last, both in, as "yyyy-mm-dd": weekends and holidays left out. */
export function workingDays(start: string, end: string, rest: { holidays?: readonly LeaveHoliday[] | undefined; weekend?: readonly number[] | undefined } = {}): string[] {
  const off = new Set((rest.holidays ?? []).map((h) => h.date)), weekend = rest.weekend ?? [0, 6];
  const out: string[] = [];
  for (let d = day(start), last = day(end); d <= last; d = shift(d, 1)) {
    if (!weekend.includes(d.getDay()) && !off.has(iso(d))) out.push(iso(d));
  }
  return out;
}

/** What's wrong with the request, as a sentence, or null when it can be sent. */
export function leaveProblem(range: { start: string; end: string } | null, kind: LeaveKind, days: number, left: number): string | null {
  if (!range) return 'Choose the first and the last day you’ll be away.';
  if (kind === 'annual' && days > left) return `That’s ${days} working days, and you have ${left} left. Choose fewer days, or ask for unpaid leave.`;
  return null;
}

const dayWords = (locale: string | undefined, a: string, b?: string, weekday = false) => {
  const f = new Intl.DateTimeFormat(locale, weekday ? { weekday: 'short', month: 'short', day: 'numeric', calendar: 'gregory', numberingSystem: 'latn' } : { dateStyle: 'medium', calendar: 'gregory', numberingSystem: 'latn' });
  return (b && b !== a ? f.formatRange(day(a), day(b)) : f.format(day(a))).replace(/[\u2009\u202f]/g, ' ');
};

/** The leave page: a skip link, a header, then main with the h1, the balance, the request form and the requests. */
export function LeaveRequest({ balance = 12, holidays = demoHolidays, weekend = [0, 6], requests: first = demoRequests, today = '2025-03-10', onSubmit, loading = false, loadFailed = false, onRetry, online }: LeaveRequestProps) {
  const locale = useLocale(undefined);
  const [requests, setRequests] = React.useState(first);
  // The kind radios' name is this form's own, so two leave requests on a page don't share one group.
  const kindName = React.useId();
  // What the app passes once loading ends replaces what was there, which was empty or the demo.
  const [wasLoading, setWasLoading] = React.useState(loading);
  if (wasLoading !== loading) { setWasLoading(loading); if (!loading) { setRequests(first); } }
  const [kind, setKind] = React.useState<LeaveKind>('annual');
  const [range, setRange] = React.useState<{ start: string; end: string } | null>(null);
  const [note, setNote] = React.useState('');
  const [asked, setAsked] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const calendar = React.useRef<HTMLDivElement>(null);
  const list = React.useRef<HTMLUListElement>(null);
  const [month, setMonth] = React.useState(() => day(today));

  const off = React.useMemo(() => new Set(holidays.map((h) => h.date)), [holidays]);
  const closed = React.useCallback((d: Date) => weekend.includes(d.getDay()) || off.has(iso(d)), [weekend, off]);
  const waiting = requests.filter((r) => r.status === 'waiting' && r.kind === 'annual').reduce((n, r) => n + r.days, 0);
  const left = balance - waiting;
  const days = range ? workingDays(range.start, range.end, { holidays, weekend }).length : 0;
  const problem = leaveProblem(range, kind, days, left);
  const shownProblem = range || asked ? problem : null;
  const inside = range ? holidays.filter((h) => h.date >= range.start && h.date <= range.end) : [];
  // The holidays in the two months shown.
  const from = iso(new Date(month.getFullYear(), month.getMonth(), 1)), to = iso(new Date(month.getFullYear(), month.getMonth() + 2, 0));
  const inView = holidays.filter((h) => h.date >= from && h.date <= to);
  const count = (n: number) => `${formatNumber(n, locale)} ${n === 1 ? 'day' : 'days'}`;

  const send = () => {
    setFailed(false);
    if (problem || !range) {
      setAsked(true);
      calendar.current?.querySelector<HTMLElement>('.srp-calendar__day[tabindex="0"]')?.focus();
      return;
    }
    const draft: LeaveDraft = { kind, ...range, days, note: note.trim() };
    setBusy(true);
    void Promise.resolve().then(() => onSubmit?.(draft)).then(() => {
      setRequests((rs) => [{ id: `new-${draft.start}-${rs.length}`, kind, start: draft.start, end: draft.end, days, status: 'waiting' }, ...rs]);
      setRange(null);
      setNote('');
      setAsked(false);
      toast({ title: `Leave requested: ${dayWords(locale, draft.start, draft.end)}`, description: 'Your manager will approve or decline it.', tone: 'success' });
      // The form is cleared, so focus goes to the new request.
      requestAnimationFrame(() => list.current?.querySelector<HTMLElement>('li')?.focus());
    }, () => setFailed(true)).finally(() => setBusy(false));
  };

  const h2 = 'm-0 text-lg font-semibold';
  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme People</p>
      </header>
      <Container as="main" size="lg" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">Your request stays here. Sending it needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Time off', href: '#time-off' }, { label: 'Request leave' }]} title="Request leave" />

          <div className="pt-6">
            {loadFailed ? <EmptyLoadFailed title="Couldn’t load your leave" onRetry={() => onRetry?.()} headingLevel={2} />
              : loading ? <Card><Skeleton shape="text" lines={6} label="Loading leave" /></Card> : (
                <div className="grid items-start gap-6 md:grid-cols-3">
                  <div className="flex flex-col gap-8 md:col-span-2">
                    <Field label="Kind of leave" group>
                      <RadioGroup name={kindName} value={kind} onValueChange={(v: LeaveKind) => { setKind(v); setFailed(false); }}>
                        {KINDS.map((k) => <Radio key={k.value} value={k.value} description={k.hint}>{k.label}</Radio>)}
                      </RadioGroup>
                    </Field>
                    <section aria-labelledby="dates" className="flex flex-col gap-4">
                      <h2 id="dates" className={h2}>Dates</h2>
                      <p className="m-0 text-sm text-text-muted">Choose your first day away, then your last. Weekends and holidays are struck through and aren’t counted.</p>
                      <RangeCalendar ref={calendar} aria-labelledby="dates" aria-describedby={shownProblem ? 'leave-problem' : undefined} months={2}
                        month={month} onMonthChange={setMonth} min={today} isDateDisabled={closed} value={range}
                        onValueChange={(_, { iso }) => { setFailed(false); setRange(iso); }} />
                      {range ? (
                        <p className="m-0 font-semibold">
                          {formatNumber(days, locale)} working {days === 1 ? 'day' : 'days'}{inside.length ? <span className="font-normal">, without {inside.map((h) => `${h.name} (${dayWords(locale, h.date)})`).join(', ')}</span> : null}
                        </p>
                      ) : null}
                      {shownProblem ? <Alert id="leave-problem" tone="danger">{shownProblem}</Alert> : null}
                      {inView.length ? (
                        <div className="flex flex-col gap-1">
                          <h3 id="holidays" className="m-0 text-base font-semibold">Holidays</h3>
                          <ul aria-labelledby="holidays" className="m-0 flex flex-col gap-1 ps-5">
                            {inView.map((h) => <li key={h.date}><time dateTime={h.date}>{dayWords(locale, h.date, undefined, true)}</time>: {h.name}</li>)}
                          </ul>
                        </div>
                      ) : null}
                    </section>
                    <Field label="Note for your manager" optional>
                      <Textarea rows={3} value={note} onChange={(e) => setNote(e.target.value)} />
                    </Field>
                    <div className="flex flex-col items-start gap-3">
                      {failed ? <Alert tone="danger">Couldn’t send the request. Try again.</Alert> : null}
                      <Button loading={busy} onClick={send}>Send request</Button>
                    </div>
                  </div>
                  <div className="flex flex-col gap-6">
                    <Card>
                      <section aria-labelledby="balance" className="flex flex-col gap-4">
                        <h2 id="balance" className={h2}>Annual leave</h2>
                        <DescriptionList layout="split">
                          <DescriptionItem term="You have">{count(balance)}</DescriptionItem>
                          <DescriptionItem term="Waiting for approval">{count(waiting)}</DescriptionItem>
                          <DescriptionItem term="Left after those" emphasis>{count(left)}</DescriptionItem>
                        </DescriptionList>
                      </section>
                    </Card>
                    <section aria-labelledby="mine" className="flex flex-col gap-4">
                      <h2 id="mine" className={h2}>Your requests</h2>
                      {requests.length ? (
                        <ul ref={list} aria-labelledby="mine" className="m-0 flex list-none flex-col gap-2 p-0">
                          {requests.map((r) => (
                            <li key={r.id} tabIndex={-1} className="flex flex-col gap-1 rounded-md border border-border p-3">
                              <span className="flex flex-wrap items-center justify-between gap-2">
                                <span className="font-medium">{dayWords(locale, r.start, r.end)}</span>
                                <Badge tone={STATUS[r.status].tone}>{STATUS[r.status].label}</Badge>
                              </span>
                              <span className="text-sm text-text-muted">{KINDS.find((k) => k.value === r.kind)!.label}, {count(r.days)}</span>
                            </li>
                          ))}
                        </ul>
                      ) : <p className="m-0 text-text-muted">No requests yet.</p>}
                    </section>
                  </div>
                </div>
              )}
          </div>
        </Stack>
      </Container>
      <Toaster />
    </div>
  );
}

