'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { List, ListItem, ListVirtualItems } from '@diki-stwn/serupa-ds';
import { Navbar, NavbarLink } from '@diki-stwn/serupa-ds';
import { NotificationCenter, type NotificationItem } from '@diki-stwn/serupa-ds';
import { RelativeTime } from '@diki-stwn/serupa-ds';
import { SegmentedControl } from '@diki-stwn/serupa-ds';
import { EmptyState } from '@diki-stwn/serupa-ds';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { EmptyLoadFailed } from './EmptyStates';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Notifications: a bell in the Navbar that opens the recent ones in a drawer, and a full inbox page with a filter,
   mark as read and mark all as read. Both read the same list. For an app to copy. What it carries (WCAG 2.2):
   - 4.1.2, 1.3.1: the bell is named with its count ("Notifications, 3 unread"), so the number is heard, not only seen.
   - 1.4.1: an unread notification says "Unread" in words, besides the dot before it and its bolder title, which
     are what make it stand out at a glance (the same dot and weight as the drawer's).
   - 4.1.3, 3.3.3: a failed load says so once, in the list's place, with Try again (EmptyLoadFailed).
   - 4.1.3: while they load, the count says "Loading notifications" and the list is busy, with placeholder rows.
   - 4.1.3: the count above the list is a status, so marking one read or changing the filter is said politely.
   - 2.4.3: marking one read on the page takes its button away (and, under "Unread", the notification too), so focus
     goes to the next unread one's button, or the heading when none are left; after Mark all as read it goes to the
     heading. Never to the top of the page. In the drawer, focus stays in the drawer.
   - People choose what interrupts them: "Notification settings" sits by the heading (in More actions on a phone), and the empty state links there
     too (the Ethical design rule: turning notifications off takes no more steps than turning them on).
   Storing what's read is the app's job: onMarkRead and onMarkAllRead hear it. */

export interface NotificationsProps {
  /** The notifications, newest first. Default: a demo account's. */
  items?: readonly NotificationItem[] | undefined;
  /** One was marked read. */
  onMarkRead?: ((id: string) => void) | undefined;
  /** All were marked read. */
  onMarkAllRead?: (() => void) | undefined;
  /** The notifications failed to load: a "Couldn’t load" message with Try again, which calls onRetry, in their place. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** The notifications are on their way: placeholder rows, and the count says "Loading notifications". Default: false. */
  loading?: boolean | undefined;
  /** Where "Notification settings" leads: the page where people choose which notifications they get. Default: "#settings-notifications". */
  settingsHref?: string | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

// Times are minutes before the page loaded, so they read the same whenever the page is drawn.
const now = Date.now();
const ago = (minutes: number) => now - minutes * 60_000;
const demo: NotificationItem[] = [
  { id: 'n1', title: 'Ana Lima mentioned you in Website redesign', description: '“Can you check the new pricing copy?”', tone: 'info', time: ago(5) },
  { id: 'n2', title: 'Your export is ready', description: 'projects-october.csv, 2.4 MB', tone: 'success', time: ago(42) },
  { id: 'n3', title: 'A payment failed', description: 'The card ending 4242 was declined. Update it to keep your plan.', tone: 'danger', time: ago(180) },
  { id: 'n4', title: 'Budi Santoso joined the team', tone: 'info', time: ago(60 * 20), read: true },
  { id: 'n5', title: 'Storage is almost full', description: '8.6 GB of 10 GB used.', tone: 'warning', time: ago(60 * 23), read: true },
];

type Filter = 'all' | 'unread';

/** The notifications page: a skip link, a Navbar with the bell, then main with the inbox. */
export function Notifications({ items = demo, onMarkRead, onMarkAllRead, settingsHref = '#settings-notifications', loading = false, loadFailed = false, onRetry, online }: NotificationsProps) {
  const locale = useLocale();
  // Marked read here, on top of what the items say, so items that arrive later (after loading) keep their own.
  const [read, setRead] = React.useState<ReadonlySet<string>>(() => new Set());
  const [filter, setFilter] = React.useState<Filter>('all');
  const [open, setOpen] = React.useState(false);
  const heading = React.useRef<HTMLHeadingElement>(null);
  const focusTo = React.useRef<string | null>(null);
  const all = items.map((n) => ({ ...n, read: !!n.read || read.has(n.id) }));
  const unread = all.filter((n) => !n.read).length;
  const shown = filter === 'unread' ? all.filter((n) => !n.read) : all;

  // every render: a focus asked for by a handler (focusTo) moves once the render it caused is on screen.
  React.useEffect(() => {
    const to = focusTo.current;
    focusTo.current = null;
    if (to === 'heading') heading.current?.focus();
    else if (to) document.getElementById(`read-${to}`)?.focus();
  });

  // onPage: pressed on the page, whose button goes away with it; the drawer keeps focus itself.
  const markRead = (id: string, onPage?: boolean) => {
    if (onPage) {
      const at = shown.findIndex((n) => n.id === id);
      const next = shown.slice(at + 1).find((n) => !n.read) || shown.slice(0, at).reverse().find((n) => !n.read);
      focusTo.current = next ? next.id : 'heading';
    }
    setRead((r) => new Set(r).add(id));
    onMarkRead?.(id);
  };
  const markAll = (onPage?: boolean) => {
    if (onPage) focusTo.current = 'heading';
    setRead(new Set(items.map((n) => n.id)));
    onMarkAllRead?.();
  };
  const bellName = unread ? `Notifications, ${formatNumber(unread, locale)} unread` : 'Notifications';

  return (
    <div className="min-h-screen bg-surface-sunken text-text">
      <SkipLink />
      <Navbar brand="Acme" actions={
        <Button variant="ghost" startIcon="notifications" aria-label={bellName} onClick={() => setOpen(true)}>
          {unread ? <Badge count={unread} /> : null}
        </Button>
      }>
        <NavbarLink href="#dashboard">Dashboard</NavbarLink>
        <NavbarLink href="#projects">Projects</NavbarLink>
        <NavbarLink href="#notifications" current>Notifications</NavbarLink>
      </Navbar>
      <NotificationCenter items={all.slice(0, 5)} open={open} onOpenChange={setOpen} onMarkRead={(id) => markRead(id)} onMarkAllRead={() => markAll()} />

      <Container as="main" size="md" className="py-8 outline-none" id="main">
        <Stack gap={6}>
          <OfflineBanner online={online} placement="inline">These are the notifications loaded before you went offline. New ones show when you’re back.</OfflineBanner>
          <PageHeader title="Notifications" headingRef={heading}
            primary={{ label: 'Mark all as read', disabled: loading || loadFailed || !unread, onSelect: () => markAll(true) }}
            secondary={[{ label: 'Notification settings', icon: 'settings', href: settingsHref }]} />
          <div className="flex flex-wrap items-center justify-between gap-3">
            <SegmentedControl aria-label="Show" value={filter} onValueChange={setFilter}
              options={[{ value: 'all', label: 'All' }, { value: 'unread', label: 'Unread' }]} />
            <p role="status" className="m-0 text-sm text-text-muted">{loadFailed ? '' : loading ? 'Loading notifications' : unread ? `${formatNumber(unread, locale)} unread` : 'All caught up'}</p>
          </div>
          {loadFailed ? (
            <EmptyLoadFailed title="Couldn’t load your notifications" onRetry={() => onRetry?.()} headingLevel={2} />
          ) : loading ? (
            // Placeholder rows the shape of a notification; the status above says it's loading, so they're pictures only.
            <ul role="list" aria-busy="true" aria-label="All notifications" className="m-0 flex list-none flex-col gap-4 rounded-lg border border-border bg-surface p-4">
              {[0, 1, 2].map((i) => <li key={i}><Skeleton shape="text" size="sm" lines={2} label="" /></li>)}
            </ul>
          ) : !items.length ? (
            <EmptyState icon="notifications" title="No notifications yet" headingLevel={2}
              description="When someone mentions you, an export finishes or a payment needs you, it shows up here."
              actions={<Button variant="outline" startIcon="settings" href={settingsHref}>Choose what you hear about</Button>} />
          ) : shown.length ? (
            // ListVirtualItems: a year of notifications draws only the rows in view, in a box that scrolls by keyboard,
            // and each row still says where it is ("5 of 1,200").
            <List variant="card" divided aria-label={filter === 'unread' ? 'Unread notifications' : 'All notifications'}>
            <ListVirtualItems count={shown.length} itemKey={(i) => shown[i]!.id} estimatedItemHeight={72}
              renderItem={(i) => { const n = shown[i]!; return (
                <ListItem
                  // The drawer's unread dot before the title (and room for it on read ones, so the titles line up); the
                  // description starts under the title, not under the dot, as in the drawer.
                  title={<span className="flex items-baseline gap-2"><span className={'srp-notification-center__dot self-center' + (n.read ? ' invisible' : '')} aria-hidden="true" /><span className={n.read ? undefined : 'font-semibold'}>{n.title}</span></span>}
                  description={<span className="block ps-4">{n.description ? <>{n.description} · </> : null}<RelativeTime date={n.time ?? now} />{n.read ? null : <> · Unread</>}</span>}
                  trailing={n.read ? null : <Button id={`read-${n.id}`} size="sm" variant="ghost" aria-label={typeof n.title === 'string' ? `Mark as read: ${n.title}` : undefined} onClick={() => markRead(n.id, true)}>Mark as read</Button>} />
              ); }} />
            </List>
          ) : (
            <p className="m-0 rounded-lg border border-border bg-surface p-6 text-center text-text-muted">No unread notifications. You’re all caught up.</p>
          )}
        </Stack>
      </Container>
    </div>
  );
}

files.Onboarding.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Checkbox } from '@diki-stwn/serupa-ds';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { Progress } from '@diki-stwn/serupa-ds';
import { EmptyState } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { announce } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { EmptyLoadFailed } from './EmptyStates';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';
import { Tour, type TourStep } from '@diki-stwn/serupa-ds';

/* Onboarding / first run: the first page a new account sees. A checklist of setup steps with how far along it
   is, an empty state that says what to do first, and progress that's kept between visits. For an app to copy.
   What it carries (WCAG 2.2):
   - 1.3.1 in Safari: role="list" on the lists without bullets, since WebKit stops calling them lists.
   - 1.3.1: the steps are an ordered list, each a heading (h3 under the checklist's h2), so a screen reader can list
     and jump between them, and hears "1 of 4".
   - 1.4.10: a long title or a URL in a description wraps inside its card at 320 px, not past it.
   - 1.4.1: a done step says "Done" in words beside its tick, not by color or a strike-through alone.
   - 4.1.3: ticking a step says the new count ("2 of 4 steps done") politely, without moving focus. The last tick says
     "You're all set" once, and the page shows what's next.
   - 2.4.3: hiding the checklist moves focus to "Show the checklist", which takes its place; showing it again moves
     focus to the checklist's heading, so focus never drops to the page's start.
   - Progress and the hidden choice are kept between visits (here in localStorage under
     `saveKey`; an app keeps them on its server with `onChange`), so nobody is asked to do a step twice.
   Doing each step (the pages its link opens) is the app's job; here the links go nowhere. */

export interface SetupStep {
  id: string;
  /** What to do, as a short command: "Invite your team". */
  title: string;
  /** Why, in a sentence. */
  description: string;
  /** Where the step is done. */
  action: { label: string; href: string };
}

export interface OnboardingState {
  /** The ids of the steps that are done. */
  done: string[];
  /** The checklist is folded away. */
  hidden: boolean;
}

export interface OnboardingProps {
  /** The person's first name, for the welcome. */
  name?: string | undefined;
  /** The setup steps, in order. Default: four steps for the demo workspace. */
  steps?: readonly SetupStep[] | undefined;
  /** Where it starts when nothing is saved yet. Default: nothing done, shown. */
  initial?: Partial<OnboardingState> | undefined;
  /** Keeps the state in localStorage under this key, so a reload or a later visit picks up where it was. */
  saveKey?: string | undefined;
  /** Called with each new state: save it on your server. */
  onChange?: ((state: OnboardingState) => void) | undefined;
  /** Where "Go to your dashboard" goes once every step is done. Default: "#dashboard". */
  dashboardHref?: string | undefined;
  /** Still loading the saved progress: a placeholder shows instead of the checklist. Default: false. */
  loading?: boolean | undefined;
  /** Loading failed: a "Couldn’t load your setup checklist" message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, from Try again. Return a promise: the button shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demoSteps: SetupStep[] = [
  { id: 'profile', title: 'Add your photo and job title', description: 'Your team sees them next to everything you write.', action: { label: 'Edit your profile', href: '#profile' } },
  { id: 'team', title: 'Invite your team', description: 'Projects are more use with the people you work with.', action: { label: 'Invite people', href: '#invite' } },
  { id: 'project', title: 'Create your first project', description: 'A project holds tasks, files and the talk about them.', action: { label: 'Create a project', href: '#new-project' } },
  { id: 'notifications', title: 'Choose your notifications', description: 'Pick what reaches you by email and what waits in the app.', action: { label: 'Open notification settings', href: '#notifications' } },
];

function load(key: string | undefined): Partial<OnboardingState> | null {
  if (!key) return null;
  try {
    const raw = window.localStorage.getItem(key);
    const s = raw ? (JSON.parse(raw) as { done?: unknown; hidden?: unknown } | null) : null;
    // Only the shape this page writes: anything else under the key (another script's value, an older shape) would
    // throw on every visit until the storage was cleared.
    return s && typeof s === 'object' ? { done: Array.isArray(s.done) ? s.done.filter((id): id is string => typeof id === 'string') : [], hidden: s.hidden === true } : null;
  } catch { return null; }
}
function save(key: string | undefined, state: OnboardingState) {
  if (!key) return;
  try { window.localStorage.setItem(key, JSON.stringify(state)); } catch { /* private mode or full: keeping it is a nicety */ }
}

/** The first-run page: a skip link, a header, then main with the welcome, the setup checklist and an empty project list. */
/** The tour: three stops, each at the part of the page it explains. */
const TOUR: TourStep[] = [
  { target: '#setup-title', title: 'Your setup checklist', content: 'A few steps that get your workspace ready. Tick each one off as you go; we keep your place.' },
  { target: '#projects-title', title: 'Your projects', content: 'Each project holds a piece of work: its tasks, its files and the talk about them.' },
  { title: 'That’s the tour', content: 'Take it again any time from Take a quick tour at the top of this page.' },
];

export function Onboarding({ name = 'Ada', steps = demoSteps, initial, saveKey, onChange, dashboardHref = '#dashboard', loading = false, loadFailed = false, onRetry, online }: OnboardingProps) {
  const locale = useLocale();
  const start = (): OnboardingState => {
    const saved = load(saveKey) ?? initial ?? {};
    const ids = new Set(steps.map((s) => s.id));
    return { done: (saved.done ?? []).filter((id) => ids.has(id)), hidden: saved.hidden ?? false };
  };
  const [state, setState] = React.useState<OnboardingState>(start);
  // The saved progress the app passes once loading ends replaces where it started.
  const [wasLoading, setWasLoading] = React.useState(loading);
  if (wasLoading !== loading) { setWasLoading(loading); if (!loading) setState(start()); }
  const update = (next: OnboardingState) => { setState(next); save(saveKey, next); onChange?.(next); };
  const count = (n: number) => `${formatNumber(n, locale)} of ${formatNumber(steps.length, locale)} steps done`;
  const finished = state.done.length === steps.length;

  const tick = (id: string, on: boolean) => {
    const done = steps.map((s) => s.id).filter((x) => (x === id ? on : state.done.includes(x)));
    update({ ...state, done });
    announce(done.length === steps.length ? `${count(done.length)}. You’re all set.` : count(done.length));
  };

  // After hiding or showing, focus goes to what took the place of the button that was pressed.
  const showButton = React.useRef<HTMLButtonElement | null>(null);
  const [touring, setTouring] = React.useState(false);
  const heading = React.useRef<HTMLHeadingElement | null>(null);
  const moved = React.useRef(false);
  React.useEffect(() => {
    if (!moved.current) return;
    moved.current = false;
    (state.hidden ? showButton.current : heading.current)?.focus();
  }, [state.hidden]);
  const setHidden = (hidden: boolean) => { moved.current = true; update({ ...state, hidden }); };

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <Container as="main" size="md" className="py-8 outline-none" id="main">
        <Stack gap={6}>
          <OfflineBanner online={online} placement="inline">Your progress is kept on this device. Some steps need a connection.</OfflineBanner>
          <PageHeader title={`Welcome to Acme, ${name}`} description="A few steps get your workspace ready. Do them in any order, now or later: we keep your place."
            primary={{ label: 'Take a quick tour', onSelect: () => setTouring(true) }} />
          <Tour open={touring} onOpenChange={setTouring} steps={TOUR} />

          {loadFailed ? <EmptyLoadFailed title="Couldn’t load your setup checklist" onRetry={() => onRetry?.()} headingLevel={2} />
            : loading ? <Card><Skeleton shape="text" lines={6} label="Loading your setup checklist" /></Card> : (
          <section aria-labelledby="setup-title" className="flex flex-col gap-4">
            {state.hidden ? (
              <Card padding="sm" className="flex flex-row flex-wrap items-center justify-between gap-3">
                <Heading level={2} size="base" id="setup-title">Set up your workspace: {count(state.done.length)}</Heading>
                <Button ref={showButton} variant="secondary" size="sm" onClick={() => setHidden(false)}>Show the checklist</Button>
              </Card>
            ) : (
              <>
                <div className="flex flex-wrap items-center justify-between gap-3">
                  <Heading level={2} size="lg" id="setup-title" ref={heading} tabIndex={-1} className="outline-none">Set up your workspace</Heading>
                  <Button variant="ghost" size="sm" onClick={() => setHidden(true)}>Hide the checklist</Button>
                </div>
                <Progress label="Setup progress" value={state.done.length} max={steps.length} showValue tone={finished ? 'success' : 'primary'}
                  formatValue={(v) => count(v)} />
                {finished ? (
                  <Card>
                    <EmptyState icon="check_circle" size="sm" headingLevel={3} title="You’re all set"
                      description="Your workspace is ready. Everything here stays where you left it."
                      actions={<Button href={dashboardHref}>Go to your dashboard</Button>} />
                  </Card>
                ) : null}
                <ol role="list" className="m-0 flex list-none flex-col gap-3 p-0">
                  {steps.map((s, i) => {
                    const done = state.done.includes(s.id);
                    return (
                      <Card as="li" key={s.id} padding="md" className="flex min-w-0 flex-col gap-3 wrap-anywhere" aria-labelledby={`step-${s.id}`}>
                        <div className="flex flex-col gap-1">
                          <Heading level={3} size="base" id={`step-${s.id}`}>
                            <span className="text-text-muted">{formatNumber(i + 1, locale)}. </span>{s.title}
                          </Heading>
                          <p className="m-0 text-sm text-text-muted">{s.description}</p>
                        </div>
                        <div className="flex flex-wrap items-center gap-x-6 gap-y-2">
                          <Button href={s.action.href} variant={done ? 'secondary' : 'primary'} size="sm">{s.action.label}</Button>
                          <Checkbox checked={done} onCheckedChange={(on) => tick(s.id, on)} description={done ? 'Done' : 'To do'}>
                            Mark “{s.title}” as done
                          </Checkbox>
                        </div>
                      </Card>
                    );
                  })}
                </ol>
              </>
            )}
          </section>
          )}

          <section aria-labelledby="projects-title" className="flex flex-col gap-4">
            <Heading level={2} size="lg" id="projects-title">Your projects</Heading>
            <Card variant="filled">
              <EmptyState icon="folder_open" size="sm" headingLevel={3} title="No projects yet"
                description="A project holds a piece of work: its tasks, its files and the talk about them. Start with one you’re doing now."
                actions={<Button href="#new-project">Create a project</Button>} />
            </Card>
          </section>
        </Stack>
      </Container>
    </div>
  );
}

files.OrderHistory.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Badge, type BadgeTone } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { SearchInput } from '@diki-stwn/serupa-ds';
import { Select } from '@diki-stwn/serupa-ds';
import { LoadMore } from '@diki-stwn/serupa-ds';
import { EmptyState } from '@diki-stwn/serupa-ds';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { Toaster, toast } from '@diki-stwn/serupa-ds';
import { FormattedNumber } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { FormattedDate } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { EmptyLoadFailed, EmptyNoResults } from './EmptyStates';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Order history: every order you've placed, newest first, found by what was in it or by where it's got to, each with a
   way to see it and buy it again. For an app to copy. What it carries (WCAG 2.2):
   - 1.3.1: the orders are a list, each headed by its number, with its date, total and items said in words.
   - 1.4.1: where an order has got to is a word in a badge ("On the way", "Delivered"), never a color alone.
   - 2.4.4, 2.4.6: each link and button names its order ("View order A-10432", "Buy again: order A-10432").
   - 4.1.3: how many orders match is a status, read out as the search or the filter changes.
   - 3.3.1: no match says so with the words searched for, and a way to clear the search and the filter.
   - 2.4.3: Show more adds the next orders and puts focus on the first new one, so nothing is read twice.
   - 4.1.3: Buy again shows it's busy, then a toast says what went into the cart, or that it couldn't.
   - 4.1.3, 3.3.1: while the orders load, a placeholder named once; a failed load says so, with Try again.
   The orders are the app's: pass them all, or page them with onLoadMore; onBuyAgain puts an order's items in the
   cart, and rejects when it can't. */

export type OrderState = 'processing' | 'shipped' | 'delivered' | 'cancelled' | 'returned';

export interface PastOrder {
  /** "A-10432". */
  number: string;
  /** When it was placed: "2025-03-04". */
  placed: string;
  total: number;
  state: OrderState;
  /** What was in it, by name: ["Linen shirt", "Canvas tote"]. */
  items: string[];
  href?: string | undefined;
}

export interface OrderHistoryProps {
  /** The orders, newest first. Default: demo orders. */
  orders?: PastOrder[] | undefined;
  /** ISO 4217 currency. Default: "USD". */
  currency?: string | undefined;
  /** How many to show at first, and add with each Show more. Default: 5. */
  pageSize?: number | undefined;
  /** Puts an order's items in the cart again. Reject when it can't. */
  onBuyAgain?: ((order: string) => unknown) | undefined;
  /** The orders are on their way: placeholders, named once ("Loading orders"). Default: false. */
  loading?: boolean | undefined;
  /** They failed to load: a message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  onRetry?: (() => void) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

export const STATES: Record<OrderState, { label: string; tone: BadgeTone }> = {
  processing: { label: 'Being packed', tone: 'neutral' },
  shipped: { label: 'On the way', tone: 'info' },
  delivered: { label: 'Delivered', tone: 'success' },
  cancelled: { label: 'Canceled', tone: 'danger' },
  returned: { label: 'Returned', tone: 'warning' },
};
const NAMES = ['Linen shirt', 'Canvas tote', 'Wool socks', 'Rain jacket', 'Clay mug', 'Desk lamp', 'Notebook', 'Tea towel'];
const KINDS: OrderState[] = ['shipped', 'processing', 'delivered', 'delivered', 'cancelled', 'delivered', 'returned', 'delivered'];
const demo: PastOrder[] = Array.from({ length: 12 }, (_, i) => ({
  number: `A-${10432 - i * 37}`,
  placed: `2025-${String(12 - Math.floor(i / 2)).padStart(2, '0')}-${String(20 - (i % 2) * 9).padStart(2, '0')}`,
  total: 24 + ((i * 29) % 140),
  state: KINDS[i % KINDS.length]!,
  items: [NAMES[i % NAMES.length]!, ...(i % 3 ? [NAMES[(i + 3) % NAMES.length]!] : []), ...(i % 4 === 0 ? [NAMES[(i + 5) % NAMES.length]!] : [])],
  href: `#order-A-${10432 - i * 37}`,
}));

/** The orders that match the words (in the number or an item's name) and the state, in their order. */
export function matchOrders(orders: readonly PastOrder[], q: string, state: OrderState | ''): PastOrder[] {
  const words = q.trim().toLowerCase();
  return orders.filter((o) => (!state || o.state === state)
    && (!words || o.number.toLowerCase().includes(words) || o.items.some((n) => n.toLowerCase().includes(words))));
}

/** "Linen shirt", "Linen shirt and Canvas tote", "Linen shirt, Canvas tote and 2 more". */
export function itemWords(items: readonly string[], more: (n: number) => string = (n) => `${n} more`): string {
  if (items.length <= 2) return items.join(' and ');
  return `${items[0]}, ${items[1]} and ${more(items.length - 2)}`;
}

/** The order history page: a skip link, a header, then main with the h1, the search and filter, and the orders. */
export function OrderHistory({ orders = demo, currency = 'USD', pageSize = 5, onBuyAgain, loading = false, loadFailed = false, onRetry, online }: OrderHistoryProps) {
  const locale = useLocale();
  const [q, setQ] = React.useState('');
  const [state, setState] = React.useState<OrderState | ''>('');
  const [shown, setShown] = React.useState(pageSize);
  const [buying, setBuying] = React.useState<string | null>(null);
  const found = matchOrders(orders, q, state);
  const page = found.slice(0, shown);
  const n = (x: number) => formatNumber(x, locale);
  const filter = (next: { q?: string; state?: OrderState | '' }) => {
    if (next.q !== undefined) setQ(next.q);
    if (next.state !== undefined) setState(next.state);
    setShown(pageSize);
  };
  const mainRef = React.useRef<HTMLElement>(null);
  const more = () => {
    const first = page.length;
    setShown((s) => s + pageSize);
    requestAnimationFrame(() => mainRef.current?.querySelectorAll<HTMLElement>('[data-order-heading]')[first]?.focus());
  };
  const buyAgain = (o: PastOrder) => {
    setBuying(o.number);
    void Promise.resolve().then(() => onBuyAgain?.(o.number)).then(
      () => toast({ title: `Added to your cart: ${itemWords(o.items, (k) => `${n(k)} more`)}`, tone: 'success' }),
      () => toast({ title: `Couldn’t add order ${o.number} to your cart. Try again.`, tone: 'danger' }),
    ).finally(() => setBuying(null));
  };

  return (
    <div className="min-h-screen bg-surface-sunken text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <Container as="main" size="lg" className="py-8 outline-none" ref={mainRef} id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">These are the orders loaded before you went offline. Buying again needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Account', href: '#account' }, { label: 'Orders' }]} title="Orders" description="Every order you’ve placed, newest first." />
          <div className="flex flex-col gap-5 pt-6">
            {loadFailed ? <EmptyLoadFailed title="Couldn’t load your orders" onRetry={() => onRetry?.()} headingLevel={2} />
              : loading ? <Card><Skeleton shape="text" lines={6} label="Loading orders" /></Card>
              : !orders.length ? <EmptyState icon="receipt_long" title="No orders yet" description="What you buy shows here, with where it’s got to." headingLevel={2}
                  actions={<Link href="#shop">Start shopping</Link>} />
              : <>
                <div role="search" aria-label="Orders" className="flex flex-wrap items-end gap-3">
                  <Field label="Search orders" hint="By order number or what was in it." className="min-w-0 flex-1">
                    <SearchInput value={q} onChange={(e) => filter({ q: e.target.value })} onClear={() => filter({ q: '' })} />
                  </Field>
                  <Field label="Show">
                    <Select value={state} onChange={(e) => filter({ state: e.target.value as OrderState | '' })}
                      options={[{ value: '', label: 'All orders' }, ...(Object.keys(STATES) as OrderState[]).map((k) => ({ value: k, label: STATES[k].label }))]} />
                  </Field>
                </div>
                <p id="order-count" role="status" className="m-0 text-sm text-text-muted">
                  {found.length === orders.length ? `${n(orders.length)} orders` : `${n(found.length)} of ${n(orders.length)} orders`}
                </p>
                {!found.length ? (
                  <EmptyNoResults query={q.trim()} title={(text) => (text ? `No orders match “${text}”` : 'No orders match this filter')}
                    description="Check the spelling, or clear the search to see every order." headingLevel={2} onClearFilters={() => filter({ q: '', state: '' })} />
                ) : (
                  <ul className="m-0 flex list-none flex-col gap-3 p-0">
                    {page.map((o) => (
                      <li key={o.number}>
                        <Card className="flex flex-col gap-3">
                          <div className="flex flex-wrap items-center justify-between gap-2">
                            <h2 data-order-heading tabIndex={-1} className="m-0 text-base font-semibold outline-none">Order {o.number}</h2>
                            <Badge tone={STATES[o.state].tone}>{STATES[o.state].label}</Badge>
                          </div>
                          <p className="m-0 text-sm text-text-muted">
                            Placed <FormattedDate value={o.placed} /> · <FormattedNumber value={o.total} format="currency" currency={currency} />
                          </p>
                          <p className="m-0 wrap-break-word">{itemWords(o.items, (k) => `${n(k)} more`)}</p>
                          <div className="flex flex-wrap items-center gap-3">
                            <Button href={o.href ?? '#'} size="sm" variant="outline" aria-label={`View order ${o.number}`}>View order</Button>
                            {o.state === 'cancelled' ? null : (
                              <Button size="sm" variant="outline" loading={buying === o.number} aria-label={`Buy again: order ${o.number}`} onClick={() => buyAgain(o)}>Buy again</Button>
                            )}
                          </div>
                        </Card>
                      </li>
                    ))}
                  </ul>
                )}
                {found.length ? <LoadMore onLoadMore={more} hasMore={page.length < found.length} count={page.length} total={found.length} label="Show more orders" /> : null}
              </>}
          </div>
        </Stack>
      </Container>
      <Toaster />
    </div>
  );
}

