'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Avatar } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { Textarea } from '@diki-stwn/serupa-ds';
import { FileUpload } from '@diki-stwn/serupa-ds';
import { SaveStatus, type SaveState } from '@diki-stwn/serupa-ds';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { ErrorSummary, type ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { EmptyLoadFailed } from './EmptyStates';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';
import { TimeZonePicker } from '@diki-stwn/serupa-ds';
import { ImageCropper, type CropArea } from '@diki-stwn/serupa-ds';

/* Profile: what other people see of you (a photo, your name, a short bio, where you are, your time zone and a link), edited in one
   form and saved when you say so. For an app to copy. What it carries (WCAG 2.2):
   - 1.1.1: the photo's preview says whose it is; without a photo, the avatar shows initials and still names you.
   - 3.3.2, 1.3.5: each field says what it's for and its limits: the bio counts what's left as you type, the photo
     says which files and how big; name and link say what they are for autofill.
   - 3.3.1, 2.4.3: a missing name, or a link that isn't one, is said in a summary that takes focus when you save, each
     a link to its field, which says it too. A photo that's too big or not an image is said by the upload itself.
   - 4.1.3: Save says where it's got to (Saving, Saved, or a failure with Try again) in a status that's read out.
   - 3.3.4: Discard changes is there only once something has changed, and puts back what was saved.
   - 2.4.6: the form's heading says whose profile it is, and its preview shows the result as others will see it.
   - 4.1.3, 3.3.1: while the profile loads, a placeholder named once; a failed load says so, with Try again.
   Saving is the app's job: onSave gets the profile, the new photo, if any, and the part of it to keep, from the
   ImageCropper under the upload (cropImage draws it); reject its promise when it fails. */

export interface ProfileInfo {
  name: string;
  /** A sentence or two about you. */
  bio: string;
  /** Where you are: "Bandung, Indonesia". */
  location: string;
  /** A link to your site, or empty. */
  website: string;
  /** The photo's address, or empty for initials. */
  photo: string;
  /** Your time zone, an IANA name ("Asia/Jakarta"), so others know when you're around. Leave it out for none. */
  timeZone?: string | undefined;
}

export interface ProfileProps {
  /** The profile as saved. Default: a demo profile. */
  profile?: ProfileInfo | undefined;
  /** The bio's limit, in characters. Default: 160. */
  bioLimit?: number | undefined;
  /** Saves the profile. With a new photo, crop is the square of it to keep, in its own pixels (cropImage draws it).
      Return its promise: a rejection keeps the changes and offers Try again. */
  onSave?: ((profile: ProfileInfo, photo: File | null, crop: CropArea | null) => unknown) | undefined;
  /** The profile is on its way from the server: placeholders, named once ("Loading profile"). Default: false. */
  loading?: boolean | undefined;
  /** The profile failed to load: a message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads the profile again, after a failed load. */
  onRetry?: (() => void) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demo: ProfileInfo = { name: 'Ana Lima', bio: 'Product designer. I draw interfaces, maps and the odd cat.', location: 'Bandung, Indonesia', website: 'https://ana.example.com', photo: '', timeZone: 'Asia/Jakarta' };

/** What's wrong with the profile, by field, or {} when it can be saved. */
export function profileProblems(p: Pick<ProfileInfo, 'name' | 'website' | 'bio'>, bioLimit = 160): Partial<Record<'name' | 'website' | 'bio', string>> {
  const out: Partial<Record<'name' | 'website' | 'bio', string>> = {};
  if (!p.name.trim()) out.name = 'Enter your name.';
  const link = p.website.trim();
  if (link && !/^https?:\/\/[^\s.]+\.[^\s]+$/.test(link)) out.website = 'Enter a link that starts with https://, like https://example.com.';
  if (p.bio.length > bioLimit) out.bio = `Shorten your bio to ${bioLimit} characters.`;
  return out;
}

/** Whether two profiles differ in anything a person typed. */
export const profileChanged = (a: ProfileInfo, b: ProfileInfo): boolean =>
  a.name !== b.name || a.bio !== b.bio || a.location !== b.location || a.website !== b.website || a.photo !== b.photo || (a.timeZone ?? '') !== (b.timeZone ?? '');

/** The profile page: a skip link, a header, then main with the h1, the form and a preview. */
/** The fields that can have a problem, in the order they show. */
const PARTS = ['name', 'bio', 'website'] as const;

export function Profile({ profile: start = demo, bioLimit = 160, onSave, loading = false, loadFailed = false, onRetry, online }: ProfileProps) {
  const [saved, setSaved] = React.useState(start);
  const [draft, setDraft] = React.useState(start);
  // What the app passes once loading ends replaces what was there, which was empty or the demo.
  const [wasLoading, setWasLoading] = React.useState(loading);
  if (wasLoading !== loading) { setWasLoading(loading); if (!loading) { setSaved(start); setDraft(start); } }
  const [files, setFiles] = React.useState<File[]>([]);
  const [crop, setCrop] = React.useState<CropArea | null>(null);
  const [problems, setProblems] = React.useState<ReturnType<typeof profileProblems>>({});
  const [tries, setTries] = React.useState(0);
  const [status, setStatus] = React.useState<SaveState>('idle');
  const [savedAt, setSavedAt] = React.useState<Date | undefined>(undefined);
  // The new photo's preview: an object URL made once per file, and let go when the file changes or the page goes.
  const preview = React.useMemo(() => (files[0] ? URL.createObjectURL(files[0]) : ''), [files]);
  // A saved one is the profile's photo now: it's let go when another is saved, or when the page goes.
  const kept = React.useRef('');
  React.useEffect(() => () => { if (preview && preview !== kept.current) URL.revokeObjectURL(preview); }, [preview]);
  React.useEffect(() => () => { if (kept.current) URL.revokeObjectURL(kept.current); }, []);
  const photo = preview || draft.photo;
  const dirty = profileChanged(draft, saved) || files.length > 0;

  const edit = (patch: Partial<ProfileInfo>) => {
    setDraft((now) => ({ ...now, ...patch }));
    if (status !== 'saving') setStatus('idle');
  };
  const discard = () => { setDraft(saved); setFiles([]); setProblems({}); setStatus('idle'); };
  const errors: ErrorSummaryItem[] = PARTS.filter((k) => problems[k]).map((k) => ({ field: `profile-${k}`, message: problems[k] }));
  const save = (e?: React.FormEvent) => {
    e?.preventDefault();
    const found = profileProblems(draft, bioLimit);
    setProblems(found);
    setTries((t) => t + 1);
    if (PARTS.some((k) => found[k])) return;
    const sent = { ...draft, name: draft.name.trim(), location: draft.location.trim(), website: draft.website.trim() };
    setStatus('saving');
    void Promise.resolve().then(() => onSave?.(sent, files[0] ?? null, files[0] ? crop : null)).then(() => {
      const next = { ...sent, photo: preview || sent.photo };
      if (preview) { if (kept.current) URL.revokeObjectURL(kept.current); kept.current = preview; }
      setSaved(next);
      setDraft(next);
      setFiles([]);
      setSavedAt(new Date());
      setStatus('saved');
    }, () => setStatus('error'));
  };

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <Container as="main" size="lg" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">Your changes stay here. Saving them needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Settings', href: '#settings' }, { label: 'Profile' }]} title="Profile"
            description="What other people see of you." />

          <div className="pt-6">
            {loadFailed ? <EmptyLoadFailed title="Couldn’t load your profile" onRetry={() => onRetry?.()} headingLevel={2} />
              : loading ? <Card><Skeleton shape="text" lines={6} label="Loading profile" /></Card> : (
                <div className="grid items-start gap-6 md:grid-cols-3">
                  <form onSubmit={save} noValidate aria-labelledby="edit" className="flex flex-col gap-4 md:col-span-2">
                    <h2 id="edit" className="m-0 text-lg font-semibold">Edit {saved.name ? `${saved.name}’s` : 'your'} profile</h2>
                    <ErrorSummary key={tries} errors={errors} headingLevel={3} />
                    <p className="m-0 text-text-muted">Fields marked * are required.</p>
                    <div className="flex flex-wrap items-center gap-4">
                      <Avatar size="xl" name={draft.name || saved.name} src={photo || undefined} alt={photo ? `Photo of ${draft.name || saved.name}` : undefined} />
                      {draft.photo && !files.length ? <Button variant="outline" size="sm" onClick={() => edit({ photo: '' })}>Remove photo</Button> : null}
                    </div>
                    <Field label="Photo" hint="A square JPEG or PNG works best, up to 2 MB." optional>
                      <FileUpload id="profile-photo" accept="image/png,image/jpeg,image/webp" maxSize={2 * 1024 * 1024} files={files} onFilesChange={(f) => { setFiles(f.slice(-1)); setCrop(null); if (status !== 'saving') setStatus('idle'); }} />
                    </Field>
                    {preview ? (
                      <Field label="Frame your photo" hint="Drag it, or use the arrow keys, to choose what shows in the circle; the slider zooms.">
                        <ImageCropper key={preview} src={preview} aspect={1} shape="round" onCropChange={setCrop} />
                      </Field>
                    ) : null}
                    <Field label="Name" id="profile-name" error={problems.name} required>
                      <Input autoComplete="name" value={draft.name} onChange={(e) => edit({ name: e.target.value })} />
                    </Field>
                    <Field label="Bio" id="profile-bio" hint={`Up to ${bioLimit} characters.`} error={problems.bio} optional>
                      <Textarea rows={3} maxLength={bioLimit} showCount value={draft.bio} onChange={(e) => edit({ bio: e.target.value })} />
                    </Field>
                    <Field label="Location" optional>
                      <Input autoComplete="address-level2" value={draft.location} onChange={(e) => edit({ location: e.target.value })} />
                    </Field>
                    <Field label="Time zone" optional>
                      <TimeZonePicker value={draft.timeZone ?? null} onValueChange={(z) => edit({ timeZone: z ?? undefined })} />
                    </Field>
                    <Field label="Website" id="profile-website" error={problems.website} optional>
                      <Input type="url" autoComplete="url" inputMode="url" value={draft.website} onChange={(e) => edit({ website: e.target.value })} />
                    </Field>
                    <div className="flex flex-wrap items-center gap-3">
                      <Button type="submit" loading={status === 'saving'}>Save profile</Button>
                      {dirty && status !== 'saving' ? <Button variant="outline" onClick={discard}>Discard changes</Button> : null}
                      <SaveStatus status={status} savedAt={savedAt} onRetry={() => save()} />
                    </div>
                    {status === 'error' ? <Alert tone="danger">Couldn’t save your profile. Your changes are still here.</Alert> : null}
                  </form>
                  <Card>
                    <section aria-labelledby="preview" className="flex flex-col items-start gap-4">
                      <h2 id="preview" className="m-0 text-lg font-semibold">How others see it</h2>
                      <Avatar size="lg" name={draft.name || saved.name} src={photo || undefined} alt="" />
                      <p className="m-0 text-base font-semibold">{draft.name.trim() || 'Your name'}</p>
                      {draft.bio ? <p className="m-0 wrap-break-word">{draft.bio}</p> : null}
                      {draft.location.trim() ? <p className="m-0 text-sm text-text-muted">{draft.location.trim()}</p> : null}
                      {draft.website.trim() && !profileProblems(draft, bioLimit).website ? <p className="m-0 text-sm wrap-break-word">{draft.website.trim().replace(/^https?:\/\//, '')}</p> : null}
                    </section>
                  </Card>
                </div>
              )}
          </div>
        </Stack>
      </Container>
    </div>
  );
}

files.Quiz.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { RadioGroup, Radio } from '@diki-stwn/serupa-ds';
import { CheckboxGroup, Checkbox } from '@diki-stwn/serupa-ds';
import { ErrorSummary, type ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { EmptyLoadFailed } from './EmptyStates';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Quiz: a few questions to check what was learned, all on one page, then the score and, for each question, whether
   it was right and why. For an app to copy. What it carries (WCAG 2.2):
   - 1.3.1, 3.3.2: each question is a fieldset whose legend is the question; one with more than one answer says
     "Choose all that apply" in its legend, and uses checkboxes, not radios.
   - 4.1.3: how many are answered is said in a status line as answers are chosen.
   - 3.3.1, 2.4.3: checking with questions left shows a summary at the top that takes focus, each a link to its
     question's first answer.
   - 2.4.3, 1.4.1: once checked, the score's heading takes focus; each question says "Right" or "Not quite" in words,
     with the right answer and why, not by color alone. The answers can't be changed until Try again.
   - 2.2.1: there's no time limit.
   Saving the score is the app's job: onCheck gets the answers and the score. */

export interface QuizQuestion {
  id: string;
  question: string;
  options: { value: string; label: string }[];
  /** The right answers: one for a radio question, more for "Choose all that apply". */
  answer: string[];
  /** Why that's the answer, shown once checked. */
  why: string;
}

export type QuizAnswers = Record<string, string[]>;

export interface QuizProps {
  /** The lesson's name, for the h1. Default: a demo lesson. */
  title?: string | undefined;
  /** The questions. Default: demo questions on accessible forms. */
  questions?: QuizQuestion[] | undefined;
  /** How many right to pass. Default: 4 of 5, or 80% of the questions rounded up. */
  pass?: number | undefined;
  /** Told the answers and the score once checked. */
  onCheck?: ((answers: QuizAnswers, score: number) => void) | undefined;
  /** Still loading: a placeholder shows instead of the questions. Default: false. */
  loading?: boolean | undefined;
  /** Loading failed: a "Couldn’t load the quiz" message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, from Try again. Return a promise: the button shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demo: QuizQuestion[] = [
  { id: 'q1', question: 'What should every form field have?', options: [{ value: 'label', label: 'A visible label' }, { value: 'placeholder', label: 'Placeholder text' }, { value: 'icon', label: 'An icon' }],
    answer: ['label'], why: 'A placeholder goes as soon as you type, and an icon can be read many ways. A label stays.' },
  { id: 'q2', question: 'Where should an error message be?', options: [{ value: 'field', label: 'Next to its field, and in a summary at the top' }, { value: 'toast', label: 'In a toast that disappears' }, { value: 'color', label: 'Only as a red border' }],
    answer: ['field'], why: 'Next to the field says what to fix where you fix it; the summary lets you find every problem at once.' },
  { id: 'q3', question: 'Which of these help people fill a form in faster?', options: [{ value: 'autocomplete', label: 'autocomplete on name, email and address fields' }, { value: 'types', label: 'The right input type, like email or tel' }, { value: 'captcha', label: 'A puzzle to prove you’re human' }],
    answer: ['autocomplete', 'types'], why: 'Autofill and the right keyboard save typing. A puzzle slows everyone down, and some can’t solve it at all.' },
  { id: 'q4', question: 'After a form is sent, where should focus go?', options: [{ value: 'answer', label: 'To the heading of what happened' }, { value: 'top', label: 'Back to the top of the page' }, { value: 'stay', label: 'Nowhere: leave it on the button' }],
    answer: ['answer'], why: 'The heading says what happened, and a screen reader reads it at once.' },
  { id: 'q5', question: 'How should a form mark which fields people must fill?', options: [{ value: 'both', label: 'A star on required fields and “(optional)” on the rest' }, { value: 'optional', label: 'Only “(optional)” on the optional ones' }, { value: 'star', label: 'Only a star on the required ones' }],
    answer: ['both'], why: 'People skip the note that explains a convention, so each field should say what it is. A sign-in form needs neither.' },
];

/** How many questions are answered right: every right option chosen and no other. */
export function scoreQuiz(questions: readonly QuizQuestion[], answers: QuizAnswers): number {
  return questions.filter((q) => {
    const a = answers[q.id] ?? [];
    return a.length === q.answer.length && q.answer.every((v) => a.includes(v));
  }).length;
}

/** The quiz page: a skip link, a header, then main with the h1, the questions, and the score once checked. */
export function Quiz({ title = 'Accessible forms: check what you learned', questions = demo, pass = Math.ceil(questions.length * 0.8), onCheck, loading = false, loadFailed = false, onRetry, online }: QuizProps) {
  const locale = useLocale();
  const [answers, setAnswers] = React.useState<QuizAnswers>({});
  const [missing, setMissing] = React.useState<string[]>([]);
  const [tries, setTries] = React.useState(0);
  const [score, setScore] = React.useState<number | null>(null);
  const result = React.useRef<HTMLHeadingElement>(null);
  const top = React.useRef<HTMLFormElement>(null);
  const answered = questions.filter((q) => answers[q.id]?.length).length;
  const n = (x: number) => formatNumber(x, locale);
  const choose = (id: string, v: string[]) => { setAnswers((a) => ({ ...a, [id]: v })); setMissing((m) => m.filter((x) => x !== id)); };
  const errors: ErrorSummaryItem[] = missing.map((id) => ({ field: `quiz-${id}`, message: `Answer question ${n(questions.findIndex((q) => q.id === id) + 1)}.` }));

  const check = (e: React.FormEvent) => {
    e.preventDefault();
    const left = questions.filter((q) => !answers[q.id]?.length).map((q) => q.id);
    setMissing(left);
    setTries((t) => t + 1);
    if (left.length) return;
    const s = scoreQuiz(questions, answers);
    setScore(s);
    onCheck?.(answers, s);
  };
  const again = () => { setAnswers({}); setScore(null); setMissing([]); requestAnimationFrame(() => top.current?.querySelector<HTMLInputElement>('input')?.focus()); };
  React.useEffect(() => { if (score !== null) result.current?.focus(); }, [score]);
  const checked = score !== null;

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme learning</p>
        <Link underline="hover" href="#course">Back to the course</Link>
      </header>
      <Container as="main" size="prose" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">Your answers stay here. Checking them needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Accessible forms', href: '#course' }, { label: 'Quiz' }]} title={title}
            description={loading || loadFailed ? undefined : `${n(questions.length)} questions, no time limit. Get ${n(pass)} right to pass; you can try as many times as you like. Questions marked * need an answer.`} />
          {loadFailed ? <div className="pt-6"><EmptyLoadFailed title="Couldn’t load the quiz" onRetry={() => onRetry?.()} headingLevel={2} /></div>
            : loading ? <Card className="mt-6"><Skeleton shape="text" lines={6} label="Loading the quiz" /></Card> : (
          <div className="flex flex-col gap-6 pt-6">
            {checked ? (
              <section aria-labelledby="quiz-score" className="flex flex-col items-start gap-3">
                <h2 id="quiz-score" ref={result} tabIndex={-1} className="m-0 text-2xl font-semibold outline-none">
                  {score >= pass ? 'You passed' : 'Not passed yet'}: {n(score)} of {n(questions.length)} right
                </h2>
                <p className="m-0">{score >= pass ? 'The next lesson is open.' : `Get ${n(pass)} right to pass. Each question below says why its answer is right.`}</p>
                <div className="flex flex-wrap gap-2">
                  {score >= pass ? <Link href="#next">Go to the next lesson</Link> : null}
                  <Button variant={score >= pass ? 'secondary' : 'primary'} onClick={again}>Try again</Button>
                </div>
              </section>
            ) : (
              <p id="quiz-progress" role="status" className="m-0 text-sm text-text-muted">{n(answered)} of {n(questions.length)} answered</p>
            )}
            <form ref={top} onSubmit={check} noValidate aria-label="Quiz" className="flex flex-col gap-6">
              <ErrorSummary key={tries} errors={errors} />
              <ol className="m-0 flex list-none flex-col gap-6 p-0">
                {questions.map((q, i) => {
                  const many = q.answer.length > 1;
                  const mine = answers[q.id] ?? [];
                  const right = checked && scoreQuiz([q], answers) === 1;
                  const label = `${n(i + 1)}. ${q.question}${many ? ' Choose all that apply.' : ''}`;
                  const error = missing.includes(q.id) ? 'Choose an answer.' : undefined;
                  return (
                    <li key={q.id} className="flex flex-col gap-3">
                      <Field label={label} error={error} group required disabled={checked}>
                        {many ? (
                          <CheckboxGroup id={`quiz-${q.id}`} value={mine} onValueChange={(v: string[]) => choose(q.id, v)}>
                            {q.options.map((o) => <Checkbox key={o.value} value={o.value}>{o.label}</Checkbox>)}
                          </CheckboxGroup>
                        ) : (
                          <RadioGroup id={`quiz-${q.id}`} name={`quiz-${q.id}`} value={mine[0] ?? ''} onValueChange={(v: string) => choose(q.id, [v])}>
                            {q.options.map((o) => <Radio key={o.value} value={o.value}>{o.label}</Radio>)}
                          </RadioGroup>
                        )}
                      </Field>
                      {checked ? (
                        <Alert tone={right ? 'success' : 'warning'} title={right ? 'Right' : 'Not quite'}>
                          {right ? '' : `The answer: ${q.options.filter((o) => q.answer.includes(o.value)).map((o) => o.label).join(', and ')}. `}{q.why}
                        </Alert>
                      ) : null}
                    </li>
                  );
                })}
              </ol>
              {checked ? null : <Button type="submit" className="self-start">Check answers</Button>}
            </form>
          </div>
          )}
        </Stack>
      </Container>
    </div>
  );
}

