'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Checkbox } from '@diki-stwn/serupa-ds';
import { DescriptionList, DescriptionItem } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Image } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { NumberInput } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { Duration } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { announce } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Recipe: what it is and how long it takes, the ingredients for as many people as you're cooking for, ticked off as
   you gather them, and the steps in order, ticked off as you go. For an app to copy. What it carries (WCAG 2.2):
   - 1.3.1: the times and servings are a description list; the ingredients a list and the steps an ordered list, each
     under its heading; the picture has a text alternative that says what's in it.
   - 3.3.2, 4.1.3: Servings says its range; changing it rescales every amount and says so.
   - 1.3.1, 4.1.2: each ingredient and each step is a checkbox named by its own text, so ticking is read with what's ticked.
   - 1.4.1: a ticked step is struck through and says "Done", never only greyed out.
   Saving what's ticked is the app's job: pass the recipe; ticks live while the page is open. */

export interface Ingredient { id: string; amount: number | null; unit: string; name: string }
export interface RecipeData {
  title: string; about: string; image: string; imageAlt: string;
  prep: number; cook: number; serves: number;
  ingredients: Ingredient[]; steps: string[];
}

export interface RecipeProps { recipe?: RecipeData | undefined }

const bowl = 'data:image/svg+xml,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="800" height="450" viewBox="0 0 800 450"><rect width="800" height="450" fill="#efe6d8"/><ellipse cx="400" cy="250" rx="230" ry="120" fill="#ffffff"/><ellipse cx="400" cy="235" rx="200" ry="90" fill="#e08a3c"/><circle cx="330" cy="215" r="22" fill="#5a8f3d"/><circle cx="450" cy="245" r="18" fill="#5a8f3d"/><circle cx="400" cy="200" r="14" fill="#f4d35e"/><circle cx="480" cy="210" r="12" fill="#f4d35e"/></svg>');
const demo: RecipeData = {
  title: 'Red lentil soup', about: 'A thick, warming soup from the cupboard, ready in under an hour.', image: bowl,
  imageAlt: 'A bowl of orange lentil soup topped with herbs and a swirl of yoghurt',
  prep: 10, cook: 35, serves: 4,
  ingredients: [
    { id: 'oil', amount: 2, unit: 'tbsp', name: 'olive oil' },
    { id: 'onion', amount: 1, unit: '', name: 'onion, chopped' },
    { id: 'garlic', amount: 2, unit: 'cloves', name: 'garlic, crushed' },
    { id: 'cumin', amount: 1.5, unit: 'tsp', name: 'ground cumin' },
    { id: 'lentils', amount: 250, unit: 'g', name: 'red lentils, rinsed' },
    { id: 'tomatoes', amount: 400, unit: 'g', name: 'chopped tomatoes (one tin)' },
    { id: 'stock', amount: 1.2, unit: 'litres', name: 'vegetable stock' },
    { id: 'lemon', amount: 0.5, unit: '', name: 'lemon, juiced' },
    { id: 'salt', amount: null, unit: '', name: 'Salt and pepper, to taste' },
  ],
  steps: [
    'Warm the oil in a large pan over a medium heat. Cook the onion for 8 minutes, until soft.',
    'Add the garlic and cumin and stir for a minute, until they smell toasted.',
    'Add the lentils, tomatoes and stock. Bring to the boil, then simmer for 25 minutes, stirring now and then.',
    'Blend until smooth, or leave it chunky. Stir in the lemon juice and season.',
  ],
};

/** An amount for `to` people from one for `from`, rounded sensibly: quarters under 10, whole numbers over. */
export function scaleAmount(amount: number, from: number, to: number) {
  const v = (amount * to) / from;
  return v < 10 ? Math.round(v * 4) / 4 : Math.round(v);
}


/** The recipe page: a skip link, a header, then main with the h1, the facts, the ingredients and the steps. */
export function Recipe({ recipe = demo }: RecipeProps) {
  const locale = useLocale();
  const num = (n: number) => formatNumber(n, locale, { maximumFractionDigits: 2 });
  const [serves, setServes] = React.useState<number | null>(recipe.serves);
  const [got, setGot] = React.useState<string[]>([]);
  const [done, setDone] = React.useState<number[]>([]);
  const people = serves && serves > 0 ? serves : recipe.serves;
  const amountOf = (i: Ingredient) => (i.amount === null ? '' : `${num(scaleAmount(i.amount, recipe.serves, people))}${i.unit ? ` ${i.unit}` : ''} `);
  const peopleWords = people === 1 ? '1 person' : `${num(people)} people`;
  const said = React.useRef(people);
  React.useEffect(() => {
    if (said.current !== people) announce(`Amounts now for ${peopleWords}.`);
    said.current = people;
  }, [people, peopleWords]);

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme Kitchen</p>
        <Link underline="hover" href="#recipes">Recipes</Link>
      </header>
      <Container as="main" size="md" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <PageHeader breadcrumb={[{ label: 'Recipes', href: '#recipes' }, { label: recipe.title }]} title={recipe.title} description={recipe.about} />
          <div className="flex flex-col gap-8 pt-6">
            <Image src={recipe.image} alt={recipe.imageAlt} ratio="video" rounded />
            <DescriptionList layout="inline">
              <DescriptionItem term="Prep"><Duration value={recipe.prep} unit="minute" /></DescriptionItem>
              <DescriptionItem term="Cook"><Duration value={recipe.cook} unit="minute" /></DescriptionItem>
              <DescriptionItem term="Ready in"><Duration value={recipe.prep + recipe.cook} unit="minute" /></DescriptionItem>
            </DescriptionList>
            <div className="grid grid-cols-1 gap-8 md:grid-cols-3">
              <section aria-labelledby="recipe-ingredients" className="flex flex-col gap-4">
                <h2 id="recipe-ingredients" className="m-0 text-lg font-semibold">Ingredients</h2>
                <Field label="Servings" hint="From 1 to 24." id="recipe-serves">
                  <NumberInput min={1} max={24} value={serves} onValueChange={setServes} className="max-w-32" />
                </Field>
                <ul className="m-0 flex list-none flex-col gap-2 p-0">
                  {recipe.ingredients.map((i) => (
                    <li key={i.id}>
                      <Checkbox checked={got.includes(i.id)} onCheckedChange={(on) => setGot((g) => (on ? [...g, i.id] : g.filter((x) => x !== i.id)))}>
                        <span className={got.includes(i.id) ? 'text-text-muted line-through' : undefined}>{amountOf(i)}{i.name}</span>
                      </Checkbox>
                    </li>
                  ))}
                </ul>
              </section>
              <section aria-labelledby="recipe-steps" className="flex flex-col gap-4 md:col-span-2">
                <h2 id="recipe-steps" className="m-0 text-lg font-semibold">Method</h2>
                <p className="m-0 text-text-muted">{done.length === recipe.steps.length ? 'Every step done. Enjoy!' : `${num(done.length)} of ${num(recipe.steps.length)} steps done.`}</p>
                <ol className="m-0 flex list-none flex-col gap-4 p-0">
                  {recipe.steps.map((s, n) => (
                    <li key={n}>
                      <h3 className="m-0 text-base font-semibold">Step {num(n + 1)}{done.includes(n) ? ', done' : ''}</h3>
                      <Checkbox checked={done.includes(n)} onCheckedChange={(on) => setDone((d) => (on ? [...d, n] : d.filter((x) => x !== n)))}>
                        <span className={done.includes(n) ? 'text-text-muted line-through' : undefined}>{s}</span>
                      </Checkbox>
                    </li>
                  ))}
                </ol>
              </section>
            </div>
          </div>
        </Stack>
      </Container>
    </div>
  );
}

files.Referral.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Badge, type BadgeTone } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { CopyButton } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { Textarea } from '@diki-stwn/serupa-ds';
import { Table, TableHead, TableBody, TableRow, TableHeaderCell, TableCell } from '@diki-stwn/serupa-ds';
import { Toaster, toast } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { FormattedDate } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { StatsRow } from './StatsRow';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Referral: invite friends with your own link or by email, and see who joined and what you've earned. For an app to
   copy. What it carries (WCAG 2.2):
   - 1.3.1, 2.4.6: the link is a read-only field labelled "Your invite link", with a Copy button that names what it
     copies and says "Copied" when it has (4.1.3).
   - 3.3.2: the email box says how to separate addresses; 3.3.1: a bad one is named next to it, and one already
     invited is said so, before anything is sent.
   - 3.3.4, 4.1.3: Send shows it's busy, and a toast says how many were sent; a send that fails says so next to the
     button and keeps the addresses.
   - 1.3.1, 1.4.1: who you've invited is a table with a caption; where each is ("Invited", "Joined", "Earned you $10")
     is said in words in a badge, not by color alone.
   - The rules are said in a sentence before the link: what each of you gets, and when.
   The invites are the app's: onInvite gets the addresses; reject its promise when they can't be sent. */

export type ReferralState = 'invited' | 'joined' | 'rewarded';

export interface ReferralInvite {
  email: string;
  state: ReferralState;
  /** When they were invited: "2025-03-04". */
  invited: string;
}

export interface ReferralProps {
  /** Your invite link. Default: a demo link. */
  link?: string | undefined;
  /** What each of you gets, in the currency's units. Default: 10. */
  reward?: number | undefined;
  /** ISO 4217 currency. Default: "USD". */
  currency?: string | undefined;
  /** Who you've invited, newest first. Default: demo invites. */
  referrals?: ReferralInvite[] | undefined;
  /** Sends invites. Reject its promise when they can't be sent. */
  onInvite?: ((emails: string[]) => unknown) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demo: ReferralInvite[] = [
  { email: 'chen@example.com', state: 'rewarded', invited: '2025-02-11' },
  { email: 'dewi@example.com', state: 'joined', invited: '2025-02-26' },
  { email: 'eko@example.com', state: 'invited', invited: '2025-03-02' },
];
const STATE: Record<ReferralState, { label: string; tone: BadgeTone }> = {
  invited: { label: 'Invited', tone: 'neutral' },
  joined: { label: 'Joined', tone: 'info' },
  rewarded: { label: 'Earned you', tone: 'success' },
};
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** The addresses in text, split at commas, semicolons, spaces and new lines, lowercased, once each. */
export const addressesIn = (text: string): string[] => [...new Set(text.split(/[\s,;]+/).map((e) => e.trim().toLowerCase()).filter(Boolean))];

/** What's wrong with these addresses, in words, or null when they can all be invited. */
export function referralProblem(emails: readonly string[], invited: readonly string[]): string | null {
  if (!emails.length) return 'Enter at least one email address.';
  const bad = emails.filter((e) => !EMAIL.test(e));
  if (bad.length) return `${bad.length === 1 ? 'This isn’t an email address' : 'These aren’t email addresses'}: ${bad.join(', ')}.`;
  const again = emails.filter((e) => invited.includes(e));
  if (again.length) return `Already invited: ${again.join(', ')}.`;
  return null;
}

/** The referral page: a skip link, a header, then main with the h1, the totals, the link, the invite form and the invites. */
export function Referral({ link = 'https://acme.example/r/ana-7k2', reward = 10, currency = 'USD', referrals = demo, onInvite, online }: ReferralProps) {
  const locale = useLocale();
  const [list, setList] = React.useState(referrals);
  const focusing = React.useRef(false);   // the press that focuses the link field
  const [text, setText] = React.useState('');
  const [problem, setProblem] = React.useState<string | null>(null);
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const money = (n: number) => formatNumber(n, locale, { style: 'currency', currency, maximumFractionDigits: 0 });
  const joined = list.filter((r) => r.state !== 'invited').length;
  const earned = list.filter((r) => r.state === 'rewarded').length * reward;

  const send = (e: React.FormEvent) => {
    e.preventDefault();
    const emails = addressesIn(text);
    const found = referralProblem(emails, list.map((r) => r.email));
    setProblem(found);
    setFailed(false);
    if (found) { document.getElementById('referral-emails')?.focus(); return; }
    setBusy(true);
    void Promise.resolve().then(() => onInvite?.(emails)).then(() => {
      const today = new Date();
      const iso = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;
      setList((l) => [...emails.map((email) => ({ email, state: 'invited' as const, invited: iso })), ...l]);
      setText('');
      toast({ title: emails.length === 1 ? `Invite sent to ${emails[0]!}` : `${formatNumber(emails.length, locale)} invites sent`, tone: 'success' });
    }, () => setFailed(true)).finally(() => setBusy(false));
  };

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <Container as="main" size="lg" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">You can copy your link. Sending invites needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Account', href: '#account' }, { label: 'Invite friends' }]} title="Invite friends"
            description={`Give ${money(reward)}, get ${money(reward)}. A friend gets ${money(reward)} off their first order, and you get ${money(reward)} in credit once it ships.`} />
          <div className="flex flex-col gap-8 pt-6">
            <StatsRow title="So far" stats={[
              { label: 'Invited', value: formatNumber(list.length, locale) },
              { label: 'Joined', value: formatNumber(joined, locale) },
              { label: 'Earned', value: money(earned) },
            ]} />

            <Card>
              <section aria-labelledby="share" className="flex flex-col gap-4">
                <h2 id="share" className="m-0 text-lg font-semibold">Share your link</h2>
                <div className="flex flex-wrap items-end gap-2">
                  <Field label="Your invite link" id="referral-link" className="min-w-0 flex-1">
                    {/* Safari puts the caret where the click lands on the mouseup after focus, which undid the select-all: that
                        one mouseup is passed over. */}
                    <Input readOnly value={link} onFocus={(e) => e.currentTarget.select()}
                      onMouseDown={(e) => { focusing.current = document.activeElement !== e.currentTarget; }}
                      onMouseUp={(e) => { if (focusing.current) e.preventDefault(); focusing.current = false; }} />
                  </Field>
                  <CopyButton value={link} copiedLabel="Copied" size="md">Copy link</CopyButton>
                </div>
                <form onSubmit={send} noValidate aria-label="Invite by email" className="flex flex-col items-start gap-3">
                  <Field label="Or invite by email" id="referral-emails" hint="Separate addresses with commas or new lines." error={problem ?? undefined} className="w-full">
                    <Textarea rows={3} autoComplete="off" value={text} onChange={(e) => { setText(e.target.value); if (problem) setProblem(null); setFailed(false); }} />
                  </Field>
                  {failed ? <Alert tone="danger">Couldn’t send the invites. Try again; the addresses are still here.</Alert> : null}
                  <Button type="submit" loading={busy}>Send invites</Button>
                </form>
              </section>
            </Card>

            <section aria-labelledby="invited" className="flex flex-col gap-4">
              <h2 id="invited" className="m-0 text-lg font-semibold">Who you’ve invited</h2>
              {list.length ? (
                <Table caption="Friends you’ve invited, newest first" hideCaption>
                  <TableHead><TableRow>
                    <TableHeaderCell>Friend</TableHeaderCell>
                    <TableHeaderCell>Invited</TableHeaderCell>
                    <TableHeaderCell>Status</TableHeaderCell>
                  </TableRow></TableHead>
                  <TableBody>{list.map((r) => (
                    <TableRow key={r.email}>
                      {/* On a phone an address breaks after its @, not past the screen's edge. */}
                      <TableCell className="wrap-break-word">{r.email.includes('@') ? <>{r.email.slice(0, r.email.indexOf('@') + 1)}<wbr />{r.email.slice(r.email.indexOf('@') + 1)}</> : r.email}</TableCell>
                      <TableCell className="whitespace-nowrap"><FormattedDate value={r.invited} /></TableCell>
                      <TableCell><Badge tone={STATE[r.state].tone}>{r.state === 'rewarded' ? `${STATE.rewarded.label} ${money(reward)}` : STATE[r.state].label}</Badge></TableCell>
                    </TableRow>
                  ))}</TableBody>
                </Table>
              ) : <p className="m-0 text-text-muted">Nobody yet. Friends you invite show here, with where they’ve got to.</p>}
            </section>
          </div>
        </Stack>
      </Container>
      <Toaster />
    </div>
  );
}

files.ReturnRequest.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Select } from '@diki-stwn/serupa-ds';
import { Checkbox } from '@diki-stwn/serupa-ds';
import { RadioGroup, Radio } from '@diki-stwn/serupa-ds';
import { DescriptionList, DescriptionItem } from '@diki-stwn/serupa-ds';
import { FormattedNumber } from '@diki-stwn/serupa-ds';
import { ErrorSummary, type ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Return request: sending back some of an order, with why, how it goes back and where the money goes, and what
   happens next. For an app to copy. What it carries (WCAG 2.2):
   - 1.3.1: the items are a named group of checkboxes; one that can't be returned is disabled and says why next to it.
   - 3.3.2: the reason is asked for only for an item you've chosen, and labelled with its name ("Why are you returning
     the Linen shirt?").
   - 3.3.1, 2.4.3: sending with nothing chosen, or a reason missing, shows a summary that takes focus, each problem a
     link to its item or reason, which says it too.
   - 1.3.1: how it goes back and where the money goes are named radio groups; a cost is said in the choice's words.
   - 4.1.3: the refund is worked out as you choose, in a summary that's read in order, with the cost taken off by name.
   - 3.3.4, 4.1.3: Send shows it's busy; one that fails says so next to the button and keeps every choice.
   - 2.4.3: once sent, the form gives way to the next steps, whose heading takes focus.
   Returns are the app's: onSend gets the items, reasons and choices; resolve with the return's number, reject when it
   can't be made. */

export interface ReturnItem {
  id: string;
  name: string;
  /** What was chosen: "Sand, M". */
  options?: string | undefined;
  price: number;
  /** Why it can't be returned, when it can't: "Worn items can't be returned." */
  notReturnable?: string | undefined;
}

export interface ReturnChoice {
  items: { id: string; reason: string }[];
  method: 'dropoff' | 'pickup';
  refund: 'original' | 'credit';
}

export interface ReturnRequestProps {
  /** The order's number. Default: "A-10432". */
  order?: string | undefined;
  /** What was in the order. Default: demo items. */
  items?: ReturnItem[] | undefined;
  /** ISO 4217 currency. Default: "USD". */
  currency?: string | undefined;
  /** What a pickup costs, taken off the refund. Default: 5. */
  pickupFee?: number | undefined;
  /** The last day to send it back, in words: "December 20". Default: "December 20". */
  until?: string | undefined;
  /** Makes the return. Resolve with its number ("R-2041"); reject when it can't be made. */
  onSend?: ((choice: ReturnChoice) => unknown) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demo: ReturnItem[] = [
  { id: 'i1', name: 'Linen shirt', options: 'Sand, M', price: 48 },
  { id: 'i2', name: 'Canvas tote', options: 'Natural', price: 18 },
  { id: 'i3', name: 'Wool socks', options: 'Gray, 39–42', price: 12, notReturnable: 'Socks can’t be returned once opened.' },
];
const REASONS = [
  { value: 'size', label: 'It doesn’t fit' },
  { value: 'looks', label: 'It looks different from the pictures' },
  { value: 'damaged', label: 'It arrived damaged' },
  { value: 'wrong', label: 'I got the wrong item' },
  { value: 'mind', label: 'I changed my mind' },
];

/** What's missing from a return, by field id ("return-items", "reason-<item>"), in the order of the form. */
export function returnProblems(chosen: readonly string[], reasons: Readonly<Record<string, string>>): Record<string, string> {
  if (!chosen.length) return { 'return-items': 'Choose at least one item to return.' };
  const out: Record<string, string> = {};
  for (const id of chosen) if (!reasons[id]) out[`reason-${id}`] = 'Choose why you’re returning it.';
  return out;
}

/** What comes back: the items' prices, less the pickup fee, and never under nothing. A damaged or wrong item is
 *  picked up free. */
export function refundOf(items: readonly ReturnItem[], chosen: readonly string[], reasons: Readonly<Record<string, string>>, pickup: boolean, fee: number) {
  const value = items.filter((i) => chosen.includes(i.id)).reduce((n, i) => n + i.price, 0);
  const ours = chosen.some((id) => reasons[id] === 'damaged' || reasons[id] === 'wrong');
  const cost = pickup && !ours ? Math.min(fee, value) : 0;
  return { value, cost, refund: value - cost };
}

/** The return page: a skip link, a header, then main with the h1 and the form, or the next steps once sent. */
export function ReturnRequest({ order = 'A-10432', items = demo, currency = 'USD', pickupFee = 5, until = 'December 20', onSend, online }: ReturnRequestProps) {
  const [chosen, setChosen] = React.useState<string[]>([]);
  const [reasons, setReasons] = React.useState<Record<string, string>>({});
  const [method, setMethod] = React.useState<ReturnChoice['method']>('dropoff');
  const [refundTo, setRefundTo] = React.useState<ReturnChoice['refund']>('original');
  const [problems, setProblems] = React.useState<Record<string, string>>({});
  const [tries, setTries] = React.useState(0);
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const [sent, setSent] = React.useState<string | null>(null);
  const next = React.useRef<HTMLHeadingElement>(null);
  const money = (n: number) => <FormattedNumber value={n} format="currency" currency={currency} />;
  const sums = refundOf(items, chosen, reasons, method === 'pickup', pickupFee);
  const clear = (id: string) => setProblems((p) => { const n = { ...p }; delete n[id]; return n; });

  const toggle = (ids: string[]) => {
    // Keep the items in their order, whatever order they were ticked in.
    setChosen(items.filter((i) => ids.includes(i.id)).map((i) => i.id));
    setFailed(false);
    if (ids.length) clear('return-items');
  };
  const errors: ErrorSummaryItem[] = Object.entries(problems).map(([field, message]) => ({ field, message }));
  const send = (e: React.FormEvent) => {
    e.preventDefault();
    const found = returnProblems(chosen, reasons);
    setProblems(found);
    setTries((t) => t + 1);
    if (Object.keys(found).length) return;
    setFailed(false);
    setBusy(true);
    const choice: ReturnChoice = { items: chosen.map((id) => ({ id, reason: reasons[id]! })), method, refund: refundTo };
    void Promise.resolve().then(() => onSend?.(choice)).then((n) => setSent(typeof n === 'string' ? n : ''), () => setFailed(true)).finally(() => setBusy(false));
  };
  React.useEffect(() => { if (sent != null) next.current?.focus(); }, [sent]);

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <Container as="main" size="md" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">Your choices stay here. Sending the request needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Orders', href: '#orders' }, { label: `Order ${order}`, href: `#order-${order}` }, { label: 'Return' }]}
            title={`Return items from order ${order}`} description={`Send them back by ${until}. Choose what, why, and how.`} />
          <div className="pt-6">
            {sent != null ? (
              <section aria-labelledby="next" className="flex flex-col items-start gap-3">
                <h2 id="next" ref={next} tabIndex={-1} className="m-0 text-2xl font-semibold outline-none">Return {sent ? `${sent} ` : ''}started</h2>
                <ol className="m-0 flex flex-col gap-2 ps-5">
                  <li>{method === 'pickup' ? 'A courier will email you to pick a day to collect it.' : 'Print the label from the email we’ve sent, or show its code at a drop-off point.'}</li>
                  <li>Pack the items with their tags, and send them by {until}.</li>
                  <li>Once they’re back, {money(sums.refund)} goes {refundTo === 'credit' ? 'to your store credit, the same day' : 'back to how you paid, in up to 5 working days'}.</li>
                </ol>
                <Link href={`#order-${order}`}>Back to order {order}</Link>
              </section>
            ) : (
              <form onSubmit={send} noValidate aria-label="Return" className="grid items-start gap-6 md:grid-cols-3">
                <ErrorSummary key={tries} errors={errors} className="md:col-span-3" />
                <div className="flex flex-col gap-6 md:col-span-2">
                  <p className="m-0 text-text-muted">Fields marked * are required.</p>
                  <Field label="What are you returning?" id="return-items" error={problems['return-items']} group required>
                    <div id="return-items" className="flex flex-col gap-4">
                      {items.map((i) => (
                        <div key={i.id} className="flex flex-col gap-2">
                          <Checkbox value={i.id} checked={chosen.includes(i.id)} disabled={!!i.notReturnable}
                            onCheckedChange={(on) => toggle(on ? [...chosen, i.id] : chosen.filter((x) => x !== i.id))}
                            description={i.notReturnable ?? i.options}>
                            {i.name} <span className="text-text-muted">· {money(i.price)}</span>
                          </Checkbox>
                          {chosen.includes(i.id) ? (
                            <Field label={`Why are you returning the ${i.name}?`} id={`reason-${i.id}`} error={problems[`reason-${i.id}`]} required className="ms-7">
                              <Select placeholder="Choose a reason" options={REASONS} value={reasons[i.id] ?? ''}
                                onChange={(e) => { setReasons((r) => ({ ...r, [i.id]: e.target.value })); clear(`reason-${i.id}`); setFailed(false); }} />
                            </Field>
                          ) : null}
                        </div>
                      ))}
                    </div>
                  </Field>
                  <Field label="How will you send it back?" group>
                    <RadioGroup name="return-method" value={method} onValueChange={(v: string) => setMethod(v as ReturnChoice['method'])}>
                      <Radio value="dropoff" description="At any post office or parcel locker.">Drop it off, free</Radio>
                      <Radio value="pickup" description="Free when it arrived damaged or wasn’t what you ordered.">
                        Have it picked up, {money(pickupFee)} off the refund
                      </Radio>
                    </RadioGroup>
                  </Field>
                  <Field label="Where should the money go?" group>
                    <RadioGroup name="return-refund" value={refundTo} onValueChange={(v: string) => setRefundTo(v as ReturnChoice['refund'])}>
                      <Radio value="original" description="Up to 5 working days after it’s back.">Back to how you paid</Radio>
                      <Radio value="credit" description="The same day it’s back, to spend here.">Store credit</Radio>
                    </RadioGroup>
                  </Field>
                </div>
                <Card>
                  <section aria-labelledby="refund" className="flex flex-col gap-4">
                    <h2 id="refund" className="m-0 text-lg font-semibold">Your refund</h2>
                    {chosen.length ? (
                      <DescriptionList layout="split">
                        <DescriptionItem term="Items">{money(sums.value)}</DescriptionItem>
                        {sums.cost ? <DescriptionItem term="Pickup">−{money(sums.cost)}</DescriptionItem> : null}
                        <DescriptionItem term="Refund" emphasis>{money(sums.refund)}</DescriptionItem>
                      </DescriptionList>
                    ) : <p className="m-0 text-text-muted">Choose an item to see what comes back.</p>}
                    {failed ? <Alert tone="danger">Couldn’t start the return. Try again; your choices are still here.</Alert> : null}
                    <Button type="submit" loading={busy}>Start return</Button>
                  </section>
                </Card>
              </form>
            )}
          </div>
        </Stack>
      </Container>
    </div>
  );
}

