'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Meter } from '@diki-stwn/serupa-ds';
import { Rating } from '@diki-stwn/serupa-ds';
import { Select } from '@diki-stwn/serupa-ds';
import { ToggleButton } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { EmptyLoadFailed } from './EmptyStates';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { FormattedDate } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Reviews: the average and how the stars split, then the reviews themselves, filtered by stars and sorted, a few at a
   time, each one marked helpful or not. For an app to copy. What it carries (WCAG 2.2):
   - 1.1.1, 1.3.1: the average is stars named in words ("4.3 out of 5") with the count beside it; the split is a list of
     meters, each named by its stars, its value in words ("62 reviews, 55%").
   - 1.3.1, 2.4.6: each review is an article named by its title, with its stars, who wrote it, when, and "Bought it"
     as a word.
   - 4.1.3: changing the filter or the order says how many reviews it shows.
   - 4.1.2: Helpful is a toggle button named by the review it's for, pressed or not; the count beside it follows.
   - 2.4.3: Show more reviews moves focus to the first one it adds.
   Loading and counting are the app's job: pass the reviews; onHelpful hears each press. */

export interface Review { id: string; stars: number; title: string; body: string; author: string; date: string; bought: boolean; helpful: number }

export interface ReviewsProps {
  product?: string | undefined;
  reviews?: Review[] | undefined;
  /** How many show at first, and how many more each time. Default: 3. */
  pageSize?: number | undefined;
  /** Hears a Helpful press. */
  onHelpful?: ((id: string, pressed: boolean) => void) | undefined;
  /** Still loading: a placeholder shows instead of the reviews. Default: false. */
  loading?: boolean | undefined;
  /** Loading failed: a "Couldn’t load the reviews" message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, from Try again. Return a promise: the button shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demo: Review[] = [
  { id: 'r1', stars: 5, title: 'Warm without the bulk', body: 'I wore it on a week of winter hikes. Warm when I stopped, never sweaty when I moved, and it packs into its own pocket.', author: 'Ana L.', date: '2026-02-20', bought: true, helpful: 14 },
  { id: 'r2', stars: 4, title: 'Great, but runs small', body: 'Lovely jacket. I usually wear a medium and needed a large to fit a jumper underneath.', author: 'Chen W.', date: '2026-02-11', bought: true, helpful: 31 },
  { id: 'r3', stars: 2, title: 'Zip broke in a month', body: 'The jacket itself is good, but the zip came off its track after a few weeks. Customer service replaced it quickly.', author: 'Sara H.', date: '2026-01-30', bought: true, helpful: 9 },
  { id: 'r4', stars: 5, title: 'Light and warm', body: 'Exactly what I wanted for travel.', author: 'Kofi M.', date: '2026-01-18', bought: false, helpful: 2 },
  { id: 'r5', stars: 3, title: 'Fine for the price', body: 'Not as warm as my old down jacket, but fine for autumn and spring.', author: 'Lena V.', date: '2026-01-05', bought: true, helpful: 5 },
];
type Sort = 'recent' | 'helpful' | 'high' | 'low';

/** The average stars to one decimal, and how many reviews give each number of stars, 5 first. */
export function starSplit(reviews: Review[]) {
  const counts = [5, 4, 3, 2, 1].map((s) => ({ stars: s, count: reviews.filter((r) => r.stars === s).length }));
  const average = reviews.length ? Math.round((reviews.reduce((a, r) => a + r.stars, 0) / reviews.length) * 10) / 10 : 0;
  return { average, counts };
}

/** The reviews with `stars` (0 for all), in the chosen order. */
export function pickReviews(reviews: Review[], stars: number, sort: Sort) {
  const by: Record<Sort, (a: Review, b: Review) => number> = {
    recent: (a, b) => b.date.localeCompare(a.date),
    helpful: (a, b) => b.helpful - a.helpful,
    high: (a, b) => b.stars - a.stars || b.date.localeCompare(a.date),
    low: (a, b) => a.stars - b.stars || b.date.localeCompare(a.date),
  };
  return reviews.filter((r) => !stars || r.stars === stars).sort(by[sort]);
}

/** The reviews page: a skip link, a header, then main with the h1, the summary, the filters and the reviews. */
export function Reviews({ product = 'Featherlight jacket', reviews = demo, pageSize = 3, onHelpful, loading = false, loadFailed = false, onRetry, online }: ReviewsProps) {
  const locale = useLocale();
  const num = (n: number) => formatNumber(n, locale);
  const [stars, setStars] = React.useState('0');
  const [sort, setSort] = React.useState<Sort>('recent');
  const [shown, setShown] = React.useState(pageSize);
  const [pressed, setPressed] = React.useState<string[]>([]);
  const firstAdded = React.useRef<string | null>(null);
  const { average, counts } = starSplit(reviews);
  const list = pickReviews(reviews, Number(stars), sort);
  const visible = list.slice(0, shown);
  const reviewsWords = (n: number) => (n === 1 ? '1 review' : `${num(n)} reviews`);
  const helpfulWords = (n: number) => (!n ? 'No one has marked this helpful yet' : n === 1 ? '1 person found this helpful' : `${num(n)} people found this helpful`);

  const more = () => { firstAdded.current = list[shown]?.id ?? null; setShown((s) => s + pageSize); };
  React.useEffect(() => {
    if (!firstAdded.current) return;
    document.getElementById(`review-${firstAdded.current}`)?.focus();
    firstAdded.current = null;
  }, [shown]);
  const press = (id: string, on: boolean) => { setPressed((p) => (on ? [...p, id] : p.filter((x) => x !== id))); onHelpful?.(id, on); };

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme Outdoors</p>
        <Link underline="hover" href="#bag">Bag</Link>
      </header>
      <Container as="main" size="lg" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">These are the reviews loaded before you went offline. Marking one helpful needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: product, href: '#product' }, { label: 'Reviews' }]} title={`Reviews of the ${product}`} />
          {loadFailed ? <div className="pt-6"><EmptyLoadFailed title="Couldn’t load the reviews" onRetry={() => onRetry?.()} headingLevel={2} /></div>
            : loading ? <Card className="mt-6"><Skeleton shape="text" lines={6} label="Loading reviews" /></Card> : (<>
          <div className="grid grid-cols-1 gap-6 pt-6 md:grid-cols-3">
            <section aria-labelledby="reviews-summary" className="flex flex-col gap-4">
              <h2 id="reviews-summary" className="m-0 text-lg font-semibold">Overall</h2>
              <div className="flex flex-wrap items-center gap-3">
                <Rating readOnly value={average} allowHalf size="lg" />
                <p className="m-0 text-text-muted">{formatNumber(average, locale, { minimumFractionDigits: 1 })} from {reviewsWords(reviews.length)}</p>
              </div>
              <ul className="m-0 flex list-none flex-col gap-2 p-0">
                {counts.map((c) => (
                  <li key={c.stars}>
                    <Meter label={c.stars === 1 ? '1 star' : `${num(c.stars)} stars`} showValue size="sm" value={c.count} max={Math.max(1, reviews.length)}
                      formatValue={(v) => `${reviewsWords(v)}, ${formatNumber(reviews.length ? v / reviews.length : 0, locale, { style: 'percent' })}`} />
                  </li>
                ))}
              </ul>
              <Link href="#write">Write a review</Link>
            </section>
            <section aria-labelledby="reviews-list" className="flex flex-col gap-4 md:col-span-2">
              <h2 id="reviews-list" className="m-0 text-lg font-semibold">What people say</h2>
              <div className="flex flex-wrap items-end gap-3">
                <Field label="Show">
                  <Select value={stars} onChange={(e) => { setStars(e.target.value); setShown(pageSize); }}
                    options={[{ value: '0', label: 'All stars' }, ...[5, 4, 3, 2, 1].map((s) => ({ value: String(s), label: s === 1 ? '1 star only' : `${num(s)} stars only` }))]} />
                </Field>
                <Field label="Sort by">
                  <Select value={sort} onChange={(e) => { setSort(e.target.value as Sort); setShown(pageSize); }}
                    options={[{ value: 'recent', label: 'Most recent' }, { value: 'helpful', label: 'Most helpful' }, { value: 'high', label: 'Highest stars' }, { value: 'low', label: 'Lowest stars' }]} />
                </Field>
              </div>
              <p role="status" id="reviews-count" className="m-0 text-sm text-text-muted">{list.length ? `Showing ${num(visible.length)} of ${reviewsWords(list.length)}` : 'No reviews with these stars yet.'}</p>
              {visible.map((r) => {
                const on = pressed.includes(r.id);
                return (
                  <article key={r.id} aria-labelledby={`review-${r.id}`} className="flex flex-col gap-2 border-b border-border pb-4">
                    <Rating readOnly value={r.stars} size="sm" />
                    <h3 id={`review-${r.id}`} tabIndex={-1} className="m-0 text-base font-semibold outline-none">{r.title}</h3>
                    <p className="m-0 flex flex-wrap items-center gap-2 text-sm text-text-muted">
                      <span>{r.author}</span>·<FormattedDate value={r.date} dateStyle="long" />{r.bought ? <Badge tone="success">Bought it</Badge> : null}
                    </p>
                    <p className="m-0">{r.body}</p>
                    <div className="flex flex-wrap items-center gap-3">
                      <ToggleButton size="sm" variant="outline" pressed={on} onPressedChange={(v) => press(r.id, v)} aria-label={`Helpful: ${r.title}`}>Helpful</ToggleButton>
                      <span className="text-sm text-text-muted">{helpfulWords(r.helpful + (on ? 1 : 0))}</span>
                    </div>
                  </article>
                );
              })}
              {list.length > shown ? <div><Button variant="secondary" onClick={more}>Show more reviews</Button></div> : null}
            </section>
          </div>
          </>)}
        </Stack>
      </Container>
    </div>
  );
}

files.RolePermissions.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Checkbox } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Table, TableHead, TableBody, TableRow, TableHeaderCell, TableCell } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { announce } from '@diki-stwn/serupa-ds';
import { EmptyLoadFailed } from './EmptyStates';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Roles and permissions: what each role in a workspace can do, as a grid of checkboxes, where a permission that needs
   another brings it along, and nothing changes until Save. For an app to copy. What it carries (WCAG 2.2):
   - 1.3.1: the grid is a table with a caption; each permission is its row's header with what it allows, and each role
     its column's, so every checkbox is read with both; each checkbox is also named "Role: Permission".
   - 3.3.2: a permission that needs another says so under its name; turning it on turns that on too, and turning that
     off turns off what needs it.
   - 4.1.3: what else changed is said in a status ("Also turned on View projects for Guest").
   - 3.2.2: nothing is saved as you go: Save says how many changes it saves, and Discard puts them back.
   - 3.3.4, 4.1.3: Save shows it's busy; changes that can't be saved say so and stay; saved ones are said.
   - 4.1.2: the owner's column can't change: its checkboxes are read-only, and the reason is said above the table.
   Storing the roles is the app's job: onSave gets every role's permissions; reject when they can't be saved. */

export interface Role { id: string; name: string; locked?: boolean | undefined }
export interface Permission { id: string; label: string; allows: string; needs?: string[] | undefined }
export type Grants = Record<string, string[]>;

export interface RolePermissionsProps {
  roles?: Role[] | undefined;
  permissions?: Permission[] | undefined;
  /** Each role's permissions, by role id. */
  grants?: Grants | undefined;
  /** Saves every role's permissions. Reject when they can't be saved. */
  onSave?: ((grants: Grants) => unknown) | undefined;
  /** The roles are still loading: a placeholder in their place. Default: false. */
  loading?: boolean | undefined;
  /** The roles failed to load: a "Couldn’t load the roles" message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads them again, from Try again. Return a promise: the button shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demoRoles: Role[] = [
  { id: 'owner', name: 'Owner', locked: true },
  { id: 'admin', name: 'Admin' },
  { id: 'member', name: 'Member' },
  { id: 'guest', name: 'Guest' },
];
const demoPerms: Permission[] = [
  { id: 'view', label: 'View projects', allows: 'Open projects and read their tasks and comments' },
  { id: 'comment', label: 'Comment', allows: 'Add comments to tasks', needs: ['view'] },
  { id: 'edit', label: 'Edit projects', allows: 'Add, change and move tasks', needs: ['view'] },
  { id: 'delete', label: 'Delete projects', allows: 'Delete a project and everything in it', needs: ['edit'] },
  { id: 'invite', label: 'Invite people', allows: 'Invite people to the workspace and set their role', needs: ['view'] },
  { id: 'billing', label: 'Manage billing', allows: 'Change the plan and see invoices' },
];
const all = demoPerms.map((p) => p.id);
const demoGrants: Grants = { owner: all, admin: ['view', 'comment', 'edit', 'delete', 'invite'], member: ['view', 'comment', 'edit'], guest: ['view'] };

/** A role's permissions after one is turned on or off: on brings what it needs, off takes what needs it. Also gives
 *  the other permissions that changed, in the table's order. */
export function applyGrant(perms: Permission[], had: string[], perm: string, on: boolean) {
  const next = new Set(had);
  const visit = (id: string) => {
    if (on ? next.has(id) : !next.has(id)) return;
    if (on) next.add(id); else next.delete(id);
    if (on) perms.find((p) => p.id === id)?.needs?.forEach(visit);
    else perms.filter((p) => p.needs?.includes(id)).forEach((p) => visit(p.id));
  };
  visit(perm);
  const now = perms.map((p) => p.id).filter((id) => next.has(id));
  const also = perms.filter((p) => p.id !== perm && next.has(p.id) !== had.includes(p.id)).map((p) => p.id);
  return { now, also };
}

/** How many role-and-permission boxes differ between two sets of grants. */
export function countChanges(before: Grants, after: Grants) {
  return [...new Set([...Object.keys(before), ...Object.keys(after)])].reduce((n, role) => {
    const a = before[role] ?? [];
    const b = after[role] ?? [];
    return n + a.filter((x) => !b.includes(x)).length + b.filter((x) => !a.includes(x)).length;
  }, 0);
}

/** The page: a skip link, a header, then main with the h1, the grid, and Save. */
export function RolePermissions({ roles = demoRoles, permissions = demoPerms, grants = demoGrants, onSave, loading = false, loadFailed = false, onRetry, online }: RolePermissionsProps) {
  const locale = useLocale();
  const [saved, setSaved] = React.useState(grants);
  const [draft, setDraft] = React.useState(grants);
  // What the app passes once loading ends replaces what was there, which was empty or the demo.
  const [wasLoading, setWasLoading] = React.useState(loading);
  if (wasLoading !== loading) { setWasLoading(loading); if (!loading) { setSaved(grants); setDraft(grants); } }
  const [also, setAlso] = React.useState('');
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const changes = countChanges(saved, draft);
  const label = (id: string) => permissions.find((p) => p.id === id)?.label ?? id;
  const locked = roles.filter((r) => r.locked);

  const toggle = (role: Role, perm: string, on: boolean) => {
    const r = applyGrant(permissions, draft[role.id] ?? [], perm, on);
    setDraft((d) => ({ ...d, [role.id]: r.now }));
    setFailed(false);
    const names = r.also.map(label);
    const list = names.length > 1 ? `${names.slice(0, -1).join(', ')} and ${names.at(-1)}` : names[0];
    setAlso(names.length ? `Also turned ${on ? 'on' : 'off'} ${list} for ${role.name}.` : '');
  };
  const save = () => {
    setBusy(true);
    setFailed(false);
    const now = draft;
    void Promise.resolve().then(() => onSave?.(now)).then(() => {
      setSaved(now);
      setAlso('');
      announce('Roles saved');
    }, () => setFailed(true)).finally(() => setBusy(false));
  };

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme Projects</p>
        <Link underline="hover" href="#workspace">Workspace settings</Link>
      </header>
      <Container as="main" size="lg" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">Your changes stay here. Saving them needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Workspace settings', href: '#workspace' }, { label: 'Roles' }]} title="Roles and permissions"
            description="Choose what people in each role can do. Changes apply to everyone in the role once you save." />
          {loadFailed ? <div className="pt-6"><EmptyLoadFailed title="Couldn’t load the roles" onRetry={() => onRetry?.()} headingLevel={2} /></div>
            : loading ? <Card className="mt-6"><Skeleton shape="text" lines={6} label="Loading roles" /></Card> : (<>
          {locked.length ? <p className="m-0 pt-6">{locked.map((r) => r.name).join(', ')} can do everything, and that can’t be changed, so the workspace always has someone who can.</p> : null}
          <div className="pt-4">
            <Table caption="What each role can do" hideCaption pinStart>
              <TableHead><TableRow>
                <TableHeaderCell>Permission</TableHeaderCell>
                {roles.map((r) => <TableHeaderCell key={r.id} align="center">{r.name}</TableHeaderCell>)}
              </TableRow></TableHead>
              <TableBody>
                {permissions.map((p) => (
                  <TableRow key={p.id}>
                    <TableHeaderCell scope="row" className="min-w-40 font-normal whitespace-normal">
                      <span className="block font-semibold">{p.label}</span>
                      <span className="block text-sm text-text-muted">{p.allows}{p.needs?.length ? `. Needs ${p.needs.map(label).join(' and ')}` : ''}.</span>
                    </TableHeaderCell>
                    {roles.map((r) => (
                      <TableCell key={r.id} align="center">
                        <Checkbox aria-label={`${r.name}: ${p.label}`} readOnly={r.locked}
                          checked={r.locked ? true : (draft[r.id] ?? []).includes(p.id)}
                          onCheckedChange={(on) => toggle(r, p.id, on)} />
                      </TableCell>
                    ))}
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
          <p role="status" id="roles-also" className="m-0 min-h-6 pt-3 text-sm">{also}</p>
          <div className="flex flex-col items-start gap-3 pt-4">
            {failed ? <Alert tone="danger">Couldn’t save the roles. Try again; your changes are still here.</Alert> : null}
            <p className="m-0 text-sm text-text-muted" id="roles-changes">
              {changes ? `${changes === 1 ? '1 change' : `${formatNumber(changes, locale)} changes`} not saved yet.` : 'Everything is saved.'}
            </p>
            {changes ? (
              <div className="flex flex-wrap gap-2">
                <Button loading={busy} onClick={save}>{changes === 1 ? 'Save 1 change' : `Save ${formatNumber(changes, locale)} changes`}</Button>
                <Button variant="outline" onClick={() => { setDraft(saved); setAlso(''); setFailed(false); announce('Changes discarded'); }}>Discard changes</Button>
              </div>
            ) : null}
          </div>
          </>)}
        </Stack>
      </Container>
    </div>
  );
}

files.SavedItems.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Image } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Select } from '@diki-stwn/serupa-ds';
import { EmptyState } from '@diki-stwn/serupa-ds';
import { Toaster, toast } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { EmptyLoadFailed } from './EmptyStates';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Saved items: things kept for later, with what changed since (a lower price, few left, sold out), and a way to move
   each to the cart or let it go. For an app to copy. What it carries (WCAG 2.2):
   - 1.3.1, 2.4.6: each item is a list item named by its heading, a link to the product.
   - 1.4.1: what changed is said in words in a badge ("Price dropped", "Only 2 left", "Sold out"), and a lower price
     shows the old one struck through with "Was" in words.
   - 2.5.3, 2.4.6: each button's name starts with its visible words and ends with the item it acts on ("Move to cart:
     Linen shirt"), so a list of buttons read alone still says which is which.
   - 3.3.4: Remove acts at once and offers Undo in a toast, rather than "Are you sure?"; focus moves to the next
     item's button, or the heading when none is left (2.4.3).
   - 4.1.3: how many items, and the sort, are said in a status line as they change.
   Moving and removing are the app's: onMoveToCart and onRemove get the item's id; reject onMoveToCart when it can't. */

export interface SavedItem {
  id: string;
  name: string;
  href: string;
  image: string;
  /** The price now, and when it was saved. */
  price: number;
  savedPrice: number;
  /** How many are left: 0 is sold out. Leave out when there are plenty. */
  left?: number | undefined;
  /** When it was saved: "2026-02-03". */
  saved: string;
}

export type SavedSort = 'newest' | 'price-low' | 'price-high' | 'dropped';

export interface SavedItemsProps {
  /** The saved items. Default: demo items. */
  items?: SavedItem[] | undefined;
  /** ISO 4217 currency. Default: "USD". */
  currency?: string | undefined;
  /** Moves an item to the cart. Reject when it can't. */
  onMoveToCart?: ((id: string) => unknown) | undefined;
  /** Removes an item for good, once its toast closes without Undo. */
  onRemove?: ((id: string) => void) | undefined;
  /** Still loading: a placeholder shows instead of the saved items. Default: false. */
  loading?: boolean | undefined;
  /** Loading failed: a "Couldn’t load your saved items" message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, from Try again. Return a promise: the button shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

// A drawn thing in a colored square, so the demo loads nothing from another server.
const pic = (fill: string, bg: string, shape: string) => 'data:image/svg+xml,' + encodeURIComponent(
  `<svg xmlns="http://www.w3.org/2000/svg" width="400" height="400" viewBox="0 0 400 400"><rect width="400" height="400" fill="${bg}"/><path d="${shape}" fill="${fill}"/></svg>`);
const SHIRT = 'M150 90 L110 110 L70 170 L115 195 L130 175 V320 H270 V175 L285 195 L330 170 L290 110 L250 90 Q200 130 150 90Z';
const BAG = 'M110 150 H290 L305 330 H95Z M160 150 Q160 90 200 90 Q240 90 240 150 H225 Q225 105 200 105 Q175 105 175 150Z';
const CUP = 'M120 150 H280 L265 300 Q260 320 240 320 H160 Q140 320 135 300Z M280 180 Q330 180 325 220 Q320 255 272 255 L275 235 Q305 235 305 218 Q305 200 278 200Z';
const HAT = 'M110 260 Q110 120 200 120 Q290 120 290 260Z M95 255 H305 V300 H95Z';
const demo: SavedItem[] = [
  { id: 's1', name: 'Linen shirt', href: '#linen-shirt', image: pic('#f5f0e6', '#d6cfc0', SHIRT), price: 39, savedPrice: 52, saved: '2026-02-12' },
  { id: 's2', name: 'Canvas tote bag', href: '#tote', image: pic('#c9b48a', '#eee6d6', BAG), price: 24, savedPrice: 24, left: 2, saved: '2026-02-08' },
  { id: 's3', name: 'Ceramic pour-over set', href: '#pour-over', image: pic('#e8e4dc', '#9fb3a8', CUP), price: 68, savedPrice: 68, left: 0, saved: '2026-01-30' },
  { id: 's4', name: 'Wool beanie', href: '#beanie', image: pic('#9b2c2c', '#e5dada', HAT), price: 18, savedPrice: 18, saved: '2026-01-21' },
];
const SORTS: { value: SavedSort; label: string }[] = [
  { value: 'newest', label: 'Newest saved first' },
  { value: 'price-low', label: 'Price, low to high' },
  { value: 'price-high', label: 'Price, high to low' },
  { value: 'dropped', label: 'Price dropped first' },
];

/** The items in the order asked for; ties keep the newest saved first. */
export function sortSaved(items: readonly SavedItem[], sort: SavedSort): SavedItem[] {
  const newest = [...items].sort((a, b) => b.saved.localeCompare(a.saved));
  if (sort === 'price-low') return newest.sort((a, b) => a.price - b.price);
  if (sort === 'price-high') return newest.sort((a, b) => b.price - a.price);
  if (sort === 'dropped') return newest.sort((a, b) => Number(b.price < b.savedPrice) - Number(a.price < a.savedPrice));
  return newest;
}

/** What changed since it was saved, in words, or null. */
export function savedChange(item: SavedItem): { label: string; tone: 'success' | 'warning' | 'neutral' } | null {
  if (item.left === 0) return { label: 'Sold out', tone: 'neutral' };
  if (item.price < item.savedPrice) return { label: 'Price dropped', tone: 'success' };
  if (item.left !== undefined && item.left <= 5) return { label: `Only ${item.left} left`, tone: 'warning' };
  return null;
}

/** The saved items page: a skip link, a header, then main with the h1, the sort, and the items, or an empty state. */
export function SavedItems({ items = demo, currency = 'USD', onMoveToCart, onRemove, loading = false, loadFailed = false, onRetry, online }: SavedItemsProps) {
  const locale = useLocale();
  const [list, setList] = React.useState(items);
  // What the app passes once loading ends replaces what was there, which was empty or the demo.
  const [wasLoading, setWasLoading] = React.useState(loading);
  if (wasLoading !== loading) { setWasLoading(loading); if (!loading) { setList(items); } }
  const [gone, setGone] = React.useState<ReadonlySet<string>>(new Set());
  const [sort, setSort] = React.useState<SavedSort>('newest');
  const [busy, setBusy] = React.useState<string | null>(null);
  const heading = React.useRef<HTMLHeadingElement>(null);
  const money = (n: number) => formatNumber(n, locale, { style: 'currency', currency });
  const shown = sortSaved(list.filter((i) => !gone.has(i.id)), sort);
  const later = (f: () => void) => requestAnimationFrame(f);
  const focusAfter = (item: SavedItem) => {
    const at = shown.indexOf(item), next = shown[at + 1] ?? shown[at - 1];
    later(() => (next ? document.getElementById(`remove-${next.id}`) : heading.current)?.focus());
  };

  const remove = (item: SavedItem) => {
    focusAfter(item);
    setGone((g) => new Set(g).add(item.id));
    toast.undo({
      title: `Removed ${item.name}`,
      commit: () => onRemove?.(item.id),
      onUndo: () => { setGone((g) => { const n = new Set(g); n.delete(item.id); return n; }); later(() => document.getElementById(`remove-${item.id}`)?.focus()); },
    });
  };
  const move = (item: SavedItem) => {
    setBusy(item.id);
    void Promise.resolve().then(() => onMoveToCart?.(item.id)).then(() => {
      focusAfter(item);
      setList((l) => l.filter((i) => i.id !== item.id));
      toast({ title: `Moved ${item.name} to your cart`, tone: 'success' });
    }, () => toast({ title: `Couldn’t move ${item.name} to your cart. Try again.`, tone: 'danger' })).finally(() => setBusy(null));
  };

  return (
    <div className="min-h-screen bg-surface-sunken text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
        <Link underline="hover" href="#cart">Cart</Link>
      </header>
      <Container as="main" size="lg" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">These prices are from when the page loaded. Moving items to your bag needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Account', href: '#account' }, { label: 'Saved items' }]} title="Saved items"
            description="Kept for later. We’ll show here when a price drops or few are left." />
          {loadFailed ? <div className="pt-6"><EmptyLoadFailed title="Couldn’t load your saved items" onRetry={() => onRetry?.()} headingLevel={2} /></div>
            : loading ? <Card className="mt-6"><Skeleton shape="text" lines={6} label="Loading saved items" /></Card> : (<>
          <section aria-labelledby="saved-list" className="flex flex-col gap-4 pt-6">
            <div className="flex flex-wrap items-end justify-between gap-3">
              <h2 id="saved-list" ref={heading} tabIndex={-1} className="m-0 text-lg font-semibold outline-none">Your list</h2>
              {shown.length > 1 ? (
                <Field label="Sort by" id="saved-sort">
                  <Select options={SORTS} value={sort} onChange={(e) => setSort(e.target.value as SavedSort)} />
                </Field>
              ) : null}
            </div>
            <p id="saved-count" role="status" className="m-0 text-sm text-text-muted">
              {shown.length === 1 ? '1 item' : `${formatNumber(shown.length, locale)} items`}{shown.length > 1 ? `, ${SORTS.find((s) => s.value === sort)!.label.toLowerCase()}` : ''}
            </p>
            {shown.length ? (
              <ul role="list" className="m-0 grid list-none grid-cols-1 gap-6 p-0 sm:grid-cols-2 lg:grid-cols-3">
                {shown.map((item) => {
                  const change = savedChange(item);
                  const out = item.left === 0;
                  return (
                    <Card as="li" key={item.id} padding="md" aria-labelledby={`saved-${item.id}`} className="flex min-w-0 flex-col gap-3 wrap-anywhere">
                      <Image src={item.image} alt="" ratio="square" rounded />
                      <h3 id={`saved-${item.id}`} className="m-0 text-base font-semibold"><Link href={item.href}>{item.name}</Link></h3>
                      <p className="m-0 flex flex-wrap items-baseline gap-x-2 gap-y-1">
                        <span className="text-lg font-semibold">{money(item.price)}</span>
                        {item.price < item.savedPrice ? <span className="text-sm text-text-muted">Was <del>{money(item.savedPrice)}</del></span> : null}
                        {change ? <Badge tone={change.tone}>{change.label}</Badge> : null}
                      </p>
                      {/* Sold out, Remove is alone: its word lines up with the card's text, its padding and border (8px and
                          1px) out past the edge, so its hover fill still shows the whole button. */}
                      <div className={out ? 'mt-auto -ms-2 flex' : 'mt-auto flex flex-wrap gap-2'}>
                        {out ? null : (
                          <Button variant="secondary" size="sm" loading={busy === item.id} onClick={() => move(item)} aria-label={`Move to cart: ${item.name}`}>Move to cart</Button>
                        )}
                        <Button id={`remove-${item.id}`} variant="ghost" size="sm" className={out ? '-ms-px' : undefined} onClick={() => remove(item)} aria-label={`Remove: ${item.name}`}>Remove</Button>
                      </div>
                    </Card>
                  );
                })}
              </ul>
            ) : (
              <EmptyState icon="favorite" headingLevel={3} title="Nothing saved yet"
                description="Choose Save on any product to keep it here, with its price as it was."
                actions={<Link href="#shop">Browse the shop</Link>} />
            )}
          </section>
          </>)}
        </Stack>
      </Container>
      <Toaster />
    </div>
  );
}

files.SendMoney.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { DescriptionList, DescriptionItem } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { NumberInput } from '@diki-stwn/serupa-ds';
import { RadioGroup, Radio } from '@diki-stwn/serupa-ds';
import { ErrorSummary, type ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Send money: choose who, say how much, see what they'll get, check it all on a review step, then send. For an app to
   copy. What it carries (WCAG 2.2):
   - 1.3.1: who it's to is a group of radios named by the question, each with their bank as its description.
   - 3.3.2, 4.1.3: your balance is said before you type; what they'll get, the fee and the rate follow the amount.
   - 3.3.1, 2.4.3: continuing with problems shows a summary at the top that takes focus, each problem a link.
   - 3.3.4: money moves only after a review step that lists who, how much, the fee, what they get and when it
     arrives; Change goes back with everything kept.
   - 2.4.3: each step's heading takes focus: the review, back to the form on Change, and the answer once sent.
   - 3.3.4, 4.1.3: Send shows it's busy; a transfer that can't be sent says nothing moved and stays on the review.
   Moving the money is the app's job: onSend gets the transfer; reject when it can't be sent. */

export interface Recipient { id: string; name: string; bank: string; currency: string; rate: number; arrives: string }
export interface Transfer { to: string; amount: number; fee: number; receives: number; reference: string }

export interface SendMoneyProps {
  /** Your money: its currency and how much you have. Default: USD 1,240.50. */
  account?: { currency: string; balance: number } | undefined;
  /** The people you've sent to before. */
  recipients?: Recipient[] | undefined;
  /** The fee: a share of the amount and a smallest fee. Default: 0.5% and 1. */
  fee?: { rate: number; min: number } | undefined;
  /** Sends the money. Reject when it can't be sent. */
  onSend?: ((transfer: Transfer) => unknown) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demoRecipients: Recipient[] = [
  { id: 'dewi', name: 'Dewi Lestari', bank: 'Bank Mandiri, account ending 4821', currency: 'IDR', rate: 15890, arrives: 'Today, within an hour' },
  { id: 'chen', name: 'Chen Wei', bank: 'Bank of China, account ending 0037', currency: 'CNY', rate: 7.12, arrives: 'In 1 to 2 working days' },
  { id: 'lena', name: 'Lena Vogel', bank: 'Sparkasse, IBAN ending 3104', currency: 'EUR', rate: 0.92, arrives: 'Tomorrow' },
];
const FIELDS = ['to', 'amount'] as const;
type Problems = Partial<Record<(typeof FIELDS)[number], string>>;

/** The fee, what leaves your account and what arrives, for an amount at a rate. */
export function transferQuote(amount: number, rate: number, fee: { rate: number; min: number }) {
  const f = amount > 0 ? Math.max(fee.min, Math.round(amount * fee.rate * 100) / 100) : 0;
  return { fee: f, total: Math.round((amount + f) * 100) / 100, receives: Math.round(amount * rate * 100) / 100 };
}

/** What's wrong with a transfer, by field, or {} when it can go to review. */
export function transferProblems(to: string, amount: number | null, total: number, balance: number, money: (n: number) => string = String): Problems {
  const out: Problems = {};
  if (!to) out.to = 'Choose who to send it to.';
  if (!amount || amount <= 0) out.amount = 'Enter how much to send.';
  else if (total > balance) out.amount = `Enter a smaller amount: with the fee, it’s more than your ${money(balance)}.`;
  return out;
}

/** The send money page: a skip link, a header, then main with the h1, and the form, the review or the answer. */
export function SendMoney({ account = { currency: 'USD', balance: 1240.5 }, recipients = demoRecipients, fee = { rate: 0.005, min: 1 }, onSend, online }: SendMoneyProps) {
  const locale = useLocale();
  const money = (n: number, currency = account.currency) => formatNumber(n, locale, { style: 'currency', currency });
  const [to, setTo] = React.useState('');
  const [amount, setAmount] = React.useState<number | null>(null);
  const [reference, setReference] = React.useState('');
  const [step, setStep] = React.useState<'form' | 'review' | 'sent'>('form');
  const [problems, setProblems] = React.useState<Problems>({});
  const [tries, setTries] = React.useState(0);
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const moved = React.useRef(false);
  const heading = React.useRef<HTMLHeadingElement>(null);
  const who = recipients.find((r) => r.id === to);
  const q = transferQuote(amount ?? 0, who?.rate ?? 1, fee);
  const errors: ErrorSummaryItem[] = FIELDS.filter((f) => problems[f]).map((f) => ({ field: `send-${f}`, message: problems[f] }));
  const go = (next: typeof step) => { moved.current = true; setStep(next); };

  const review = (e: React.FormEvent) => {
    e.preventDefault();
    const found = transferProblems(to, amount, q.total, account.balance, money);
    setProblems(found);
    setTries((t) => t + 1);
    if (!Object.keys(found).length) go('review');
  };
  const send = () => {
    setFailed(false);
    setBusy(true);
    void Promise.resolve().then(() => onSend?.({ to, amount: amount!, fee: q.fee, receives: q.receives, reference: reference.trim() }))
      .then(() => go('sent'), () => setFailed(true)).finally(() => setBusy(false));
  };
  React.useEffect(() => { if (moved.current) heading.current?.focus(); }, [step]);
  const h2 = 'm-0 text-lg font-semibold outline-none';

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme Bank</p>
        <Link underline="hover" href="#accounts">Accounts</Link>
      </header>
      <Container as="main" size="prose" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">Your transfer stays here. Sending it needs a connection, and the fee is checked again first.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Accounts', href: '#accounts' }, { label: 'Send money' }]} title="Send money"
            description={`You have ${money(account.balance)} in your account.`} />
          <div className="flex flex-col gap-5 pt-6">
            {step === 'form' ? (
              <form onSubmit={review} noValidate aria-labelledby="send-form" className="flex flex-col gap-4">
                <h2 id="send-form" ref={heading} tabIndex={-1} className={h2}>Who and how much</h2>
                <ErrorSummary key={tries} errors={errors} />
                <p className="m-0 text-text-muted">Fields marked * are required.</p>
                <Field label="Send to" group error={problems.to} required>
                  <RadioGroup id="send-to" name="send-to" variant="card" value={to} onValueChange={(v: string) => { setTo(v); setFailed(false); }}>
                    {recipients.map((r) => <Radio key={r.id} value={r.id} description={r.bank}>{r.name}</Radio>)}
                  </RadioGroup>
                </Field>
                <Field label={`Amount in ${account.currency}`} id="send-amount" hint={`Up to ${money(account.balance)}, with the fee.`} error={problems.amount} required>
                  <NumberInput currency={account.currency} min={0} value={amount} onValueChange={setAmount} className="max-w-56" />
                </Field>
                <Card padding="sm" variant="filled">
                  <p className="m-0" id="send-quote" aria-live="polite">
                    {who && amount ? <>{who.name} gets <strong>{money(q.receives, who.currency)}</strong>. Fee {money(q.fee)}; {money(q.total)} leaves your account. 1 {account.currency} = {formatNumber(who.rate, locale)} {who.currency}.</>
                      : 'Choose who and how much to see what they get.'}
                  </p>
                </Card>
                <Field label="Reference" id="send-reference" hint="They see this on their statement." optional>
                  <Input maxLength={35} value={reference} onChange={(e) => setReference(e.target.value)} />
                </Field>
                <div><Button type="submit">Review</Button></div>
              </form>
            ) : step === 'review' && who ? (
              <section aria-labelledby="send-review" className="flex flex-col items-start gap-4">
                <h2 id="send-review" ref={heading} tabIndex={-1} className={h2}>Check and send</h2>
                <p className="m-0">Nothing has moved yet. Once you send, it can’t be stopped.</p>
                <DescriptionList layout="split" className="w-full max-w-md">
                  <DescriptionItem term="To">{who.name}<span className="block text-sm text-text-muted">{who.bank}</span></DescriptionItem>
                  <DescriptionItem term="You send">{money(amount!)}</DescriptionItem>
                  <DescriptionItem term="Fee">{money(q.fee)}</DescriptionItem>
                  <DescriptionItem term="Leaves your account">{money(q.total)}</DescriptionItem>
                  <DescriptionItem term="They get">{money(q.receives, who.currency)}</DescriptionItem>
                  <DescriptionItem term="Arrives">{who.arrives}</DescriptionItem>
                  {reference.trim() ? <DescriptionItem term="Reference">{reference.trim()}</DescriptionItem> : null}
                </DescriptionList>
                {failed ? <Alert tone="danger">Couldn’t send it, and nothing has moved. Try again in a moment.</Alert> : null}
                <div className="flex flex-wrap gap-3">
                  <Button onClick={send} loading={busy}>Send {money(q.total)}</Button>
                  <Button variant="secondary" onClick={() => { setFailed(false); go('form'); }} disabled={busy}>Change</Button>
                </div>
              </section>
            ) : (
              <section aria-labelledby="send-done" className="flex flex-col items-start gap-3">
                <h2 id="send-done" ref={heading} tabIndex={-1} className="m-0 text-2xl font-semibold outline-none">Sent to {who?.name}</h2>
                <p className="m-0">{money(q.receives, who?.currency)} arrives {who?.arrives.toLowerCase()}. We’ve emailed you a receipt.</p>
                <div className="flex flex-wrap gap-3">
                  <Link href="#accounts">Back to accounts</Link>
                  <Link href="#send" onClick={(e) => { e.preventDefault(); setAmount(null); setReference(''); setTo(''); setProblems({}); go('form'); }}>Send more money</Link>
                </div>
              </section>
            )}
          </div>
        </Stack>
      </Container>
    </div>
  );
}

files.SessionTimeout.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Dialog } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { Textarea } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { announce } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Session time-out warning: warns well before a session ends, lets one action keep it, and loses nothing
   typed if it ends anyway. For an app to copy. What it carries (WCAG 2.2):
   - 2.2.1: typing or clicking on the page counts as activity and keeps the session (at most once every
     `activityEvery` seconds, through `onExtend`), so nobody writing a long message is interrupted mid-sentence.
   - 2.2.1: with nothing happening, a Dialog opens `warnBefore` seconds before the end (two minutes by default, well over the 20 seconds
     2.2.1 asks for). "Stay signed in", focused first, is the one action that extends it; Escape extends it too,
     since pressing anything means someone is there.
   - 4.1.3: the time left is said when the warning opens, then only at each whole minute and at 30 seconds, never
     every second. The countdown on screen updates every second, outside any live region.
   - 2.2.6, 3.3.7: what's typed is kept as it's typed (here in sessionStorage under `saveKey`), so if the session
     ends, signing in again in the same tab brings it all back, and the page says so before and after. Signing out on
     purpose or sending the message clears it, so the next person on the computer doesn't find it. Closing the tab
     doesn't: a browser that reopens a closed tab brings its sessionStorage back, so sign out on a shared computer.
     Only the subject and the message are kept: never a password, card number or ID number.
   - 2.4.3: when the warning closes, focus goes back to where it was; when the session ends, to the "Signed out"
     heading.
   Keeping the session on the server (a request from `onExtend`), and signing in again, is the app's job. */

export interface SessionTimeoutProps {
  /** How long the session lasts with nothing done, in seconds. Default: 1200 (20 minutes). */
  duration?: number | undefined;
  /** How long before the end the warning opens, in seconds. Default: 120. */
  warnBefore?: number | undefined;
  /** Refresh the session on the server: "Stay signed in" was pressed, or the person typed or clicked (at most once every
      `activityEvery` seconds). A rejected promise lets the session run out. */
  onExtend?: (() => void | Promise<unknown>) | undefined;
  /** The session ended: sign out on the server. */
  onExpire?: (() => void) | undefined;
  /** Typing or clicking keeps the session, at most once every this many seconds. Default: 60. */
  activityEvery?: number | undefined;
  /** Keeps what's typed in sessionStorage under this key, so it survives a time-out or a reload in the same tab.
      Signing out or sending the message clears it; a closed tab that the browser reopens brings it back. */
  saveKey?: string | undefined;
  /** Send the message. Once it resolves, the kept draft is cleared; a rejected promise keeps it. */
  onSend?: ((draft: { subject: string; message: string }) => void | Promise<unknown>) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

interface Draft { subject: string; message: string }
const TICK = 1000;

/** Words for a time left: "2 minutes", "1 minute 30 seconds", "45 seconds". */
export function timeLeft(seconds: number, locale = 'en-US'): string {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  const unit = (n: number, one: string) => `${formatNumber(n, locale)} ${one}${n === 1 ? '' : 's'}`;
  return [m ? unit(m, 'minute') : '', s || !m ? unit(s, 'second') : ''].filter(Boolean).join(' ');
}
/** Whether the time left is worth saying: each whole minute, and 30 seconds. */
const worthSaying = (seconds: number) => seconds > 0 && (seconds % 60 === 0 || seconds === 30);

// Drafts go in sessionStorage, not localStorage: they last for the tab, not for every later visit from the computer.
// Only the two fields below are written, so a field added to the form isn't kept until it's named here; never name a
// password, card number or ID number.
const keep = (d: Partial<Draft>): Draft => ({ subject: String(d.subject ?? ''), message: String(d.message ?? '') });
function load(key: string | undefined): Draft | null {
  if (!key) return null;
  try {
    const raw = window.sessionStorage.getItem(key);
    return raw ? keep(JSON.parse(raw) as Partial<Draft>) : null;
  } catch { return null; }
}
function forget(key: string | undefined) {
  if (!key) return;
  try { window.sessionStorage.removeItem(key); } catch { /* blocked: nothing was kept */ }
}
function save(key: string | undefined, draft: Draft) {
  if (!key) return;
  try { window.sessionStorage.setItem(key, JSON.stringify(keep(draft))); } catch { /* full or blocked: the draft stays in the page */ }
}

/** A page with a form, a warning Dialog before the session ends, and a signed-out page that keeps what was typed. */
export function SessionTimeout({ duration = 1200, warnBefore = 120, activityEvery = 60, onExtend, onExpire, onSend, saveKey, online }: SessionTimeoutProps) {
  const locale = useLocale();
  const [deadline, setDeadline] = React.useState(() => Date.now() + duration * 1000);
  const [left, setLeft] = React.useState(duration);
  const [draft, setDraft] = React.useState<Draft>(() => load(saveKey) ?? { subject: '', message: '' });
  const expired = left <= 0;
  const warning = !expired && left <= warnBefore;
  const signedOut = React.useRef<HTMLHeadingElement | null>(null);
  const [byChoice, setByChoice] = React.useState(false);

  React.useEffect(() => {
    if (expired) return;
    const id = window.setInterval(() => {
      const next = Math.max(0, Math.ceil((deadline - Date.now()) / 1000));
      setLeft(next);
      if (!next) onExpire?.();
    }, TICK);
    return () => window.clearInterval(id);
  }, [deadline, expired, onExpire]);

  // Say the time left when the warning opens, then only at sensible steps.
  const opened = React.useRef(false);
  React.useEffect(() => {
    if (!warning) { opened.current = false; return; }
    if (!opened.current) { opened.current = true; announce(`You’ll be signed out in ${timeLeft(left, locale)}.`); }
    else if (worthSaying(left)) announce(`${timeLeft(left, locale)} left.`);
  }, [warning, left, locale]);

  React.useEffect(() => { if (expired) signedOut.current?.focus(); }, [expired]);

  const restart = React.useCallback(() => { setDeadline(Date.now() + duration * 1000); setLeft(duration); setByChoice(false); }, [duration]);

  // Typing or clicking is activity: it refreshes the session, at most once every activityEvery seconds. Not while
  // the warning is open, where staying takes the warning's own answer.
  // The session last started at deadline - duration, and one refresh is asked for at a time.
  const asking = React.useRef(false);
  React.useEffect(() => {
    if (expired || warning) return;
    const active = () => {
      if (asking.current || Date.now() - (deadline - duration * 1000) < activityEvery * 1000) return;
      asking.current = true;
      Promise.resolve(onExtend?.()).then(() => { if (Date.now() < deadline) restart(); }, () => { /* the session runs out as warned */ }).finally(() => { asking.current = false; });
    };
    document.addEventListener('keydown', active, true);
    document.addEventListener('pointerdown', active, true);
    return () => { document.removeEventListener('keydown', active, true); document.removeEventListener('pointerdown', active, true); };
  }, [expired, warning, deadline, duration, activityEvery, onExtend, restart]);

  const signOut = () => {
    forget(saveKey);
    setDraft({ subject: '', message: '' });
    setByChoice(true);
    setLeft(0);
    onExpire?.();
  };
  // "Stay signed in" shows it's working while onExtend runs, and takes no second press. When it fails, the warning stays
  // open and says so, with the time still counting, so the person can try again or save their work.
  const [extending, setExtending] = React.useState(false);
  const [extendFailed, setExtendFailed] = React.useState(false);
  const extendingNow = React.useRef(false);
  const extend = async () => {
    if (extendingNow.current) return;
    extendingNow.current = true;
    setExtending(true);
    setExtendFailed(false);
    // An answer that comes after the session ran out is too late: onExpire was called, and it stays signed out.
    const asked = deadline;
    try { await onExtend?.(); if (Date.now() < asked) { restart(); announce('You’re still signed in.'); } } catch {
      setExtendFailed(true);
      announce('Couldn’t keep you signed in. Check your connection and try again.');
    } finally { extendingNow.current = false; setExtending(false); }
  };
  // While a send is under way the button shows it and takes no more presses, so a second click doesn't send the
  // message twice (the ref covers a second press before the re-render). An empty Subject or Message isn't sent: each
  // says what's missing and the first takes focus. The outcome shows on screen, not only to a screen reader: a sent
  // message is confirmed above the form, which takes focus (the form is empty again); a failed one says so beside
  // the button, and what was typed stays.
  const [sending, setSending] = React.useState(false);
  const [missing, setMissing] = React.useState<{ subject?: string; message?: string }>({});
  const [outcome, setOutcome] = React.useState<'sent' | 'failed' | null>(null);
  const sentRef = React.useRef<HTMLDivElement>(null);
  React.useEffect(() => { if (outcome === 'sent') sentRef.current?.focus(); }, [outcome]);
  const sendingNow = React.useRef(false);
  const send = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (sendingNow.current) return;
    const form = e.currentTarget;
    const empty = { subject: draft.subject.trim() ? undefined : 'Enter a subject', message: draft.message.trim() ? undefined : 'Enter your message' };
    setMissing(empty);
    if (empty.subject || empty.message) { setOutcome(null); (form.elements.namedItem(empty.subject ? 'subject' : 'message') as HTMLElement).focus(); return; }
    sendingNow.current = true;
    setSending(true);
    setOutcome(null);
    try { await onSend?.(draft); } catch { setOutcome('failed'); return; } finally { sendingNow.current = false; setSending(false); }
    forget(saveKey);
    setDraft({ subject: '', message: '' });
    setOutcome('sent');
  };
  const type = (k: keyof Draft) => (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const next = { ...draft, [k]: e.target.value };
    if (missing[k] && e.target.value.trim()) setMissing({ ...missing, [k]: undefined });
    setDraft(next);
    save(saveKey, next);
  };

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <Container as="main" size="prose" className="py-8 outline-none" id="main">
        <Stack gap={6}>
          <OfflineBanner online={online} placement="inline">Your work stays here. Staying signed in needs a connection.</OfflineBanner>
          {expired ? (
            <div className="flex flex-col gap-3">
              <Heading level={1} ref={signedOut} tabIndex={-1} className="outline-none">{byChoice ? 'You’ve signed out' : 'You’ve been signed out'}</Heading>
              <p className="m-0">{byChoice
                ? 'What you typed is cleared from this computer, so nobody else finds it.'
                : `We signed you out because nothing happened for ${timeLeft(duration, locale)}. What you typed is kept: sign in again to carry on where you left off.`}</p>
              <div><Button onClick={restart}>Sign in again</Button></div>
            </div>
          ) : (
            <>
              <PageHeader title="Contact support"
                description={<>For your security, you’re signed out after {timeLeft(duration, locale)} with nothing happening: typing counts. We’ll warn you first, and keep what you’ve typed.</>} />
              <Card as="section" aria-labelledby="message-title">
                <form className="flex flex-col gap-4" noValidate onSubmit={(e) => void send(e)}>
                  <Heading level={2} size="lg" id="message-title">Your message</Heading>
                  {outcome === 'sent' ? <Alert ref={sentRef} tabIndex={-1} tone="success" className="outline-none">Message sent. We’ll reply by email.</Alert> : null}
                  <p className="m-0 text-text-muted">Fields marked * are required.</p>
                  <Field label="Subject" error={missing.subject} required>
                    <Input name="subject" value={draft.subject} onChange={type('subject')} />
                  </Field>
                  <Field label="Message" hint="What happened, and what you expected." error={missing.message} required>
                    <Textarea name="message" rows={6} value={draft.message} onChange={type('message')} />
                  </Field>
                  {outcome === 'failed' ? <Alert tone="danger">The message wasn’t sent. What you typed is kept: try again.</Alert> : null}
                  <div><Button type="submit" loading={sending}>Send message</Button></div>
                </form>
              </Card>
            </>
          )}
        </Stack>
      </Container>
      <Dialog open={warning} alert size="sm" title="You’ll be signed out soon"
        onOpenChange={(open) => { if (!open) void extend(); }}
        footer={<>
          <Button variant="secondary" onClick={signOut}>Sign out</Button>
          <Button data-autofocus loading={extending} onClick={() => void extend()}>Stay signed in</Button>
        </>}>
        <p className="m-0">You’ll be signed out in <strong>{timeLeft(left, locale)}</strong> because nothing has happened for a while.</p>
        <p className="m-0 mt-2 text-sm text-text-muted">If the time runs out, what you’ve typed is kept. Signing out clears it.</p>
        {extendFailed ? <p className="m-0 mt-2 text-sm text-text-danger">Couldn’t keep you signed in. Check your connection and try again.</p> : null}
      </Dialog>
    </div>
  );
}

files.SettingsForm.tsx:
'use client';
import * as React from 'react';
import { AppShell } from '@diki-stwn/serupa-ds';
import { Center } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { Textarea } from '@diki-stwn/serupa-ds';
import { Select } from '@diki-stwn/serupa-ds';
import { Switch } from '@diki-stwn/serupa-ds';
import { useUnsavedChanges } from '@diki-stwn/serupa-ds';
import type { ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import type { SaveState } from '@diki-stwn/serupa-ds';
import { SettingsSection } from './SettingsSection';
import { EmptyLoadFailed } from './EmptyStates';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { ColorPicker } from '@diki-stwn/serupa-ds';

/* Settings form: a settings page of sections, each with its own Save, errors and status, and a question before
   unsaved changes are lost. For an app to copy. What it carries (WCAG 2.2):
   - 1.3.1: each section is a region named by its heading; the switches are real checkboxes (role="switch") with
     their own labels and descriptions.
   - 3.3.1, 3.3.3: a Save with problems shows an ErrorSummary at the top of that section, which takes focus and links
     to each field, and each field says what to write ("Enter an email address, like name@example.com").
   - 4.1.3: SaveStatus says "Saved" politely when a save finishes, or "Couldn't save" with Try again, without moving
     focus.
   - 3.2.2: nothing saves on its own. Each section waits for its own Save, so a change in one never saves another.
   - 3.3.4-ish: leaving with unsaved changes (the "Back to the dashboard" link, or closing the tab) asks "Discard
     changes?" first, with Keep editing focused (useUnsavedChanges).
   Storing the settings is the app's job: `onSave` gets each section's values. */

export interface Profile {
  name: string; email: string; bio: string; timeZone: string;
  /** The color behind your initials where there's no photo, as #rrggbb. Leave it out for the app's own. */
  color?: string | undefined;
}
export interface Notifications { comments: boolean; summary: boolean; news: boolean }
export interface SettingsValues { profile: Profile; notifications: Notifications }

export interface SettingsFormProps {
  /** The settings as saved. Default: a demo account. */
  initial?: SettingsValues | undefined;
  /** Saves one section. A rejected promise shows "Couldn't save" with Try again. */
  onSave?: (<K extends keyof SettingsValues>(section: K, values: SettingsValues[K]) => void | Promise<unknown>) | undefined;
  /** "Back to the dashboard" was followed, after any unsaved changes were discarded: go there. */
  onLeave?: (() => void) | undefined;
  /** The saved settings are on their way: each section shows placeholder fields, and the form starts from `initial` once
      they're in. Default: false. */
  loading?: boolean | undefined;
  /** The saved settings failed to load: a "Couldn’t load your settings" message with Try again, which calls onRetry, in
      place of the sections. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demo: SettingsValues = {
  profile: { name: 'Ada Lovelace', email: 'ada@example.com', bio: '', timeZone: 'Europe/London', color: '#1d4ed8' },
  notifications: { comments: true, summary: true, news: false },
};
const ZONES = [
  { value: 'America/Los_Angeles', label: 'Los Angeles (UTC−8)' }, { value: 'America/New_York', label: 'New York (UTC−5)' },
  { value: 'Europe/London', label: 'London (UTC+0)' }, { value: 'Europe/Berlin', label: 'Berlin (UTC+1)' },
  { value: 'Asia/Jakarta', label: 'Jakarta (UTC+7)' }, { value: 'Asia/Tokyo', label: 'Tokyo (UTC+9)' },
];
/** The colors behind initials, each dark enough for white letters on it (4.5:1). */
const COLORS = [
  { value: '#1d4ed8', label: 'Blue' }, { value: '#6d28d9', label: 'Violet' }, { value: '#047857', label: 'Green' },
  { value: '#b91c1c', label: 'Red' }, { value: '#a16207', label: 'Ochre' }, { value: '#3f3f46', label: 'Gray' },
];
const BIO_MAX = 160;
const id = (k: keyof Profile) => `profile-${k}`;

/** What's wrong with the profile, in the order of its fields. */
export function profileProblems(p: Profile): ErrorSummaryItem[] {
  const rules: [keyof Profile, boolean, string][] = [
    ['name', !p.name.trim(), 'Enter your name, as your team should see it'],
    ['email', !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(p.email.trim()), 'Enter an email address, like name@example.com'],
    ['bio', p.bio.length > BIO_MAX, `Shorten your bio to ${BIO_MAX} characters or fewer`],
  ];
  return rules.filter(([, bad]) => bad).map(([k, , message]) => ({ field: id(k), message }));
}

/** One section's draft, saved copy, errors and save status. */
function useSection<K extends keyof SettingsValues>(key: K, saved0: SettingsValues[K], check: (v: SettingsValues[K]) => ErrorSummaryItem[],
  onSave: SettingsFormProps['onSave']) {
  const [draft, setDraft] = React.useState(saved0);
  const [saved, setSaved] = React.useState(saved0);
  const [errors, setErrors] = React.useState<ErrorSummaryItem[]>([]);
  const [status, setStatus] = React.useState<SaveState>('idle');
  const [savedAt, setSavedAt] = React.useState<number | undefined>(undefined);
  const dirty = JSON.stringify(draft) !== JSON.stringify(saved);
  const save = async () => {
    const found = check(draft);
    setErrors(found);
    if (found.length) { setStatus('idle'); return; }
    setStatus('saving');
    try {
      await onSave?.(key, draft);
      setSaved(draft);
      setSavedAt(Date.now());
      setStatus('saved');
    } catch { setStatus('error'); }
  };
  const set = (patch: Partial<SettingsValues[K]>) => { setDraft({ ...draft, ...patch }); if (status === 'saved') setStatus('idle'); };
  return { draft, set, dirty, errors, status, savedAt, save: () => void save() };
}

/** The settings page: a skip link, a header with the way back, then main with the h1 and a section per group. */
export function SettingsForm({ loading = false, loadFailed = false, onRetry, online, ...props }: SettingsFormProps) {
  // The form takes `initial` when it mounts, so it mounts once the settings are in, not before.
  return loading || loadFailed ? <Loading failed={loadFailed} onRetry={onRetry} online={online} /> : <Loaded {...props} online={online} />;
}

// While the settings load: the same page, with a busy placeholder per section, named once ("Loading settings"). When
// they failed to load: the page says so in the sections' place, with Try again.
function Loading({ failed, onRetry, online }: { failed: boolean; onRetry: SettingsFormProps['onRetry']; online: boolean | undefined }) {
  return (
    <AppShell header={<header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
      <p className="m-0 text-base font-semibold">Acme</p>
      <Link underline="hover" href="#dashboard">Back to the dashboard</Link>
    </header>}>
      <Center maxWidth="container-4xl" padded={false} aria-busy={failed ? undefined : true}>
        <Stack gap={6}>
          <OfflineBanner online={online} placement="inline">Saving needs a connection.</OfflineBanner>
        <PageHeader title="Settings" description="Fields marked * are required." />
        {failed ? <EmptyLoadFailed title="Couldn’t load your settings" onRetry={() => onRetry?.()} headingLevel={2} /> : ['Profile', 'Notifications'].map((t, i) => (
          <Stack as="section" key={t} aria-labelledby={'settings-loading-' + i} gap={4}>
            <Heading level={2} size="lg" id={'settings-loading-' + i}>{t}</Heading>
            <Skeleton shape="text" lines={i === 0 ? 6 : 3} label={i === 0 ? 'Loading settings' : ''} />
          </Stack>
        ))}
        </Stack>
      </Center>
    </AppShell>
  );
}

function Loaded({ initial = demo, onSave, onLeave, online }: Omit<SettingsFormProps, 'loading' | 'loadFailed' | 'onRetry'>) {
  const profile = useSection('profile', initial.profile, profileProblems, onSave);
  const notes = useSection('notifications', initial.notifications, () => [], onSave);
  const { confirm, dialog } = useUnsavedChanges(profile.dirty || notes.dirty);
  const p = profile.draft;
  const n = notes.draft;
  const err = (k: keyof Profile) => profile.errors.find((e) => e.field === id(k))?.message;

  const leave = async (e: React.MouseEvent) => {
    e.preventDefault();
    if (await confirm()) onLeave?.();
  };

  return (
    <AppShell header={<header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
      <p className="m-0 text-base font-semibold">Acme</p>
      <Link underline="hover" href="#dashboard" onClick={(e) => void leave(e)}>Back to the dashboard</Link>
    </header>}>
      <Center maxWidth="container-4xl" padded={false}>
        <OfflineBanner online={online} placement="inline" className="mb-6">Your changes stay here. Saving them needs a connection.</OfflineBanner>
        <PageHeader title="Settings" description="Fields marked * are required." />
        <SettingsSection title="Profile" description="How you appear to your team." onSave={profile.save}
          errors={profile.errors} status={profile.status} savedAt={profile.savedAt} onRetry={profile.save} saveLabel="Save profile">
          <Field label="Name" error={err('name')} required>
            <Input id={id('name')} name="name" autoComplete="name" value={p.name} onChange={(e) => profile.set({ name: e.target.value })} />
          </Field>
          <Field label="Email" hint="Where we send your notifications." error={err('email')} required>
            <Input id={id('email')} name="email" type="email" autoComplete="email" spellCheck={false} value={p.email}
              onChange={(e) => profile.set({ email: e.target.value })} />
          </Field>
          <Field label="Bio" hint={`A line about you, up to ${BIO_MAX} characters.`} error={err('bio')} optional>
            <Textarea id={id('bio')} name="bio" rows={3} showCount maxLength={BIO_MAX} value={p.bio} onChange={(e) => profile.set({ bio: e.target.value })} />
          </Field>
          <Field label="Time zone" hint="For the times on comments and the weekly summary.">
            <Select id={id('timeZone')} name="timeZone" value={p.timeZone} options={ZONES} onChange={(e) => profile.set({ timeZone: e.target.value })} />
          </Field>
          <Field label="Initials color" hint="Behind your initials where there’s no photo. A color of your own is checked against the white letters.">
            <ColorPicker swatches={COLORS} value={p.color ?? null} onValueChange={(color) => profile.set({ color })} custom contrastWith="#ffffff" minContrast={4.5} />
          </Field>
        </SettingsSection>
        <SettingsSection title="Notifications" description="What reaches you by email. Everything is in the app either way."
          onSave={notes.save} status={notes.status} savedAt={notes.savedAt} onRetry={notes.save} saveLabel="Save notifications">
          <Switch checked={n.comments} onCheckedChange={(on) => notes.set({ comments: on })} description="When someone replies to you or mentions you.">Comments</Switch>
          <Switch checked={n.summary} onCheckedChange={(on) => notes.set({ summary: on })} description="Every Monday: what changed in your projects.">Weekly summary</Switch>
          <Switch checked={n.news} onCheckedChange={(on) => notes.set({ news: on })} description="New features, at most once a month.">Product news</Switch>
        </SettingsSection>
        {dialog}
      </Center>
    </AppShell>
  );
}

files.ShareDialog.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Avatar } from '@diki-stwn/serupa-ds';
import { AvatarGroup } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { CopyButton } from '@diki-stwn/serupa-ds';
import { Dialog } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { Select } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { announce } from '@diki-stwn/serupa-ds';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Share dialog: who can open one document, what each may do, and the link to it. For an app to copy.
   What it carries (WCAG 2.2):
   - One Share button, in the page's header where people look for it, and beside it who the document is shared with
     as soon as it is shared: the faces, and the count in words.
   - 1.3.1, 2.4.6: each person's access picker is named with the person ("Access for Budi Santoso").
   - 4.1.3: a changed access, a removal, its undo and the link's setting are each said.
   - 3.3.4, 2.4.3: Remove takes the person out at once and leaves "Removed" with Undo in their row, where focus
     goes, so nothing needs "Are you sure?" and focus is never lost. It's done for good when the dialog closes.
   - The link's setting is one picker whose choices are whole phrases ("Anyone with the link can view"), and the
     same phrase is on the page, so people never work out who can see the document from two controls.
   - 3.3.1, 3.3.3: the add-people field names each address that isn't one, or has access already, and keeps what
     was typed; an invite that fails says so, and the dialog stays open.
   - Copy link is always there. "Share via…" opens the device's own share sheet and shows only where the browser has one.
   Storing the changes and sending the email are the app's job: onInvite, onAccessChange, onRemove and
   onLinkAccessChange get them. */

export type ShareAccess = 'view' | 'edit';
export type ShareLinkAccess = 'restricted' | ShareAccess;
export interface SharePerson { id: string; name: string; email: string; access: ShareAccess | 'owner'; avatar?: string | undefined; you?: boolean | undefined }

export interface ShareDialogProps {
  /** The document's name. Default: a demo name. */
  name?: string | undefined;
  /** The link to it. Default: a demo link. */
  url?: string | undefined;
  /** The people with access, the owner first. Default: a demo list. */
  people?: readonly SharePerson[] | undefined;
  /** Who the link alone lets in at first: 'restricted' (only people added, the default), 'view' or 'edit'. */
  linkAccess?: ShareLinkAccess | undefined;
  /** Open on arrival. Default: false. */
  defaultOpen?: boolean | undefined;
  /** Invite was pressed with good addresses. Return its promise: a rejection keeps what was typed and says so. */
  onInvite?: ((emails: string[], access: ShareAccess) => unknown) | undefined;
  /** A person's access was changed. */
  onAccessChange?: ((id: string, access: ShareAccess) => void) | undefined;
  /** The dialog closed with this person removed and not undone: remove them for good. */
  onRemove?: ((id: string) => void) | undefined;
  /** The link's setting was changed. */
  onLinkAccessChange?: ((access: ShareLinkAccess) => void) | undefined;
  /** Opens the device's share sheet. Default: navigator.share where the browser has it. null leaves "Share via…" out. */
  nativeShare?: ((data: { title: string; url: string }) => unknown) | null | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demoPeople: SharePerson[] = [
  { id: 'u1', name: 'Ana Lima', email: 'ana@example.com', access: 'owner', you: true },
  { id: 'u2', name: 'Budi Santoso', email: 'budi@example.com', access: 'edit' },
  { id: 'u3', name: 'Chen Wei', email: 'chen@example.com', access: 'view' },
];
const ACCESS = [{ value: 'edit', label: 'Can edit' }, { value: 'view', label: 'Can view' }];
const LINK: Record<ShareLinkAccess, string> = {
  restricted: 'Only people added can open',
  view: 'Anyone with the link can view',
  edit: 'Anyone with the link can edit',
};
const linkOptions = (Object.keys(LINK) as ShareLinkAccess[]).map((value) => ({ value, label: LINK[value] }));
const EMAIL = /^[^\s@,;]+@[^\s@,;]+\.[^\s@,;]+$/;

const still = () => () => {};
const never = () => false;
const canShare = () => typeof navigator.share === 'function';

/** What's wrong with what was typed, in words, or null when every address can be invited. */
export function shareProblem(emails: readonly string[], taken: readonly string[]): string | null {
  if (!emails.length) return 'Enter an email address.';
  const bad = emails.filter((e) => !EMAIL.test(e));
  if (bad.length) return `${bad.length === 1 ? 'This isn’t an email address' : 'These aren’t email addresses'}: ${bad.join(', ')}.`;
  const on = emails.filter((e) => taken.includes(e));
  if (on.length) return `Already has access: ${on.join(', ')}.`;
  return null;
}

/** How many people it's shared with, in words: the owner doesn't count. */
export function sharedWith(count: number, locale = 'en-US'): string {
  return count === 0 ? 'Not shared' : count === 1 ? 'Shared with 1 person' : `Shared with ${formatNumber(count, locale)} people`;
}

/** A document page with Share in its header, and the dialog it opens: add people, change or remove access, and the link. */
export function ShareDialog({ name = 'Q3 plan', url = 'https://acme.example/d/q3-plan', people = demoPeople, linkAccess = 'restricted', defaultOpen = false,
  onInvite, onAccessChange, onRemove, onLinkAccessChange, nativeShare, online }: ShareDialogProps) {
  const locale = useLocale();
  const [open, setOpen] = React.useState(defaultOpen);
  const [list, setList] = React.useState<readonly SharePerson[]>(people);
  const [removed, setRemoved] = React.useState<ReadonlySet<string>>(new Set());
  const [link, setLink] = React.useState<ShareLinkAccess>(linkAccess);
  const [text, setText] = React.useState('');
  const [access, setAccess] = React.useState<ShareAccess>('view');
  const [problem, setProblem] = React.useState<string | null>(null);
  const [failed, setFailed] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  // The device's share sheet. A browser never gains or loses it: no subscription. Hydration renders the server's answer (none) first.
  const found = React.useSyncExternalStore(still, canShare, never);
  const sheet = nativeShare !== undefined ? nativeShare : found ? (data: { title: string; url: string }) => navigator.share(data) : null;
  const later = (f: () => void) => requestAnimationFrame(f);
  const focusId = (id: string) => () => document.getElementById(id)?.focus();
  const others = list.filter((p) => p.access !== 'owner' && !removed.has(p.id));

  const close = (o: boolean) => {
    setOpen(o);
    if (o) return;
    // Closing is when a removal is for good.
    removed.forEach((id) => onRemove?.(id));
    setList((l) => l.filter((p) => !removed.has(p.id)));
    setRemoved(new Set());
    setProblem(null);
    setFailed(false);
  };
  const change = (p: SharePerson, a: ShareAccess) => {
    setList((l) => l.map((x) => (x.id === p.id ? { ...x, access: a } : x)));
    onAccessChange?.(p.id, a);
    announce(`${p.name} ${a === 'edit' ? 'can edit' : 'can view'}`);
  };
  const remove = (p: SharePerson) => {
    setRemoved((r) => new Set(r).add(p.id));
    announce(`Removed ${p.name}`);
    later(focusId(`undo-${p.id}`));
  };
  const undo = (p: SharePerson) => {
    setRemoved((r) => { const n = new Set(r); n.delete(p.id); return n; });
    announce(`${p.name} has access again`);
    later(focusId(`remove-${p.id}`));
  };
  const setLinkAccess = (a: ShareLinkAccess) => {
    setLink(a);
    onLinkAccessChange?.(a);
    announce(LINK[a]);
  };
  const invite = (e: React.FormEvent) => {
    e.preventDefault();
    const emails = [...new Set(text.split(/[\s,;]+/).map((x) => x.trim().toLowerCase()).filter(Boolean))];
    const found = shareProblem(emails, list.filter((p) => !removed.has(p.id)).map((p) => p.email.toLowerCase()));
    setProblem(found);
    setFailed(false);
    if (found) { later(focusId('share-emails')); return; }
    setBusy(true);
    void Promise.resolve().then(() => onInvite?.(emails, access)).then(() => {
      // Someone removed and invited again keeps their row, with the new access, rather than being removed on close.
      const back = list.filter((p) => removed.has(p.id) && emails.includes(p.email.toLowerCase()));
      const again = new Set(back.map((p) => p.email.toLowerCase())), ids = new Set(back.map((p) => p.id));
      setRemoved((r) => new Set([...r].filter((id) => !ids.has(id))));
      setList((l) => [...l.map((p) => (ids.has(p.id) ? { ...p, access } : p)), ...emails.filter((x) => !again.has(x)).map((email) => ({ id: email, name: email, email, access }))]);
      setText('');
      announce(emails.length === 1 ? `Added ${emails[0]}` : `Added ${formatNumber(emails.length, locale)} people`);
      later(focusId('share-emails'));
    }, () => setFailed(true)).finally(() => setBusy(false));
  };

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center gap-3 border-b border-border bg-surface px-4 py-3">
        <p className="m-0 flex-1 text-base font-semibold">Acme Docs</p>
        {others.length ? (
          <AvatarGroup size="sm" max={3} aria-label={sharedWith(others.length, locale)}>
            {others.map((p) => <Avatar key={p.id} name={p.name} src={p.avatar} />)}
          </AvatarGroup>
        ) : null}
        <Button startIcon="share" onClick={() => close(true)}>Share</Button>
      </header>
      <Container as="main" size="prose" className="py-8 outline-none" id="main" tabIndex={-1}>
        <Stack gap={4}>
          <OfflineBanner online={online} placement="inline">Sharing and changing who has access need a connection.</OfflineBanner>
          <Heading level={1}>{name}</Heading>
          <p className="m-0 text-sm text-text-muted">{sharedWith(others.length, locale)} · {LINK[link]}</p>
          <p className="m-0">Goals for the quarter, who owns each, and what we’ll stop doing to make room.</p>
        </Stack>
      </Container>

      <Dialog open={open} onOpenChange={close} title={`Share “${name}”`}
        footer={<>
          <CopyButton value={url} variant="secondary" size="md">Copy link</CopyButton>
          {sheet ? <Button variant="secondary" onClick={() => { void Promise.resolve(sheet({ title: name, url })).catch(() => {}); }}>Share via…</Button> : null}
          <Button onClick={() => close(false)}>Done</Button>
        </>}>
        <div className="flex flex-col gap-5">
          <form onSubmit={invite} noValidate className="flex flex-col gap-3">
            {failed ? <Alert tone="danger">Couldn’t add them. Try again.</Alert> : null}
            <Field label="Add people" id="share-emails" hint="Email addresses, separated by commas." error={problem ?? undefined}>
              <Input type="email" multiple value={text} onChange={(e) => { setText(e.target.value); if (problem) setProblem(null); }} autoComplete="off" data-autofocus />
            </Field>
            <div className="flex flex-wrap items-center gap-3">
              <Select size="sm" aria-label="Access for the people you add" value={access} options={ACCESS}
                onChange={(e) => setAccess(e.target.value as ShareAccess)} className="w-32" />
              <Button type="submit" variant="secondary" size="sm" loading={busy}>Add</Button>
            </div>
          </form>

          <section aria-labelledby="share-people" className="flex flex-col gap-1">
            <Heading level={3} size="sm" id="share-people">People with access</Heading>
            <ul className="m-0 flex list-none flex-col divide-y divide-border p-0">
              {list.map((p) => (
                <li key={p.id} className="flex flex-wrap items-center gap-3 py-2">
                  {removed.has(p.id) ? (
                    <>
                      <span className="min-w-0 flex-1 text-sm wrap-break-word text-text-muted">Removed {p.name}</span>
                      <Button id={`undo-${p.id}`} size="sm" variant="ghost" aria-label={`Undo removing ${p.name}`} onClick={() => undo(p)}>Undo</Button>
                    </>
                  ) : (
                    <>
                      <Avatar size="sm" name={p.name} src={p.avatar} alt="" />
                      <div className="flex min-w-0 grow basis-40 flex-col">
                        <span className="font-medium wrap-break-word">{p.name}{p.you ? <Badge className="ms-2">You</Badge> : null}</span>
                        {p.email !== p.name ? <span className="text-sm wrap-break-word text-text-muted">{p.email}</span> : null}
                      </div>
                      {p.access === 'owner' ? <span className="text-sm text-text-muted">Owner</span> : (
                        <div className="flex items-center gap-3">
                          <Select size="sm" aria-label={`Access for ${p.name}`} value={p.access} options={ACCESS}
                            onChange={(e) => change(p, e.target.value as ShareAccess)} className="w-32" />
                          <Button id={`remove-${p.id}`} size="sm" variant="ghost" aria-label={`Remove ${p.name}`} onClick={() => remove(p)}>Remove</Button>
                        </div>
                      )}
                    </>
                  )}
                </li>
              ))}
            </ul>
          </section>

          <Field label="Link" id="share-link" hint={link === 'restricted' ? 'The link opens only for the people above.' : 'Anyone who gets the link can open it, without signing in.'}>
            <Select value={link} options={linkOptions} onChange={(e) => setLinkAccess(e.target.value as ShareLinkAccess)} />
          </Field>
        </div>
      </Dialog>
    </div>
  );
}

files.SignAgreement.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Checkbox } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Prose } from '@diki-stwn/serupa-ds';
import { ScrollArea } from '@diki-stwn/serupa-ds';
import { SignaturePad, type SignatureValue } from '@diki-stwn/serupa-ds';
import { ErrorSummary, type ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Sign agreement: an agreement to read in a box of its own, a box to tick that you agree, and your signature, drawn or
   typed. For an app to copy. What it carries (WCAG 2.2):
   - 2.1.1: the agreement scrolls in a ScrollArea that is a Tab stop and a region named by its title, so the keyboard
     can read all of it; the page doesn't need it scrolled to the end before you sign.
   - 2.5.7, 2.1.1: the signature can be typed instead of drawn (SignaturePad's Type), so nobody needs to drag.
   - 3.3.2: what signing means is said next to the button, before it's pressed.
   - 3.3.1, 2.4.3: signing with something missing shows a summary that takes focus, each problem a link to its field.
   - 3.3.4, 4.1.3: Sign shows it's busy; a signature that can't be sent says so and keeps what was filled in; once
     signed, the answer's heading takes focus.
   Storing the signature is the app's job: onSign gets it; reject when it can't be sent. */

export interface SignAgreementProps {
  /** The agreement's title: the h1. Default: a demo freelance agreement. */
  title?: string | undefined;
  /** The agreement itself, as paragraphs (or any content). Default: the demo's terms. */
  children?: React.ReactNode;
  /** Who signs, for the page's description. Default: Ana Lima. */
  signer?: string | undefined;
  /** Sends the signature. Reject when it can't be sent. */
  onSign?: ((signature: SignatureValue) => unknown) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demoTerms = (
  <>
    <h2>1. The work</h2>
    <p>You design the screens set out in the brief, in two rounds of changes, and hand over the files when they’re approved.</p>
    <h2>2. Payment</h2>
    <p>Acme pays half when this is signed and half when the files are handed over, within 14 days of each invoice.</p>
    <h2>3. Who owns what</h2>
    <p>Once paid for, the designs belong to Acme. You can show them in your portfolio after the product launches.</p>
    <h2>4. Keeping things private</h2>
    <p>Neither of us shares what we learn about the other’s business, during the work or after it.</p>
    <h2>5. Ending early</h2>
    <p>Either of us can end this with 14 days’ notice in writing. Acme pays for the work done up to then.</p>
  </>
);

/** What's missing before signing, in the order of the fields. */
export function signProblems(agreed: boolean, signature: SignatureValue | null): ErrorSummaryItem[] {
  const out: ErrorSummaryItem[] = [];
  if (!agreed) out.push({ field: 'sign-agree', message: 'Tick the box to say you agree.' });
  if (!signature) out.push({ field: 'sign-signature', message: 'Sign: draw your signature, or choose Type and type your name.' });
  return out;
}

/** The signing page: a skip link, a header, then main with the h1, the agreement, and the signature. */
export function SignAgreement({ title = 'Design work agreement', children = demoTerms, signer = 'Ana Lima', onSign, online }: SignAgreementProps) {
  const [agreed, setAgreed] = React.useState(false);
  const [signature, setSignature] = React.useState<SignatureValue | null>(null);
  const [errors, setErrors] = React.useState<ErrorSummaryItem[]>([]);
  const [tries, setTries] = React.useState(0);
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const [signed, setSigned] = React.useState(false);
  const answer = React.useRef<HTMLHeadingElement>(null);
  const problem = (field: string) => errors.find((e) => e.field === field)?.message;

  const sign = (e: React.FormEvent) => {
    e.preventDefault();
    const found = signProblems(agreed, signature);
    setErrors(found);
    setTries((t) => t + 1);
    setFailed(false);
    if (found.length || !signature) return;
    setBusy(true);
    void Promise.resolve().then(() => onSign?.(signature)).then(() => setSigned(true), () => setFailed(true)).finally(() => setBusy(false));
  };
  React.useEffect(() => { if (signed) answer.current?.focus(); }, [signed]);

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
        <Link underline="hover" href="#documents">Documents</Link>
      </header>
      <Container as="main" size="md" className="py-8 outline-none" id="main">
        <Stack gap={6}>
          <OfflineBanner online={online} placement="inline">You can read the agreement. Signing it needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Documents', href: '#documents' }, { label: title }]} title={title}
            description={`For ${signer} to sign. Read it through, then sign at the end.`} />
          {signed ? (
            <section aria-labelledby="sign-done" className="flex flex-col items-start gap-3">
              <Heading level={2} size="lg" id="sign-done" ref={answer} tabIndex={-1} className="outline-none">Signed</Heading>
              <p className="m-0">Thanks, {signer}. We’ve emailed you a copy of the signed agreement.</p>
              <Button href="#documents" variant="secondary">Back to documents</Button>
            </section>
          ) : (
            <>
              <ScrollArea aria-label={title} fade className="max-h-96 rounded-lg border border-border p-4">
                <Prose>{children}</Prose>
              </ScrollArea>
              <form onSubmit={sign} noValidate aria-label="Sign" className="flex flex-col gap-4">
                <ErrorSummary key={tries} errors={errors} />
                <Field error={problem('sign-agree')}>
                  <Checkbox id="sign-agree" checked={agreed} onCheckedChange={(on) => { setAgreed(on); setErrors((x) => x.filter((p) => p.field !== 'sign-agree')); }}>
                    I’ve read the agreement and I agree to it
                  </Checkbox>
                </Field>
                <Field label="Your signature" id="sign-signature" error={problem('sign-signature')} required>
                  <SignaturePad value={signature} onValueChange={(v) => { setSignature(v); if (v) setErrors((x) => x.filter((p) => p.field !== 'sign-signature')); }} />
                </Field>
                <div className="flex flex-col items-start gap-3">
                  {failed ? <Alert tone="danger">Couldn’t send your signature. Try again; nothing is lost.</Alert> : null}
                  <p className="m-0 text-sm text-text-muted">Signing here is the same as signing on paper.</p>
                  <Button type="submit" loading={busy}>Sign the agreement</Button>
                </div>
              </form>
            </>
          )}
        </Stack>
      </Container>
    </div>
  );
}

