'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { StatusTracker, type StatusDay, type StatusState } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { EmptyLoadFailed } from './EmptyStates';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { FormattedDate } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Status page: is it working now, each service's last 90 days, what's being done about a problem, and email updates.
   For an app to copy. What it carries (WCAG 2.2):
   - 1.3.1, 1.4.1: the overall state leads, in words, as an alert's title; each service's state is a word in a badge,
     never a color alone; each day of its strip is named in words by StatusTracker.
   - 1.3.1, 2.4.6: each service and each incident is named by its heading; an incident's updates are an ordered list,
     newest first, each with its time in a <time>.
   - 3.3.1, 4.1.3: subscribing with a wrong email says so next to the field; subscribed, it says so in a status and
     what to expect.
   Knowing the state is the app's job: pass the services, their days, and the incidents. */

export type ServiceState = 'up' | 'degraded' | 'down';
export interface Service { id: string; name: string; state: ServiceState; days: StatusDay[] }
export interface Incident { id: string; title: string; services: string[]; resolved: boolean; updates: { at: string; status: string; text: string }[] }

export interface StatusPageProps {
  services?: Service[] | undefined;
  incidents?: Incident[] | undefined;
  /** Adds an email to the updates list. Reject when it can't be added. */
  onSubscribe?: ((email: string) => unknown) | undefined;
  /** The services are still loading: a placeholder in their place. Default: false. */
  loading?: boolean | undefined;
  /** The services failed to load: a "Couldn’t load the status" message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads them again, from Try again. Return a promise: the button shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

/** `count` days ending on `end` (YYYY-MM-DD), oldest first: up, except the days given by how many days before the end. */
export function serviceDays(end: string, count: number, events: Record<number, { state: StatusState; note?: string }> = {}): StatusDay[] {
  const [y, m, d] = end.split('-').map(Number) as [number, number, number];
  return Array.from({ length: count }, (_, i) => {
    const back = count - 1 - i;
    const date = new Date(y, m - 1, d - back);
    return { date, state: events[back]?.state ?? 'up', note: events[back]?.note };
  });
}

/** The worst state of the services: one down makes it down, else one degraded makes it degraded. */
export function overallState(services: Service[]): ServiceState {
  return services.some((s) => s.state === 'down') ? 'down' : services.some((s) => s.state === 'degraded') ? 'degraded' : 'up';
}

const END = '2026-03-12';
const demoServices: Service[] = [
  { id: 'api', name: 'API', state: 'up', days: serviceDays(END, 90, { 34: { state: 'down', note: 'Outage, 38 minutes' }, 61: { state: 'degraded', note: 'Slow responses' } }) },
  { id: 'dashboard', name: 'Dashboard', state: 'up', days: serviceDays(END, 90, { 34: { state: 'degraded', note: 'Sign-in failing for some' } }) },
  { id: 'webhooks', name: 'Webhooks', state: 'degraded', days: serviceDays(END, 90, { 0: { state: 'degraded', note: 'Deliveries delayed' } }) },
  { id: 'email', name: 'Email delivery', state: 'up', days: serviceDays(END, 90) },
];
const demoIncidents: Incident[] = [
  { id: 'i3', title: 'Webhooks delivered late', services: ['webhooks'], resolved: false, updates: [
    { at: '2026-03-12T10:40', status: 'Monitoring', text: 'The backlog is clearing; deliveries are about 2 minutes late and catching up.' },
    { at: '2026-03-12T09:55', status: 'Identified', text: 'A queue worker stopped after a deploy. We’ve restarted it and are adding more.' },
    { at: '2026-03-12T09:20', status: 'Investigating', text: 'Some webhooks are arriving up to 20 minutes late. Nothing is lost.' },
  ] },
  { id: 'i2', title: 'API down for 38 minutes', services: ['api', 'dashboard'], resolved: true, updates: [
    { at: '2026-02-06T15:12', status: 'Resolved', text: 'A database failover took longer than it should. Everything is back, and we’re changing how failover is tested.' },
    { at: '2026-02-06T14:34', status: 'Investigating', text: 'The API is returning errors. The dashboard can’t sign people in.' },
  ] },
];
const STATE: Record<ServiceState, { word: string; tone: 'success' | 'warning' | 'danger' }> = {
  up: { word: 'Working', tone: 'success' },
  degraded: { word: 'Slow or partly working', tone: 'warning' },
  down: { word: 'Not working', tone: 'danger' },
};
const TITLE: Record<ServiceState, string> = {
  up: 'Everything is working',
  degraded: 'Some things are slow or partly working',
  down: 'Some things aren’t working',
};

/** The status page: a skip link, a header, then main with the h1, the overall state, incidents, services and updates. */
export function StatusPage({ services = demoServices, incidents = demoIncidents, onSubscribe, loading = false, loadFailed = false, onRetry, online }: StatusPageProps) {
  const locale = useLocale();
  const [email, setEmail] = React.useState('');
  const [problem, setProblem] = React.useState('');
  const [busy, setBusy] = React.useState(false);
  const [done, setDone] = React.useState('');
  const overall = overallState(services);
  const open = incidents.filter((i) => !i.resolved);
  const past = incidents.filter((i) => i.resolved);
  const names = (ids: string[]) => ids.map((id) => services.find((s) => s.id === id)?.name ?? id).join(', ');

  const subscribe = (e: React.FormEvent) => {
    e.preventDefault();
    const v = email.trim();
    const wrong = !v ? 'Enter your email address.' : /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v) ? '' : 'Enter an email address like name@example.com.';
    setProblem(wrong);
    setDone('');
    if (wrong) { document.getElementById('status-email')?.focus(); return; }
    setBusy(true);
    void Promise.resolve().then(() => onSubscribe?.(v)).then(() => { setDone(`Subscribed. Updates go to ${v}.`); setEmail(''); },
      () => setProblem('Couldn’t subscribe you. Try again in a moment.')).finally(() => setBusy(false));
  };

  const incident = (i: Incident) => (
    <article key={i.id} aria-labelledby={`incident-${i.id}`} className="flex flex-col gap-3 text-sm">
      <h3 id={`incident-${i.id}`} className="m-0 text-base font-semibold">{i.title}</h3>
      <p className="m-0 text-sm text-text-muted">Affects {names(i.services)}</p>
      <ol className="m-0 flex list-none flex-col gap-3 border-s-2 border-border ps-4">
        {i.updates.map((u) => (
          <li key={u.at}>
            <p className="m-0"><strong>{u.status}</strong> · <FormattedDate value={u.at} options={{ day: 'numeric', month: 'long', hour: 'numeric', minute: '2-digit' }} className="text-sm text-text-muted" /></p>
            <p className="m-0">{u.text}</p>
          </li>
        ))}
      </ol>
    </article>
  );

  return (
    <div className="min-h-screen bg-surface-sunken text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme status</p>
        <Link underline="hover" href="#support">Contact support</Link>
      </header>
      <Container as="main" size="md" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">This is the status from when the page loaded. It may have changed.</OfflineBanner>
          <PageHeader title="Acme status" description="How our services are doing now and over the last 90 days." />
          {loadFailed ? <div className="pt-6"><EmptyLoadFailed title="Couldn’t load the status" onRetry={() => onRetry?.()} headingLevel={2} /></div>
            : loading ? <Card className="mt-6"><Skeleton shape="text" lines={6} label="Loading the status" /></Card> : (<>
          <div className="flex flex-col gap-8 pt-6">
            <Alert tone={STATE[overall].tone} title={TITLE[overall]}>
              {open.length ? `${open.length === 1 ? 'An incident is' : `${formatNumber(open.length, locale)} incidents are`} open; the latest updates are below.` : 'No open incidents.'}
            </Alert>
            {open.length ? (
              <section aria-labelledby="status-now" className="flex flex-col gap-4">
                <h2 id="status-now" className="m-0 text-lg font-semibold">Open incidents</h2>
                {open.map((i) => <Card key={i.id}>{incident(i)}</Card>)}
              </section>
            ) : null}
            <section aria-labelledby="status-services" className="flex flex-col gap-4">
              <h2 id="status-services" className="m-0 text-lg font-semibold">Services</h2>
              <ul className="m-0 flex list-none flex-col gap-4 p-0">
                {services.map((s, n) => (
                  <li key={s.id}>
                    <Card className="flex flex-col gap-3">
                      <div className="flex flex-wrap items-center justify-between gap-2">
                        <h3 className="m-0 text-base font-semibold">{s.name}</h3>
                        <Badge tone={STATE[s.state].tone}>{STATE[s.state].word}</Badge>
                      </div>
                      <StatusTracker label={s.name} days={s.days} legend={n === services.length - 1} />
                    </Card>
                  </li>
                ))}
              </ul>
            </section>
            {past.length ? (
              <section aria-labelledby="status-past" className="flex flex-col gap-4">
                <h2 id="status-past" className="m-0 text-lg font-semibold">Past incidents</h2>
                {past.map((i) => incident(i))}
              </section>
            ) : null}
            <section aria-labelledby="status-updates" className="flex flex-col gap-4">
              <h2 id="status-updates" className="m-0 text-lg font-semibold">Get updates by email</h2>
              <form onSubmit={subscribe} noValidate className="flex max-w-md flex-col items-start gap-3" aria-labelledby="status-updates">
                <Field label="Email" id="status-email" hint="We email when an incident starts, changes or ends. Unsubscribe from any email." error={problem || undefined} className="w-full">
                  <Input type="email" autoComplete="email" value={email} onChange={(e) => { setEmail(e.target.value); setProblem(''); }} />
                </Field>
                <Button type="submit" loading={busy}>Subscribe</Button>
              </form>
              <p role="status" id="status-subscribed" className="m-0">{done}</p>
            </section>
          </div>
          </>)}
        </Stack>
      </Container>
    </div>
  );
}

files.StockCount.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { DataGrid, type DataGridCellChange, type DataGridColumn } from '@diki-stwn/serupa-ds';
import { Dialog } from '@diki-stwn/serupa-ds';
import { EmptyState } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { MenuItem } from '@diki-stwn/serupa-ds';
import { Menubar, MenubarMenu } from '@diki-stwn/serupa-ds';
import { ToggleButton } from '@diki-stwn/serupa-ds';
import { ToggleGroup } from '@diki-stwn/serupa-ds';
import { Toolbar } from '@diki-stwn/serupa-ds';
import { TransferList } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { EmptyLoadFailed } from './EmptyStates';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* StockCount: a shop's stock counted shelf by shelf, typed into a grid like a spreadsheet, with what differs from
   the record said as it goes. For an app to copy. What it carries (WCAG 2.2):
   - 1.3.1: the products are a grid (role="grid") whose column headers name every cell; arrows move, Enter or F2
     edits a count, and a block pasted from a spreadsheet fills many at once.
   - 4.1.3: how many are counted, and how many differ from the record, is a status line that updates as counts go in.
   - 1.4.1: a difference is a signed number in its own column, never a color alone.
   - 2.1.1: the view's controls are one toolbar (one tab stop, arrows between them): the row size, and Columns, a
     dialog that moves columns between hidden and shown with buttons as well as a list.
   - 2.1.1, 4.1.2: what the whole count can do is a Menubar, as in a spreadsheet: File (download, print), Edit (clear
     every count, which asks first) and View (columns). Arrows move between its menus and through each.
   - 3.3.1: a save that fails says so where Save is, and every count stays.
   Fetching the products and saving the counts are the app's job: pass them, and onSave. */

export interface StockItem {
  id: string;
  sku: string;
  name: string;
  /** Where it's kept: an aisle, a shelf, a bin. */
  location: string;
  /** How many the record says there are. */
  expected: number;
  /** How many were counted; null until someone counts it. */
  counted: number | null;
}

type Density = 'sm' | 'md' | 'lg';
type Optional = 'sku' | 'location' | 'expected' | 'difference';

export interface StockCountProps {
  items?: StockItem[] | undefined;
  /** The place being counted, in the title. */
  place?: string | undefined;
  /** Saves the counts. Return a promise: Save shows it's working until it settles, and a rejection says it failed. */
  onSave?: ((items: StockItem[]) => void | Promise<unknown>) | undefined;
  /** File, Download as CSV was picked: the counts so far, for a spreadsheet. */
  onDownload?: ((items: StockItem[]) => void) | undefined;
  /** Still loading: placeholder rows show in the grid. Default: false. */
  loading?: boolean | undefined;
  /** Loading failed: a "Couldn’t load the stock" message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, from Try again. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const I = (id: string, sku: string, name: string, location: string, expected: number, counted: number | null): StockItem => ({ id, sku, name, location, expected, counted });
const demo: StockItem[] = [
  I('a', 'KP-001', 'Toraja coffee, 250 g', 'Aisle 1, shelf A', 42, 42),
  I('b', 'KP-002', 'Gayo coffee, 250 g', 'Aisle 1, shelf A', 18, 16),
  I('c', 'TH-010', 'Jasmine tea, 100 g', 'Aisle 1, shelf B', 120, 120),
  I('d', 'GL-005', 'Palm sugar, 500 g', 'Aisle 2, shelf A', 30, null),
  I('e', 'MD-020', 'Forest honey, 350 ml', 'Aisle 2, shelf B', 9, null),
  I('f', 'CK-014', 'Ginger cookies, 200 g', 'Aisle 3, shelf A', 55, null),
];

const OPTIONAL: { value: Optional; label: string }[] = [
  { value: 'sku', label: 'SKU' },
  { value: 'location', label: 'Location' },
  { value: 'expected', label: 'On record' },
  { value: 'difference', label: 'Difference' },
];

/** A count from what was typed or pasted: a whole number of 0 or more, or null for blank or anything else. */
export function parseCount(text: string): number | null {
  const t = text.trim();
  return /^\d+$/.test(t) ? Number(t) : null;
}

/** The counts after a grid change: each Counted cell typed, pasted or cleared. */
export function applyCounts(items: StockItem[], changes: DataGridCellChange[]): StockItem[] {
  return items.map((it) => {
    const c = changes.filter((x) => x.rowId === it.id && x.column === 'counted').pop();
    return c ? { ...it, counted: parseCount(c.value) } : it;
  });
}

/** How many are counted, and how many of those differ from the record. */
export function countProgress(items: StockItem[]) {
  const counted = items.filter((it) => it.counted != null);
  return { counted: counted.length, differ: counted.filter((it) => it.counted !== it.expected).length };
}

/** The page: a skip link, a header, then main with the h1, the count's progress, the view toolbar, the grid and Save. */
export function StockCount({ items: initial = demo, place = 'Main Street shop', onSave, onDownload, loading = false, loadFailed = false, onRetry, online }: StockCountProps) {
  const locale = useLocale();
  const num = (n: number) => formatNumber(n, locale);
  const [items, setItems] = React.useState(initial);
  const [density, setDensity] = React.useState<Density>('md');
  const [shown, setShown] = React.useState<string[]>(['location', 'expected', 'difference']);
  const [choosing, setChoosing] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  const [result, setResult] = React.useState<'saved' | 'failed' | null>(null);
  const [clearing, setClearing] = React.useState(false);
  const keep = React.useRef<HTMLButtonElement>(null);
  const has = (k: Optional) => shown.includes(k);
  const progress = countProgress(items);

  const columns: DataGridColumn<StockItem>[] = [
    ...(has('sku') ? [{ key: 'sku', header: 'SKU' } as const] : []),
    { key: 'name', header: 'Product' },
    ...(has('location') ? [{ key: 'location', header: 'Location' } as const] : []),
    ...(has('expected') ? [{ key: 'expected', header: 'On record', align: 'end', format: (r: StockItem) => num(r.expected) } as const] : []),
    { key: 'counted', header: 'Counted', align: 'end', editable: true, format: (r) => (r.counted == null ? '' : String(r.counted)) },
    // The difference is a signed number in words' place: "+2", "−2", or blank until counted (1.4.1).
    ...(has('difference') ? [{ key: 'id', header: 'Difference', align: 'end', format: (r: StockItem) => {
      if (r.counted == null) return '';
      const d = r.counted - r.expected;
      return d === 0 ? '0' : `${d > 0 ? '+' : '−'}${num(Math.abs(d))}`;
    } } as const] : []),
  ];

  const save = () => {
    setResult(null);
    setBusy(true);
    void Promise.resolve().then(() => onSave?.(items)).then(() => setResult('saved'), () => setResult('failed')).finally(() => setBusy(false));
  };

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme Stock</p>
        <Link underline="hover" href="#counts">All counts</Link>
      </header>
      <Container as="main" size="xl" className="py-8 outline-none" id="main">
        <Stack gap={6}>
          <OfflineBanner online={online} placement="inline">Keep counting: every count stays here. Saving them needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'All counts', href: '#counts' }, { label: place }]} title={`Stock count: ${place}`}
            description="Type each count in Counted. Arrows move between cells, Enter edits one, and you can paste a column from a spreadsheet." />
          {loadFailed ? <EmptyLoadFailed title="Couldn’t load the stock" onRetry={() => onRetry?.()} headingLevel={2} /> : (<>
            <Menubar aria-label="Stock count" className="self-start">
              <MenubarMenu label="File">
                <MenuItem icon="download" onSelect={() => onDownload?.(items)}>Download as CSV</MenuItem>
                <MenuItem icon="print" onSelect={() => window.print()}>Print</MenuItem>
              </MenubarMenu>
              <MenubarMenu label="Edit">
                <MenuItem icon="restart_alt" disabled={!progress.counted} onSelect={() => setClearing(true)}>Clear all counts…</MenuItem>
              </MenubarMenu>
              <MenubarMenu label="View">
                <MenuItem icon="view_column" onSelect={() => setChoosing(true)}>Columns…</MenuItem>
              </MenubarMenu>
            </Menubar>
            <div className="flex flex-wrap items-center justify-between gap-3">
              <p role="status" id="sc-progress" className="m-0">
                {loading ? 'Loading the stock…' : !items.length ? 'No products to count yet.'
                  : `Counted ${num(progress.counted)} of ${num(items.length)} products. ${progress.differ === 1 ? '1 differs' : `${num(progress.differ)} differ`} from the record.`}
              </p>
              <Toolbar aria-label="Count view" size="sm">
                <ToggleGroup aria-label="Row size" selectionMode="single" required size="sm" value={[density]} onValueChange={(v) => { if (v[0]) setDensity(v[0] as Density); }}>
                  <ToggleButton value="sm">Compact</ToggleButton>
                  <ToggleButton value="md">Standard</ToggleButton>
                  <ToggleButton value="lg">Touch</ToggleButton>
                </ToggleGroup>
                <Button variant="outline" size="sm" startIcon="view_column" onClick={() => setChoosing(true)}>Columns</Button>
              </Toolbar>
            </div>
            <DataGrid<StockItem> aria-label={`Stock at ${place}`} aria-describedby="sc-progress" columns={columns} rows={items} size={density}
              onRowsChange={(_, { changes }) => { setItems((now) => applyCounts(now, changes)); setResult(null); }}
              loading={loading} loadingRows={6} loadingLabel="Loading the stock"
              message={<EmptyState size="sm" icon="inventory_2" title="Nothing to count here" headingLevel={2}
                description="Products show here once they’re stocked at this place." />} />
            {items.length && !loading ? (
              <div className="flex flex-col items-start gap-3">
                {result === 'failed' ? <Alert tone="danger">Couldn’t save the counts. Try again; every count is still here.</Alert>
                  : result === 'saved' ? <Alert tone="success">Counts saved.</Alert> : null}
                <Button onClick={save} loading={busy}>Save counts</Button>
              </div>
            ) : null}
          </>)}
        </Stack>
      </Container>
      <Dialog alert initialFocus={keep} open={clearing} onOpenChange={setClearing} title="Clear all counts?" description={`The ${num(progress.counted)} counts typed so far go, and every product is to count again.`}
        footer={<>
          <Button ref={keep} variant="outline" onClick={() => setClearing(false)}>Keep them</Button>
          <Button destructive onClick={() => { setItems((now) => now.map((it) => ({ ...it, counted: null }))); setResult(null); setClearing(false); }}>Clear counts</Button>
        </>} />
      <Dialog open={choosing} onOpenChange={setChoosing} title="Columns" description="Product and Counted always show."
        footer={<Button onClick={() => setChoosing(false)}>Done</Button>}>
        <TransferList aria-label="Columns" options={OPTIONAL} value={shown} onValueChange={setShown} availableLabel="Hidden" chosenLabel="Shown" />
      </Dialog>
    </div>
  );
}

files.StoreLocator.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Accordion, AccordionItem } from '@diki-stwn/serupa-ds';
import { DescriptionList, DescriptionItem } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { SearchInput } from '@diki-stwn/serupa-ds';
import { Switch } from '@diki-stwn/serupa-ds';
import { EmptyState } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { EmptyLoadFailed } from './EmptyStates';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Store locator: find a shop by town or postcode, or by where you are, with each one's distance, whether it's open
   now, its hours and directions. A list, not a map alone, so it works with any screen reader and at any zoom. For an
   app to copy. What it carries (WCAG 2.2):
   - 1.3.1, 2.4.6: the search is a labelled landmark; the results are a list, each shop named by its heading.
   - 1.4.1: "Open now" or "Closed now" is said in words in a badge, with when it next opens or closes, not a color.
   - 4.1.3: how many shops match, and in what order, is said in a status line as the search or the filter changes.
   - 3.3.1: when the browser can't give your location, it says so next to the button and what to do instead.
   - 2.5.3: each Directions link's name ends with its shop ("Directions: Acme Kemang").
   - A map is an extra the app can add beside the list; nothing here needs one.
   Finding where someone is, and the shops, are the app's: locate stands in for the browser's location. */

export interface Store {
  id: string;
  name: string;
  address: string;
  /** Words people search by: town, district, postcode. */
  area: string;
  lat: number;
  lng: number;
  /** Opening hours for each day, Sunday first: ["10:00", "21:00"], or null when closed all day. */
  hours: ([string, string] | null)[];
  phone: string;
}

export interface StoreLocatorProps {
  /** The shops. Default: demo shops in Jakarta. */
  stores?: Store[] | undefined;
  /** Now, for open or closed. Default: the time it renders. */
  now?: Date | undefined;
  /** Where the person is. Default: the browser's geolocation. Reject when it can't be had. */
  locate?: (() => Promise<{ lat: number; lng: number }>) | undefined;
  /** The stores are still loading: a placeholder in their place. Default: false. */
  loading?: boolean | undefined;
  /** The stores failed to load: a "Couldn’t load the stores" message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads them again, from Try again. Return a promise: the button shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const week = (open: string, close: string, sunday: [string, string] | null = ['11:00', '18:00']) =>
  [sunday, ...Array.from({ length: 6 }, () => [open, close] as [string, string])];
const demo: Store[] = [
  { id: 's1', name: 'Acme Kemang', address: 'Jl. Kemang Raya 8, South Jakarta 12730', area: 'Kemang South Jakarta 12730', lat: -6.2607, lng: 106.8137, hours: week('10:00', '21:00'), phone: '+62 21 555 0101' },
  { id: 's2', name: 'Acme Sudirman', address: 'Jl. Jend. Sudirman 21, Central Jakarta 10220', area: 'Sudirman Central Jakarta 10220', lat: -6.2088, lng: 106.8227, hours: week('08:00', '20:00', null), phone: '+62 21 555 0102' },
  { id: 's3', name: 'Acme Kelapa Gading', address: 'Jl. Boulevard Raya 3, North Jakarta 14240', area: 'Kelapa Gading North Jakarta 14240', lat: -6.1588, lng: 106.9056, hours: week('10:00', '22:00'), phone: '+62 21 555 0103' },
  { id: 's4', name: 'Acme Bandung', address: 'Jl. Braga 40, Bandung 40111', area: 'Braga Bandung 40111', lat: -6.9175, lng: 107.6191, hours: week('09:00', '21:00'), phone: '+62 22 555 0104' },
];
const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

/** The distance between two points in km, along the earth's surface. */
export function distanceKm(a: { lat: number; lng: number }, b: { lat: number; lng: number }): number {
  const rad = (d: number) => (d * Math.PI) / 180;
  const h = Math.sin(rad(b.lat - a.lat) / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(rad(b.lng - a.lng) / 2) ** 2;
  return 2 * 6371 * Math.asin(Math.sqrt(h));
}

/** Whether a shop is open at a time, and when that changes, in words: "Open now · closes 21:00". */
export function openState(store: Store, at: Date): { open: boolean; words: string } {
  const mins = (t: string) => { const [h, m] = t.split(':').map(Number); return h! * 60 + m!; };
  const day = at.getDay(), now = at.getHours() * 60 + at.getMinutes(), today = store.hours[day];
  if (today && now >= mins(today[0]) && now < mins(today[1])) return { open: true, words: `closes ${today[1]}` };
  if (today && now < mins(today[0])) return { open: false, words: `opens ${today[0]}` };
  for (let i = 1; i <= 7; i++) {
    const d = (day + i) % 7, h = store.hours[d];
    if (h) return { open: false, words: `opens ${i === 1 ? 'tomorrow' : DAYS[d]} ${h[0]}` };
  }
  return { open: false, words: 'closed for now' };
}

/** The shops whose name or area has every word searched for. */
export function matchStores(stores: readonly Store[], q: string): Store[] {
  const words = q.toLowerCase().split(/\s+/).filter(Boolean);
  return stores.filter((s) => words.every((w) => `${s.name} ${s.area} ${s.address}`.toLowerCase().includes(w)));
}

const fromBrowser = () => new Promise<{ lat: number; lng: number }>((ok, no) => {
  if (!navigator.geolocation) { no(new Error('none')); return; }
  navigator.geolocation.getCurrentPosition((p) => ok({ lat: p.coords.latitude, lng: p.coords.longitude }), no, { timeout: 10000 });
});

/** The store locator: a skip link, a header, then main with the h1, the search, and the shops. */
export function StoreLocator({ stores = demo, now, locate = fromBrowser, loading = false, loadFailed = false, onRetry, online }: StoreLocatorProps) {
  const locale = useLocale();
  const at = now ?? new Date();
  const [q, setQ] = React.useState('');
  const [here, setHere] = React.useState<{ lat: number; lng: number } | null>(null);
  const [locating, setLocating] = React.useState(false);
  const [noLocation, setNoLocation] = React.useState(false);
  const [openOnly, setOpenOnly] = React.useState(false);
  const matched = matchStores(stores, q).filter((s) => !openOnly || openState(s, at).open);
  const shown = here ? [...matched].sort((a, b) => distanceKm(here, a) - distanceKm(here, b)) : matched;
  const km = (s: Store) => formatNumber(distanceKm(here!, s), locale, { maximumFractionDigits: 1 });

  const findMe = () => {
    setLocating(true); setNoLocation(false);
    void locate().then((p) => { setHere(p); setQ(''); }, () => setNoLocation(true)).finally(() => setLocating(false));
  };

  return (
    <div className="min-h-screen bg-surface-sunken text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border bg-surface px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
        <Link underline="hover" href="#help">Help</Link>
      </header>
      <Container as="main" size="md" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">These stores and hours are from when the page loaded. Finding stores near you needs a connection.</OfflineBanner>
          <PageHeader title="Find a shop" description="Collect an order, return something, or try it on first." />
          {loadFailed ? <div className="pt-6"><EmptyLoadFailed title="Couldn’t load the stores" onRetry={() => onRetry?.()} headingLevel={2} /></div>
            : loading ? <Card className="mt-6"><Skeleton shape="text" lines={6} label="Loading stores" /></Card> : (<>
          <div className="flex flex-col gap-6 pt-6">
            <div role="search" aria-label="Shops" className="flex flex-col gap-3">
              <div className="flex flex-wrap items-end gap-3">
                <Field label="Town or postcode" className="min-w-0 flex-1">
                  <SearchInput value={q} onChange={(e) => setQ(e.target.value)} onClear={() => setQ('')} />
                </Field>
                <Button variant="secondary" loading={locating} onClick={findMe}>Use my location</Button>
              </div>
              {noLocation ? <Alert tone="warning">Couldn’t get your location. Your browser may have been asked not to share it; search by town or postcode instead.</Alert> : null}
              <Switch checked={openOnly} onCheckedChange={setOpenOnly}>Open now only</Switch>
            </div>
            <p id="store-count" role="status" className="m-0 text-sm text-text-muted">
              {shown.length === 1 ? '1 shop' : `${formatNumber(shown.length, locale)} shops`}{here && shown.length ? ', nearest first' : ''}
            </p>
            {shown.length ? (
              <ul role="list" className="m-0 flex list-none flex-col gap-4 p-0">
                {shown.map((s) => {
                  const st = openState(s, at);
                  return (
                    <Card as="li" key={s.id} aria-labelledby={`store-${s.id}`} className="flex flex-col gap-3">
                      <div className="flex flex-wrap items-baseline justify-between gap-2">
                        <h2 id={`store-${s.id}`} className="m-0 text-lg font-semibold">{s.name}</h2>
                        {here ? <span className="text-text-muted">{km(s)} km away</span> : null}
                      </div>
                      <p className="m-0">{s.address}</p>
                      <p className="m-0 flex flex-wrap items-center gap-2">
                        <Badge tone={st.open ? 'success' : 'neutral'}>{st.open ? 'Open now' : 'Closed now'}</Badge>
                        <span className="text-text-muted">{st.words}</span>
                      </p>
                      {/* The week's hours fold away under the system's disclosure (its chevron, focus ring and motion), not the
                          browser's own triangle. Today is in bold at the list's size: emphasis is for a total, and its larger
                          text would make one day stand out of the column. */}
                      <Accordion headingLevel={3}>
                        <AccordionItem title="Opening hours">
                          <DescriptionList layout="split" className="max-w-xs text-sm">
                            {DAYS.map((d, i) => (
                              <DescriptionItem key={d} term={d} className={i === at.getDay() ? 'font-semibold' : undefined}>{s.hours[i] ? `${s.hours[i][0]} to ${s.hours[i][1]}` : 'Closed'}</DescriptionItem>
                            ))}
                          </DescriptionList>
                        </AccordionItem>
                      </Accordion>
                      <p className="m-0 flex flex-wrap gap-x-4 gap-y-2">
                        <Link href={`https://www.openstreetmap.org/directions?to=${s.lat}%2C${s.lng}`} aria-label={`Directions: ${s.name}`}>Directions</Link>
                        <Link href={`tel:${s.phone.replace(/\s/g, '')}`} aria-label={`Call ${s.phone}: ${s.name}`}>Call {s.phone}</Link>
                      </p>
                    </Card>
                  );
                })}
              </ul>
            ) : (
              <EmptyState icon="search_off" headingLevel={2} title="No shops match"
                description={openOnly ? 'None that match are open now. Turn off “Open now only” to see the rest.' : 'Try a town or a postcode near you, or use your location.'} />
            )}
          </div>
          </>)}
        </Stack>
      </Container>
    </div>
  );
}

files.SupportTicket.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Avatar } from '@diki-stwn/serupa-ds';
import { Badge, type BadgeTone } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { DescriptionList, DescriptionItem } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { FileUpload } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Textarea } from '@diki-stwn/serupa-ds';
import { Toaster, toast } from '@diki-stwn/serupa-ds';
import { FormattedDate } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Support ticket: one request to a support team, as the person who asked sees it. Where it's got to, the
   conversation so far, and a reply box; or a way to reopen it once solved. For an app to copy. What it carries
   (WCAG 2.2):
   - 1.4.1, 1.3.1: where it's got to is a word in a badge ("Waiting on you"), with what that means in a sentence, not
     a color alone. The reference, opened and priority are named facts.
   - 1.3.1: the conversation is a list, oldest first; each message is an article named by who wrote it and when, and
     says "Support" or "You" in words, besides its picture.
   - 3.3.1, 3.3.2: the reply says what it takes; an empty one is named next to the box, which takes focus.
   - 4.1.3, 3.3.4: Send shows it's busy; a sent reply joins the list and a toast says so; one that can't be sent
     says so next to the button and keeps the words and the files.
   - 2.4.3: Mark as solved moves focus to the heading that says it's solved, with Reopen; Reopen brings the reply box
     back and focuses it.
   Sending and solving are the app's: onReply gets the words and files (reject when it can't send), onSolve and
   onReopen hear the rest. */

export type TicketState = 'open' | 'waiting' | 'solved';

export interface TicketMessage {
  id: string;
  /** "you" for the person who asked; otherwise the agent's name. */
  from: string;
  body: string;
  /** When: an ISO date and time. */
  at: string;
  /** Names of files sent with it. */
  files?: string[] | undefined;
}

export interface Ticket {
  reference: string;
  subject: string;
  state: TicketState;
  /** When it was opened: an ISO date and time. */
  opened: string;
  priority: string;
  messages: TicketMessage[];
}

export interface SupportTicketProps {
  /** The ticket. Default: a demo ticket waiting on you. */
  ticket?: Ticket | undefined;
  /** Sends a reply. Reject when it can't be sent. */
  onReply?: ((reply: { body: string; files: File[] }) => unknown) | undefined;
  /** Marks it solved. */
  onSolve?: (() => void) | undefined;
  /** Reopens it. */
  onReopen?: (() => void) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demo: Ticket = {
  reference: 'SR-30418', subject: 'Refund hasn’t arrived for order A-10432', state: 'waiting', opened: '2026-02-10T09:12:00Z', priority: 'Normal',
  messages: [
    { id: 'm1', from: 'you', body: 'I returned two items on 2 February and the tracking says they arrived, but I haven’t had the refund yet.', at: '2026-02-10T09:12:00Z' },
    { id: 'm2', from: 'Rina Wijaya', body: 'Thanks for writing. I can see the parcel arrived on 6 February. Could you send a photo of the bank statement where the refund should be, so I can check it with our payments team?', at: '2026-02-10T13:40:00Z' },
  ],
};
const STATE: Record<TicketState, { label: string; tone: BadgeTone; means: string }> = {
  open: { label: 'Open', tone: 'info', means: 'We’re looking into it, and will reply here.' },
  waiting: { label: 'Waiting on you', tone: 'warning', means: 'We’ve asked you something. Reply below, and we’ll pick it up again.' },
  solved: { label: 'Solved', tone: 'success', means: 'Closed. Reopen it within 30 days if it isn’t sorted.' },
};
const LIMIT = 4000;

/** What's wrong with a reply, in words, or null when it can be sent. */
export function replyProblem(body: string, files: readonly File[]): string | null {
  if (!body.trim() && !files.length) return 'Write a reply, or add a file.';
  if (body.length > LIMIT) return `Shorten your reply to ${LIMIT} characters.`;
  return null;
}

/** The ticket's page: a skip link, a header, then main with the h1, where it's got to, the conversation and the reply box. */
export function SupportTicket({ ticket = demo, onReply, onSolve, onReopen, online }: SupportTicketProps) {
  const [state, setState] = React.useState<TicketState>(ticket.state);
  const [messages, setMessages] = React.useState(ticket.messages);
  const [body, setBody] = React.useState('');
  const [files, setFiles] = React.useState<File[]>([]);
  const [problem, setProblem] = React.useState<string | null>(null);
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const solvedHeading = React.useRef<HTMLHeadingElement>(null);
  const reply = React.useRef<HTMLTextAreaElement>(null);
  const focusNext = React.useRef<'solved' | 'reply' | null>(null);

  const send = (e: React.FormEvent) => {
    e.preventDefault();
    setFailed(false);
    const found = replyProblem(body, files);
    setProblem(found);
    if (found) { reply.current?.focus(); return; }
    setBusy(true);
    const out = { body: body.trim(), files };
    void Promise.resolve().then(() => onReply?.(out)).then(() => {
      setMessages((m) => [...m, { id: `r${m.length + 1}`, from: 'you', body: out.body, at: new Date().toISOString(), files: out.files.map((f) => f.name) }]);
      setBody(''); setFiles([]);
      if (state === 'waiting') setState('open');
      toast({ title: 'Reply sent', tone: 'success' });
    }, () => setFailed(true)).finally(() => setBusy(false));
  };
  const solve = () => { onSolve?.(); focusNext.current = 'solved'; setState('solved'); };
  const reopen = () => { onReopen?.(); focusNext.current = 'reply'; setState('open'); };
  React.useEffect(() => {
    if (focusNext.current === 'solved') solvedHeading.current?.focus();
    if (focusNext.current === 'reply') reply.current?.focus();
    focusNext.current = null;
  }, [state]);

  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme help</p>
        <Link underline="hover" href="#tickets">Your requests</Link>
      </header>
      <Container as="main" size="md" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">Your reply stays here. Sending it needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Your requests', href: '#tickets' }, { label: ticket.reference }]} title={ticket.subject} />
          <div className="flex flex-col gap-8 pt-6">
            <Card>
              <section aria-labelledby="ticket-state" className="flex flex-col gap-4">
                <div className="flex flex-wrap items-center gap-3">
                  <h2 id="ticket-state" className="m-0 text-lg font-semibold">Where it’s got to</h2>
                  <Badge tone={STATE[state].tone}>{STATE[state].label}</Badge>
                </div>
                <p className="m-0">{STATE[state].means}</p>
                <DescriptionList>
                  <DescriptionItem term="Reference">{ticket.reference}</DescriptionItem>
                  <DescriptionItem term="Opened"><FormattedDate value={ticket.opened} timeStyle="short" /></DescriptionItem>
                  <DescriptionItem term="Priority">{ticket.priority}</DescriptionItem>
                </DescriptionList>
              </section>
            </Card>

            <section aria-labelledby="conversation" className="flex flex-col gap-4">
              <h2 id="conversation" className="m-0 text-lg font-semibold">Conversation</h2>
              <ol className="m-0 flex list-none flex-col gap-4 p-0">
                {messages.map((m) => {
                  const mine = m.from === 'you';
                  const who = mine ? 'You' : m.from;
                  return (
                    <li key={m.id}>
                      <article aria-labelledby={`msg-${m.id}`} className="flex gap-3">
                        <Avatar name={mine ? 'You' : m.from} size="sm" />
                        <div className="flex min-w-0 flex-1 flex-col gap-1">
                          <h3 id={`msg-${m.id}`} className="m-0 flex flex-wrap items-baseline gap-x-2 text-sm font-semibold">
                            <span>{who}</span>
                            {/* Yours is named "You" already, so only the time follows; theirs says "Support" too. */}
                            <span className="font-normal text-text-muted">{mine ? null : 'Support, '}<FormattedDate value={m.at} timeStyle="short" /></span>
                          </h3>
                          <p className="m-0 whitespace-pre-line wrap-break-word">{m.body}</p>
                          {m.files?.length ? <p className="m-0 text-sm text-text-muted">Attached: {m.files.join(', ')}</p> : null}
                        </div>
                      </article>
                    </li>
                  );
                })}
              </ol>
            </section>

            {state === 'solved' ? (
              <section aria-labelledby="solved" className="flex flex-col items-start gap-3">
                <h2 id="solved" ref={solvedHeading} tabIndex={-1} className="m-0 text-lg font-semibold outline-none">This request is solved</h2>
                <p className="m-0">If it isn’t sorted after all, reopen it and reply; it goes back to the same person.</p>
                <Button variant="secondary" onClick={reopen}>Reopen</Button>
              </section>
            ) : (
              <form onSubmit={send} noValidate aria-labelledby="reply-heading" className="flex flex-col gap-4">
                <h2 id="reply-heading" className="m-0 text-lg font-semibold">Reply</h2>
                <p className="m-0 text-text-muted">Fields marked * are required.</p>
                <Field label="Your reply" id="ticket-reply" hint="We reply within 1 working day." error={problem ?? undefined} required>
                  <Textarea ref={reply} rows={5} maxLength={LIMIT} value={body} onChange={(e) => { setBody(e.target.value); setProblem(null); setFailed(false); }} />
                </Field>
                <Field label="Files" optional>
                  <FileUpload id="ticket-files" multiple maxFiles={3} maxSize={10 * 1024 * 1024} accept="image/*,.pdf" hint="Photos or PDFs, up to 3, 10 MB each" files={files} onFilesChange={(f) => { setFiles(f); setProblem(null); }} />
                </Field>
                {failed ? <Alert tone="danger">Couldn’t send your reply. Try again; your words and files are still here.</Alert> : null}
                <div className="flex flex-wrap gap-2">
                  <Button type="submit" loading={busy}>Send reply</Button>
                  <Button variant="ghost" disabled={busy} onClick={solve}>Mark as solved</Button>
                </div>
              </form>
            )}
          </div>
        </Stack>
      </Container>
      <Toaster />
    </div>
  );
}

files.TaskBoard.tsx:
'use client';
import * as React from 'react';
import { SkipLink } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Badge } from '@diki-stwn/serupa-ds';
import { Dialog } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { Input } from '@diki-stwn/serupa-ds';
import { Select } from '@diki-stwn/serupa-ds';
import { Alert } from '@diki-stwn/serupa-ds';
import { Toaster, toast } from '@diki-stwn/serupa-ds';
import { Kanban, type KanbanColumn, type KanbanMove } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { PageHeader } from './PageHeader';
import { EmptyLoadFailed } from './EmptyStates';
import { OfflineBanner } from '@diki-stwn/serupa-ds';
import { Container } from '@diki-stwn/serupa-ds';
import { Stack } from '@diki-stwn/serupa-ds';

/* Task board: a team's tasks in columns, moved between stages and saved as they move, with a way to add one. For an
   app to copy. What it carries (WCAG 2.2):
   - 2.5.7, 2.1.1: Kanban moves a card by dragging its handle, by keyboard, or from its "Move to…" menu, so no move
     needs a drag.
   - 4.1.3: Kanban says each move as it happens. A move that can't be saved puts the card back where it was and says
     so in a toast that names the card and the column, so nobody is left looking at a board that isn't true.
   - 1.4.1, 3.3.1: a column over its limit says "Over limit" in words (Kanban), and a line above the board says which
     column and what to do about it.
   - 3.3.2, 3.3.1: a new task needs only a title; a missing one is said next to the field, which gets focus. An add
     that fails says so in the dialog, which stays open with what was typed.
   - 2.4.3: after an add, focus goes back to New task, and a toast says where the task went.
   - 4.1.3, 3.3.1: while the tasks load, each column shows placeholder cards, named once; a failed load says so, with
     Try again.
   Saving is the app's job: onMove gets each move and onAdd each new task; reject their promises when saving fails. */

export interface BoardTask {
  id: string;
  /** Short and unlike the others: it's read on the card's buttons and in every move. */
  title: string;
  /** Who has it: "Ana Lima". */
  assignee?: string | undefined;
  /** A word for its kind: "Bug". */
  tag?: string | undefined;
}
export type BoardColumn = KanbanColumn<BoardTask>;
export interface BoardTaskDraft {
  title: string;
  /** The id of the column it starts in. */
  column: string;
}

export interface TaskBoardProps {
  /** The board's name: the page's h1. Default: "Sprint 42". */
  title?: string | undefined;
  /** The columns and their tasks, in order. Default: a demo sprint. */
  columns?: readonly BoardColumn[] | undefined;
  /** A card was dropped somewhere new. Return its promise: a rejection puts the card back and says so. */
  onMove?: ((move: KanbanMove<BoardTask>) => unknown) | undefined;
  /** A task was added. Return its id, or a promise of it: a rejection keeps the dialog open and says so. */
  onAdd?: ((draft: BoardTaskDraft) => unknown) | undefined;
  /** The tasks are on their way: placeholder cards in each column, named once ("Loading tasks"). Default: false. */
  loading?: boolean | undefined;
  /** The tasks failed to load: a message with Try again, which calls onRetry, in the board's place. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads the tasks again, after a failed load. */
  onRetry?: (() => void) | undefined;
  /** Whether the app can reach its server. Left out, it follows the browser; false shows “You’re offline” at the top of
      the page, with what still works. */
  online?: boolean | undefined;
}

const demo: BoardColumn[] = [
  { id: 'todo', title: 'To do', items: [
    { id: 't1', title: 'Fix login on Safari', assignee: 'Budi Santoso', tag: 'Bug' },
    { id: 't2', title: 'Write the release notes', assignee: 'Ana Lima' },
    { id: 't3', title: 'Translate checkout into Indonesian' },
  ] },
  { id: 'doing', title: 'In progress', limit: 2, items: [
    { id: 't4', title: 'Dark mode for charts', assignee: 'Ana Lima' },
    { id: 't5', title: 'Invoice PDF export', assignee: 'Chen Wei' },
  ] },
  { id: 'review', title: 'In review', limit: 3, items: [{ id: 't6', title: 'Cart summary block', assignee: 'Budi Santoso' }] },
  { id: 'done', title: 'Done', items: [{ id: 't7', title: 'Audit form labels', assignee: 'Chen Wei' }] },
];

/** "1 task" or "3 tasks": English's rule, since the words are English; an app translating them uses its own. */
export const countTasks = (n: number, locale = 'en-US'): string => (n === 1 ? '1 task' : `${formatNumber(n, locale)} tasks`);

/** The columns with a moved card back where it came from, wherever it is now. */
export function putBack(columns: readonly BoardColumn[], move: KanbanMove<BoardTask>): BoardColumn[] {
  return columns.map((c) => {
    const items = c.items.filter((t) => t.id !== move.item.id);
    if (c.id === move.from.column) items.splice(Math.min(move.from.index, items.length), 0, move.item);
    return { ...c, items };
  });
}

/** The columns holding more than their limit, each as a sentence: "In progress has 3 tasks, over its limit of 2." */
export function overLimit(columns: readonly BoardColumn[], locale = 'en-US'): string[] {
  return columns.filter((c) => c.limit != null && c.items.length > c.limit).map((c) => `${c.title} has ${countTasks(c.items.length, locale)}, over its limit of ${formatNumber(c.limit!, locale)}.`);
}

/** The task board: a skip link, a header, then main with the board's h1, New task and the columns. */
export function TaskBoard({ title = 'Sprint 42', columns: start = demo, onMove, onAdd, loading = false, loadFailed = false, onRetry, online }: TaskBoardProps) {
  const locale = useLocale();
  const [columns, setColumns] = React.useState<readonly BoardColumn[]>(start);
  // What the app passes once loading ends replaces what was there, which was empty or the demo.
  const [wasLoading, setWasLoading] = React.useState(loading);
  if (wasLoading !== loading) { setWasLoading(loading); if (!loading) setColumns(start); }
  const total = columns.reduce((n, c) => n + c.items.length, 0);
  const over = overLimit(columns);

  // A move shows at once and is saved after. One that can't be saved goes back, and says so.
  const move = (next: KanbanColumn<BoardTask>[], m: KanbanMove<BoardTask>) => {
    setColumns(next);
    void Promise.resolve().then(() => onMove?.(m)).catch(() => {
      setColumns((now) => putBack(now, m));
      const from = columns.find((c) => c.id === m.from.column)?.title ?? '';
      toast({ title: `Couldn’t move “${m.item.title}”`, description: `It’s back in ${from}. Try again.`, tone: 'danger' });
    });
  };

  // Adding: a dialog with a title and the column to start in.
  const [adding, setAdding] = React.useState(false);
  const [draft, setDraft] = React.useState<BoardTaskDraft>({ title: '', column: start[0]?.id ?? '' });
  const [titleError, setTitleError] = React.useState<string | null>(null);
  const [addFailed, setAddFailed] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  const made = React.useRef(0);
  const ask = (open: boolean) => {
    if (open) { setDraft({ title: '', column: columns[0]?.id ?? '' }); setTitleError(null); setAddFailed(false); }
    setAdding(open);
  };
  const add = (e: React.FormEvent) => {
    e.preventDefault();
    const kept = draft.title.trim();
    if (!kept) { setTitleError('Enter a title for the task.'); document.getElementById('task-title')?.focus(); return; }
    const sent = { title: kept, column: draft.column };
    setAddFailed(false);
    setBusy(true);
    void Promise.resolve().then(() => onAdd?.(sent)).then((id) => {
      const task: BoardTask = { id: typeof id === 'string' && id ? id : `new-${++made.current}`, title: kept };
      setColumns((now) => now.map((c) => (c.id === sent.column ? { ...c, items: [...c.items, task] } : c)));
      setAdding(false);
      toast({ title: `Added “${kept}” to ${columns.find((c) => c.id === sent.column)?.title ?? ''}`, tone: 'success' });
    }, () => setAddFailed(true)).finally(() => setBusy(false));
  };

  const card = (t: BoardTask) => (
    <div className="flex flex-col items-start gap-1">
      <span>{t.title}</span>
      {t.assignee || t.tag ? (
        <span className="flex flex-wrap items-center gap-2 text-sm text-text-muted">
          {t.tag ? <Badge tone={t.tag === 'Bug' ? 'danger' : 'info'}>{t.tag}</Badge> : null}
          {t.assignee}
        </span>
      ) : null}
    </div>
  );
  return (
    <div className="min-h-screen bg-surface text-text">
      <SkipLink />
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="m-0 text-base font-semibold">Acme</p>
      </header>
      <Container as="main" size="xl" className="py-8 outline-none" id="main">
        <Stack gap={0}>
          <OfflineBanner online={online} placement="inline" className="mb-6">This is the board as it was when the page loaded. Moving or adding cards needs a connection.</OfflineBanner>
          <PageHeader breadcrumb={[{ label: 'Boards', href: '#boards' }, { label: title }]} title={title}
            description={loading || loadFailed ? undefined : countTasks(total, locale)}
            primary={{ label: 'New task', icon: 'add', onSelect: () => ask(true), disabled: loading || loadFailed }} />

          <div className="flex flex-col gap-4 pt-6">
            {loadFailed ? <EmptyLoadFailed title="Couldn’t load the board" onRetry={() => onRetry?.()} headingLevel={2} /> : <>
              {!loading && over.length ? (
                <Alert tone="warning" role="status" title={over.join(' ')}>Finish or move a task before starting another.</Alert>
              ) : null}
              <Kanban aria-label={title} headingLevel={2} loading={loading} loadingLabel="Loading tasks"
                columns={loading ? columns.map((c) => ({ ...c, items: [] })) : columns}
                getKey={(t) => t.id} getLabel={(t) => t.title} renderCard={card} onMove={move} />
            </>}
          </div>

          <Dialog open={adding} onOpenChange={ask} title="New task">
            <form onSubmit={add} noValidate className="flex flex-col gap-4">
              {addFailed ? <Alert tone="danger">Couldn’t add the task. Try again.</Alert> : null}
              <p className="m-0 text-text-muted">Fields marked * are required.</p>
              <Field label="Title" id="task-title" hint="A few words that say what’s to be done." error={titleError ?? undefined} required>
                <Input name="title" value={draft.title} autoComplete="off" onChange={(e) => { setDraft({ ...draft, title: e.target.value }); if (titleError) setTitleError(null); }} />
              </Field>
              <Field label="Column" id="task-column">
                <Select value={draft.column} options={columns.map((c) => ({ value: c.id, label: c.title }))} onChange={(e) => setDraft({ ...draft, column: e.target.value })} />
              </Field>
              <div className="flex flex-wrap gap-2">
                <Button type="submit" loading={busy}>Add task</Button>
                <Button variant="outline" onClick={() => ask(false)}>Cancel</Button>
              </div>
            </form>
          </Dialog>
        </Stack>
      </Container>
      <Toaster />
    </div>
  );
}

