'use client';
import * as React from 'react';
import { Button } from '@diki-stwn/serupa-ds';
import { Chat, ChatComposer, ChatMessage } from '@diki-stwn/serupa-ds';
import { CopyButton } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { announce } from '@diki-stwn/serupa-ds';

/* AI chat (RU20): a conversation with an assistant whose replies stream in, for an app to copy. It's Chat with what
   an assistant needs around it. What it carries (WCAG 2.2):
   - 1.3.1: a region named by its heading, holding the conversation (Chat's log) and the message box.
   - 4.1.3: a streaming reply is aria-busy in the log until it's whole, so a screen reader reads it once, when it's
     done, not word by word. A stopped reply and one that failed say so in words, under the text.
   - 2.4.3: a suggested prompt sends itself and the suggestions go, Stop turns back into Send, and Regenerate's reply
     is replaced: each time, focus moves to the message box rather than dropping to the page.
   - 2.5.3 / 2.4.6: Copy and Regenerate are named for what they act on ("Copy reply"), so a list of them is clear.
   - Copy and Regenerate are there from the start of a reply, turned off until it's whole, so finishing doesn't add
     buttons the log would read out.
   - Each word is a label, English by default. */

export interface AIChatMessage {
  id: string;
  role: 'user' | 'assistant';
  text: string;
  /** The reply is still arriving: it's read once, when this goes false. */
  streaming?: boolean | undefined;
  /** The reply was stopped before it was done: "Stopped" under what arrived. */
  stopped?: boolean | undefined;
  /** The reply couldn't be finished: the reason, under what arrived, with Try again (onRegenerate). */
  error?: string | undefined;
}

export interface AIChatLabels {
  title: string;
  assistant: string;
  /** Above the suggested prompts, while there are no messages yet. */
  intro: string;
  suggestions: string;
  copy: string;
  regenerate: string;
  stopped: string;
  /** Said when a reply is stopped. */
  stoppedSaid: string;
  tryAgain: string;
}

const english: AIChatLabels = {
  title: 'Assistant',
  assistant: 'Assistant',
  intro: 'Ask a question, or start with one of these.',
  suggestions: 'Suggestions',
  copy: 'Copy reply',
  regenerate: 'Regenerate',
  stopped: 'Stopped',
  stoppedSaid: 'Reply stopped',
  tryAgain: 'Try again',
};

export interface AIChatProps {
  /** The conversation, oldest first. The last one is the reply in progress while it streams. */
  messages: readonly AIChatMessage[];
  /** Prompts to start with, shown as buttons while there are no messages. */
  suggestions?: readonly string[] | undefined;
  /** Sends a message: from the box, or a suggestion pressed. */
  onSend: (text: string) => void;
  /** Stops the reply that's streaming. Mark what arrived `stopped`. */
  onStop?: (() => void) | undefined;
  /** Asks again for the last reply, which the app replaces. */
  onRegenerate?: (() => void) | undefined;
  /** The heading's level, to fit the page. Default: 2. */
  headingLevel?: 1 | 2 | 3 | 4 | 5 | 6 | undefined;
  labels?: Partial<AIChatLabels> | undefined;
  className?: string | undefined;
}

export function AIChat({ messages, suggestions = [], onSend, onStop, onRegenerate, headingLevel = 2, labels, className }: AIChatProps) {
  const l = { ...english, ...labels };
  const id = React.useId(), titleId = `${id}-title`;
  const box = React.useRef<HTMLFormElement | null>(null);
  const last = messages[messages.length - 1];
  const streaming = !!(last && last.role === 'assistant' && last.streaming);
  const field = () => box.current && box.current.querySelector('textarea');

  // Stop turns into Send, and a reply asked for again replaces the one its button was in: focus would drop to the
  // page, so it goes to the box.
  const toBox = () => { const f = field(); if (f) f.focus(); };
  const suggest = (text: string) => {
    onSend(text);
    toBox();   // the suggestions go with the first message: focus waits in the box for the next one
  };
  const stop = () => {
    if (!onStop) return;
    onStop();
    announce(l.stoppedSaid);
    toBox();
  };
  const again = () => {
    if (!onRegenerate) return;
    onRegenerate();
    toBox();
  };

  return (
    <section aria-labelledby={titleId} className={['flex min-h-0 flex-col gap-3', className].filter(Boolean).join(' ')}>
      <Heading level={headingLevel} size="lg" id={titleId}>{l.title}</Heading>
      {messages.length ? (
        <Chat aria-labelledby={titleId} className="min-h-0 flex-1">
          {messages.map((m, i) => {
            const own = m.role === 'user', whole = !m.streaming, newest = i === messages.length - 1;
            return (
              // What's under a reply (whether it stopped, Copy, Regenerate) sits in the message's attachments row,
              // below the text and its Thinking… line, rather than in the bubble.
              <ChatMessage key={m.id} own={own} author={own ? undefined : l.assistant} streaming={m.streaming}
                thinking={!!m.streaming && !m.text} attachments={own ? undefined : (
                  <span className="flex flex-col gap-1">
                    {m.stopped || m.error ? (
                      <span className="text-sm text-text-muted">
                        <span>{m.error || l.stopped}</span>
                        {m.error && newest && onRegenerate ? <> <Button variant="link" size="sm" onClick={again}>{l.tryAgain}</Button></> : null}
                      </span>
                    ) : null}
                    <span className="flex flex-wrap gap-1">
                      <CopyButton size="sm" variant="ghost" value={m.text} disabled={!whole || !m.text}>{l.copy}</CopyButton>
                      {newest && onRegenerate ? (
                        <Button size="sm" variant="ghost" startIcon="refresh" disabled={!whole} onClick={again}>{l.regenerate}</Button>
                      ) : null}
                    </span>
                  </span>
                )}>
                {m.text ? <span className="whitespace-pre-wrap">{m.text}</span> : null}
              </ChatMessage>
            );
          })}
        </Chat>
      ) : suggestions.length ? (
        <div className="flex flex-col gap-3">
          <p className="text-text-muted">{l.intro}</p>
          <ul role="list" aria-label={l.suggestions} className="flex flex-wrap gap-2">
            {suggestions.map((s) => <li key={s}><Button variant="secondary" size="sm" onClick={() => suggest(s)}>{s}</Button></li>)}
          </ul>
        </div>
      ) : null}
      <ChatComposer ref={box} streaming={streaming} onStop={onStop ? stop : undefined} onSend={onSend} />
    </section>
  );
}

files.ActivityFeed.tsx:
'use client';
import * as React from 'react';
import { Avatar } from '@diki-stwn/serupa-ds';
import { Heading, type HeadingSize } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { EmptyLoadFailed } from './EmptyStates';
import { LoadMore } from '@diki-stwn/serupa-ds';
import { RelativeTime } from '@diki-stwn/serupa-ds';
import { Timeline, TimelineItem, type TimelineTone } from '@diki-stwn/serupa-ds';

/* Activity feed (BL7): who did what and when, newest first, for an app to copy. What it carries (WCAG 2.2):
   - 1.3.1: the feed is a region named by its heading, and the events are an ordered list, so a screen reader hears
     how many there are and can move between them.
   - 1.1.1: each event says who in words; the avatar beside the name is decoration and is hidden from screen readers.
   - 1.3.1: each time is a <time> with the exact moment for machines, "5 minutes ago" for people, and the full date in
     its tooltip (RelativeTime).
   - 2.4.3 / 4.1.3: "Load more" (LoadMore) keeps focus on the button as new events land above it, says how many
     were added, and moves focus to the end text after the last page, so focus is never lost.
   - 4.1.3: while the first page loads, the list says it's busy (aria-busy) and its skeleton rows are named once
     ("Loading: Activity"), not once per row; the heading is there from the start, so the page doesn't jump.
   - 4.1.3, 3.3.3: a failed first load says so once, under the heading, with Try again (EmptyLoadFailed).
   - Each word is a prop or a label, English by default. */

function line(e: ActivityEvent): React.ReactNode {
  const target = e.target && (e.target.href ? <Link href={e.target.href}>{e.target.label}</Link> : e.target.label);
  if (typeof e.action === 'function') return e.action(target);
  return <>{e.action}{target && <> {target}</>}</>;
}

export interface ActivityEvent {
  id: string;
  /** Who did it. */
  actor: { name: string; avatar?: string | undefined };
  /** What they did, after their name: "commented on", "closed". When the language puts the target inside the
      sentence (German "hat Bericht 3 kommentiert", Japanese "が報告書3にコメントしました"), pass a function: it
      gets the target, link and all, and returns the words around it. */
  action: string | ((target: React.ReactNode) => React.ReactNode);
  /** What they did it to, after the action: a page or a record, with a link when it has one. */
  target?: { label: string; href?: string | undefined } | undefined;
  /** When. A Date, a timestamp or an ISO string. */
  date: Date | number | string;
  /** More about it, under the line: a comment's first words, what changed. */
  detail?: React.ReactNode | undefined;
  /** The marker's color, from the event's kind; the words still say what happened. */
  status?: TimelineTone | undefined;
}

export interface ActivityFeedProps {
  events: readonly ActivityEvent[];
  /** Loads the next page. Return its promise, so the button shows loading and takes one press at a time. */
  onLoadMore: () => void | PromiseLike<unknown>;
  /** False after the last page. */
  hasMore: boolean;
  /** How many events there are in all, for "Showing 20 of 134". */
  total?: number | undefined;
  /** The feed's heading. Default: "Activity". */
  title?: string | undefined;
  headingLevel?: 2 | 3 | 4 | undefined;
  /** The heading's look, to match the page's other section headings ("lg" on Dashboard). Default: the level's own. */
  headingSize?: HeadingSize | undefined;
  /** Shown when there are no events. Default: "No activity yet". */
  emptyText?: string | undefined;
  /** The button's words. Default: LoadMore's "Load more". */
  loadMoreLabel?: string | undefined;
  /** Shown after the last page. Default: LoadMore's "You’ve reached the end". */
  endText?: string | undefined;
  /** The first page is on its way: skeleton rows in place of the events. Default: false. */
  loading?: boolean | undefined;
  /** How many skeleton rows to show while loading. Default: 3. */
  loadingCount?: number | undefined;
  /** The skeletons' one name, said to screen readers. Default: "Loading: " and the title. */
  loadingLabel?: string | undefined;
  /** The load failed: a "Couldn’t load" message with Try again, which calls onRetry, in the list's place. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** The failed load's title. Default: "Couldn’t load the activity". */
  loadFailedText?: string | undefined;
}

/** Who did what and when, newest first, with "Load more" that keeps focus in place and says how many were added. */
export function ActivityFeed({ events, onLoadMore, hasMore, total, title = 'Activity', headingLevel = 2, headingSize, emptyText = 'No activity yet', loadMoreLabel, endText, loading = false, loadingCount = 3, loadingLabel, loadFailed = false, onRetry, loadFailedText = 'Couldn’t load the activity' }: ActivityFeedProps) {
  const id = React.useId();
  return (
    <section aria-labelledby={id} className="flex flex-col gap-4">
      <Heading level={headingLevel} size={headingSize} id={id}>{title}</Heading>
      {loadFailed ? <EmptyLoadFailed title={loadFailedText} onRetry={() => onRetry?.()} headingLevel={headingLevel === 2 ? 3 : 4} size="sm" /> : loading ? (
        <ul role="list" aria-busy="true" className="m-0 flex list-none flex-col gap-4 p-0">
          {Array.from({ length: loadingCount }, (_, i) => (
            <li key={i} className="flex items-start gap-2">
              <Skeleton shape="circle" label="" className="shrink-0" />
              {/* One name for all of them: the first row is named, the others are only pictures. */}
              <Skeleton shape="text" size="sm" lines={2} label={i === 0 ? (loadingLabel ?? 'Loading: ' + title) : ''} className="min-w-0 flex-1" />
            </li>
          ))}
        </ul>
      ) : events.length === 0 ? <p className="text-sm text-text-muted">{emptyText}</p> : (
        <Timeline>
          {events.map((e) => (
            // The time and the detail sit in the avatar's text column, so a sentence that wraps, its time and its
            // detail all start at one edge rather than the time and detail falling back under the avatar.
            <TimelineItem key={e.id} tone={e.status}
              title={<span className="flex items-start gap-2 font-normal">
                <Avatar size="xs" name={e.actor.name} src={e.actor.avatar} alt="" />
                <span className="flex min-w-0 flex-col">
                  <span><strong className="font-semibold">{e.actor.name}</strong> {line(e)}</span>
                  <RelativeTime date={e.date} className="text-sm text-text-muted" />
                  {e.detail != null && e.detail !== '' ? <span className="mt-1 text-sm">{e.detail}</span> : null}
                </span>
              </span>} />
          ))}
        </Timeline>
      )}
      {!loading && !loadFailed && events.length > 0 && <LoadMore onLoadMore={onLoadMore} hasMore={hasMore} count={events.length} total={total} label={loadMoreLabel} endText={endText} />}
    </section>
  );
}

