'use client';
import * as React from 'react';
import { Badge } from '@diki-stwn/serupa-ds';
import { Button } from '@diki-stwn/serupa-ds';
import { Card } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { Image } from '@diki-stwn/serupa-ds';
import { Link } from '@diki-stwn/serupa-ds';
import { Skeleton } from '@diki-stwn/serupa-ds';
import { Rating } from '@diki-stwn/serupa-ds';
import { toast } from '@diki-stwn/serupa-ds';
import { formatNumber } from '@diki-stwn/serupa-ds';
import { useLocale } from '@diki-stwn/serupa-ds';
import { EmptyLoadFailed } from './EmptyStates';

/* Product grid (RU18): product cards in a responsive grid, for a shop's category or search page. What it carries
   (WCAG 2.2):
   - 1.3.1: the products are a list (role="list", since WebKit stops calling a list without bullets one), each card
     is a list item named by its product, and each name is a heading, so a screen reader can list and jump between them.
   - 2.4.4: the name is the one link to the product page; the picture beside it is decorative (alt=""), so a reader
     doesn't hear each product twice.
   - 1.4.1 / 1.3.1: a sale price says "Was" in words beside the old price, and the saving in a Badge: never a
     strike-through alone, which isn't read out and is easy to miss.
   - 1.1.1: the rating is one image named by its value ("Rating, 4.5 out of 5"), with the number of reviews in text.
   - 2.4.6 / 2.5.3: each Add to cart button starts with its visible words and ends with the product's name, so a list of
     buttons still makes sense out of context and voice control still finds "Add to cart".
   - 4.1.3: adding shows the button busy (loading), then a toast says what was added, or that it failed and why.
   - Sold out says so in words, in place of the button.
   - 4.1.3: while the products load, the list says it's busy (aria-busy) and its placeholder cards are named once, not
     once per card; a failed load says so once, with Try again (EmptyLoadFailed).
   - Prices are written the way the reader's locale writes money. Each word is a label, English by default. */

export interface Product {
  id: string;
  name: string;
  /** The product's page. */
  href: string;
  /** A picture of it. It's decorative beside the name, so it needs no alt text. */
  image: string;
  /** The price now. */
  price: number;
  /** The price before a sale, when it's on sale: higher than price. */
  was?: number | undefined;
  /** The average rating, out of 5. */
  rating?: number | undefined;
  /** How many reviews the rating comes from. */
  reviews?: number | undefined;
  soldOut?: boolean | undefined;
}

export interface ProductGridLabels {
  /** Before the old price of a product on sale. */
  was: string;
  /** The sale Badge: the saving as a whole percentage. */
  off: (percent: number) => string;
  /** The rating image's name, before its value. */
  rating: string;
  /** The number of reviews: count to pick the word, formatted to show (in the locale's digits). */
  reviews: (count: number, formatted: string) => string;
  addToCart: string;
  /** The toast once a product is in the cart. */
  added: (name: string) => string;
  /** The toast when adding failed. */
  notAdded: (name: string) => string;
  soldOut: string;
  /** The one name of the placeholder cards while the products load. */
  loading: string;
  /** The failed load's title. */
  loadFailed: string;
}

const english: ProductGridLabels = {
  was: 'Was',
  off: (percent) => `${percent}% off`,
  rating: 'Rating',
  reviews: (count, formatted) => `${formatted} ${count === 1 ? 'review' : 'reviews'}`,
  addToCart: 'Add to cart',
  added: (name) => `Added ${name} to your cart`,
  notAdded: (name) => `Couldn’t add ${name} to your cart. Try again.`,
  soldOut: 'Sold out',
  loading: 'Loading products',
  loadFailed: 'Couldn’t load the products',
};

export interface ProductGridProps {
  products: readonly Product[];
  /** An ISO 4217 code: "USD", "IDR", "EUR". */
  currency: string;
  /** Add to cart was pressed: the button stays busy until the promise settles, then a toast says how it went. */
  onAddToCart: (productId: string) => void | Promise<unknown>;
  /** Each product's name. Default: 3, under the page's h2. */
  headingLevel?: 2 | 3 | 4 | undefined;
  labels?: Partial<ProductGridLabels> | undefined;
  /** Placeholder cards in place of the products while they load, named once ("Loading products"). Default: false. */
  loading?: boolean | undefined;
  /** How many placeholder cards to show while loading. Default: 4. */
  loadingCount?: number | undefined;
  /** The products failed to load: a "Couldn’t load the products" message with Try again, which calls onRetry. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
}

/** One product: its picture, name as the link to its page, price, rating and Add to cart. */
export function ProductCard({ product: p, currency, onAddToCart, headingLevel = 3, labels }: Omit<ProductGridProps, 'products' | 'loading' | 'loadingCount' | 'loadFailed' | 'onRetry'> & { product: Product }) {
  const l = { ...english, ...labels };
  const locale = useLocale();
  const [busy, setBusy] = React.useState(false);
  const money = (value: number) => formatNumber(value, locale, { format: 'currency', currency, ...(Number.isInteger(value) && { minimumFractionDigits: 0, maximumFractionDigits: 0 }) });
  const sale = p.was !== undefined && p.was > p.price;
  const add = async () => {
    setBusy(true);
    try {
      await onAddToCart(p.id);
      toast({ title: l.added(p.name), tone: 'success' });
    } catch {
      toast({ title: l.notAdded(p.name), tone: 'danger' });
    } finally { setBusy(false); }
  };
  const nameId = `${React.useId()}-name`;   // its own on the page: two grids can hold the same product
  return (
    <Card as="li" padding="md" aria-labelledby={nameId} className="flex h-full min-w-0 flex-col gap-3 wrap-anywhere">
      <Image src={p.image} alt="" ratio="square" rounded />
      <Heading level={headingLevel} size="base" id={nameId}><Link href={p.href}>{p.name}</Link></Heading>
      <p className="flex flex-wrap items-baseline gap-x-2 gap-y-1">
        <span className="text-lg font-semibold">{money(p.price)}</span>
        {sale && <span className="text-sm text-text-muted">{l.was} <del>{money(p.was!)}</del></span>}
        {sale && <Badge tone="danger">{l.off(Math.floor(Number(((1 - p.price / p.was!) * 100).toFixed(6))))}</Badge>}
      </p>
      {p.rating !== undefined && (
        // A <div>, since Rating is one: inside a <p>, server HTML would end the <p> there and hydrating wouldn't match.
        <div className="flex flex-wrap items-center gap-2 text-sm text-text-muted">
          <Rating readOnly value={p.rating} size="sm" aria-label={l.rating} />
          {p.reviews !== undefined && <span>{l.reviews(p.reviews, formatNumber(p.reviews, locale))}</span>}
        </div>
      )}
      <div className="mt-auto">
        {p.soldOut
          ? <p className="text-sm font-semibold text-text-muted">{l.soldOut}</p>
          : <Button className="w-full" variant="secondary" loading={busy} onClick={add}
              aria-label={`${l.addToCart}, ${p.name}`}>{l.addToCart}</Button>}
      </div>
    </Card>
  );
}

/** Products in a grid that fits the screen: one column on a phone, up to four on a wide screen. */
export function ProductGrid({ products, loading = false, loadingCount = 4, loadFailed = false, onRetry, ...card }: ProductGridProps) {
  const l = { ...english, ...card.labels };
  if (loadFailed) return <EmptyLoadFailed title={l.loadFailed} onRetry={() => onRetry?.()} headingLevel={card.headingLevel ?? 3} />;
  return (
    <ul role="list" aria-busy={loading || undefined} className="m-0 grid list-none grid-cols-1 gap-6 p-0 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
      {loading
        ? Array.from({ length: loadingCount }, (_, i) => (
          // One name for all of them: the first card's lines are named, the rest are only pictures.
          <Card as="li" key={i} padding="md" className="flex flex-col gap-3">
            <Skeleton shape="rect" label="" className="aspect-square h-auto" />
            <Skeleton shape="text" lines={3} label={i === 0 ? l.loading : ''} />
          </Card>
        ))
        : products.map((p) => <ProductCard key={p.id} product={p} {...card} />)}
    </ul>
  );
}

files.SettingsSection.tsx:
'use client';
import * as React from 'react';
import { Button } from '@diki-stwn/serupa-ds';
import { ErrorSummary, type ErrorSummaryItem } from '@diki-stwn/serupa-ds';
import { Heading } from '@diki-stwn/serupa-ds';
import { SaveStatus, type SaveState } from '@diki-stwn/serupa-ds';

/* Settings section (BL4): one group of settings with its own heading, its own Save and its own status, built from the
   components only, for an app to copy. A settings page stacks several. What it carries (WCAG 2.2):
   - 1.3.1: a section named by its heading, so a screen reader lists it and can jump to it; the description says what
     the group is for.
   - 3.3.1 / 3.3.3: a failed save shows an ErrorSummary at the top of this section's form, which takes focus, with a
     link to each field; each field also says its own error (the app passes it to the Field). A second Save with the
     same problems takes focus again (GR163).
   - 4.1.3: SaveStatus says "Saved" politely once a save finishes, and "Couldn't save" with Try again if it fails, so
     the person doesn't have to look for a change.
   - 3.2.2: nothing saves on its own: changes wait for this section's Save, so other sections are left alone.
   - 1.4.10 reflow: the heading sits beside the fields on a wide screen and above them on a phone. */

export interface SettingsSectionProps {
  /** The section's heading: "Notifications". */
  title: string;
  /** What the settings are for, in a sentence, under the heading. */
  description?: React.ReactNode;
  /** The heading level, to fit the page's outline. Default: 2. The error summary's heading is one below it. */
  headingLevel?: 2 | 3 | 4 | undefined;
  /** Called by Save (the form's submit): check the fields, then save. */
  onSave: () => void;
  /** The problems from the last Save, in the order of the fields. With any, the summary shows and takes focus. */
  errors?: readonly ErrorSummaryItem[] | undefined;
  /** Where saving is: 'idle', 'saving', 'saved' or 'error'. Default: 'idle'. */
  status?: SaveState | undefined;
  /** When the last save finished, for "Saved 2 minutes ago". */
  savedAt?: Date | number | undefined;
  /** Shown with a failed save as Try again. */
  onRetry?: (() => void) | undefined;
  /** The save button's text, in the page's language. Default: "Save". */
  saveLabel?: string | undefined;
  /** The fields: Field with Input or Select, Switch, and so on. */
  children: React.ReactNode;
}

/** One group of settings with its own heading, its own Save, its own status and its own error summary. */
export function SettingsSection({ title, description, headingLevel = 2, onSave, errors = [], status = 'idle', savedAt, onRetry, saveLabel = 'Save', children }: SettingsSectionProps) {
  const id = React.useId();
  // Each Save remounts the summary, so a second try with the same problems takes focus and is read again (GR163).
  const [tries, setTries] = React.useState(0);
  return (
    <section aria-labelledby={id} className="grid grid-cols-1 gap-4 border-b border-border py-6 md:grid-cols-3 md:gap-8">
      <div className="flex flex-col gap-1">
        <Heading level={headingLevel} size="lg" id={id}>{title}</Heading>
        {description ? <p className="m-0 text-sm text-text-muted">{description}</p> : null}
      </div>
      <form noValidate onSubmit={(e) => { e.preventDefault(); setTries((t) => t + 1); onSave(); }} className="flex min-w-0 flex-col gap-4 md:col-span-2">
        {errors.length ? <ErrorSummary key={tries} errors={errors} headingLevel={(headingLevel + 1) as 3 | 4 | 5} /> : null}
        {children}
        <div className="flex flex-wrap items-center gap-3">
          <Button type="submit" loading={status === 'saving'}>{saveLabel}</Button>
          <SaveStatus status={status} savedAt={savedAt} onRetry={onRetry} />
        </div>
      </form>
    </section>
  );
}

