'use client';
import * as React from 'react';
import { Heading } from '@diki-stwn/serupa-ds';
import { StatTile } from '@diki-stwn/serupa-ds';
import { SerupaProvider } from '@diki-stwn/serupa-ds';
import { EmptyLoadFailed } from './EmptyStates';

/* Stats row (BL2): a row of key numbers for the top of a dashboard, built from the components only, for an app to copy.
   Each number is a StatTile, which says its change in words and names its trend line.
   What it carries (WCAG 2.2):
   - 1.4.1 Use of color: a change says "Up" or "Down" in words, with an arrow, as well as its color; whether up is good
     is the app's call (`good`), so a rise in costs isn't shown in green.
   - 1.1.1: each Sparkline is an image named by what it measures and its first, last, low and high values.
   - 1.3.1 in Safari: role="list" on the lists without bullets, since WebKit stops calling them lists (FU1, GR151).
   - 1.3.1: the row is a list under its own heading, so a screen reader says how many numbers there are, and each
     card reads label, value, change in that order.
   - 4.1.3: while loading, the list says it's busy (aria-busy) and the skeletons are named once, not once per card.
   - 4.1.3, 3.3.3: a failed load says so once, under the heading, with Try again (EmptyLoadFailed).
   - 1.4.10 reflow: the cards wrap to one column on a phone. */

export interface Stat {
  /** What the number is: "Revenue". */
  label: string;
  /** The number, formatted: "€48,200". */
  value: string;
  /** How it changed since the last period. */
  change?: {
    /** The size of the change, formatted: "12%". */
    amount: string;
    direction: 'up' | 'down' | 'flat';
    /** Whether this direction is good news. Default: up is good, down is bad. */
    good?: boolean;
  };
  /** The values over time, oldest first, for a Sparkline. */
  trend?: readonly number[];
}
export interface StatsRowProps {
  /** The row's heading: "This month". */
  title: string;
  /** The heading level, to fit the page's outline. Default: 2. */
  headingLevel?: 2 | 3 | 4;
  /** The numbers, 2 to 4 of them. */
  stats: readonly Stat[];
  /** What the change compares with: "vs last month". */
  period?: string;
  /** Shows skeletons in place of the numbers while they load. */
  loading?: boolean;
  /** How many skeleton cards to show while loading. Default: 4. */
  loadingCount?: number;
  /** The numbers failed to load: a "Couldn’t load" message with Try again, which calls onRetry, in the cards' place. Default: false. */
  loadFailed?: boolean | undefined;
  /** Loads again, after a failed load. Return a promise: Try again shows it's working until it settles. */
  onRetry?: (() => void | Promise<unknown>) | undefined;
  /** Its words, in the page's language. Each one left out stays English. */
  labels?: Partial<StatsRowLabels> | undefined;
}

/** The words StatsRow says. Pass your own for a page in another language. */
export interface StatsRowLabels {
  /** The change badge for a rise: "Up 12%". */
  up: (amount: string) => string;
  /** The change badge for a fall: "Down 4%". */
  down: (amount: string) => string;
  /** The change badge when nothing changed: "No change". */
  flat: string;
  /** The one name while loading, from the title as given: "Loading: This month". */
  loading: (title: string) => string;
  /** The failed load's title, from the title as given: "Couldn’t load This month". */
  loadFailed: (title: string) => string;
  /** A trend line's name: "Revenue, last 8 periods". */
  trend: (label: string, count: number) => string;
}
const EN: StatsRowLabels = {
  up: (amount) => `Up ${amount}`,
  down: (amount) => `Down ${amount}`,
  flat: 'No change',
  loading: (title) => `Loading: ${title}`,
  loadFailed: (title) => `Couldn’t load ${title}`,
  trend: (label, count) => `${label}, last ${count} periods`,
};
/* The grid fits the count: two or three numbers share one row from sm, so a third doesn't sit alone under two;
   four or more go two then four across. */
const COLUMNS: Record<number, string> = { 1: '', 2: 'sm:grid-cols-2', 3: 'sm:grid-cols-3', 4: 'sm:grid-cols-2 lg:grid-cols-4' };

/** A row of key numbers, each with its change said in words and an optional trend line. */
export function StatsRow({ title, headingLevel = 2, stats, period, loading = false, loadingCount = 4, loadFailed = false, onRetry, labels }: StatsRowProps) {
  const id = React.useId();
  const w = { ...EN, ...labels };
  // The tiles' words: StatTile's own (the provider's language) unless this row's labels set them.
  const tileWords: NonNullable<React.ComponentProps<typeof SerupaProvider>['labels']> = {};
  if (labels?.up) tileWords.statTileUp = labels.up;
  if (labels?.down) tileWords.statTileDown = labels.down;
  if (labels?.flat) tileWords.statTileFlat = labels.flat;
  if (labels?.trend) tileWords.statTileTrend = labels.trend;
  return (
    <section aria-labelledby={id} className="flex flex-col gap-4">
      <Heading level={headingLevel} size="lg" id={id}>{title}</Heading>
      {loadFailed ? <EmptyLoadFailed title={w.loadFailed(title)} onRetry={() => onRetry?.()} headingLevel={headingLevel === 2 ? 3 : 4} /> : <SerupaProvider labels={tileWords}><ul role="list" aria-busy={loading || undefined} className={`m-0 grid list-none grid-cols-1 gap-6 p-0 ${COLUMNS[loading ? loadingCount : stats.length] ?? COLUMNS[4]}`}>
        {loading
          // One name for all of them: the first skeleton is named, the others are only pictures.
          ? Array.from({ length: loadingCount }, (_, i) => <StatTile as="li" key={i} label="" value="" loading loadingLabel={i === 0 ? w.loading(title) : ''} />)
          : stats.map((s) => <StatTile as="li" key={s.label} label={s.label} value={s.value} change={s.change} period={s.change ? period : undefined} trend={s.trend} />)}
      </ul></SerupaProvider>}
    </section>
  );
}

files.TableToolbar.tsx:
'use client';
import * as React from 'react';
import { Button } from '@diki-stwn/serupa-ds';
import { Field } from '@diki-stwn/serupa-ds';
import { SearchInput } from '@diki-stwn/serupa-ds';
import { Select, type SelectOption } from '@diki-stwn/serupa-ds';
import { TableActionBar } from '@diki-stwn/serupa-ds';

/* Table toolbar (BL3): search, filters, a results count and bulk actions above a table, built from the components only,
   for an app to copy. What it carries (WCAG 2.2):
   - 1.3.1 / 2.4.6: the search and filters sit in a search landmark with its own name, and each control has a visible label.
   - 4.1.3 status messages: the results count is a status region, so "8 of 24 projects" is read out when it changes,
     without moving focus.
   - 2.4.3 focus order / 2.4.11: "Clear filters" disappears once pressed, so focus goes to the search field rather than
     being lost on the page.
   - Bulk actions use TableActionBar ("3 selected", the actions, Clear selection), which says the count and moves focus
     to the table's "Select all" when the selection is cleared. It has to come just before the table, so the table is
     this block's child.
   - Filters as chips: pass a FilterBar as filterBar. It sits in the same search landmark, each chip says its filter in
     words ("Status is Active") and its × removes it; its own Clear all clears them, and Clear filters the search.
   - A column picker: pass Table's TableColumnsMenu as columns. It sits beside the count, outside the search landmark,
     since it changes what the table shows, not which rows.
   - 1.4.10 reflow: the controls stack on a phone; the table scrolls in its own frame. */

export interface TableFilter {
  /** The filter's visible label: "Status". */
  label: string;
  /** The picked value. '' means no filter: the first option. */
  value: string;
  /** The choices. Start with { value: '', label: 'All' }, the one that means no filter. */
  options: SelectOption[];
  onChange: (value: string) => void;
}

export interface TableToolbarProps {
  /** What the table lists: "projects". Names the search landmark ("Search and filter projects"). */
  noun: string;
  /** The search text. */
  query: string;
  onQueryChange: (query: string) => void;
  /** The filters beside the search field. */
  filters?: TableFilter[] | undefined;
  /** Filters as chips, under the search field: a FilterBar. Leave its resultsCount out, since results says the count. */
  filterBar?: React.ReactNode;
  /** A column picker beside the count: Table's TableColumnsMenu, drawn from the same list as the table. */
  columns?: React.ReactNode;
  /** The results count, formatted and in words: "8 of 24 projects". Read out when it changes. */
  results: string;
  /** Called by "Clear filters": empty the search and set every filter back to ''. It's shown while any is set. */
  onClearFilters: () => void;
  /** How many rows are selected. The bulk actions show while it's more than 0. Default: 0. */
  selectedCount?: number | undefined;
  /** Clears the selection. */
  onClearSelection?: (() => void) | undefined;
  /** How many rows match the search and filters, across every page. With onSelectAll, the bulk actions offer
      "Select all 24" while fewer are selected, and say "All 24 selected" once selectedCount reaches it. Leave it
      out when every row is on one page. */
  matchingCount?: number | undefined;
  /** Called by "Select all 24": select every matching row, on every page. */
  onSelectAll?: (() => void) | undefined;
  /** The actions for the selected rows: small Buttons such as Export or Archive. */
  bulkActions?: React.ReactNode;
  /** Its words, in the page's language. Each one left out stays English. */
  labels?: Partial<TableToolbarLabels> | undefined;
  /** The table. */
  children: React.ReactNode;
}

/** The words TableToolbar says. Pass your own for a page in another language. */
export interface TableToolbarLabels {
  /** The search landmark's name, from noun: "Search and filter projects". */
  landmark: (noun: string) => string;
  /** The search field's visible label: "Search". */
  search: string;
  /** The button that empties the search and filters: "Clear filters". */
  clearFilters: string;
}
const EN: TableToolbarLabels = {
  landmark: (noun) => `Search and filter ${noun}`,
  search: 'Search',
  clearFilters: 'Clear filters',
};

export function TableToolbar({ noun, query, onQueryChange, filters = [], filterBar, columns, results, onClearFilters, selectedCount = 0, onClearSelection, matchingCount, onSelectAll, bulkActions, labels, children }: TableToolbarProps) {
  const w = { ...EN, ...labels };
  const search = React.useRef<HTMLInputElement | null>(null);
  const filtered = query !== '' || filters.some((f) => f.value !== '');
  const clear = () => {
    onClearFilters();
    search.current?.focus();   // the button goes away, so focus would be lost with it
  };
  return (
    <div className="flex flex-col gap-3">
      <form role="search" aria-label={w.landmark(noun)} onSubmit={(e) => e.preventDefault()} className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-end">
        <Field label={w.search} className="sm:flex-1">
          <SearchInput ref={search} value={query} onChange={(e) => onQueryChange(e.target.value)} />
        </Field>
        {filters.map((f) => (
          <Field key={f.label} label={f.label}>
            <Select value={f.value} options={f.options} onChange={(e) => f.onChange(e.target.value)} />
          </Field>
        ))}
        {filtered ? <Button type="button" variant="ghost" onClick={clear}>{w.clearFilters}</Button> : null}
        {filterBar ? <div className="w-full">{filterBar}</div> : null}
      </form>
      {columns ? (
        <div className="flex flex-wrap items-center justify-between gap-2">
          <p role="status" className="m-0 text-sm text-text-muted">{results}</p>
          {columns}
        </div>
      ) : <p role="status" className="m-0 text-sm text-text-muted">{results}</p>}
      <TableActionBar count={selectedCount} onClear={onClearSelection} total={matchingCount} onSelectAll={onSelectAll}>{bulkActions}</TableActionBar>
      {children}
    </div>
  );
}
